-- Alice's Library -- traduções em português (leitura bilíngue).
-- Gerado por scripts/build-traducoes-sql.mjs a partir de public/alices-library/livros/*.pt.json. Não edite à mão.
-- Rodar DEPOIS de livros.sql e livros_texto.sql, na ordem dos números dos arquivos (00, 01, 02 ... e o último). Pode repetir: é um "upsert".
--
-- IMPORTANTE: o leitor do iPad lê as traduções dos arquivos livros/<slug>.pt.json que vão no app; rodar este SQL
-- NÃO é necessário para a leitura bilíngue funcionar. Ele guarda a mesma tradução no banco (consulta, backup,
-- revisão) e marca em public.livros quais livros têm tradução.

-- parte 7 de 10: 5 livros
begin;

-- william-shakespeare_a-midsummer-nights-dream (369 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_a-midsummer-nights-dream', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"acti":"Ato I","actii":"Ato II","actiii":"Ato III"}$tr$::jsonb, $tr${"scenei~scenei~6":"Cena I","athensthepalaceoftheseus~athensthepalaceoftheseus~24":"Atenas. O palácio de Teseu.","entertheseushippolytaphilostrateandatten~philostrateandattendants~45":"Entram Teseu, Hipólita, Filóstrato e Criados.","theseusnowfairhippolytaournuptialhourdra~ringoutayoungmansrevenue~192":"Teseu — Agora, bela Hipólita, nossa hora nupcial\nAvança depressa; quatro dias felizes trazem\nOutra lua: mas, ó, como me parece lenta\nEsta velha lua a minguar! Ela retarda meus desejos,\nComo uma madrasta ou uma viúva dotada\nQue por longo tempo consome a renda de um jovem.","hippolytafourdayswillquicklysteepthemsel~thenightofoursolemnities~167":"Hipólita — Quatro dias logo se embeberão de noite;\nQuatro noites logo sonharão o tempo a passar;\nE então a lua, como um arco de prata\nRecém-curvado no céu, contemplará a noite\nDas nossas solenidades.","theseusgophilostratestiruptheathenianyou~htriumphandwithrevelling~284":"Teseu — Vai, Filóstrato,\nDespertai a juventude ateniense para os festejos;\nAcorda o espírito vivo e ágil da alegria:\nManda a melancolia para os funerais;\nA pálida companheira não é para a nossa pompa. Sai Filóstrato.\nHipólita, cortejei-te com a minha espada\nE ganhei teu amor causando-te ofensas;\nMas casar-me-ei contigo em outro tom,\nCom pompa, com triunfo e com folguedos.","enteregeushermialysanderanddemetrius~rmialysanderanddemetrius~36":"Entram Egeu, Hérmia, Lisandro e Demétrio.","egeushappybetheseusourrenownedduke~betheseusourrenownedduke~34":"Egeu — Feliz seja Teseu, nosso renomado duque!","theseusthanksgoodegeuswhatsthenewswithth~geuswhatsthenewswiththee~42":"Teseu — Obrigado, bom Egeu: que novas me trazes?","egeusfullofvexationcomeiwithcomplaintaga~iatelyprovidedinthatcase~812":"Egeu — Cheio de aflição venho, com queixa\nContra minha filha, minha filha Hérmia.\nAvança, Demétrio. Meu nobre senhor,\nEste homem tem meu consentimento para casar com ela.\nAvança, Lisandro: e, meu gracioso duque,\nEste homem enfeitiçou o coração de minha filha:\nTu, tu, Lisandro, tu lhe deste versos\nE trocaste com minha filha penhores de amor:\nTu, ao luar, à janela dela cantaste\nCom voz fingida versos de fingido amor,\nE roubaste a impressão de sua fantasia\nCom pulseiras de teus cabelos, anéis, bugigangas, galanteios,\nQuinquilharias, ninharias, ramalhetes, doces, mensageiros\nDe forte poder sobre a juventude ainda não endurecida:\nCom astúcia furtaste o coração de minha filha,\nTransformaste a obediência que me é devida\nEm teimosa aspereza: e, meu gracioso duque,\nSe ela não consentir aqui, perante vossa graça,\nEm casar com Demétrio,\nPeço o antigo privilégio de Atenas:\nSendo ela minha, posso dispor dela:\nO que será ou para este cavalheiro\nOu para a morte, conforme nossa lei\nImediatamente prevista neste caso.","theseuswhatsayyouhermiabeadvisedfairmaid~etriusisaworthygentleman~219":"Teseu — Que dizes, Hérmia? Aconselha-te, bela donzela:\nPara ti teu pai deveria ser como um deus;\nAquele que compôs tuas belezas, sim, e aquele\nPara quem és apenas como uma forma em cera\nPor ele impressa e em seu poder\nDeixar a figura ou desfigurá-la.\nDemétrio é um digno cavalheiro.","hermiasoislysander~hermiasoislysander~18":"Hérmia — Lisandro também é.","theseusinhimselfheisbutinthiskindwanting~hermustbeheldtheworthier~85":"Teseu — Em si mesmo é;\nMas, neste caso, faltando-lhe a voz de teu pai,\nO outro deve ser tido como mais digno.","hermiaiwouldmyfatherlookdbutwithmyeyes~fatherlookdbutwithmyeyes~38":"Hérmia — Quisera que meu pai olhasse com os meus olhos.","theseusratheryoureyesmustwithhisjudgment~smustwithhisjudgmentlook~44":"Teseu — Antes devem teus olhos olhar com o juízo dele.","hermiaidoentreatyourgracetopardonmeiknow~eifirefusetoweddemetrius~216":"Hérmia — Suplico a vossa graça que me perdoe.\nNão sei por que poder me sinto tão ousada,\nNem como isso pode afetar meu recato,\nAo expor meus pensamentos em tal presença;\nMas rogo a vossa graça que eu saiba\nO pior que pode me acontecer neste caso,\nSe eu recusar casar com Demétrio.","theseuseithertodiethedeathortoabjurefore~ddiesinsingleblessedness~472":"Teseu — Ou morrer a morte ou abjurar\nPara sempre a sociedade dos homens.\nPor isso, bela Hérmia, interroga teus desejos;\nConsulta tua juventude, examina bem teu sangue,\nVê se, caso não cedas à escolha de teu pai,\nPodes suportar a libré de uma freira,\nPara sempre em sombrio claustro enclausurada,\nPara viver estéril irmã toda a vida,\nEntoando hinos débeis à fria lua infrutífera.\nTrês vezes bem-aventurados os que dominam assim o sangue\nPara suportar tal peregrinação virginal;\nMas mais terrenamente feliz é a rosa destilada\nDo que a que, murchando no espinho virgem,\nCresce, vive e morre em bem-aventurança solitária.","hermiasowilligrowsolivesodiemylordereiwi~entsnottogivesovereignty~129":"Hérmia — Assim crescerei, assim viverei, assim morrerei, meu senhor,\nAntes de entregar minha patente virginal\nA sua senhoria, cujo indesejado jugo\nMinha alma não consente em dar soberania.","theseustaketimetopauseandbythenextnewmoo~yeausterityandsinglelife~244":"Theseus — Toma tempo para refletir; e, pela próxima lua nova —\nDia do selo entre meu amor e mim,\nPara eterno laço de companhia —\nNesse dia ou prepara-te para morrer\nPor desobediência à vontade de teu pai,\nOu para casar com Demetrius, como ele quer;\nOu no altar de Diana para jurar\nPara sempre austeridade e vida solteira.","demetriusrelentsweethermiaandlysanderyie~zedtitletomycertainright~72":"Demetrius — Cede, doce Hermia; e tu, Lysander, rende\nTeu título desvairado ao meu direito certo.","lysanderyouhaveherfatherslovedemetriusle~havehermiasdoyoumarryhim~67":"Lysander — Tens o amor do pai dela, Demetrius;\nDeixa-me o de Hermia: casa tu com ele.","egeusscornfullysandertruehehathmyloveand~eridoestateuntodemetrius~122":"Egeus — Desdenhoso Lysander! É verdade, tem meu amor,\nE o que é meu, meu amor lhe renderá.\nE ela é minha, e todo o meu direito sobre ela\nTransfiro a Demetrius.","lysanderiammylordaswellderivedasheaswell~sspottedandinconstantman~373":"Lysander — Sou, meu senhor, tão bem nascido quanto ele,\nTão bem provido; meu amor é maior que o dele;\nMinha fortuna em tudo tão bem classificada,\nSe não com vantagem, que a de Demetrius;\nE, o que é mais do que todas estas jactâncias podem ser,\nSou amado pela bela Hermia:\nPor que então não perseguiria eu o meu direito?\nDemetrius, eu o sustento na sua própria cara,\nCortejou a filha de Nedar, Helena,\nE lhe ganhou a alma; e ela, doce dama, delira,\nDevotamente delira, delira em idolatria,\nPor este homem manchado e inconstante.","theseusimustconfessthatihaveheardsomucha~lythatconcernsyourselves~510":"Theseus — Devo confessar que ouvi tanto disso,\nE pensava falar a respeito com Demetrius;\nMas, demasiado cheio de meus próprios afazeres,\nMinha mente o perdeu. Mas, Demetrius, vem;\nE vem, Egeus; irás comigo,\nTenho uma lição privada para os dois.\nQuanto a ti, bela Hermia, cuida de armar-te\nPara ajustar teus desejos à vontade de teu pai;\nOu então a lei de Atenas te entrega —\nO que de modo algum podemos atenuar —\nÀ morte ou a um voto de vida solteira.\nVem, minha Hippolyta: que ânimo, meu amor?\nDemetrius e Egeus, vinde também:\nPreciso empregar-vos em certo negócio\nPara as nossas núpcias e conferir convosco\nAlgo que de perto vos diz respeito.","egeuswithdutyanddesirewefollowyouexeunta~tallbutlysanderandhermia~62":"Egeus — Com dever e desejo vos seguimos. Saem todos, exceto Lysander e Hermia.","lysanderhownowmylovewhyisyourcheeksopale~herosestheredofadesofast~74":"Lysander — Então, meu amor! por que tua face está tão pálida?\nComo é que as rosas ali murcham tão depressa?","hermiabelikeforwantofrainwhichicouldwell~fromthetempestofmineeyes~74":"Hermia — Talvez por falta de chuva, que eu bem poderia\nConceder-lhes da tempestade de meus olhos.","lysanderaymeforaughtthatevericouldreadco~heritwasdifferentinblood~132":"Lysander — Ai de mim! Por tudo que pude ler,\nPor tudo que pude ouvir em conto ou história,\nO curso do verdadeiro amor jamais correu liso;\nMas, ou era diferente em sangue —","hermiaocrosstoohightobeenthralldtolow~oohightobeenthralldtolow~37":"Hermia — Oh, cruz! Alto demais para ser escravo do baixo.","lysanderorelsemisgraffedinrespectofyears~sgraffedinrespectofyears~40":"Lysander — Ou então mal enxertado quanto aos anos —","hermiaospitetoooldtobeengagedtoyoung~toooldtobeengagedtoyoung~36":"Hermia — Oh, despeito! Velho demais para ser noivo do jovem.","lysanderorelseitstooduponthechoiceoffrie~oduponthechoiceoffriends~43":"Lysander — Ou então dependia da escolha dos amigos —","hermiaohelltochooselovebyanotherseyes~chooselovebyanotherseyes~37":"Hermia — Oh, inferno! Escolher o amor pelos olhos de outrem.","lysanderoriftherewereasympathyinchoicewa~ghtthingscometoconfusion~292":"Lysander — Ou, se houvesse simpatia na escolha,\nGuerra, morte ou doença o sitiava,\nTornando-o momentâneo como um som,\nVeloz como uma sombra, curto como um sonho;\nBreve como o relâmpago na noite escurecida,\nQue, num acesso, desvenda céu e terra,\nE antes que um homem tenha poder de dizer “Olha!”\nAs fauces da escuridão o devoram:\nTão depressa as coisas brilhantes caem em confusão.","hermiaifthentruelovershaveevercrossditst~tearspoorfancysfollowers~189":"Hermia — Se então os verdadeiros amantes sempre foram contrariados,\nIsso está como um édito no destino:\nEnsinemos, pois, paciência à nossa prova,\nPorque é uma cruz costumeira,\nTão devida ao amor quanto pensamentos, sonhos e suspiros,\nDesejos e lágrimas, pobres seguidores da fantasia.","lysanderagoodpersuasionthereforehearmehe~maytherewillistayforthee~408":"Lysander — Boa persuasão: portanto, ouve-me, Hermia.\nTenho uma tia viúva, uma dotada,\nDe grande renda, e não tem filho:\nDe Atenas sua casa dista sete léguas;\nE ela me estima como a seu único filho.\nAli, gentil Hermia, posso casar contigo;\nE até esse lugar a áspera lei ateniense\nNão pode nos perseguir. Se me amas, pois,\nEsgueira-te da casa de teu pai amanhã à noite;\nE no bosque, a uma légua da cidade,\nOnde uma vez te encontrei com Helena,\nPara fazer observância a uma manhã de maio,\nAli te esperarei.","hermiamygoodlysanderisweartotheebycupids~owtrulywillimeetwiththee~349":"Hermia — Meu bom Lysander!\nJuro-te, pelo mais forte arco de Cupido,\nPela sua melhor flecha de ponta dourada,\nPela simplicidade das pombas de Vênus,\nPor aquilo que une as almas e faz prosperar os amores,\nE por aquele fogo que queimou a rainha de Cartago,\nQuando o falso troiano foi visto a velejar,\nPor todos os votos que homens já romperam,\nEm número maior do que mulheres jamais proferiram,\nNaquele mesmo lugar que me marcaste,\nAmanhã sem falta me encontrarei contigo.","lysanderkeeppromiselovelookherecomeshele~elovelookherecomeshelena~42":"Lysander — Cumpre a promessa, amor. Olha, aí vem Helena.","enterhelena~enterhelena~11":"Entra Helena.","hermiagodspeedfairhelenawhitheraway~eedfairhelenawhitheraway~35":"Hermia — Deus te guie, bela Helena! Para onde vais?","helenacallyoumefairthatfairagainunsaydem~hemotionofdemetriusheart~456":"Helena — Chamas-me bela? Desdiz esse belo.\nDemetrius ama o teu belo: oh, feliz belo!\nTeus olhos são estrelas-guia; e o doce ar de tua língua\nMais afinado que a cotovia ao ouvido do pastor,\nQuando o trigo está verde, quando brotam os botões do espinheiro.\nA doença é contagiosa: oh, se o encanto o fosse,\nO teu eu pegaria, bela Hermia, antes de partir;\nMeu ouvido pegaria tua voz, meu olho teu olho,\nMinha língua pegaria a doce melodia da tua.\nFosse o mundo meu, tirado Demetrius,\nDaria o resto para ser em ti transformada.\nOh, ensina-me como olhas, e com que arte\nGovernas o movimento do coração de Demetrius.","hermiaifrownuponhimyethelovesmestill~uponhimyethelovesmestill~36":"Hermia — Franzo-lhe o cenho, e ainda assim ele me ama.","helenaothatyourfrownswouldteachmysmiless~ldteachmysmilessuchskill~48":"Helena — Oh, se teus cenhos ensinassem tal perícia a meus sorrisos!","hermiaigivehimcursesyethegivesmelove~imcursesyethegivesmelove~36":"Hermia — Dou-lhe maldições, e ele me dá amor.","helenaothatmyprayerscouldsuchaffectionmo~rscouldsuchaffectionmove~42":"Helena — Oh, se minhas preces pudessem mover tal afeição!","hermiathemoreihatethemorehefollowsme~eihatethemorehefollowsme~36":"Hermia — Quanto mais odeio, mais ele me segue.","helenathemoreilovethemorehehatethme~reilovethemorehehatethme~35":"Helena — Quanto mais amo, mais ele me odeia.","hermiahisfollyhelenaisnofaultofmine~llyhelenaisnofaultofmine~35":"Hermia — A tolice dele, Helena, não é culpa minha.","helenanonebutyourbeautywouldthatfaultwer~tywouldthatfaultweremine~45":"Helena — De ninguém, exceto da tua beleza: quem dera essa culpa fosse minha!","hermiatakecomforthenomoreshallseemyfacel~hathturndaheavenintohell~186":"Hermia — Consola-te: ele não verá mais o meu rosto;\nLysander e eu fugiremos deste lugar.\nAntes do tempo em que vi Lysander,\nAtenas me parecia um paraíso:\nOh, então, que graças habitam em meu amor,\nQue transformou um céu em inferno!","lysanderhelentoyouourmindswewillunfoldto~ateshavewedevisedtosteal~214":"Lysander — Helena, a ti nossos pensamentos revelaremos:\nAmanhã à noite, quando Febe contemplar\nSeu rosto de prata no espelho das águas,\nAdornando de pérola líquida a relva de lâminas,\nHora que sempre oculta as fugas dos amantes,\nPelas portas de Atenas planejamos escapulir.","hermiaandinthewoodwhereoftenyouandiuponf~odtillmorrowdeepmidnight~348":"Hermia — E no bosque, onde muitas vezes tu e eu\nSobre leitos de prímulas pálidas costumávamos deitar,\nEsvaziando o peito de seus doces segredos,\nAli meu Lysander e eu nos encontraremos;\nE dali de Atenas desviaremos os olhos,\nPara buscar novos amigos e companhias estranhas.\nAdeus, doce companheira de brinquedos: reza por nós;\nE que a boa sorte te conceda teu Demetrius!\nCumpre a palavra, Lysander: devemos matar de fome a vista\nDo alimento dos amantes até amanhã, à meia-noite funda.","lysanderiwillmyhermiaexithermiahelenaadi~imdemetriusdoteonyouexit~74":"Lysander — Cumprirei, minha Hermia. Sai Hermia.\nHelena, adeus:\nQue Demetrius por ti delire como tu por ele! Sai.","helenahowhappysomeoerothersomecanbethrou~tthitherandbackagainexit~856":"Helena — Quão felizes alguns podem ser mais que outros!\nPor Atenas me tomam por tão bela quanto ela.\nMas que importa? Demetrius não pensa assim;\nNão quer saber o que todos, menos ele, sabem:\nE como ele erra, delirando pelos olhos de Hermia,\nAssim eu, admirando suas qualidades:\nCoisas baixas e vis, sem valor algum,\nO amor pode transpor a forma e dignidade:\nO amor não olha com os olhos, mas com a mente;\nE por isso Cupido alado é pintado cego:\nNem tem a mente do Amor gosto de juízo algum;\nAsas e sem olhos figuram pressa descuidada:\nE por isso se diz que o Amor é criança,\nPorque na escolha é tantas vezes iludido.\nComo meninos travessos no jogo perjuram a si mesmos,\nAssim o menino Amor é perjuro em toda parte:\nPois antes que Demetrius pusesse os olhos nos de Hermia,\nChoveu juras de granizo de que era só meu;\nE quando esse granizo sentiu algum calor de Hermia,\nDissolveu-se, e chuvas de juras derreteram.\nVou contar-lhe a fuga da bela Hermia:\nEntão ao bosque ele, amanhã à noite,\nHá de segui-la; e por esta informação\nSe tiver agradecimentos, é caro gasto:\nMas nisto pretendo enriquecer minha dor,\nTendo a vista dele ali e de volta outra vez. Sai.","sceneii~sceneii~7":"Cena II","athensquinceshouse~athensquinceshouse~18":"Atenas. A casa de Quince.","enterquincesnugbottomflutesnoutandstarve~mflutesnoutandstarveling~44":"Entram Quince, Snug, Bottom, Flute, Snout e Starveling.","quinceisallourcompanyhere~uinceisallourcompanyhere~25":"Quince — Está aqui toda a nossa companhia?","bottomyouwerebesttocallthemgenerallymanb~bymanaccordingtothescrip~63":"Bottom — Melhor seria chamá-los em geral, homem por homem, segundo o rol.","quincehereisthescrollofeverymansnamewhic~ssonhisweddingdayatnight~134":"Quince — Aqui está o rolo com o nome de cada homem que se julga apto, por toda Atenas, para representar em nosso interlúdio diante do duque e da duquesa, na noite do dia do casamento dele.","bottomfirstgoodpeterquincesaywhattheplay~eactorsandsogrowtoapoint~92":"Bottom — Primeiro, bom Peter Quince, diz de que trata a peça, depois lê os nomes dos atores, e assim chega-se ao ponto.","quincemarryourplayisthemostlamentablecom~ldeathofpyramusandthisbe~78":"Quince — Pois bem, nossa peça é A Mais Lamentável Comédia e Mais Cruel Morte de Píramo e Tisbe.","bottomaverygoodpieceofworkiassureyouanda~lmastersspreadyourselves~116":"Bottom — Obra muito boa, garanto-vos, e alegre. Agora, bom Peter Quince, chama os atores pelo rolo. Mestres, espalhai-vos.","quinceanswerasicallyounickbottomtheweave~llyounickbottomtheweaver~41":"Quince — Respondei quando eu chamar. Nick Bottom, o tecelão.","bottomreadynamewhatpartiamforandproceed~whatpartiamforandproceed~39":"Bottom — Pronto. Diz que papel me cabe e prossegue.","quinceyounickbottomaresetdownforpyramus~ttomaresetdownforpyramus~39":"Quince — Tu, Nick Bottom, estás designado para Píramo.","bottomwhatispyramusaloveroratyrant~ispyramusaloveroratyrant~34":"Bottom — Que é Píramo? Um amante ou um tirano?","quincealoverthatkillshimselfmostgallantf~imselfmostgallantforlove~46":"Quince — Um amante, que se mata com a maior galhardia por amor.","bottomthatwillasksometearsinthetrueperfo~einaloverismorecondoling~425":"Bottom — Isso pedirá algumas lágrimas na verdadeira execução: se eu o fizer, que a plateia cuide dos olhos; moverei tempestades, condoer-me-ei em alguma medida. Quanto aos demais: no entanto minha principal veia é para um tirano: poderia representar Ercles com perfeição, ou um papel de rasgar um gato, de fazer tudo rachar. As rochas furiosas\nE os choques tremorosos\nQuebrarão os ferrolhos\nDas portas da prisão;\nE o carro de Febo\nBrilhará ao longe\nE fará e desfará\nAs Parcas tolas. Isto foi sublime! Agora nomeia o resto dos atores. Esta é a veia de Ercles, veia de tirano; um amante é mais lastimoso.","quincefrancisflutethebellowsmender~cisflutethebellowsmender~34":"Quince — Francis Flute, o remendador de foles.","fluteherepeterquince~fluteherepeterquince~20":"Flute — Aqui, Peter Quince.","quincefluteyoumusttakethisbyonyou~teyoumusttakethisbyonyou~33":"Quince — Flute, tens de tomar Tisbe a teu cargo.","flutewhatisthisbyawanderingknight~isthisbyawanderingknight~33":"Flute — Que é Tisbe? Um cavaleiro andante?","quinceitistheladythatpyramusmustlove~eladythatpyramusmustlove~36":"Quince — É a dama que Píramo deve amar.","flutenayfaithletnotmeplayawomanihaveabea~yawomanihaveabeardcoming~48":"Flute — Não, por minha fé, não me deixeis representar uma mulher; estou com a barba por vir.","quincethatsalloneyoushallplayitinamaskan~mayspeakassmallasyouwill~68":"Quince — Tanto faz: representarás de máscara, e podes falar tão fininho quanto quiseres.","bottomanimayhidemyfaceletmeplaythisbytoo~thythisbedearandladydear~127":"Bottom — Se eu puder esconder o rosto, deixai-me representar Tisbe também, falarei com uma vozinha monstruosa: “Tisne, Tisne”; “Ah Píramo, meu amante querido! tua Tisbe querida, e dama querida!”","quincenonoyoumustplaypyramusandfluteyout~pyramusandfluteyouthisby~45":"Quince — Não, não; tens de representar Píramo: e tu, Flute, Tisbe.","bottomwellproceed~bottomwellproceed~17":"Bottom — Bem, prossegue.","quincerobinstarvelingthetailor~robinstarvelingthetailor~30":"Quince — Robin Starveling, o alfaiate.","starvelingherepeterquince~tarvelingherepeterquince~25":"Starveling — Aqui, Peter Quince.","quincerobinstarvelingyoumustplaythisbesm~smothertomsnoutthetinker~62":"Quince — Robin Starveling, tens de representar a mãe de Tisbe. Tom Snout, o funileiro.","snoutherepeterquince~snoutherepeterquince~20":"Snout — Aqui, Peter Quince.","quinceyoupyramusfathermyselfthisbysfathe~ndihopehereisaplayfitted~94":"Quince — Tu, o pai de Píramo: eu mesmo, o pai de Tisbe. Snug, o marceneiro; tu, o papel do leão: e, espero, aqui está uma peça bem distribuída.","snughaveyouthelionspartwrittenprayyouifi~iveitmeforiamslowofstudy~68":"Snug — Tendes escrito o papel do leão? Rogo-vos, se estiver, dai-mo, pois sou lento no estudo.","quinceyoumaydoitextemporeforitisnothingb~foritisnothingbutroaring~49":"Quince — Podes fazê-lo de improviso, pois não é nada além de rugir.","bottomletmeplaytheliontooiwillroarthatiw~roaragainlethimroaragain~131":"Bottom — Deixai-me representar o leão também: rugirei de tal modo que farei bem ao coração de qualquer um que me ouvir; rugirei de tal modo que farei o duque dizer: “Que ele ruja outra vez, que ele ruja outra vez.”","quinceanyoushoulddoittooterriblyyouwould~hatwereenoughtohangusall~115":"Quince — Se o fizerdes terrível demais, assustaríeis a duquesa e as damas, de modo que gritariam; e isso bastaria para nos enforcarem a todos.","allthatwouldhanguseverymothersson~uldhanguseverymothersson~33":"Todos — Isso nos enforcaria, filho de mãe por filho de mãe.","bottomigrantyoufriendsifyoushouldfrightt~youantwereanynightingale~201":"Bottom — Concedo-vos, amigos, que se assustásseis as damas até lhes tirar o juízo, elas não teriam mais discrição que a de nos enforcar: mas eu aumentarei a minha voz de modo que rugirei tão gentilmente quanto qualquer pombinho de peito; rugirei como se fosse um rouxinol.","quinceyoucanplaynopartbutpyramusforpyram~eyoumustneedsplaypyramus~153":"Quince — Não podes representar outro papel senão Píramo; pois Píramo é homem de rosto doce; homem de boa presença, como se vê em dia de verão; homem de lindo ar fidalgo: portanto tens de representar Píramo.","bottomwelliwillundertakeitwhatbeardwerei~beardwereibesttoplayitin~54":"Bottom — Bem, assumirei. Com que barba seria melhor representá-lo?","quincewhywhatyouwill~quincewhywhatyouwill~20":"Quince — Ora, com a que quiseres.","bottomiwilldischargeitineitheryourstrawc~urbeardyourperfectyellow~137":"Bottom — Desempenhá-lo-ei ou com vossa barba cor de palha, ou com vossa barba laranja-acastanhada, ou com vossa barba púrpura-em-grão, ou com vossa barba cor de coroa francesa, vosso amarelo perfeito.","quincesomeofyourfrenchcrownshavenohairat~aywantsiprayyoufailmenot~371":"Quince — Algumas de vossas coroas francesas não têm cabelo algum, e então representareis de cara limpa. Mas, mestres, aqui estão vossos papéis: e devo implorar-vos, pedir-vos e desejar-vos que os decoreis até amanhã à noite; e encontrai-me no bosque do palácio, a uma milha fora da cidade, à luz da lua; ali ensaiaremos, pois se nos reunirmos na cidade seremos seguidos por gente, e nossos planos conhecidos. Entretempo, farei uma lista de acessórios, quais a nossa peça requer. Rogo-vos que não me falteis.","bottomwewillmeetandtherewemayrehearsemos~ytakepainsbeperfectadieu~88":"Bottom — Encontrar-nos-emos; e ali poderemos ensaiar com a maior obscenidade e coragem. Esforçai-vos; sabei-o de cor: adeus.","quinceatthedukesoakwemeet~uinceatthedukesoakwemeet~25":"Quince — No carvalho do duque nos encontramos.","bottomenoughholdorcutbowstringsexeunt~oldorcutbowstringsexeunt~37":"Bottom — Basta; segura, ou corta as cordas do arco. Saem.","awoodnearathens~awoodnearathens~15":"Um bosque perto de Atenas.","enterfromoppositesidesafairyandpuck~positesidesafairyandpuck~35":"Entram, por lados opostos, uma Fada e Puck.","puckhownowspiritwhitherwanderyou~owspiritwhitherwanderyou~32":"Puck — Olá, espírito! Para onde vagueias?","fairyoverhilloverdalethoroughbushthoroug~dallherelvescomehereanon~415":"Fada — Sobre colina, sobre vale,\nPor entre sarça e espinheiro,\nSobre parque, sobre cerca,\nPor entre fogo e aguaceiro,\nEu vago por toda parte,\nMais veloz que a esfera da lua;\nE sirvo à rainha das fadas,\nPara orvalhar-lhe os círculos na relva.\nAs altas prímulas são suas pensionistas:\nEm seus casacos dourados vês pintas;\nSão rubis, dádivas de fada,\nNessas sardas moram seus perfumes:\nPreciso buscar aqui algumas gotas de orvalho\nE pendurar uma pérola na orelha de cada prímula.\nAdeus, tu, rústico dos espíritos; vou-me embora:\nNossa rainha e todos os seus elfos chegam já.","puckthekingdothkeephisrevelsheretonightt~corncupsandhidethemthere~488":"Puck — O rei faz aqui suas festas esta noite:\nCuida que a rainha não lhe caia sob os olhos;\nPois Oberon está furioso e colérico em excesso,\nPorque ela tem como pajem\nUm menino encantador, roubado a um rei indiano;\nNunca teve criança trocada tão doce;\nE o ciumento Oberon quer o menino\nComo cavaleiro de seu séquito, para percorrer as florestas bravias;\nMas ela, à força, retém o menino amado,\nCoroa-o de flores e faz dele toda a sua alegria:\nE agora nunca se encontram em bosque ou relvado,\nEm fonte clara ou sob o brilho estrelado da noite,\nSem que briguem, de modo que todos os seus elfos, de medo,\nRastejam para dentro de cálices de bolota e ali se escondem.","fairyeitherimistakeyourshapeandmakingqui~lhavegoodluckarenotyouhe~385":"Fada — Ou eu me engano de todo quanto à tua figura e feitio,\nOu és aquele astuto e travesso duende\nChamado Robin Goodfellow: não és tu\nQuem assusta as moças da aldeia;\nDesnata o leite, e às vezes trabalha na azenha\nE faz a ofegante dona de casa bater manteiga em vão;\nE às vezes faz a bebida não criar espuma;\nDesencaminha os viajantes noturnos, rindo-se do seu mal?\nAos que te chamam Hobgoblin e doce Puck,\nTu fazes o serviço, e eles têm boa sorte:\nNão és tu?","puckthouspeakstarightiamthatmerrywandere~roomfairyherecomesoberon~533":"Puck — Falas com acerto;\nSou esse alegre andarilho da noite.\nDivirto Oberon e o faço sorrir\nQuando engano um cavalo gordo, nutrido a favas,\nRelinchando como uma potra nova:\nE às vezes me escondo na tigela de uma comadre,\nBem na forma de uma maçã assada,\nE quando ela bebe, bato-lhe nos lábios\nE derramo a cerveja sobre a sua papada murcha.\nA mais sábia das tias, contando o mais triste dos casos,\nÀs vezes me toma por um banquinho de três pés;\nEntão escorrego de sob o seu traseiro, e ela tomba,\nE grita “alfaiate!”, e cai numa tosse;\nE então todo o coro agarra os quadris e ri,\nE se desmancha de alegria, e espirra, e jura\nQue nunca se gastou hora mais alegre.\nMas, abre alas, fada! Aí vem Oberon.","fairyandheremymistresswouldthatheweregon~tresswouldthatheweregone~41":"Fada — E aqui minha senhora. Quem me dera que ele se fosse!","enterfromonesideoberonwithhistrainfromth~mtheothertitaniawithhers~61":"Entram, de um lado, Oberon, com seu séquito; do outro, Titânia, com o seu.","oberonillmetbymoonlightproudtitania~tbymoonlightproudtitania~35":"Oberon — Mal encontrada ao luar, orgulhosa Titânia.","titaniawhatjealousoberonfairiesskiphence~forswornhisbedandcompany~69":"Titânia — Como, o ciumento Oberon! Fadas, saltai daqui:\nJurei renunciar à sua cama e à sua companhia.","oberontarryrashwantonamnotithylord~yrashwantonamnotithylord~34":"Oberon — Espera, imprudente: não sou eu o teu senhor?","titaniathenimustbethyladybutiknowwhentho~theirbedjoyandprosperity~324":"Titânia — Então devo ser a tua senhora: mas sei\nQuando fugiste da terra das fadas,\nE sob a forma de Corin ficaste o dia inteiro\nTocando flautas de palha e versejando amor\nA amorosa Filida. Por que estás aqui,\nVindo do mais longínquo confim da Índia?\nSenão porque, na verdade, a fogosa Amazona,\nTua amante de coturnos e teu amor guerreiro,\nDeve casar-se com Teseu, e vieste\nDar alegria e prosperidade ao leito deles.","oberonhowcanstthouthusforshametitaniagla~ithwithariadneandantiopa~222":"Oberon — Como podes, sem vergonha, Titânia,\nAludir ao meu apreço por Hipólita,\nSabendo que sei do teu amor por Teseu?\nNão foste tu que o levaste pela noite bruxuleante\nDe Perigênia, a quem ele violou?\nE o fizeste romper a fé com a bela Egle,\nCom Ariadne e Antíope?","titaniathesearetheforgeriesofjealousyand~etheirparentsandoriginal~1235":"Titânia — São invenções do ciúme:\nE nunca, desde o começo do pleno verão,\nNos encontramos em colina, vale, floresta ou prado,\nEm fonte calçada ou riacho de juncos,\nOu na orla praiana do mar,\nPara dançar nossas rodas ao vento que assobia,\nSem que com tuas brigas perturbasses o nosso folguedo.\nPor isso os ventos, tocando flauta para nós em vão,\nComo em vingança, sugaram do mar\nNévoas contagiosas; as quais, caindo sobre a terra,\nFizeram cada riacho mesquinho tão soberbo\nQue transbordou de seus leitos:\nPor isso o boi esticou seu jugo em vão,\nO lavrador perdeu seu suor, e o milho verde\nApodreceu antes que sua juventude ganhasse barba;\nO aprisco jaz vazio no campo afogado,\nE os corvos se engordam com o rebanho morto de peste;\nO jogo da amarelinha dos nove homens está cheio de lama,\nE os graciosos labirintos no relvado viçoso,\nPor falta de pisadas, não se distinguem mais:\nOs mortais humanos aqui sentem falta do inverno;\nNenhuma noite é agora abençoada com hino ou cântico:\nPor isso a lua, governanta das águas,\nPálida em sua cólera, banha todo o ar,\nDe modo que as doenças reumáticas abundam:\nE por essa desordem vemos\nAs estações se alterarem: geadas de cabeça encanecida\nCaem no colo fresco da rosa carmesim,\nE sobre a coroa fina e gelada do velho Hiems\nUma guirlanda perfumada de doces botões de verão\nÉ posta, como em zombaria: a primavera, o verão,\nO outono fecundo, o inverno colérico, trocam\nSuas librés habituais, e o mundo atônito,\nPor seus produtos, já não sabe qual é qual:\nE toda essa prole de males vem\nDe nossa discórdia, de nossa dissensão;\nSomos nós os seus pais e a sua origem.","oberondoyouamenditthenitliesinyouwhyshou~ngelingboytobemyhenchman~106":"Oberon — Então corrige-o tu; está em teu poder:\nPor que Titânia contraria seu Oberon?\nNão peço mais que um pequeno menino trocado\nPara ser meu pajem.","titaniasetyourheartatrestthefairylandbuy~rsakeiwillnotpartwithhim~548":"Titânia — Sossega o teu coração:\nA terra das fadas não compra de mim a criança.\nSua mãe era devota da minha ordem:\nE, no ar perfumado de especiarias da Índia, à noite,\nMuitas vezes conversou ao meu lado,\nE sentou comigo nas areias amarelas de Netuno,\nObservando os mercadores embarcados nas águas,\nQuando ríamos de ver as velas conceberem\nE inchar o ventre com o vento travesso;\nO que ela, com seu andar gracioso e ondulante,\nSeguindo-as — o ventre então rico do meu pequeno escudeiro —\nImitava, e navegava sobre a terra,\nPara trazer-me bagatelas, e voltava\nComo de uma viagem, rica de mercadorias.\nMas ela, sendo mortal, morreu desse menino;\nE por amor a ela crio o seu filho,\nE por amor a ela não me separarei dele.","oberonhowlongwithinthiswoodintendyoustay~hinthiswoodintendyoustay~40":"Oberon — Quanto tempo pensas ficar neste bosque?","titaniaperchancetillaftertheseusweddingd~eandiwillspareyourhaunts~141":"Titânia — Talvez até depois do dia das bodas de Teseu.\nSe quiseres dançar pacientemente em nossa roda\nE ver nossas festas ao luar, vem conosco;\nSe não, evita-me, e pouparei os teus redutos.","oberongivemethatboyandiwillgowiththee~hatboyandiwillgowiththee~37":"Oberon — Dá-me esse menino, e irei contigo.","titanianotforthyfairykingdomfairiesawayw~yexittitaniawithhertrain~96":"Titânia — Nem pelo teu reino de fadas. Fadas, vamos embora!\nHaveremos de brigar de vez, se eu ficar mais tempo. Sai Titânia com seu séquito.","oberonwellgothywaythoushaltnotfromthisgr~estoheartheseamaidsmusic~299":"Oberon — Pois bem, segue teu caminho: não sairás deste bosque\nAntes que eu te atormente por esta injúria.\nMeu gentil Puck, vem cá. Lembras-te\nDe quando uma vez me sentei num promontório\nE ouvi uma sereia no dorso de um golfinho\nExalar tão doce e harmonioso sopro\nQue o mar bravio se tornou civil ao seu canto\nE certas estrelas, loucamente, saltaram de suas esferas\nPara ouvir a música da donzela do mar.","puckiremember~puckiremember~13":"Puck — Lembro-me.","oberonthatverytimeisawbutthoucouldstnotf~eleviathancanswimaleague~661":"Oberon — Naquele mesmo instante vi, mas tu não podias,\nVoando entre a fria lua e a terra,\nCupido, todo armado: tomou certeira mira\nSobre uma bela vestal entronizada no ocidente,\nE soltou com vigor a flecha do amor de seu arco,\nComo se fosse trespassar cem mil corações;\nMas pude ver a flecha ardente do jovem Cupido\nApagar-se nos raios castos da lua aquosa,\nE a imperial sacerdotisa seguiu adiante,\nEm meditação virginal, livre de amor.\nContudo notei onde o dardo de Cupido caiu:\nCaiu sobre uma pequena flor do ocidente,\nAntes branca como leite, agora púrpura da ferida do amor,\nE as donzelas a chamam amor-perfeito.\nTraze-me essa flor; a erva que uma vez te mostrei:\nO seu suco, posto sobre pálpebras adormecidas,\nFará homem ou mulher perder-se de amores\nPela primeira criatura viva que vir.\nTraze-me essa erva; e volta aqui\nAntes que o leviatã nade uma légua.","puckillputagirdleroundabouttheearthinfor~eearthinfortyminutesexit~53":"Puck — Colocarei um cinto em torno da terra\nEm quarenta minutos. Sai.","oberonhavingoncethisjuiceillwatchtitania~loverheartheirconference~353":"Oberon — Uma vez de posse deste suco,\nEspiarei Titânia quando estiver dormindo,\nE pingarei o licor em seus olhos.\nA primeira coisa que ela vir ao acordar,\nSeja leão, urso ou lobo, ou touro,\nMacaco intrometido ou símio azafamado,\nPerseguirá com a alma do amor:\nE antes que eu tire este encanto de sua vista,\nO que posso fazer com outra erva,\nFarei que me entregue o seu pajem.\nMas quem vem aí? Estou invisível;\nE ouvirei a conversa deles.","enterdemetriushelenafollowinghim~etriushelenafollowinghim~32":"Entram Demétrio, e Helena, que o segue.","demetriusilovetheenotthereforepursuemeno~heegoneandfollowmenomore~229":"Demétrio — Não te amo, portanto não me persigas.\nOnde estão Lisandro e a bela Hérmia?\nUm eu matarei, a outra me mata.\nDisseste-me que haviam fugido para este bosque;\nE aqui estou eu, e enlouqueço neste bosque,\nPorque não posso encontrar Hérmia.\nAfasta-te, some, e não me sigas mais.","helenayoudrawmeyouhardheartedadamantbuty~llhavenopowertofollowyou~133":"Helena — Tu me atrais, ó duro coração de diamante;\nMas não atrais ferro, pois meu coração\nÉ firme como aço: tira de ti o poder de atrair,\nE não terei poder para seguir-te.","demetriusdoienticeyoudoispeakyoufairorra~uidonotnoricannotloveyou~95":"Demétrio — Eu a seduzo? Falo-lhe com doçura?\nOu antes não lhe digo, na mais pura verdade,\nQue não a amo, nem posso amá-la?","helenaandevenforthatdoiloveyouthemoreiam~ntobeusedasyouuseyourdog~273":"Helena — E por isso mesmo eu te amo ainda mais.\nSou o teu cãozinho; e, Demétrio,\nQuanto mais me bateres, mais te farei festa:\nTrata-me apenas como teu cãozinho, despreza-me, golpeia-me,\nNegligencia-me, perde-me; só me dá licença,\nIndigna como sou, de seguir-te.\nQue lugar pior posso pedir em teu amor —\nE contudo lugar de alta estima para mim —\nQue ser tratada como tratas o teu cão?","demetriustemptnottoomuchthehatredofmyspi~iamsickwhenidolookonthee~70":"Demétrio — Não tentes demais o ódio do meu espírito,\nPois fico doente quando te olho.","helenaandiamsickwhenilooknotonyou~iamsickwhenilooknotonyou~33":"Helena — E eu fico doente quando não te olho.","demetriusyoudoimpeachyourmodestytoomucht~richworthofyourvirginity~191":"Demétrio — Comprometes demais o teu recato,\nAo deixar a cidade e entregar-te\nÀs mãos de quem não te ama;\nAo confiar na oportunidade da noite\nE no mau conselho de um lugar deserto\nO rico valor da tua virgindade.","helenayourvirtueismyprivilegeforthatitis~theworldisheretolookonme~219":"Helena — Tua virtude é o meu privilégio: pois\nNão é noite quando vejo o teu rosto,\nPor isso penso que não estou na noite;\nNem falta a este bosque um mundo de companhia,\nPois tu, a meus olhos, és todo o mundo:\nComo se pode então dizer que estou sozinha,\nQuando todo o mundo está aqui a me olhar?","demetriusillrunfromtheeandhidemeinthebra~eetothemercyofwildbeasts~77":"Demétrio — Fugirei de ti e me esconderei nas moitas,\nE te deixarei à mercê das feras.","helenathewildesthathnotsuchaheartasyouru~icepursuesandvalourflies~214":"Helena — A mais selvagem não tem coração como o teu.\nCorre quando quiseres, a história será mudada:\nApolo foge e Dafne persegue;\nA pomba persegue o grifo; a mansa corça\nCorre para caçar o tigre; corrida inútil,\nQuando a covardia persegue e o valor foge.","demetriusiwillnotstaythyquestionsletmego~ldotheemischiefinthewood~100":"Demétrio — Não esperarei tuas perguntas; deixa-me ir:\nOu, se me seguires, não creias\nQue não te farei mal neste bosque.","helenaayinthetempleinthetownthefieldyoud~onthehandilovesowellexit~233":"Helena — Sim, no templo, na cidade, no campo,\nMe fazes mal. Ora, Demétrio!\nTuas ofensas lançam escândalo sobre o meu sexo:\nNão podemos lutar por amor, como os homens;\nDevíamos ser cortejadas e não fomos feitas para cortejar. Sai Demétrio.\nSeguir-te-ei e farei do inferno um céu,\nPara morrer pela mão que tanto amo.","oberonfaretheewellnympherehedoleavethisg~himandheshallseekthylove~80":"Oberon — Adeus, ninfa: antes que ele deixe este bosque,\nFugirás dele e ele buscará o teu amor.","reenterpuck~reenterpuck~11":"Entra de novo Puck.","hastthoutheflowertherewelcomewanderer~owertherewelcomewanderer~37":"Tens aí a flor? Bem-vindo, andarilho.","puckaythereitis~puckaythereitis~15":"Puck — Sim, aqui está.","oberonipraytheegiveitmeiknowabankwhereth~eetmeerethefirstcockcrow~660":"Oberon — Peço-te, dá-ma.\nConheço um barranco onde sopra o tomilho silvestre,\nOnde crescem a prímula e a violeta que se inclina,\nTodo coberto de um dossel de madressilva luxuriante,\nDe rosas almiscaradas e de eglantina:\nAli dorme Titânia por algum tempo da noite,\nEmbalada nessas flores com danças e deleite;\nE ali a cobra solta sua pele esmaltada,\nManto bastante largo para envolver uma fada:\nE com o suco desta erva ungirei seus olhos,\nE a encherei de fantasias odiosas.\nLeva um pouco dele, e busca por este bosque:\nUma doce dama ateniense está apaixonada\nPor um jovem desdenhoso: unge-lhe os olhos;\nMas faze-o de modo que a primeira coisa que ele avistar\nSeja a dama: reconhecerás o homem\nPelas vestes atenienses que traz.\nExecuta isso com algum cuidado, para que ele se mostre\nMais apaixonado por ela do que ela pelo seu amor:\nE cuida de me encontrar antes que o primeiro galo cante.","puckfearnotmylordyourservantshalldosoexe~urservantshalldosoexeunt~43":"Puck — Não temais, meu senhor, vosso servo assim fará. Saem.","anotherpartofthewood~anotherpartofthewood~20":"Outra parte do bosque.","entertitaniawithhertrain~entertitaniawithhertrain~24":"Entra Titânia, com seu séquito.","titaniacomenowaroundelandafairysongthenf~oyourofficesandletmerest~283":"Titânia — Vamos, agora uma ciranda e uma canção de fadas;\nDepois, por um terço de minuto, fora daqui;\nAlgumas a matar lagartas nos botões das rosas almiscaradas,\nOutras a guerrear morcegos por suas asas de couro,\nPara fazer casacos a meus pequenos elfos, e outras a manter afastada\nA coruja clamorosa que pia à noite e se espanta\nCom nossos espíritos graciosos. Cantai agora para me adormecer;\nDepois ide a vossos ofícios e deixai-me repousar.","thefairiessing~thefairiessing~14":"As Fadas cantam.","youspottedsnakeswithdoubletonguethornyhe~ncephilomelwithmelodyetc~374":"Vós, serpentes malhadas de língua dupla,\nOuriços espinhosos, não vos mostreis;\nTritões e cobras-cegas, não façais mal,\nNão vos aproximeis de nossa rainha das fadas.\nRouxinol, com tua melodia\nCanta em nosso doce acalanto;\nLula, lula, lulaby; lula, lula, lulaby:\nNunca dano,\nNem feitiço nem encanto\nChegue perto de nossa bela senhora;\nAssim, boa noite, com acalanto.\nAranhas tecelãs, não venhais aqui;\nFora, fiandeiras de pernas longas, fora!\nBesouros negros, não vos aproximeis;\nVerme nem caracol, não ofendais.\nRouxinol, com tua melodia, etc.","afairyhenceawaynowalliswellonealoofstand~euntfairiestitaniasleeps~74":"Uma Fada — Fora, ide embora! Agora tudo vai bem:\nUma fique de longe como sentinela. Saem as Fadas. Titânia dorme.","enteroberonandsqueezestheflowerontitania~eflowerontitaniaseyelids~48":"Entra Oberon, e espreme a flor sobre as pálpebras de Titânia.","oberonwhatthouseestwhenthoudostwakedoitf~nsomevilethingisnearexit~207":"Oberon — O que vires ao despertar,\nToma-o por teu verdadeiro amor,\nAma e definha por ele:\nSeja onça, ou gato, ou urso,\nLeopardo, ou javali de cerdas eriçadas,\nO que a teus olhos aparecer\nQuando acordares, será teu querido:\nDesperta quando algo vil estiver perto. Sai.","enterlysanderandhermia~enterlysanderandhermia~22":"Entram Lisandro e Hérmia.","lysanderfairloveyoufaintwithwanderingint~rryforthecomfortoftheday~139":"Lisandro — Doce amor, desfaleces de tanto vagar pelo bosque;\nE, a dizer verdade, esqueci o nosso caminho:\nDescansaremos, Hérmia, se achas bom,\nE esperaremos o conforto do dia.","hermiabeitsolysanderfindyououtabedforiup~onthisbankwillrestmyhead~64":"Hérmia — Seja assim, Lisandro: procura um leito;\nPois eu neste barranco repousarei a cabeça.","lysanderoneturfshallserveaspillowforusbo~ebedtwobosomsandonetroth~76":"Lisandro — Um só torrão servirá de travesseiro a ambos;\nUm coração, um leito, dois peitos e uma só fé.","hermianaygoodlysanderformysakemydearlief~theroffyetdonotliesonear~66":"Hérmia — Não, bom Lisandro; por mim, meu querido,\nDeita-te mais longe, não te deites tão perto.","lysanderotakethesensesweetofmyinnocencel~orlyingsohermiaidonotlie~251":"Lisandro — Ó, toma o sentido, doce, da minha inocência!\nO amor entende o sentido na conversa do amor.\nQuero dizer que meu coração ao teu está atado\nDe modo que dele só um coração podemos fazer;\nDois peitos acorrentados por um juramento;\nAssim, dois peitos e uma só fé.\nEntão não me negues leito ao teu lado;\nPois deitando-me assim, Hérmia, não minto.","hermialysanderriddlesveryprettilynowmuch~altertillthysweetlifeend~289":"Hérmia — Lisandro faz adivinhas com muita graça:\nMaldito seja meu modo e meu orgulho,\nSe Hérmia quis dizer que Lisandro mentia.\nMas, gentil amigo, por amor e cortesia\nDeita-te mais longe; em recato humano,\nTal separação como bem se pode dizer\nConvém a um solteiro virtuoso e a uma donzela,\nFica tão distante; e, boa noite, doce amigo:\nQue teu amor nunca mude até o fim de tua doce vida!","lysanderamenamentothatfairprayersayiandt~dsleepgivetheeallhisrest~99":"Lisandro — Amém, amém a essa bela prece, digo eu;\nE que termine a vida quando eu terminar a lealdade!\nAqui está o meu leito: que o sono te dê todo o seu repouso!","hermiawithhalfthatwishthewisherseyesbepr~erseyesbepressdtheysleep~53":"Hérmia — Que a metade desse desejo feche os olhos de quem o faz! Dormem.","enterpuck~enterpuck~9":"Entra Puck.","puckthroughtheforesthaveigonebutathenian~eforimustnowtooberonexit~442":"Puck — Pela floresta andei,\nMas ateniense não encontrei,\nEm cujos olhos eu pudesse provar\nA força desta flor de o amor despertar.\nNoite e silêncio — Quem está aqui?\nVestes de Atenas ele traz:\nÉ este, disse meu mestre,\nQue desprezou a donzela ateniense;\nE aqui a donzela, dormindo profundamente,\nNo chão úmido e sujo.\nPobre alma! Não ousou deitar-se\nPerto deste sem-amor, deste mata-cortesia.\nVilão, sobre teus olhos lanço\nTodo o poder que este encanto possui.\nQuando acordares, que o amor impeça\nO sono de ocupar tua pálpebra:\nAssim desperta quando eu me for;\nPois devo agora ir a Oberon. Sai.","enterdemetriusandhelenarunning~emetriusandhelenarunning~30":"Entram Demétrio e Helena, correndo.","helenastaythoughthoukillmesweetdemetrius~thoukillmesweetdemetrius~40":"Helena — Fica, ainda que me mates, doce Demétrio.","demetriusichargetheehenceanddonothauntme~henceanddonothauntmethus~44":"Demétrio — Ordeno-te, vai embora, e não me assombres assim.","helenaowiltthoudarklingleavemedonotso~oudarklingleavemedonotso~37":"Helena — Oh, vais deixar-me às escuras? Não faças isso.","demetriusstayonthyperilialonewillgoexit~thyperilialonewillgoexit~39":"Demétrio — Fica, por tua conta e risco: irei sozinho. Sai.","helenaoiamoutofbreathinthisfondchasethem~derifyoulivegoodsirawake~477":"Helena — Oh, estou sem fôlego nesta perseguição insensata!\nQuanto mais rogo, menos favor encontro.\nFeliz é Hérmia, onde quer que esteja;\nPois tem olhos abençoados e atraentes.\nComo seus olhos ficaram tão brilhantes? Não de lágrimas salgadas:\nSe fosse assim, os meus são mais lavados que os dela.\nNão, não, sou feia como um urso;\nPois as feras que me encontram fogem de medo:\nPor isso não admira que Demétrio\nFuja de minha presença como de um monstro.\nQue espelho malvado e enganador o meu\nMe fez comparar-me aos olhos esféricos de Hérmia?\nMas quem está aqui? Lisandro! no chão!\nMorto? ou dormindo? Não vejo sangue, nem ferida.\nLisandro, se vives, bom senhor, acorda.","lysanderawakingandrunthroughfireiwillfor~ilenametoperishonmysword~179":"Lisandro — Acordando. E por teu doce amor atravessarei o fogo.\nTransparente Helena! A natureza mostra arte,\nQue através do teu peito me faz ver o teu coração.\nOnde está Demétrio? Oh, como é apropriada a palavra\nQue é aquele nome vil para perecer na minha espada!","helenadonotsaysolysandersaynotsowhatthou~illlovesyouthenbecontent~107":"Helena — Não digas isso, Lisandro; não digas isso.\nQue importa se ele ama a tua Hérmia? Senhor, que importa?\nHérmia ainda assim te ama: portanto contenta-te.","lysandercontentwithhermianoidorepentthet~ritteninlovesrichestbook~396":"Lisandro — Contentar-me com Hérmia! Não; arrependo-me\nDos tediosos minutos que com ela passei.\nNão Hérmia mas Helena eu amo:\nQuem não trocaria um corvo por uma pomba?\nA vontade do homem é regida pela razão;\nE a razão diz que és a donzela mais digna.\nO que cresce não amadurece antes da estação:\nAssim eu, sendo jovem, até agora não amadureci para a razão;\nE tocando agora o ponto do saber humano,\nA razão se torna marechal da minha vontade,\nE me leva aos teus olhos, onde leio\nAs histórias do amor escritas no mais rico livro do amor.","helenawhereforewasitothiskeenmockeryborn~herthereforebeabusedexit~390":"Helena — Para que zombaria tão cruel nasci?\nQuando de tuas mãos mereci este desdém?\nNão basta, não basta, jovem,\nQue eu nunca, não, nem jamais possa\nMerecer um doce olhar de Demétrio,\nSem que tu zombes de minha insuficiência?\nPor minha fé, fazes-me mal, em verdade fazes,\nA cortejar-me com tal desdém.\nMas adeus: forçada, devo confessar\nQue te julguei senhor de mais verdadeira gentileza.\nOh, que uma dama, recusada por um homem,\nDeva por isso ser ultrajada por outro! Sai.","lysandersheseesnothermiahermiasleepthout~elenandtobeherknightexit~329":"Lisandro — Ela não vê Hérmia. Hérmia, dorme aí:\nE nunca mais te aproximes de Lisandro!\nPois como o excesso das coisas mais doces\nTraz ao estômago o mais profundo nojo,\nOu como as heresias que os homens abandonam\nSão odiadas sobretudo por aqueles que enganaram,\nAssim tu, meu excesso e minha heresia,\nSejas odiada por todos, mas por mim acima de todos!\nE todas as minhas forças, dirigi vosso amor e vigor\nPara honrar Helena e ser seu cavaleiro! Sai.","hermiaawakinghelpmelysanderhelpmedothybe~ouillfindimmediatelyexit~402":"Hérmia — Acordando. Ajuda-me, Lisandro, ajuda-me! faze o que puderes\nPara arrancar esta serpente rastejante de meu peito!\nAi de mim, por piedade! que sonho foi esse!\nLisandro, vê como tremo de medo:\nParecia-me que uma serpente devorava meu coração,\nE tu sentado sorrias de sua cruel presa.\nLisandro! como, afastado? Lisandro! senhor!\nComo, fora do alcance da voz? foste? nem som, nem palavra?\nAi de mim, onde estás? fala, se me ouves;\nFala, por todos os amores! Quase desmaio de medo.\nNão? então bem percebo que não estás perto:\nOu a morte ou a ti encontrarei de imediato. Sai.","thewoodtitanialyingasleep~hewoodtitanialyingasleep~25":"O bosque. Titânia deitada, adormecida.","bottomareweallmet~bottomareweallmet~17":"Bottom — Estamos todos reunidos?","quincepatpatandheresamarvellousconvenien~swewilldoitbeforetheduke~166":"Quince — Pontuais, pontuais; e eis aqui um lugar maravilhosamente cômodo para o nosso ensaio. Este gramado será o nosso palco, esta moita de espinheiro o nosso camarim; e faremos tudo em ação, como o faremos diante do duque.","bottompeterquince~bottompeterquince~17":"Bottom — Pedro Quince —","quincewhatsayestthoubullybottom~hatsayestthoubullybottom~31":"Quince — Que dizes, valente Bottom?","bottomtherearethingsinthiscomedyofpyramu~notabidehowansweryouthat~149":"Bottom — Há coisas nesta comédia de Píramo e Tisbe que nunca vão agradar. Primeiro, Píramo tem de puxar da espada para se matar; o que as damas não suportam. Que respondes a isso?","snoutbyrlakinaparlousfear~noutbyrlakinaparlousfear~25":"Snout — Pela Virgem, um medo terrível.","starvelingibelievewemustleavethekillingo~ekillingoutwhenallisdone~55":"Starveling — Creio que, no fim das contas, temos de deixar de fora a matança.","bottomnotawhitihaveadevicetomakeallwellw~thiswillputthemoutoffear~241":"Bottom — Nem um pouco: tenho um expediente para pôr tudo em ordem. Escrevei-me um prólogo; e que o prólogo pareça dizer que não faremos mal algum com as espadas, e que Píramo não é morto de verdade; e, para maior segurança, dizei-lhes que eu, Píramo, não sou Píramo, mas Bottom, o tecelão: isso lhes tirará o medo.","quincewellwewillhavesuchaprologueanditsh~llbewrittenineightandsix~65":"Quince — Bem, teremos tal prólogo; e será escrito em oito e seis.","bottomnomakeittwomoreletitbewrittenineig~bewrittenineightandeight~50":"Bottom — Não, fazei com mais duas; que seja escrito em oito e oito.","snoutwillnottheladiesbeafeardofthelion~eladiesbeafeardofthelion~38":"Snout — As damas não terão medo do leão?","starvelingifearitipromiseyou~velingifearitipromiseyou~28":"Starveling — Eu receio que sim, prometo-vos.","bottommastersyououghttoconsiderwithyours~ivingandweoughttolooktot~171":"Bottom — Mestres, deveis refletir convosco mesmos: trazer — Deus nos guarde! — um leão entre damas é coisa terribilíssima; pois não há ave selvagem mais temível que o vosso leão vivo; e devemos cuidar disso.","snoutthereforeanotherprologuemusttellhei~oguemusttellheisnotalion~49":"Snout — Portanto outro prólogo tem de dizer que ele não é leão.","bottomnayyoumustnamehisnameandhalfhisfac~plainlyheissnugthejoiner~375":"Bottom — Não, tendes de dizer-lhe o nome, e metade do seu rosto deve ser vista através do pescoço do leão: e ele mesmo deve falar por ali, dizendo assim, ou com o mesmo efeito — “Damas” —, ou “Belas damas — eu desejaria que” —, ou “eu vos pediria” —, ou “eu vos rogaria — que não temêsseis, que não tremêsseis: minha vida pela vossa. Se pensais que venho aqui como leão, seria pena da minha vida: não, não sou tal coisa; sou um homem como os outros homens são”; e aí, sim, que diga o seu nome, e lhes diga claramente que é Snug, o marceneiro.","quincewellitshallbesobutthereistwohardth~andthisbymeetbymoonlight~122":"Quince — Bem, assim será. Mas há duas coisas difíceis: a saber, trazer o luar para dentro de uma sala; pois, sabeis, Píramo e Tisbe se encontram ao luar.","snugdoththemoonshinethatnightweplayourpl~nethatnightweplayourplay~42":"Snug — A lua brilha na noite em que representamos a nossa peça?","bottomacalendaracalendarlookinthealmanac~oonshinefindoutmoonshine~72":"Bottom — Um calendário, um calendário! olhai no almanaque; descobri o luar, descobri o luar.","quinceyesitdothshinethatnight~eyesitdothshinethatnight~29":"Quince — Sim, ela brilha nessa noite.","bottomwhythenmayyouleaveacasementofthegr~nmayshineinatthecasement~104":"Bottom — Ora, então podeis deixar aberta uma janela do grande salão onde representamos, e a lua poderá brilhar por essa janela.","quinceayorelseonemustcomeinwithabushofth~lkthroughthechinkofawall~225":"Quince — Sim; ou então alguém tem de entrar com um feixe de espinhos e uma lanterna, e dizer que vem para desfigurar, ou representar, a pessoa do Luar. Depois, há outra coisa: precisamos de um muro no grande salão; pois Píramo e Tisbe, diz a história, falavam através da fresta de um muro.","snugyoucanneverbringinawallwhatsayyoubot~ginawallwhatsayyoubottom~43":"Snug — Nunca conseguireis trazer um muro. Que dizes, Bottom?","bottomsomemanorothermustpresentwallandle~lpyramusandthisbywhisper~180":"Bottom — Algum homem ou outro tem de representar o Muro: e que tenha um pouco de gesso, ou de barro, ou de reboco sobre si, para significar muro; e que mantenha os dedos assim, e por essa fresta Píramo e Tisbe cochicharão.","quinceifthatmaybethenalliswellcomesitdow~veryoneaccordingtohiscue~166":"Quince — Se isso for possível, então tudo está bem. Vamos, sentai-vos, filhos de mães, e ensaiai vossos papéis. Píramo, tu começas: quando tiveres dito tua fala, entra naquela moita: e assim cada um segundo a sua deixa.","enterpuckbehind~enterpuckbehind~15":"Entra Puck, por trás.","puckwhathempenhomespunshaveweswaggeringh~tortooperhapsifiseecause~130":"Puck — Que caipiras de pano de cânhamo temos aqui, pavoneando-se\nTão perto do berço da rainha das fadas?\nComo, uma peça em preparo! Serei espectador;\nE ator também, talvez, se achar motivo.","quincespeakpyramusthisbystandforth~kpyramusthisbystandforth~34":"Quince — Fala, Píramo. Tisbe, adianta-te.","bottomthisbytheflowersofodioussavoursswe~wersofodioussavourssweet~42":"Bottom — Tisbe, as flores de odiosos sabores doces —","quinceodoursodours~quinceodoursodours~18":"Quince — Odores, odores.","bottomodourssavourssweetsohaththybreathm~dbyiwilltotheeappearexit~123":"Bottom — — odores sabores doces:\nAssim o teu hálito, minha queridíssima Tisbe.\nMas ouve, uma voz! fica aqui só um instante,\nE já já a ti aparecerei. Sai.","puckastrangerpyramusthaneerplayedhereexi~musthaneerplayedhereexit~41":"Puck — Um Píramo mais estranho que nunca aqui se viu. Sai.","flutemustispeaknow~flutemustispeaknow~18":"Flute — Devo falar agora?","quinceaymarrymustyouforyoumustunderstand~theheardandistocomeagain~87":"Quince — Sim, por certo, deves; pois deves entender que ele só vai ver um barulho que ouviu, e há de voltar.","flutemostradiantpyramusmostlilywhiteofhu~ttheepyramusatninnystomb~186":"Flute — Radiantíssimo Píramo, de tez branquíssima como o lírio,\nDe cor como a rosa rubra sobre o triunfante espinheiro,\nVivacíssimo juvenil e também amabilíssimo Judeu,\nFiel como o mais fiel cavalo que jamais se cansaria,\nEncontrar-te-ei, Píramo, no túmulo de Ninho.","quinceninustombmanwhyyoumustnotspeakthat~urcueispastitisnevertire~138":"Quince — “Túmulo de Nino”, homem: ora, não deves falar isso ainda; isso é o que respondes a Píramo: dizes todo o teu papel de uma vez, deixas e tudo. Píramo, entra: tua deixa já passou; é “se cansaria”.","fluteoastrueastruesthorsethatyetwouldnev~rsethatyetwouldnevertire~46":"Flute — Ó — Fiel como o mais fiel cavalo, que jamais se cansaria.","reenterpuckandbottomwithanassshead~kandbottomwithanassshead~34":"Entram de novo Puck, e Bottom com uma cabeça de burro.","bottomifiwerefairthisbyiwereonlythine~fairthisbyiwereonlythine~37":"Bottom — Se eu fosse belo, Tisbe, seria só teu.","quinceomonstrousostrangewearehauntedpray~gflutesnoutandstarveling~100":"Quince — Ó monstruoso! Ó estranho! estamos assombrados. Rezai, mestres! fugi, mestres! Socorro! Saem Quince, Snug, Flute, Snout e Starveling.","puckillfollowyouillleadyouaboutaroundthr~gbearfireateveryturnexit~222":"Puck — Seguir-vos-ei, far-vos-ei dar voltas,\nPor pântano, por mato, por moita, por espinheiro:\nÀs vezes serei cavalo, às vezes cão de caça,\nPorco, urso sem cabeça, às vezes fogo;\nE relincharei, e latirei, e grunhirei, e rugirei, e arderei,\nComo cavalo, cão, porco, urso, fogo, a cada volta. Sai.","bottomwhydotheyrunawaythisisaknaveryofth~veryofthemtomakemeafeard~56":"Bottom — Por que fogem? isto é uma patifaria deles para me assustar.","reentersnout~reentersnout~12":"Entra de novo Snout.","snoutobottomthouartchangedwhatdoiseeonth~tchangedwhatdoiseeonthee~42":"Snout — Ó Bottom, estás transformado! que vejo sobre ti?","bottomwhatdoyouseeyouseeanassheadofyouro~dofyourowndoyouexitsnout~56":"Bottom — Que vês? vês uma cabeça de burro só tua, não é? Sai Snout.","reenterquince~reenterquince~13":"Entra de novo Quince.","quinceblesstheebottomblesstheethouarttra~heethouarttranslatedexit~51":"Quince — Deus te abençoe, Bottom! te abençoe! estás traduzido. Sai.","bottomiseetheirknaverythisistomakeanasso~uethewrenwithlittlequill~266":"Bottom — Vejo a patifaria deles: isto é para fazer de mim um burro; para me assustar, se pudessem. Mas não sairei deste lugar, façam o que fizerem: andarei de um lado para o outro e cantarei, para que ouçam que não tenho medo. Canta. O melro de plumagem tão negra,\nDe bico laranja-fulvo,\nO tordo de canto tão verdadeiro,\nO carriça de pequena pena —","titaniaawakingwhatangelwakesmefrommyflow~lwakesmefrommyflowerybed~46":"Titânia — Despertando. Que anjo me acorda do meu leito de flores?","bottomsingsthefinchthesparrowandthelarkt~thoughhecrycuckooneverso~199":"Bottom — Canta. O tentilhão, o pardal e a cotovia,\nO cuco cinzento de cantochão,\nCujo canto tantos homens notam,\nE não ousam responder que não; — pois, na verdade, quem poria seu engenho numa ave tão tola? quem desmentiria uma ave, por mais que ela grite “cuco”?","titaniaipraytheegentlemortalsingagainmin~iewtosaytoswearilovethee~173":"Titânia — Rogo-te, gentil mortal, canta de novo:\nMeu ouvido está muito enamorado de teu canto;\nAssim meu olho está cativo de tua forma;\nE a força de tua bela virtude me move à força,\nÀ primeira vista, a dizer, a jurar: eu te amo.","bottommethinksmistressyoushouldhavelittl~nayicangleekuponoccasion~203":"Bottom — Parece-me, senhora, que tendes pouca razão para isso: e no entanto, a dizer a verdade, razão e amor andam hoje em dia em pouca companhia; e é pena que alguns bons vizinhos não os façam amigos. Não, sei também gracejar quando é ocasião.","titaniathouartaswiseasthouartbeautiful~aswiseasthouartbeautiful~38":"Titânia — És tão sábio quanto és belo.","bottomnotsoneitherbutifihadwitenoughtoge~enoughtoservemineownturn~83":"Bottom — Nem tanto, tampouco: mas se eu tivesse juízo bastante para sair deste bosque, já teria o suficiente para meu próprio proveito.","titaniaoutofthiswooddonotdesiretogothous~cobwebmothandmustardseed~372":"Titânia — Não desejes sair deste bosque:\nFicarás aqui, queiras ou não queiras.\nSou um espírito de nada vulgar condição:\nO verão ainda assiste à minha corte;\nE eu te amo: portanto, vem comigo;\nDar-te-ei fadas que te sirvam;\nE elas te trarão joias do fundo do mar,\nE cantarão enquanto dormes sobre flores prensadas:\nE purgarei de tal modo tua grosseria mortal\nQue irás como um espírito aéreo.\nFlor-de-Ervilha! Teia-de-Aranha! Traça! e Semente-de-Mostarda!","enterpeaseblossomcobwebmothandmustardsee~cobwebmothandmustardseed~41":"Entram Flor-de-Ervilha, Teia-de-Aranha, Traça e Semente-de-Mostarda.","peaseblossomready~peaseblossomready~17":"Flor-de-Ervilha — Pronto.","cobwebandi~cobwebandi~10":"Teia-de-Aranha — E eu.","mothandi~mothandi~8":"Traça — E eu.","mustardseedandi~mustardseedandi~15":"Semente-de-Mostarda — E eu.","allwhereshallwego~allwhereshallwego~17":"Todos — Aonde iremos?","titaniabekindandcourteoustothisgentleman~melvesanddohimcourtesies~380":"Titânia — Sede bondosos e corteses com este cavalheiro;\nSaltai em seus passeios e brincai diante de seus olhos;\nAlimentai-o com damascos e amoras-silvestres,\nCom uvas roxas, figos verdes e amoras;\nRoubai o mel dos sacos dos zangões,\nE para velas da noite colhei-lhes as coxas de cera\nE acendei-as nos olhos do ardente vaga-lume,\nPara levar meu amor ao leito e levantá-lo;\nE arrancai as asas das borboletas pintadas\nPara abanar os raios da lua de seus olhos adormecidos:\nInclinai-vos diante dele, elfos, e fazei-lhe reverências.","peaseblossomhailmortal~peaseblossomhailmortal~22":"Flor-de-Ervilha — Salve, mortal!","cobwebhail~cobwebhail~10":"Teia-de-Aranha — Salve!","mothhail~mothhail~8":"Traça — Salve!","mustardseedhail~mustardseedhail~15":"Semente-de-Mostarda — Salve!","bottomicryyourworshipsmercyheartilyibese~ibeseechyourworshipsname~59":"Bottom — Peço mil perdões a vossas senhorias, de coração: rogo-vos o nome de vossa senhoria.","cobwebcobweb~cobwebcobweb~12":"Teia-de-Aranha — Teia-de-Aranha.","bottomishalldesireyouofmoreacquaintanceg~uyournamehonestgentleman~113":"Bottom — Desejarei de vós mais conhecimento, bom Mestre Teia-de-Aranha: se eu cortar o dedo, tomarei a liberdade convosco. Vosso nome, honrado cavalheiro?","peaseblossompeaseblossom~peaseblossompeaseblossom~24":"Flor-de-Ervilha — Flor-de-Ervilha.","bottomiprayyoucommendmetomistresssquashy~ooyournameibeseechyousir~157":"Bottom — Rogo-vos, recomendai-me à Senhora Abóbora, vossa mãe, e ao Mestre Vagem, vosso pai. Bom Mestre Flor-de-Ervilha, desejarei de vós mais conhecimento também. Vosso nome, suplico-vos, senhor?","mustardseedmustardseed~mustardseedmustardseed~22":"Semente-de-Mostarda — Semente-de-Mostarda.","bottomgoodmastermustardseediknowyourpati~ncegoodmastermustardseed~212":"Bottom — Bom Mestre Semente-de-Mostarda, conheço bem a vossa paciência: aquele mesmo covarde e gigantesco rosbife devorou muitos cavalheiros de vossa casa: prometo-vos que vossa parentela já me fez chorar os olhos antes disto. Desejo de vós mais conhecimento, bom Mestre Semente-de-Mostarda.","titaniacomewaituponhimleadhimtomybowerth~uebringhimsilentlyexeunt~178":"Titânia — Vamos, servi-o; levai-o ao meu caramanchão.\nA lua, parece-me, olha com olho lacrimoso;\nE quando ela chora, chora cada florzinha,\nLamentando alguma castidade forçada.\nAmarrai a língua de meu amor, levai-o em silêncio. Saem.","enteroberon~enteroberon~11":"Entra Oberon.","oberoniwonderiftitaniabeawakedthenwhatit~shemustdoteoninextremity~92":"Oberon — Pergunto-me se Titânia já despertou;\nE o que foi a primeira coisa que lhe veio aos olhos,\nPor que ela deve enlouquecer de amor ao extremo.","herecomesmymessengerhownowmadspiritwhatn~nowaboutthishauntedgrove~72":"Aí vem meu mensageiro.\nEntão, espírito louco!\nQue travessura noturna houve neste bosque assombrado?","puckmymistresswithamonsterisinlovenearto~andstraightwaylovedanass~968":"Puck — Minha senhora está apaixonada por um monstro.\nPerto de seu retiro fechado e consagrado,\nEnquanto ela estava em sua hora pesada de sono,\nUm bando de remendões, rudes artesãos,\nQue trabalham por pão nas bancas de Atenas,\nReuniu-se para ensaiar uma peça\nDestinada ao dia das núpcias do grande Teseu.\nO mais obtuso paquiderme daquele estéril bando,\nQue representava Píramo em seu folguedo,\nDeixou sua cena e entrou numa moita:\nQuando o apanhei nessa ocasião,\nFixei-lhe na cabeça uma cabeça de burro:\nLogo sua Tisbe devia ser respondida,\nE lá sai o meu comediante. Quando o avistam,\nComo gansos selvagens que o caçador rastejante enxergam,\nOu gralhas de cabeça ruiva, muitas em bando,\nQue se erguem grasnando ao estampido da arma,\nSe separam e varrem o céu loucamente,\nAssim, à vista dele, os companheiros fogem;\nE, a um pisar nosso, aqui um tomba por sobre outro;\nGrita assassino e chama socorro de Atenas.\nSeu juízo assim fraco, perdido em seus medos assim fortes,\nFez que coisas sem sentido começassem a lhes fazer mal;\nPois sarças e espinhos lhes agarram as roupas;\nUma manga, um chapéu: de quem cede tudo se apanha.\nGuiei-os neste medo desvairado,\nE deixei o doce Píramo traduzido ali:\nQuando nesse momento, assim aconteceu,\nTitânia despertou e logo amou um burro.","oberonthisfallsoutbetterthanicoulddevise~lovejuiceasididbidtheedo~107":"Oberon — Isto sai melhor do que eu poderia imaginar.\nMas já prendeste os olhos do ateniense\nCom o suco do amor, como te mandei fazer?","puckitookhimsleepingthatisfinishdtooandt~akedofforceshemustbeeyed~99":"Puck — Tomei-o dormindo — isso também está feito —\nE a mulher ateniense a seu lado;\nDe modo que, quando ele acordasse, por força a veria.","enterhermiaanddemetrius~enterhermiaanddemetrius~23":"Entram Hérmia e Demétrio.","oberonstandclosethisisthesameathenian~osethisisthesameathenian~37":"Oberon — Fica perto: este é o mesmo ateniense.","puckthisisthewomanbutnotthistheman~thewomanbutnotthistheman~34":"Puck — Esta é a mulher, mas este não é o homem.","demetriusowhyrebukeyouhimthatlovesyousol~hsobitteronyourbitterfoe~71":"Demétrio — Oh, por que repreendes quem tanto te ama?\nDeita palavras tão amargas sobre teu amargo inimigo.","hermianowibutchidebutishouldusetheeworse~murdererlooksodeadsogrim~421":"Hérmia — Por ora apenas repreendo; mas devia tratar-te pior,\nPois tu, receio, me deste motivo de maldição.\nSe mataste Lisandro enquanto dormia,\nJá estando afundado em sangue até os sapatos, mergulha no fundo,\nE mata-me também.\nO sol não foi tão fiel ao dia\nQuanto ele a mim: teria ele fugido\nDe Hérmia adormecida? Mais depressa creria\nQue toda esta terra pode ser furada e que a lua\nPode rastejar pelo centro e assim desagradar\nAo meio-dia do irmão dela entre os Antípodas.\nNão pode ser senão que o assassinaste;\nAssim deve parecer um assassino, tão morto, tão sombrio.","demetriussoshouldthemurderdlookandsoshou~nusinherglimmeringsphere~155":"Demétrio — Assim deve parecer o assassinado, e assim eu,\nTraspassado no coração pela tua severa crueldade:\nContudo tu, a assassina, pareces tão luminosa, tão clara,\nComo aquela Vênus ali em sua esfera cintilante.","hermiawhatsthistomylysanderwhereisheahgo~metriuswiltthougivehimme~68":"Hérmia — Que tem isso a ver com meu Lisandro? onde está ele?\nAh, bom Demétrio, queres devolvê-lo a mim?","demetriusihadrathergivehiscarcasstomyhou~givehiscarcasstomyhounds~43":"Demétrio — Prefiro dar o seu cadáver aos meus cães.","hermiaoutdogoutcurthoudrivestmepastthebo~ouserpentneveradderstung~315":"Hérmia — Fora, cão! fora, vira-lata! levas-me além dos limites\nDa paciência de uma donzela. Mataste-o, então?\nDe agora em diante nunca sejas contado entre os homens!\nOh, uma vez diz a verdade, diz a verdade, ao menos por mim!\nTiveste coragem de olhá-lo acordado,\nE o mataste dormindo? Oh, belo golpe!\nNão poderia um verme, uma víbora, fazer tanto?\nFoi uma víbora; pois com língua mais dupla\nQue a tua, serpente, nunca víbora picou.","demetriusyouspendyourpassiononamisprised~deadforaughtthaticantell~103":"Demétrio — Gastas tua paixão num humor equivocado:\nNão sou culpado do sangue de Lisandro;\nNem ele está morto, até onde posso saber.","hermiaipraytheetellmethenthatheiswell~eetellmethenthatheiswell~37":"Hérmia — Peço-te, diz-me então que ele está bem.","demetriusandificouldwhatshouldigettheref~dwhatshouldigettherefore~43":"Demétrio — E se eu pudesse, que ganharia por isso?","hermiaaprivilegenevertoseememoreandfromt~ewhetherhebedeadornoexit~96":"Hérmia — O privilégio de nunca mais me ver.\nE de tua odiada presença assim me aparto:\nNão me vejas mais, esteja ele morto ou não. Sai.","demetriusthereisnofollowingherinthisfier~omestayliesdownandsleeps~233":"Demétrio — Não há como segui-la neste humor feroz:\nAqui, portanto, por um tempo ficarei.\nAssim o peso da tristeza mais pesado se torna\nPela dívida que o sono falido deve à tristeza;\nA qual agora em alguma pequena medida ele pagará,\nSe aqui eu fizer alguma pausa para oferecer-lhe o pagamento. Deita-se e dorme.","oberonwhathastthoudonethouhastmistakenqu~rndandnotafalseturndtrue~152":"Oberon — Que fizeste? enganaste-te por completo\nE puseste o suco do amor nos olhos de algum amor verdadeiro:\nDo teu erro deve por força resultar\nUm amor verdadeiro virado, e não um falso virado verdadeiro.","puckthenfateoerrulesthatonemanholdingtro~ailconfoundingoathonoath~75":"Puck — Então o destino domina, que, mantendo um homem a fé,\nUm milhão a falte, confundindo juramento sobre juramento.","oberonaboutthewoodgoswifterthanthewindan~iseyesagainstshedoappear~205":"Oberon — Percorre o bosque mais veloz que o vento,\nE procura Helena de Atenas:\nEstá toda doente de paixão e pálida de semblante,\nCom suspiros de amor, que custam caro ao sangue fresco:\nPor alguma ilusão trata de trazê-la aqui:\nEncantarei os olhos dele para quando ela aparecer.","puckigoigolookhowigoswifterthanarrowfrom~rowfromthetartarsbowexit~57":"Puck — Vou, vou; vê como vou,\nMais veloz que flecha do arco do tártaro. Sai.","oberonflowerofthispurpledyehitwithcupids~shebebybegofherforremedy~168":"Oberon — Flor desta cor púrpura,\nAtingida pelo arco de Cupido,\nAfunda na menina de seus olhos.\nQuando ele avistar seu amor,\nQue ela brilhe tão gloriosa\nQuanto a Vênus do céu.\nQuando acordares, se ela estiver perto,\nPede-lhe remédio.","puckcaptainofourfairybandhelenaishereath~dwhatfoolsthesemortalsbe~139":"Puck — Capitão de nosso bando de fadas,\nHelena está aqui à mão;\nE o jovem, enganado por mim,\nImplorando o prêmio de amante.\nVeremos seu tolo espetáculo?\nSenhor, que tolos são esses mortais!","oberonstandasidethenoisetheymakewillcaus~illcausedemetriustoawake~57":"Oberon — Afasta-te: o ruído que fazem\nFará Demétrio despertar.","puckthenwilltwoatoncewooonethatmustneeds~thatbefallpreposterously~104":"Puck — Então dois a um só cortejarão;\nIsso há de ser divertido por si só;\nE as coisas que mais me agradam\nSão as que acontecem às avessas.","enterlysanderandhelena~enterlysanderandhelena~22":"Entram Lisandro e Helena.","lysanderwhyshouldyouthinkthatishouldwooi~geoffaithtoprovethemtrue~210":"Lisandro — Por que pensas que eu cortejaria por escárnio?\nEscárnio e zombaria nunca vêm em lágrimas:\nVê, quando juro, choro; e votos assim nascidos,\nEm seu nascimento mostram toda a verdade.\nComo podem estas coisas em mim parecer-te escárnio,\nTrazendo o emblema da fé, que as prova verdadeiras?","helenayoudoadvanceyourcunningmoreandmore~ighandbothaslightastales~217":"Helena — Aumentas cada vez mais a tua astúcia.\nQuando a verdade mata a verdade, ó combate diabólico-santo!\nEsses votos são de Hérmia: vais abandoná-la?\nPesa juramento com juramento, e nada pesarás:\nTeus votos a ela e a mim, postos em duas balanças,\nPesarão igual, e ambos leves como contos.","lysanderihadnojudgmentwhentoheriswore~ojudgmentwhentoheriswore~37":"Lisandro — Não tinha juízo quando a ela jurei.","helenanornoneinmymindnowyougiveheroer~inmymindnowyougiveheroer~37":"Helena — Nem tens, a meu ver, agora que a abandonas.","lysanderdemetriuslovesherandhelovesnotyo~lovesherandhelovesnotyou~41":"Lisandro — Demétrio a ama, e não ama a ti.","demetriusawakingohelengoddessnymphperfec~purewhitethissealofbliss~290":"Demétrio — Despertando. Ó Helena, deusa, ninfa, perfeita, divina!\nA que, meu amor, compararei teus olhos?\nO cristal é turvo. Oh, como maduros na aparência\nTeus lábios, aquelas cerejas de beijar, tentadores crescem!\nAquele branco puro e congelado, neve do alto Touro,\nAbanado pelo vento do leste, vira corvo\nQuando ergues a mão: oh, deixa-me beijar\nEsta princesa de puro branco, este selo de ventura!","helenaospiteohelliseeyouallarebenttoseta~atiencealltomakeyousport~517":"Helena — Oh, despeito! Oh, inferno! Vejo que todos estais empenhados\nEm vos pôr contra mim para vosso divertimento:\nSe fôsseis civilizados e soubésseis cortesia,\nNão me farias tamanha injúria.\nNão podeis odiar-me, como sei que odiais,\nSem que unais as almas para zombar de mim também?\nSe fôsseis homens, como homens sois na aparência,\nNão tratarias assim uma dama gentil;\nJurar, e prometer, e sobrelouvar meus dotes,\nQuando estou certa de que me odiais de coração.\nSois ambos rivais, e amais Hérmia;\nE agora ambos rivais, para zombar de Helena:\nUma bela proeza, uma empresa varonil,\nConjurar lágrimas aos olhos de uma pobre donzela\nCom vossa zombaria! ninguém de nobre estirpe\nOfenderia assim uma virgem e extorquiria\nA paciência de uma pobre alma, tudo para vos divertir.","lysanderyouareunkinddemetriusbenotsofory~loveandwilldotillmydeath~193":"Lisandro — És cruel, Demétrio; não sejas assim;\nPois amas Hérmia; isto sabes que eu sei:\nE aqui, com toda a boa vontade, com todo o coração,\nNo amor de Hérmia cedo-te a minha parte;\nE lega-me a tua de Helena,\nA quem amo e amarei até a minha morte.","helenaneverdidmockerswastemoreidlebreath~ckerswastemoreidlebreath~40":"Helena — Nunca zombadores gastaram fôlego mais vão.","demetriuslysanderkeepthyhermiaiwillnonei~homereturndtheretoremain~145":"Demétrio — Lisandro, guarda a tua Hérmia; não a quero:\nSe alguma vez a amei, todo esse amor se foi.\nMeu coração com ela apenas como hóspede se demorou,\nE agora a Helena voltou para casa,\nPara ali ficar.","lysanderhelenitisnotso~lysanderhelenitisnotso~22":"Lisandro — Helena, não é assim.","demetriusdisparagenotthefaiththoudostnot~lovecomesyonderisthydear~107":"Demétrio — Não desprezes a fé que não conheces,\nPara que, por teu perigo, não a pagues caro.\nVê, ali vem teu amor; lá está tua querida.","reenterhermia~reenterhermia~13":"Entra de novo Hérmia.","hermiadarknightthatfromtheeyehisfunction~kindlydidstthouleavemeso~242":"Hérmia — Noite escura, que ao olho tira a sua função,\nO ouvido mais ágil de percepção torna;\nNo que prejudica o sentido da vista,\nPaga ao ouvido recompensa em dobro.\nNão foste achado por meu olho, Lisandro;\nMeu ouvido, agradeço-lhe, levou-me ao teu som.\nMas por que cruelmente me deixaste assim?","lysanderwhyshouldhestaywhomlovedothpress~taywhomlovedothpresstogo~44":"Lisandro — Por que ficaria aquele a quem o amor impele a partir?","hermiawhatlovecouldpresslysanderfrommysi~dpresslysanderfrommyside~42":"Hérmia — Que amor poderia impelir Lisandro do meu lado?","lysanderlysanderslovethatwouldnotlethimb~aretheemademeleavetheeso~179":"Lisandro — O amor de Lisandro, que não o deixava ficar,\nA bela Helena, que mais doura a noite\nQue todos aqueles círculos de fogo e olhos de luz.\nPor que me procuras? Não poderia isto fazer-te saber\nQue o ódio que te tinha me fez deixar-te assim?","hermiayouspeaknotasyouthinkitcannotbe~knotasyouthinkitcannotbe~37":"Hérmia — Não falas como pensas: não pode ser.","helenalosheisoneofthisconfederacynowiper~ughialonedofeeltheinjury~920":"Helena — Vê, ela é uma desta conspiração!\nAgora percebo que se uniram os três\nPara forjar este falso folguedo, para me afrontar.\nHérmia injuriosa! donzela ingratíssima!\nConspiraste, tramaste com estes\nPara me atormentar com esta vil zombaria?\nÉ todo o conselho que nós duas partilhamos,\nOs votos de irmãs, as horas que passamos,\nQuando repreendemos o tempo de pés apressados\nPor nos separar — oh, está tudo esquecido?\nA amizade dos dias de escola, a inocência da infância?\nNós, Hérmia, como dois deuses artífices,\nCriamos com as agulhas uma só flor,\nAmbas num só bastidor, sentadas numa só almofada,\nAmbas gorjeando uma só canção, ambas na mesma tonalidade,\nComo se nossas mãos, flancos, vozes e mentes\nTivessem sido incorporados. Assim crescemos juntas,\nComo uma cereja dupla, que parece separada,\nMas é contudo uma união na partição;\nDuas belas bagas moldadas num só caule;\nAssim, com dois corpos aparentes, mas um só coração;\nDuas das primeiras, como brasões na heráldica,\nDevidos a um só e coroados por um só timbre.\nE queres rasgar nosso antigo amor,\nPara juntar-te aos homens em desprezo à tua pobre amiga?\nNão é de amiga, não é de donzela:\nNosso sexo, tanto quanto eu, pode repreender-te por isso,\nEmbora só eu sinta a injúria.","hermiaiamamazedatyourpassionatewordsisco~notitseemsthatyouscornme~69":"Hérmia — Estou pasmada com tuas palavras apaixonadas.\nEu não te desprezo: parece que tu me desprezas.","helenahaveyounotsetlysanderasinscorntofo~uldpityratherthandespise~450":"Helena — Não puseste Lisandro, como por escárnio,\nA seguir-me e louvar meus olhos e meu rosto?\nE não fizeste teu outro amor, Demétrio,\nQue ainda agora me repelia com o pé,\nChamar-me deusa, ninfa, divina e rara,\nPreciosa, celestial? Por que diz isso\nA quem odeia? e por que Lisandro\nNega o teu amor, tão rico em sua alma,\nE me oferece, em verdade, afeição,\nSenão por tua instigação, por teu consentimento?\nQue importa que eu não seja tão agraciada quanto tu,\nTão cumulada de amor, tão afortunada,\nMas miserabilíssima, a amar sem ser amada?\nIsto deverias antes lastimar que desprezar.","hermiaiunderstandnotwhatyoumeanbythis~tandnotwhatyoumeanbythis~37":"Hérmia — Não compreendo o que queres dizer com isso.","helenaaydopersevercounterfeitsadlooksmak~orabsencesoonshallremedy~265":"Helena — Sim, persevera, finge olhares tristes,\nFaze caretas para mim quando eu virar as costas;\nPiscai um para o outro; mantende viva a doce brincadeira:\nEste folguedo, bem levado, será registrado em crônica.\nSe tivésseis alguma piedade, graça ou boas maneiras,\nNão faríeis de mim tal assunto.\nMas adeus: é em parte minha própria culpa;\nA qual a morte ou a ausência logo remediarão.","lysanderstaygentlehelenahearmyexcusemylo~vemylifemysoulfairhelena~64":"Lisandro — Fica, gentil Helena; ouve minha desculpa:\nMeu amor, minha vida, minha alma, bela Helena!","helenaoexcellent~helenaoexcellent~16":"Helena — Oh, excelente!","hermiasweetdonotscornherso~rmiasweetdonotscornherso~26":"Hérmia — Doce, não a desprezes assim.","demetriusifshecannotentreaticancompel~ecannotentreaticancompel~37":"Demétrio — Se ela não pode suplicar, eu posso obrigar.","lysanderthoucanstcompelnomorethansheentr~alsethatsaysilovetheenot~182":"Lisandro — Não podes obrigar mais do que ela suplica:\nTuas ameaças não têm mais força que suas fracas preces.\nHelena, eu te amo; por minha vida, amo:\nJuro por aquilo que perderei por ti,\nPara provar falso quem diz que não te amo.","demetriusisayilovetheemorethanhecando~ilovetheemorethanhecando~37":"Demétrio — Digo que te amo mais do que ele pode amar.","lysanderifthousaysowithdrawandproveittoo~ysowithdrawandproveittoo~40":"Lisandro — Se o dizes, afasta-te, e prova-o também.","demetriusquickcome~demetriusquickcome~18":"Demétrio — Depressa, vem!","hermialysanderwheretotendsallthis~anderwheretotendsallthis~33":"Hérmia — Lisandro, aonde tende tudo isto?","lysanderawayyouethiope~lysanderawayyouethiope~22":"Lisandro — Afasta-te, etíope!","demetriusnonohellseemtobreakloosetakeona~tcomenotyouareatamemango~84":"Demétrio — Não, não; ele\nFingirá soltar-se; faz como se quisesses seguir,\nMas não venhas: és um homem manso, vai!","lysanderhangoffthoucatthouburrvilethingl~ketheefrommelikeaserpent~81":"Lisandro — Solta-te, gata, carrapicho! coisa vil, larga,\nOu te sacudirei de mim como a uma serpente!","hermiawhyareyougrownsorudewhatchangeisth~hatchangeisthissweetlove~51":"Hérmia — Por que te tornaste tão rude? que mudança é esta,\nDoce amor —","lysanderthyloveouttawnytartaroutoutloath~medicinehatedpotionhence~66":"Lisandro — Teu amor! fora, tártara morena, fora!\nFora, remédio detestável! poção odiada, some!","hermiadoyounotjest~hermiadoyounotjest~18":"Hérmia — Não estás brincando?","helenayessoothandsodoyou~helenayessoothandsodoyou~24":"Helena — Sim, na verdade; e tu também.","lysanderdemetriusiwillkeepmywordwiththee~siwillkeepmywordwiththee~40":"Lisandro — Demétrio, manterei minha palavra contigo.","demetriusiwouldihadyourbondforiperceivea~dsyouillnottrustyourword~75":"Demétrio — Quisera ter o teu compromisso, pois percebo\nQue um fraco laço te prende: não confiarei em tua palavra.","lysanderwhatshouldihurtherstrikeherkillh~hihateherillnotharmherso~77":"Lisandro — Como, devo feri-la, golpeá-la, matá-la?\nEmbora a odeie, não lhe farei tal mal.","hermiawhatcanyoudomegreaterharmthanhateh~forbidinearnestshallisay~216":"Hérmia — Como, podes fazer-me mal maior que o ódio?\nOdiar-me! por quê? Ai de mim! que novidade, meu amor!\nNão sou eu Hérmia? não és tu Lisandro?\nSou agora tão bela quanto era há pouco.\nÀ noite me amavas; contudo à noite me deixaste:\nPor que então me deixaste — oh, os deuses não o permitam! —\nSério, devo dizer?","lysanderaybymylifeandneverdiddesiretosee~idohatetheeandlovehelena~143":"Lisandro — Sim, por minha vida;\nE nunca desejei ver-te mais.\nPortanto fica sem esperança, sem pergunta, sem dúvida;\nTem certeza, nada mais verdadeiro; não é brincadeira\nQue te odeio e amo Helena.","hermiaomeyoujuggleryoucankerblossomyouth~tolenmylovesheartfromhim~99":"Hérmia — Ai de mim! trapaceira! lagarta da flor!\nLadra do amor! como, vieste de noite\nE roubaste dele o coração do meu amor?","helenafineifaithhaveyounomodestynomaiden~ucounterfeityoupuppetyou~146":"Helena — Muito bem, por minha fé!\nNão tens recato, nem pudor de donzela,\nNem um toque de vergonha? Como, queres arrancar\nRespostas impacientes da minha língua gentil?\nVergonha, vergonha! tu, fingida, tu, fantoche!","hermiapuppetwhysoaythatwaygoesthegamenow~ilscanreachuntothineeyes~333":"Hérmia — Fantoche! por quê? sim, é por aí que corre o jogo.\nAgora percebo que ela fez comparação\nEntre nossas estaturas; ela usou sua altura;\nE com sua figura, sua figura alta,\nSua altura, em verdade, prevaleceu sobre ele.\nE ficaste tão alta em sua estima,\nPorque sou tão anã e tão baixa?\nQuão baixa sou, tu, mastro de maio pintado? fala;\nQuão baixa sou? Ainda não sou tão baixa\nQue minhas unhas não alcancem teus olhos.","helenaiprayyouthoughyoumockmegentlemenle~anmyselfthaticanmatchher~211":"Helena — Peço-vos, ainda que zombeis de mim, cavalheiros,\nNão deixeis que ela me machuque: nunca fui brigona;\nNão tenho dom algum para a rabugice;\nSou verdadeira donzela em minha covardia:\nNão deixeis que ela me bata. Talvez penseis,\nPorque ela é um pouco mais baixa que eu,\nQue posso me medir com ela.","hermialowerharkagain~hermialowerharkagain~20":"Hérmia — Mais baixa! ouvi, de novo.","helenagoodhermiadonotbesobitterwithmeiev~eehowsimpleandhowfondiam~365":"Helena — Boa Hérmia, não sejas tão amarga comigo.\nSempre te amei, Hérmia,\nSempre guardei teus segredos, nunca te fiz mal;\nSalvo que, por amor a Demétrio,\nContei-lhe de tua fuga para este bosque.\nEle te seguiu; por amor eu o segui;\nMas ele me repeliu daqui e me ameaçou\nBater-me, chutar-me, e até matar-me:\nE agora, se me deixares ir em paz,\nA Atenas levarei de volta a minha tolice\nE não te seguirei mais: deixa-me ir:\nVês quão simples e tola eu sou.","hermiawhygetyougonewhoistthathindersyou~gonewhoistthathindersyou~39":"Hérmia — Ora, vai-te: quem é que te impede?","helenaafoolishheartthatileaveherebehind~eartthatileaveherebehind~39":"Helena — Um coração tolo, que deixo aqui para trás.","hermiawhatwithlysander~hermiawhatwithlysander~22":"Hérmia — Como, com Lisandro?","helenawithdemetrius~helenawithdemetrius~19":"Helena — Com Demétrio.","lysanderbenotafraidsheshallnotharmtheehe~heshallnotharmtheehelena~44":"Lisandro — Não tenhas medo; ela não te fará mal, Helena.","demetriusnosirsheshallnotthoughyoutakehe~lnotthoughyoutakeherpart~45":"Demétrio — Não, senhor, não fará, ainda que tomeis o partido dela.","helenaowhenshesangrysheiskeenandshrewdsh~hebebutlittlesheisfierce~103":"Helena — Oh, quando ela se zanga, é afiada e astuta!\nEra uma raposa quando ia à escola;\nE embora seja pequena, é feroz.","hermialittleagainnothingbutlowandlittlew~loutmethusletmecometoher~85":"Hérmia — “Pequena” de novo! só “baixa” e “pequena”!\nPor que deixais que ela me escarneça assim?\nDeixai-me chegar a ela.","lysandergetyougoneyoudwarfyouminimusofhi~grassmadeyoubeadyouacorn~75":"Lisandro — Vai-te, anã;\nTu, minimozinha, feita de grama que enreda;\nTu, conta, tu, bolota.","demetriusyouaretooofficiousinherbehalfth~flovetoherthoushaltabyit~162":"Demétrio — És por demais solícito\nEm favor de quem despreza os teus serviços.\nDeixa-a em paz: não fales de Helena;\nNão tomes o partido dela; pois, se pretendes\nMostrar-lhe o mínimo sinal de amor,\nPagá-lo-ás caro.","lysandernowsheholdsmenotnowfollowifthoud~hineormineismostinhelena~87":"Lisandro — Agora ela não me segura;\nSegue-me agora, se ousas, para provar de quem o direito,\nTeu ou meu, é maior sobre Helena.","demetriusfollownayillgowiththeecheekbyjo~euntlysanderanddemetrius~68":"Demétrio — Seguir! não, irei contigo, face a face. Saem Lisandro e Demétrio.","hermiayoumistressallthiscoilislongofyoun~lislongofyounaygonotback~51":"Hérmia — Tu, senhora, todo este tumulto é por tua causa:\nNão, não recues.","helenaiwillnottrustyouinorlongerstayinyo~ongerthoughtorunawayexit~123":"Helena — Não confio em ti, eu,\nNem ficarei mais em tua maldita companhia.\nTuas mãos são mais rápidas que as minhas para a briga,\nMinhas pernas são mais longas, porém, para fugir. Sai.","hermiaiamamazedandknownotwhattosayexit~dandknownotwhattosayexit~38":"Hérmia — Estou pasmada, e não sei o que dizer. Sai.","oberonthisisthynegligencestillthoumistak~tstthyknaverieswillfully~79":"Oberon — Isto é tua negligência: sempre te enganas,\nOu então cometes tuas patifarias de propósito.","puckbelievemekingofshadowsimistookdidnot~eirjanglingiesteemasport~218":"Puck — Crede-me, rei das sombras, enganei-me.\nNão me dissestes que eu conheceria o homem\nPelas vestes atenienses que trazia?\nE até aí se mostra sem culpa minha empresa,\nPois ungi os olhos de um ateniense;\nE até aí estou contente de que assim sucedesse,\nPois julgo esta briga deles um divertimento.","oberonthouseesttheseloversseekaplacetofi~andallthingsshallbepeace~822":"Oberon — Vês que estes amantes buscam um lugar para lutar:\nApressa-te, portanto, Robin, escurece a noite;\nCobre logo o firmamento estrelado\nCom névoa baixa, negra como o Aqueronte,\nE leva esses rivais irascíveis tão desencaminhados\nQue um não cruze o caminho do outro.\nÀs vezes molda a língua como Lisandro,\nE depois açula Demétrio com amarga ofensa;\nE às vezes insulta como Demétrio;\nE trata de afastá-los assim um do outro,\nAté que sobre suas frontes o sono que imita a morte\nCom pernas de chumbo e asas de morcego se arraste:\nEntão esmaga esta erva no olho de Lisandro;\nCujo licor tem esta virtuosa propriedade,\nDe tirar dali todo erro com sua força,\nE fazer seus globos oculares girar com a vista de costume.\nQuando acordarem de novo, toda esta zombaria\nParecerá um sonho e visão sem fruto,\nE a Atenas voltarão os amantes,\nCom pacto cujo prazo até a morte nunca terminará.\nEnquanto neste negócio te emprego,\nIrei à minha rainha pedir-lhe o menino indiano;\nE então libertarei seu olho encantado\nDa visão do monstro, e tudo será paz.","puckmyfairylordthismustbedonewithhastefo~nsortwithblackbrowdnight~368":"Puck — Meu senhor das fadas, isto deve ser feito com pressa,\nPois os velozes dragões da noite cortam as nuvens depressa,\nE ali brilha o arauto de Aurora;\nÀ cuja chegada os fantasmas, errantes aqui e ali,\nVoltam em tropel aos cemitérios: espíritos condenados todos,\nQue em encruzilhadas e águas têm sepultura,\nJá foram para seus leitos de vermes;\nPor medo de que o dia lhes veja as vergonhas,\nExilam-se de propósito da luz\nE devem para sempre conviver com a noite de sobrancelhas negras.","oberonbutwearespiritsofanothersortiwitht~hisbusinessyeteredayexit~280":"Oberon — Mas somos espíritos de outra espécie:\nEu com o amor da manhã muitas vezes brinquei,\nE, como um guarda-florestal, posso pisar os bosques,\nAté que o portão do oriente, todo rubro de fogo,\nAbrindo-se sobre Netuno com raios belos e abençoados,\nTransforma em ouro amarelo suas correntes verde-salgadas.\nMas, apesar disso, apressa-te; não demores:\nPoderemos ainda realizar este negócio antes do dia. Sai.","puckupanddownupanddowniwillleadthemupand~hemupanddownherecomesone~101":"Puck — Para cima e para baixo, para cima e para baixo,\nOs levarei para cima e para baixo:\nSou temido no campo e na cidade:\nDuende, leva-os para cima e para baixo.\nAqui vem um.","reenterlysander~reenterlysander~15":"Entra de novo Lisandro.","lysanderwhereartthouprouddemetriusspeakt~ouddemetriusspeakthounow~46":"Lisandro — Onde estás, orgulhoso Demétrio? fala agora.","puckherevillaindrawnandreadywhereartthou~rawnandreadywhereartthou~40":"Puck — Aqui, vilão; com a espada desembainhada e pronto. Onde estás?","lysanderiwillbewiththeestraight~riwillbewiththeestraight~31":"Lisandro — Estarei contigo já.","puckfollowmethenoplainergroundexitlysand~anderasfollowingthevoice~61":"Puck — Segue-me, então,\nAo terreno mais plano. Sai Lisandro, como seguindo a voz.","reenterdemetrius~reenterdemetrius~16":"Entra de novo Demétrio.","demetriuslysanderspeakagainthourunawayth~wheredostthouhidethyhead~98":"Demétrio — Lisandro! fala de novo:\nFugitivo, covarde, fugiste?\nFala! Em algum arbusto? Onde escondes a cabeça?","puckthoucowardartthoubraggingtothestarst~ledthatdrawsaswordonthee~166":"Puck — Covarde, estás te gabando às estrelas,\nDizendo aos arbustos que procuras guerra,\nE não queres vir? Vem, renegado; vem, criança;\nChicotear-te-ei com uma vara: desonrado está\nQuem desembainha espada contra ti.","demetriusyeaartthouthere~demetriusyeaartthouthere~24":"Demétrio — Sim, estás aí?","puckfollowmyvoicewelltrynomanhoodhereexe~lltrynomanhoodhereexeunt~43":"Puck — Segue a minha voz: não provaremos varonilidade aqui. Saem.","lysanderhegoesbeforemeandstilldaresmeonw~ndrevengethisspitesleeps~279":"Lisandro — Ele vai à minha frente e sempre me desafia:\nQuando chego onde ele chama, já se foi.\nO vilão tem pés bem mais leves que os meus:\nSegui depressa, mas mais depressa ele fugiu;\nDe modo que caí em caminho escuro e acidentado,\nE aqui descansarei. Deita-se. Vem, gentil dia!\nPois se uma vez me mostrares tua luz cinzenta,\nEncontrarei Demétrio e vingarei esta afronta. Dorme.","reenterpuckanddemetrius~reenterpuckanddemetrius~23":"Entram de novo Puck e Demétrio.","puckhohohocowardwhycomestthounot~hocowardwhycomestthounot~32":"Puck — Ho, ho, ho! Covarde, por que não vens?","demetriusabidemeifthoudarestforwelliwott~inthefacewhereartthounow~125":"Demétrio — Espera-me, se ousas; pois bem sei\nQue corres à minha frente, mudando de lugar a cada instante,\nE não ousas parar, nem olhar-me no rosto.\nOnde estás agora?","puckcomehitheriamhere~puckcomehitheriamhere~21":"Puck — Vem cá: estou aqui.","demetriusnaythenthoumockstmethoushaltbuy~visitedliesdownandsleeps~188":"Demétrio — Não, então zombas de mim. Pagarás caro por isto,\nSe alguma vez eu te vir o rosto à luz do dia:\nAgora, segue teu caminho. A fraqueza me obriga\nA medir meu comprimento neste leito frio.\nQuando o dia chegar, espera ser visitado. Deita-se e dorme.","reenterhelena~reenterhelena~13":"Entra de novo Helena.","helenaowearynightolongandtediousnightaba~companyliesdownandsleeps~222":"Helena — Ó noite cansada, ó noite longa e tediosa,\nAbrevia tuas horas! Brilhai, consolos, do oriente,\nPara que eu volte a Atenas à luz do dia,\nDestes que detestam a minha pobre companhia:\nE sono, que às vezes fecha o olho da tristeza,\nFurta-me por um instante da minha própria companhia. Deita-se e dorme.","puckyetbutthreecomeonemoretwoofbothkinds~thustomakepoorfemalesmad~116":"Puck — Ainda só três? Venha mais uma;\nDois de cada sexo fazem quatro.\nAí vem ela, zangada e triste:\nCupido é um rapaz travesso,\nPor fazer assim enlouquecer pobres mulheres.","hermianeversowearyneversoinwoebedabbledw~anafrayliesdownandsleeps~212":"Hérmia — Nunca tão cansada, nunca tão aflita,\nEncharcada de orvalho e rasgada por espinhos,\nNão posso mais me arrastar, não posso mais andar;\nMinhas pernas não acompanham o passo dos meus desejos.\nAqui descansarei até o romper do dia.\nQue os céus protejam Lisandro, se pretendem briga! Deita-se e dorme.","puckonthegroundsleepsoundillapplytoyoure~ainandallshallbewellexit~313":"Puck — No chão\nDorme em paz:\nAplicarei\nAo teu olho,\nGentil amante, remédio. Espremendo o suco nos olhos de Lisandro.\nQuando acordares,\nTomarás\nVerdadeiro prazer\nAo ver\nO olho de tua antiga dama:\nE o provérbio do campo conhecido,\nQue cada homem deve tomar o que é seu,\nEm teu despertar será mostrado:\nJoão terá Joana;\nNada irá mal;\nO homem terá sua égua de volta, e tudo ficará bem. Sai."}$tr$::jsonb, 369)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- william-shakespeare_as-you-like-it (591 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_as-you-like-it', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"acti":"Ato I","actii":"Ato II","actiii":"Ato III"}$tr$::jsonb, $tr${"scenei~scenei~6":"Cena I","orchardofolivershouse~orchardofolivershouse~21":"Pomar da casa de Oliver.","enterorlandoandadam~enterorlandoandadam~19":"Entram Orlando e Adam.","orlandoasirememberadamitwasuponthisfashi~nowiseremedyhowtoavoidit~960":"Orlando — Pelo que me lembro, Adam, foi desta maneira que ele me legou por testamento apenas mil coroas e, como dizes, encarregou meu irmão, sob sua bênção, de me criar bem: e é aí que começa a minha tristeza. Meu irmão Jaques ele mantém na escola, e a fama fala em ouro de seu aproveitamento; quanto a mim, ele me mantém rusticamente em casa ou, para falar com mais propriedade, me retém aqui sem criação; pois chamas a isso criar um cavalheiro de meu nascimento, quando em nada difere do estabulamento de um boi? Seus cavalos são mais bem criados; pois, além de serem bonitos pela boa ração, são ensinados na equitação, e para isso se pagam caro os cavaleiros; mas eu, seu irmão, nada ganho com ele senão crescimento; pelo que seus animais nos esterqueiros lhe são tão obrigados quanto eu. Além deste nada que tão fartamente me dá, o pouco que a natureza me deu o seu semblante parece tirar-me: deixa-me comer com seus criados, nega-me o lugar de irmão e, tanto quanto está em seu poder, mina minha fidalguia com a minha educação. É isto, Adam, o que me aflige; e o espírito de meu pai, que creio estar em mim, começa a se amotinar contra esta servidão: não a suportarei mais, embora ainda não saiba nenhum remédio sensato para evitá-la.","adamyondercomesmymasteryourbrother~comesmymasteryourbrother~34":"Adam — Eis que vem aí meu amo, vosso irmão.","orlandogoapartadamandthoushalthearhowhew~lthearhowhewillshakemeup~52":"Orlando — Afasta-te, Adam, e ouvirás como ele vai me sacudir.","enteroliver~enteroliver~11":"Entra Oliver.","olivernowsirwhatmakeyouhere~vernowsirwhatmakeyouhere~27":"Oliver — Então, senhor! que fazeis aqui?","orlandonothingiamnottaughttomakeanything~mnottaughttomakeanything~40":"Orlando — Nada: não fui ensinado a fazer coisa alguma.","oliverwhatmaryouthensir~oliverwhatmaryouthensir~23":"Oliver — Que estragais, então, senhor?","orlandomarrysiriamhelpingyoutomarthatwhi~otherofyourswithidleness~88":"Orlando — Ora, senhor, ajudo-vos a estragar, com ociosidade, o que Deus fez: um pobre e indigno irmão vosso.","olivermarrysirbebetteremployedandbenaugh~mployedandbenaughtawhile~47":"Oliver — Ora, senhor, empregai-vos melhor e sumi por um tempo.","orlandoshallikeepyourhogsandeathuskswith~tishouldcometosuchpenury~100":"Orlando — Hei de guardar vossos porcos e comer bolotas com eles? Que porção pródiga gastei eu, para chegar a tamanha penúria?","oliverknowyouwhereyouraresir~erknowyouwhereyouraresir~28":"Oliver — Sabeis onde estais, senhor?","orlandoosirverywellhereinyourorchard~erywellhereinyourorchard~36":"Orlando — Oh, senhor, muito bem: aqui, em vosso pomar.","oliverknowyoubeforewhomsir~iverknowyoubeforewhomsir~26":"Oliver — Sabeis diante de quem, senhor?","orlandoaybetterthanhimiambeforeknowsmeik~meisnearertohisreverence~326":"Orlando — Sim, melhor do que aquele diante de quem estou me conhece. Sei que sois meu irmão mais velho e, na gentil condição do sangue, assim deveríeis conhecer-me. A cortesia das nações vos permite ser meu superior, por serdes o primogênito; mas essa mesma tradição não tira meu sangue, ainda que houvesse vinte irmãos entre nós: tenho tanto de meu pai em mim quanto vós; embora, confesso, o fato de virdes antes de mim vos aproxime mais de sua reverência.","oliverwhatboy~oliverwhatboy~13":"Oliver — O quê, rapaz!","orlandocomecomeelderbrotheryouaretooyoun~theryouaretooyounginthis~47":"Orlando — Vamos, vamos, irmão mais velho, sois novo demais nisto.","oliverwiltthoulayhandsonmevillain~tthoulayhandsonmevillain~33":"Oliver — Ousas pôr as mãos em mim, vilão?","orlandoiamnovillainiamtheyoungestsonofsi~othouhastrailedonthyself~242":"Orlando — Não sou vilão; sou o filho mais novo de Sir Rowland de Boys; ele foi meu pai, e três vezes vilão é quem diz que tal pai gerou vilões. Não fosses meu irmão, não tiraria esta mão de tua garganta até que a outra te arrancasse a língua por dizeres tal coisa: injuriaste a ti mesmo.","adamsweetmastersbepatientforyourfathersr~ersremembrancebeataccord~60":"Adam — Doces senhores, tende paciência: em memória de vosso pai, estai em paz.","oliverletmegoisay~oliverletmegoisay~17":"Oliver — Soltai-me, digo.","orlandoiwillnottillipleaseyoushallhearme~thatiwillgobuymyfortunes~350":"Orlando — Não o farei até que me apraza: ouvir-me-eis. Meu pai vos encarregou em testamento de dar-me boa educação: criastes-me como um camponês, obscurecendo e ocultando de mim todas as qualidades de um cavalheiro. O espírito de meu pai cresce forte em mim, e não o suportarei mais: portanto permiti-me os exercícios que convêm a um cavalheiro, ou dai-me a pobre quota que meu pai me deixou por testamento; com ela irei comprar a minha fortuna.","oliverandwhatwiltthoudobegwhenthatisspen~fyourwilliprayyouleaveme~130":"Oliver — E que farás tu? Mendigar, quando isso acabar? Pois bem, senhor, entra: não serei incomodado por ti por muito tempo; terás alguma parte de tua vontade: peço-te, deixa-me.","orlandoiwillnofurtheroffendyouthanbecome~outhanbecomesmeformygood~52":"Orlando — Não vos ofenderei além do que convém ao meu bem.","olivergetyouwithhimyouolddog~ergetyouwithhimyouolddog~28":"Oliver — Vai com ele, velho cão.","adamisolddogmyrewardmosttrueihavelostmyt~wordexeuntorlandoandadam~125":"Adão — “Velho cão” é a minha recompensa? Verdade verdadeira, perdi os dentes a vosso serviço. Deus esteja com meu velho amo! ele não teria dito tal palavra. Saem Orlando e Adão.","oliverisitevensobeginyoutogrowuponmeiwil~crownsneitherholladennis~103":"Oliver — Chegamos a isso? começas a crescer sobre mim? Purgarei tua insolência, e contudo não darei as mil coroas. Olá, Dênis!","enterdennis~enterdennis~11":"Entra Dênis.","denniscallsyourworship~denniscallsyourworship~22":"Dênis — Chama vossa senhoria?","oliverwasnotcharlesthedukeswrestlerheret~restlerheretospeakwithme~52":"Oliver — Não estava aqui Charles, o lutador do duque, para falar comigo?","dennissopleaseyouheishereatthedoorandimp~andimportunesaccesstoyou~58":"Dênis — Se vos apraz, está aqui à porta e importuna por acesso a vós.","olivercallhiminexitdennistwillbeagoodway~ndtomorrowthewrestlingis~65":"Oliver — Faze-o entrar. Sai Dênis. Será um bom meio; e amanhã é a luta.","entercharles~entercharles~12":"Entra Charles.","charlesgoodmorrowtoyourworship~sgoodmorrowtoyourworship~30":"Charles — Bom dia a vossa senhoria.","olivergoodmonsieurcharleswhatsthenewnews~sthenewnewsatthenewcourt~53":"Oliver — Bom monsieur Charles, quais são as novas notícias da nova corte?","charlestheresnonewsatthecourtsirbuttheol~vesthemgoodleavetowander~241":"Charles — Não há notícia na corte, senhor, senão a velha notícia: a saber, o velho duque foi banido pelo irmão mais novo, o novo duque; e três ou quatro nobres afeiçoados se puseram em exílio voluntário com ele, cujas terras e rendas enriquecem o novo duque; por isso ele lhes dá boa licença para vagar.","olivercanyoutellifrosalindthedukesdaught~rbebanishedwithherfather~65":"Oliver — Sabeis dizer se Rosalinda, a filha do duque, foi banida com o pai?","charlesonoforthedukesdaughterhercousinso~ertwoladieslovedastheydo~231":"Charles — Oh, não; pois a filha do duque, sua prima, a ama tanto, tendo sido criadas juntas desde o berço, que teria seguido seu exílio, ou morrido por ficar sem ela. Ela está na corte, e não menos amada pelo tio que a própria filha dele; e nunca duas damas se amaram como elas.","oliverwherewilltheolddukelive~rwherewilltheolddukelive~29":"Oliver — Onde viverá o velho duque?","charlestheysayheisalreadyintheforestofar~stheydidinthegoldenworld~203":"Charles — Dizem que já está na floresta de Arden, e muitos alegres companheiros com ele; e ali vivem como o velho Robin Hood da Inglaterra: dizem que muitos jovens fidalgos acorrem a ele todos os dias, e passam o tempo sem cuidados, como faziam na idade de ouro.","oliverwhatyouwrestletomorrowbeforethenew~tomorrowbeforethenewduke~44":"Oliver — Como, lutais amanhã diante do novo duque?","charlesmarrydoisirandicametoacquaintyouw~daltogetheragainstmywill~538":"Charles — Por certo, senhor; e vim inteirar-vos de um assunto. Foi-me dado a entender, senhor, em segredo, que vosso irmão mais novo, Orlando, tem a disposição de entrar disfarçado contra mim para tentar uma queda. Amanhã, senhor, luto por minha reputação; e quem escapar de mim sem algum membro quebrado se sairá muito bem. Vosso irmão é ainda jovem e tenro; e, por vosso amor, eu seria relutante em vencê-lo, como devo, por minha própria honra, se ele entrar: portanto, por meu afeto a vós, vim aqui inteirar-vos, para que ou o detenhais de seu intento ou suporteis bem a desgraça em que ele incorrerá, por ser coisa de sua própria procura e totalmente contra a minha vontade.","olivercharlesithanktheeforthylovetomewhi~houmustlookpaleandwonder~823":"Oliver — Charles, agradeço-te o afeto que me tens, que verás que retribuirei da maneira mais bondosa. Eu mesmo tive notícia do propósito de meu irmão e por meios dissimulados me esforcei para dissuadi-lo, mas ele está resoluto. Dir-te-ei, Charles: é o rapaz mais teimoso da França, cheio de ambição, um invejoso êmulo das boas partes de todos, um secreto e vilão urdidor contra mim, seu irmão de sangue: portanto usa tua discrição; tanto me faz que lhe quebres o pescoço como o dedo. E é melhor que cuides disso; pois se lhe fizeres a mais leve desgraça, ou se ele não se cobrir de glória sobre ti, tramará contra ti com veneno, enredar-te-á por alguma traiçoeira maquinação e não te deixará até te tomar a vida por algum meio indireto ou outro; pois, asseguro-te, e quase com lágrimas o digo, não há hoje vivo outro tão jovem e tão vilão. Falo dele apenas como irmão; mas se eu o dissecasse a ti tal como é, eu haveria de corar e chorar, e tu haverias de empalidecer e pasmar.","charlesiamheartilygladicamehithertoyouif~eandsogodkeepyourworship~144":"Charles — Estou de coração contente de ter vindo a vós. Se ele vier amanhã, dar-lhe-ei o seu pagamento: se alguma vez ele andar sozinho de novo, nunca mais lutarei por prêmio: e assim Deus guarde vossa senhoria!","oliverfarewellgoodcharlesexitcharlesnoww~erwhichnowillgoaboutexit~423":"Oliver — Adeus, bom Charles. Sai Charles. Agora atiçarei este jogador: espero ver o fim dele; pois minha alma, sem que eu saiba por quê, nada odeia mais do que ele. E contudo é gentil, nunca instruído e contudo sabido, cheio de nobre engenho, de todas as classes encantadoramente amado, e na verdade tão no coração do mundo, e sobretudo de minha própria gente, que o conhece melhor, que eu sou de todo menosprezado: mas não será assim por muito tempo; este lutador resolverá tudo: nada resta senão que eu incite o rapaz a ir lá; o que agora irei fazer. Sai.","sceneii~sceneii~7":"Cena II","lawnbeforethedukespalace~lawnbeforethedukespalace~24":"Gramado diante do palácio do Duque.","enterceliaandrosalind~enterceliaandrosalind~21":"Entram Célia e Rosalinda.","celiaipraytheerosalindsweetmycozbemerry~osalindsweetmycozbemerry~39":"Célia — Peço-te, Rosalinda, doce prima, sê alegre.","rosalinddearceliaishowmoremirththaniammi~anyextraordinarypleasure~172":"Rosalinda — Cara Célia, mostro mais alegria do que sou senhora de ter; e ainda queres que eu seja mais alegre? A menos que me ensines a esquecer um pai banido, não deves me ensinar a lembrar qualquer prazer extraordinário.","celiahereiniseethoulovestmenotwiththeful~lytemperedasmineistothee~265":"Célia — Nisto vejo que não me amas com todo o peso com que eu te amo. Se meu tio, teu pai banido, tivesse banido teu tio, o duque meu pai, desde que tivesses ficado sempre comigo, eu teria podido ensinar meu amor a tomar teu pai pelo meu: assim farias tu, se a verdade de teu amor por mim fosse tão retamente temperada quanto o meu por ti.","rosalindwelliwillforgettheconditionofmye~myestatetorejoiceinyours~61":"Rosalinda — Pois bem, esquecerei a condição de meu estado, para me alegrar com o teu.","celiayouknowmyfatherhathnochildbutinorno~eetrosemydearrosebemerry~255":"Célia — Sabes que meu pai não tem filho senão eu, nem é provável que tenha: e, na verdade, quando ele morrer, serás sua herdeira, pois o que ele tomou de teu pai à força, eu o devolverei a ti em afeição; por minha honra, devolverei; e quando eu quebrar esse juramento, que eu me torne monstro: portanto, minha doce Rosa, minha querida Rosa, sê alegre.","rosalindfromhenceforthiwillcozanddevises~tthinkyouoffallinginlove~80":"Rosalinda — De agora em diante serei, prima, e inventarei diversões. Vejamos; que pensas de nos apaixonarmos?","celiamarryipritheedotomakesportwithalbut~aystinhonourcomeoffagain~143":"Célia — Por certo, peço-te, faze-o, para nos divertirmos: mas não ames homem algum a sério; nem mais longe, em brincadeira, do que com a segurança de um puro rubor possas honradamente sair de novo.","rosalindwhatshallbeoursportthen~dwhatshallbeoursportthen~31":"Rosalinda — Qual será então nossa diversão?","celialetussitandmockthegoodhousewifefort~ceforthbebestowedequally~97":"Célia — Sentemo-nos e zombemos da boa dona de casa Fortuna, para fazê-la descer de sua roda, a fim de que seus dons sejam daqui em diante distribuídos com igualdade.","rosalindiwouldwecoulddosoforherbenefitsa~mistakeinhergiftstowomen~116":"Rosalinda — Quisera que pudéssemos, pois seus benefícios estão muitíssimo mal postos, e a generosa mulher cega mais erra em seus dons às mulheres.","celiatistrueforthosethatshemakesfairshes~hemakesveryillfavouredly~107":"Célia — É verdade; pois as que ela faz belas, mal as faz honestas, e as que ela faz honestas, faz muito feias.","rosalindnaynowthougoestfromfortunesoffic~tinthelineamentsofnature~106":"Rosalinda — Não, agora passas do ofício da Fortuna ao da Natureza: a Fortuna reina nos dons do mundo, não nos traços da Natureza.","entertouchstone~entertouchstone~15":"Entra Touchstone.","celianowhennaturehathmadeafaircreaturema~sfooltocutofftheargument~160":"Célia — Não? quando a Natureza fez uma bela criatura, não pode ela, pela Fortuna, cair no fogo? Embora a Natureza nos tenha dado engenho para zombar da Fortuna, não enviou a Fortuna este bobo para cortar a discussão?","rosalindindeedthereisfortunetoohardforna~thecutteroffofnatureswit~98":"Rosalinda — Na verdade, há uma Fortuna forte demais para a Natureza, quando a Fortuna faz do tolo da Natureza o cortador do engenho da Natureza.","celiaperadventurethisisnotfortunesworkne~ownowwitwhitherwanderyou~225":"Célia — Talvez isto não seja obra da Fortuna tampouco, mas da Natureza; que, percebendo nossos engenhos naturais embotados demais para arrazoar sobre tais deusas, enviou este tolo natural como nossa pedra de amolar; pois sempre a estupidez do bobo é a pedra de amolar dos engenhos. Então, engenho! aonde vagueias?","touchstonemistressyoumustcomeawaytoyourf~mustcomeawaytoyourfather~45":"Touchstone — Senhora, tendes de vir ter com vosso pai.","celiawereyoumadethemessenger~awereyoumadethemessenger~28":"Célia — Fostes feito o mensageiro?","touchstonenobyminehonourbutiwasbidtocome~urbutiwasbidtocomeforyou~46":"Touchstone — Não, por minha honra, mas me mandaram buscar-vos.","rosalindwherelearnedyouthatoathfool~relearnedyouthatoathfool~35":"Rosalinda — Onde aprendeste esse juramento, bobo?","touchstoneofacertainknightthatsworebyhis~twasnottheknightforsworn~189":"Touchstone — De um certo cavaleiro que jurava por sua honra que as panquecas eram boas e jurava por sua honra que a mostarda era ruim: agora sustentarei que as panquecas eram ruins e a mostarda era boa, e contudo o cavaleiro não perjurou.","celiahowproveyouthatinthegreatheapofyour~greatheapofyourknowledge~49":"Célia — Como provas isso, no grande monte de teu saber?","rosalindaymarrynowunmuzzleyourwisdom~rrynowunmuzzleyourwisdom~36":"Rosalinda — Sim, por certo, agora desamordaça tua sabedoria.","touchstonestandyoubothforthnowstrokeyour~yyourbeardsthatiamaknave~78":"Touchstone — Colocai-vos ambas adiante agora: alisai o queixo e jurai por vossas barbas que sou um velhaco.","celiabyourbeardsifwehadthemthouart~beardsifwehadthemthouart~34":"Célia — Por nossas barbas, se as tivéssemos, és.","touchstonebymyknaveryifihadittheniwerebu~osepancakesorthatmustard~203":"Touchstone — Por minha velhacaria, se a tivesse, então eu seria; mas se jurais por aquilo que não existe, não perjurais: nem este cavaleiro, jurando por sua honra, pois nunca a teve; ou se teve, já a havia jurado fora antes de jamais ver aquelas panquecas ou aquela mostarda.","celiapritheewhoistthatthoumeanest~heewhoistthatthoumeanest~33":"Célia — Peço-te, quem é que queres dizer?","touchstoneonethatoldfrederickyourfatherl~frederickyourfatherloves~44":"Touchstone — Alguém a quem o velho Frederico, vosso pai, ama.","celiamyfathersloveisenoughtohonourhimeno~ortaxationoneofthesedays~98":"Célia — O amor de meu pai basta para honrá-lo: basta! não fales mais dele; serás chicoteado por censura um destes dias.","touchstonethemorepitythatfoolsmaynotspea~lywhatwisemendofoolishly~69":"Touchstone — É pena que os bobos não possam falar sabiamente o que os sábios fazem tolamente.","celiabymytroththousayesttrueforsincethel~wherecomesmonsieurlebeau~141":"Célia — Por minha fé, dizes a verdade; pois desde que o pouco engenho que os bobos têm foi silenciado, a pouca tolice que os sábios têm faz grande figura. Aí vem monsieur Le Beau.","rosalindwithhismouthfullofnews~ndwithhismouthfullofnews~30":"Rosalinda — Com a boca cheia de notícias.","celiawhichhewillputonusaspigeonsfeedthei~saspigeonsfeedtheiryoung~46":"Célia — Que ele nos enfiará, como os pombos alimentam seus filhotes.","rosalindthenshallwebenewscrammed~thenshallwebenewscrammed~32":"Rosalinda — Então seremos empanturradas de notícias.","celiaallthebetterweshallbethemoremarketa~shallbethemoremarketable~43":"Célia — Tanto melhor; seremos mais vendáveis.","enterlebeau~enterlebeau~11":"Entra Le Beau.","bonjourmonsieurlebeauwhatsthenews~nsieurlebeauwhatsthenews~33":"Bom dia, monsieur Le Beau: quais são as novas?","lebeaufairprincessyouhavelostmuchgoodspo~youhavelostmuchgoodsport~42":"Le Beau — Bela princesa, perdestes muito bom divertimento.","celiasportofwhatcolour~celiasportofwhatcolour~22":"Célia — Divertimento! de que cor?","lebeauwhatcolourmadamhowshalliansweryou~rmadamhowshalliansweryou~39":"Le Beau — De que cor, senhora! como vos responderei?","rosalindaswitandfortunewill~alindaswitandfortunewill~27":"Rosalinda — Como o engenho e a fortuna quiserem.","touchstoneorasthedestiniesdecree~neorasthedestiniesdecree~32":"Touchstone — Ou como os Destinos decretarem.","celiawellsaidthatwaslaidonwithatrowel~thatwaslaidonwithatrowel~37":"Célia — Bem dito: isso foi aplicado com a colher de pedreiro.","touchstonenayifikeepnotmyrank~stonenayifikeepnotmyrank~29":"Touchstone — Não, se não mantenho minha posição —","rosalindthoulosestthyoldsmell~indthoulosestthyoldsmell~29":"Rosalinda — Perdes teu velho cheiro.","lebeauyouamazemeladiesiwouldhavetoldyouo~ichyouhavelostthesightof~80":"Le Beau — Espantais-me, senhoras: queria ter-vos contado de uma boa luta, de cuja vista estais privadas.","rosalindyoutellusthemannerofthewrestling~sthemannerofthewrestling~40":"Rosalinda — Contai-nos como foi a luta.","lebeauiwilltellyouthebeginningandifitple~theyarecomingtoperformit~132":"Le Beau — Contar-vos-ei o começo; e, se aprouver a vossas senhorias, podereis ver o fim; pois o melhor ainda está por fazer; e aqui, onde estais, eles vêm para realizá-lo.","celiawellthebeginningthatisdeadandburied~nningthatisdeadandburied~40":"Célia — Pois bem, o começo, esse está morto e enterrado.","lebeautherecomesanoldmanandhisthreesons~sanoldmanandhisthreesons~39":"Le Beau — Vem um velho com seus três filhos —","celiaicouldmatchthisbeginningwithanoldta~isbeginningwithanoldtale~42":"Célia — Eu poderia combinar este começo com um conto velho.","lebeauthreeproperyoungmenofexcellentgrow~cellentgrowthandpresence~53":"Le Beau — Três jovens bem-apessoados, de excelente estatura e presença.","rosalindwithbillsontheirnecksbeitknownun~ntoallmenbythesepresents~63":"Rosalinda — Com letreiros no pescoço: “Seja notório a todos os homens por estas presentes.”","lebeautheeldestofthethreewrestledwithcha~rstakehispartwithweeping~282":"Le Beau — O mais velho dos três lutou com Charles, o lutador do duque; e Charles num instante o derrubou e lhe quebrou três costelas, de modo que há pouca esperança de vida nele: assim fez com o segundo, e assim com o terceiro. Ali jazem; o pobre velho, pai deles, fazendo tão piedoso lamento sobre eles que todos os que veem tomam o seu partido com lágrimas.","rosalindalas~rosalindalas~12":"Rosalinda — Ai de mim!","touchstonebutwhatisthesportmonsieurthatt~eurthattheladieshavelost~56":"Touchstone — Mas qual é o divertimento, monsieur, que as damas perderam?","lebeauwhythisthatispeakof~ebeauwhythisthatispeakof~25":"Le Beau — Ora, este de que falo.","touchstonethusmenmaygrowwisereverydayiti~gofribswassportforladies~98":"Touchstone — Assim os homens podem ficar mais sábios a cada dia: é a primeira vez que ouço dizer que quebrar costelas era divertimento para damas.","celiaoriipromisethee~celiaoriipromisethee~20":"Célia — Ou eu, prometo-te.","rosalindbutisthereanyelselongstoseethisb~weseethiswrestlingcousin~126":"Rosalinda — Mas há mais alguém que deseje ver esta música quebrada em seus flancos? há ainda outro que se enamore de quebrar costelas? Veremos esta luta, prima?","lebeauyoumustifyoustayhereforhereisthepl~dtheyarereadytoperformit~93":"Le Beau — Tereis de ver, se ficardes aqui; pois aqui é o lugar designado para a luta, e eles estão prontos para realizá-la.","celiayondersuretheyarecomingletusnowstay~mingletusnowstayandseeit~48":"Célia — Ali, por certo, estão vindo: fiquemos agora e vejamos.","flourishenterdukefredericklordsorlandoch~andocharlesandattendants~58":"Fanfarra. Entram o Duque Frederico, Nobres, Orlando, Charles e Criados.","dukefrederickcomeonsincetheyouthwillnotb~ownperilonhisforwardness~77":"Duque Frederico — Vamos: já que o jovem não se deixa convencer, seu próprio perigo recaia sobre sua ousadia.","rosalindisyondertheman~rosalindisyondertheman~22":"Rosalinda — É aquele o homem?","lebeauevenhemadam~lebeauevenhemadam~17":"Le Beau — Ele mesmo, senhora.","celiaalasheistooyoungyethelookssuccessfu~ngyethelookssuccessfully~43":"Célia — Ai de mim, é jovem demais! contudo tem aspecto de vencedor.","dukefrederickhownowdaughterandcousinarey~thithertoseethewrestling~70":"Duque Frederico — Então, filha e sobrinha! esgueirastes-vos até aqui para ver a luta?","rosalindaymyliegesopleaseyougiveusleave~gesopleaseyougiveusleave~39":"Rosalinda — Sim, meu senhor, se vos apraz dar-nos licença.","dukefrederickyouwilltakelittledelightini~ladiesseeifyoucanmovehim~180":"Duque Frederico — Tereis pouco deleite nela, posso dizer-vos; há tamanha desigualdade no homem. Por piedade da juventude do desafiante, bem quisera dissuadi-lo, mas ele não se deixa convencer. Falai-lhe, senhoras; vede se podeis demovê-lo.","celiacallhimhithergoodmonsieurlebeau~hithergoodmonsieurlebeau~36":"Célia — Chamai-o aqui, bom monsieur Le Beau.","dukefrederickdosoillnotbeby~efrederickdosoillnotbeby~27":"Duque Frederico — Fazei-o: eu não estarei por perto.","lebeaumonsieurthechallengertheprincesses~rtheprincessescallforyou~50":"Le Beau — Senhor desafiante, as princesas vos chamam.","orlandoiattendthemwithallrespectandduty~hemwithallrespectandduty~39":"Orlando — Atendo-as com todo respeito e dever.","rosalindyoungmanhaveyouchallengedcharles~lengedcharlesthewrestler~51":"Rosalinda — Jovem, desafiastes Charles, o lutador?","orlandonofairprincessheisthegeneralchall~hhimthestrengthofmyyouth~97":"Orlando — Não, bela princesa; ele é o desafiante geral: venho apenas, como outros fazem, provar com ele a força de minha juventude.","celiayounggentlemanyourspiritsaretoobold~tyandgiveoverthisattempt~275":"Célia — Jovem cavalheiro, vossos ânimos são ousados demais para vossos anos. Vistes cruel prova da força deste homem: se vos vísseis com vossos olhos ou vos conhecêsseis com vosso juízo, o medo de vossa aventura vos aconselharia uma empresa mais igual. Rogamo-vos, por vosso próprio bem, que abraceis vossa segurança e abandoneis esta tentativa.","rosalinddoyoungsiryourreputationshallnot~estlingmightnotgoforward~121":"Rosalinda — Fazei-o, jovem senhor; vossa reputação não será por isso menosprezada: faremos de nosso pedido ao duque que a luta não prossiga.","orlandoibeseechyoupunishmenotwithyourhar~liedwhenihavemadeitempty~411":"Orlando — Suplico-vos, não me castigueis com vossos duros pensamentos; no que confesso ser muito culpado, em negar algo a tão belas e excelentes damas. Mas que vossos belos olhos e gentis desejos me acompanhem à minha prova: na qual, se eu for vencido, só um será envergonhado que nunca foi agraciado; se morto, só um morto que estava disposto a sê-lo: não farei mal a meus amigos, pois não tenho quem me lamente, nem injúria ao mundo, pois nele nada tenho; apenas no mundo ocupo um lugar, que poderá ser melhor preenchido quando eu o tiver esvaziado.","rosalindthelittlestrengththatihaveiwould~ihaveiwoulditwerewithyou~53":"Rosalinda — A pouca força que tenho, quisera que estivesse convosco.","celiaandminetoekeouthers~celiaandminetoekeouthers~24":"Célia — E a minha, para completar a dela.","rosalindfareyouwellprayheavenibedeceived~ayheavenibedeceivedinyou~45":"Rosalinda — Adeus: queira o céu que eu me engane a vosso respeito!","celiayourheartsdesiresbewithyou~urheartsdesiresbewithyou~31":"Célia — Que os desejos de vosso coração estejam convosco!","charlescomewhereisthisyounggallantthatis~stoliewithhismotherearth~73":"Charles — Vamos, onde está esse jovem galante tão desejoso de deitar-se com sua mãe terra?","orlandoreadysirbuthiswillhathinitamoremo~thinitamoremodestworking~51":"Orlando — Pronto, senhor; mas a vontade dele tem nisso uma obra mais modesta.","dukefrederickyoushalltrybutonefall~ickyoushalltrybutonefall~34":"Duque Frederico — Tentareis apenas uma queda.","charlesnoiwarrantyourgraceyoushallnotent~lypersuadedhimfromafirst~96":"Charles — Não, garanto a vossa graça, não o levareis a uma segunda, vós que tão poderosamente o persuadistes de uma primeira.","orlandoanyoumeantomockmeafteryoushouldno~dmebeforebutcomeyourways~74":"Orlando — Se pretendeis zombar de mim depois, não deveríeis ter zombado de mim antes: mas vinde.","rosalindnowherculesbethyspeedyoungman~rculesbethyspeedyoungman~37":"Rosalinda — Agora Hércules te dê pressa, jovem!","celiaiwouldiwereinvisibletocatchthestron~ellowbythelegtheywrestle~66":"Célia — Quisera ser invisível, para agarrar pela perna o forte rapaz. Lutam.","rosalindoexcellentyoungman~salindoexcellentyoungman~26":"Rosalinda — Oh, excelente jovem!","celiaifihadathunderboltinmineeyeicantell~downshoutcharlesisthrown~73":"Célia — Se eu tivesse um raio no olho, posso dizer quem cairia. Gritos. Charles é derrubado.","dukefredericknomorenomore~ukefredericknomorenomore~25":"Duque Frederico — Basta, basta.","orlandoyesibeseechyourgraceiamnotyetwell~aceiamnotyetwellbreathed~48":"Orlando — Não, suplico a vossa graça: ainda não recuperei bem o fôlego.","dukefrederickhowdostthoucharles~derickhowdostthoucharles~31":"Duque Frederico — Como estás, Charles?","lebeauhecannotspeakmylord~ebeauhecannotspeakmylord~25":"Le Beau — Ele não pode falar, meu senhor.","dukefrederickbearhimawaywhatisthynameyou~waywhatisthynameyoungman~45":"Duque Frederico — Levai-o daqui. Qual é teu nome, jovem?","orlandoorlandomyliegetheyoungestsonofsir~estsonofsirrowlanddeboys~53":"Orlando — Orlando, meu senhor; o filho mais novo de Sir Rowland de Boys.","dukefrederickiwouldthouhadstbeensontosom~efredericktrainandlebeau~291":"Duque Frederico — Quisera que fosses filho de algum outro homem:\nO mundo estimava honrado teu pai,\nMas eu o achei sempre meu inimigo:\nMais me terias agradado com esta façanha,\nTivesses descendido de outra casa.\nMas passa bem; és um jovem galante:\nQuisera que me tivesses falado de outro pai. Saem o Duque Frederico, o séquito e Le Beau.","celiawereimyfathercozwouldidothis~imyfathercozwouldidothis~33":"Célia — Fosse eu meu pai, prima, faria isto?","orlandoiammoreproudtobesirrowlandssonhis~beadoptedheirtofrederick~105":"Orlando — Mais orgulho tenho de ser filho de Sir Rowland,\nSeu filho mais novo; e não trocaria essa condição\nPara ser adotado herdeiro de Frederico.","rosalindmyfatherlovedsirrowlandashissoul~heshouldthushaveventured~170":"Rosalinda — Meu pai amava Sir Rowland como a sua alma,\nE todo o mundo era da opinião de meu pai:\nTivesse eu sabido antes que este jovem era seu filho,\nEu lhe teria dado lágrimas junto às súplicas,\nAntes que ele assim se aventurasse.","celiagentlecousinletusgothankhimandencou~yourmistressshallbehappy~208":"Célia — Gentil prima,\nVamos agradecer-lhe e animá-lo:\nA rude e invejosa índole de meu pai\nMe fere no coração. Senhor, bem merecestes:\nSe cumprirdes vossas promessas de amor\nSó com justiça, como excedestes toda promessa,\nVossa dama será feliz.","rosalindgentlemangivinghimachainfromhern~ndlacksmeansshallwegocoz~133":"Rosalinda — Cavalheiro, Dando-lhe uma corrente do pescoço. Usai isto por mim, alguém desavindo com a fortuna,\nQue daria mais, não fosse a mão dela sem meios.\nVamos, prima?","celiaayfareyouwellfairgentleman~fareyouwellfairgentleman~31":"Célia — Sim. Passai bem, belo cavalheiro.","orlandocaninotsayithankyoumybetterpartsa~intainamerelifelessblock~111":"Orlando — Não posso dizer: agradeço-vos? Minhas melhores partes\nEstão todas derrubadas, e o que aqui se ergue\nÉ apenas um boneco de treino, um mero bloco sem vida.","rosalindhecallsusbackmypridefellwithmyfo~hrownmorethanyourenemies~133":"Rosalinda — Ele nos chama de volta: meu orgulho caiu com minha fortuna;\nPerguntarei o que deseja. Chamastes, senhor?\nSenhor, lutastes bem e derrubastes\nMais do que vossos inimigos.","celiawillyougocoz~celiawillyougocoz~17":"Célia — Vamos, prima?","rosalindhavewithyoufareyouwellexeuntrosa~llexeuntrosalindandcelia~52":"Rosalinda — Vou convosco. Passai bem. Saem Rosalinda e Célia.","orlandowhatpassionhangstheseweightsuponm~methingweakermastersthee~151":"Orlando — Que paixão pendura estes pesos em minha língua?\nNão posso falar-lhe, embora ela pedisse conversa.\nÓ pobre Orlando, estás derrubado!\nOu Charles ou algo mais fraco te domina.","reenterlebeau~reenterlebeau~13":"Entra de novo Le Beau.","lebeaugoodsiridoinfriendshipcounselyouto~toconceivethanitospeakof~242":"Le Beau — Bom senhor, aconselho-vos em amizade\nA deixar este lugar. Embora tenhais merecido\nAlto louvor, verdadeiro aplauso e amor,\nContudo tal é agora a condição do duque\nQue ele interpreta mal tudo o que fizestes.\nO duque é de humor instável; o que ele é na verdade,\nMais vos convém conceber do que a mim falar.","orlandoithankyousirandprayyoutellmethisw~hatherewasatthewrestling~97":"Orlando — Agradeço-vos, senhor: e, rogo-vos, dizei-me isto:\nQual das duas era a filha do duque\nque estava aqui na luta?","lebeauneitherhisdaughterifwejudgebymanne~oreloveandknowledgeofyou~516":"Le Beau — Nenhuma é sua filha, se julgarmos pelos modos;\nMas na verdade a menor é a filha dele;\nA outra é filha do duque banido,\nE aqui retida pelo tio usurpador,\nPara fazer companhia à filha dele; cujos afetos\nSão mais caros que o laço natural de irmãs.\nMas posso dizer-vos que há pouco este duque\nTomou desagrado contra a gentil sobrinha,\nFundado em nenhum outro argumento\nSenão que o povo a louva por suas virtudes\nE a lastima pelo bem de seu bom pai;\nE, por minha vida, sua malícia contra a dama\nIrromperá de súbito. Senhor, passai bem:\nDe ora em diante, num mundo melhor que este,\nDesejarei mais amizade e conhecimento de vós.","orlandoirestmuchboundentoyoufareyouwelle~rbutheavenlyrosalindexit~139":"Orlando — Fico-vos muito obrigado: passai bem. Sai Le Beau.\nAssim devo ir da fumaça para o sufoco;\nDo duque tirano para um irmão tirano:\nMas celestial Rosalinda! Sai.","sceneiii~sceneiii~8":"Cena III","aroominthepalace~aroominthepalace~16":"Uma sala no palácio.","celiawhycousinwhyrosalindcupidhavemercyn~ndcupidhavemercynotaword~47":"Célia — Ora, prima! ora, Rosalinda! Cupido tenha piedade! nem uma palavra?","rosalindnotonetothrowatadog~alindnotonetothrowatadog~27":"Rosalinda — Nem uma para atirar a um cão.","celianothywordsaretooprecioustobecastawa~tmecomelamemewithreasons~89":"Célia — Não, tuas palavras são preciosas demais para serem lançadas a vira-latas; atira algumas a mim; vamos, aleija-me com razões.","rosalindthenthereweretwocousinslaidupwhe~andtheothermadwithoutany~95":"Rosalinda — Então haveria duas primas de cama; quando uma fosse aleijada com razões e a outra louca sem nenhuma.","celiabutisallthisforyourfather~utisallthisforyourfather~30":"Célia — Mas é tudo isto por teu pai?","rosalindnosomeofitisformychildsfatheroho~ersisthisworkingdayworld~74":"Rosalinda — Não, parte é pelo pai de meus filhos. Oh, quão cheio de espinhos é este mundo de dias de trabalho!","celiatheyarebutburscousinthrownupontheei~ypetticoatswillcatchthem~113":"Célia — São só carrapichos, prima, atirados sobre ti em tolice de feriado: se não andamos pelos caminhos batidos, nossas próprias anáguas os apanham.","rosalindicouldshakethemoffmycoatthesebur~oatthesebursareinmyheart~53":"Rosalinda — Poderia sacudi-los da minha saia: estes carrapichos estão em meu coração.","celiahemthemaway~celiahemthemaway~16":"Célia — Tosse-os para fora.","rosalindiwouldtryificouldcryhemandhavehi~ificouldcryhemandhavehim~41":"Rosalinda — Tentaria, se pudesse tossir “hem” e tê-lo.","celiacomecomewrestlewiththyaffections~wrestlewiththyaffections~37":"Célia — Vamos, vamos, luta com tuas afeições.","rosalindotheytakethepartofabetterwrestle~betterwrestlerthanmyself~51":"Rosalinda — Oh, elas tomam o partido de um lutador melhor que eu!","celiaoagoodwishuponyouyouwilltryintimein~ldsirrowlandsyoungestson~194":"Célia — Oh, um bom desejo sobre ti! tentarás a tempo, apesar de uma queda. Mas, pondo de lado estas pilhérias, falemos a sério: é possível que, tão de repente, tenhas caído em tão forte afeição pelo filho mais novo do velho Sir Rowland?","rosalindthedukemyfatherlovedhisfatherdea~therlovedhisfatherdearly~43":"Rosalinda — O duque, meu pai, amava seu pai ternamente.","celiadothitthereforeensuethatyoushouldlo~dearlyyetihatenotorlando~134":"Célia — Segue-se por isso que deves amar ternamente o filho dele? Por esse tipo de raciocínio, eu deveria odiá-lo, pois meu pai odiava ternamente o pai dele; contudo não odeio Orlando.","rosalindnofaithhatehimnotformysake~faithhatehimnotformysake~34":"Rosalinda — Não, na verdade, não o odeies, por mim.","celiawhyshouldinotdothhenotdeservewell~inotdothhenotdeservewell~38":"Célia — Por que não deveria? não merece ele bem?","rosalindletmelovehimforthatanddoyouloveh~eidolookherecomestheduke~72":"Rosalinda — Deixa-me amá-lo por isso, e ama-o tu porque eu o amo. Olha, aí vem o duque.","celiawithhiseyesfullofanger~iawithhiseyesfullofanger~27":"Célia — Com os olhos cheios de ira.","enterdukefrederickwithlords~erdukefrederickwithlords~27":"Entram o Duque Frederico, com Nobres.","dukefrederickmistressdispatchyouwithyour~steandgetyoufromourcourt~72":"Duque Frederico — Senhora, despacha-te com a mais segura pressa\nE sai de nossa corte.","rosalindmeuncle~rosalindmeuncle~15":"Rosalinda — Eu, tio?","dukefrederickyoucousinwithinthesetendays~wentymilesthoudiestforit~106":"Duque Frederico — Tu, sobrinha:\nSe dentro destes dez dias fores achada\nTão perto de nossa corte pública quanto vinte milhas,\nMorres por isso.","rosalindidobeseechyourgraceletmetheknowl~rndidioffendyourhighness~239":"Rosalinda — Suplico a vossa graça,\nDeixai-me levar comigo o conhecimento de minha falta:\nSe comigo mesma mantenho entendimento\nOu tenho conhecimento de meus próprios desejos,\nSe não sonho nem estou frenética —\nComo confio que não estou —, então, querido tio,\nNunca, nem em pensamento por nascer,\nOfendi vossa alteza.","dukefrederickthusdoalltraitorsiftheirpur~icetheethatitrusttheenot~126":"Duque Frederico — Assim fazem todos os traidores:\nSe sua purgação consistisse em palavras,\nSão tão inocentes quanto a própria graça:\nBasta-te que eu não confio em ti.","rosalindyetyourmistrustcannotmakemeatrai~reonthelikelihooddepends~76":"Rosalinda — Contudo vossa desconfiança não pode fazer de mim traidora:\nDizei-me em que se funda a probabilidade.","dukefrederickthouartthyfathersdaughterth~hersdaughtertheresenough~50":"Duque Frederico — És filha de teu pai; basta.","rosalindsowasiwhenyourhighnesstookhisduk~nkmypovertyistreacherous~229":"Rosalinda — Assim era eu quando vossa alteza tomou seu ducado;\nAssim era eu quando vossa alteza o baniu:\nA traição não se herda, meu senhor;\nOu, se a derivássemos de nossos parentes,\nQue tem isso a ver comigo? meu pai não era traidor:\nEntão, bom senhor, não me interpreteis tão mal\nQue penseis traiçoeira a minha pobreza.","celiadearsovereignhearmespeak~dearsovereignhearmespeak~29":"Célia — Caro soberano, ouvi-me falar.","dukefrederickayceliawestaydherforyoursak~withherfatherrangedalong~75":"Duque Frederico — Sim, Célia; nós a retivemos por tua causa,\nSenão teria vagado com o pai.","celiaididnotthenentreattohaveherstayitwa~entcoupledandinseparable~264":"Célia — Eu não roguei então que ela ficasse;\nFoi vosso prazer e vossa própria compaixão:\nEu era jovem demais então para valorizá-la;\nMas agora a conheço: se ela é traidora,\nEntão também eu o sou; sempre dormimos juntas,\nLevantamos no mesmo instante, aprendemos, brincamos, comemos juntas,\nE por onde quer que fôssemos, como os cisnes de Juno,\nSempre fomos emparelhadas e inseparáveis.","dukefredericksheistoosubtlefortheeandher~passduponhersheisbanishd~275":"Duque Frederico — Ela é sutil demais para ti; e sua suavidade,\nSeu próprio silêncio e sua paciência\nFalam ao povo, e ele a lastima.\nÉs uma tola: ela te rouba o nome;\nE tu parecerás mais brilhante e mais virtuosa\nQuando ela se for. Então não abras os lábios:\nFirme e irrevogável é minha sentença\nQue sobre ela proferi; está banida.","celiapronouncethatsentencethenonmemylieg~annotliveoutofhercompany~67":"Célia — Pronunciai então essa sentença sobre mim, meu senhor:\nNão posso viver fora de sua companhia.","dukefrederickyouareafoolyounieceprovidey~untdukefrederickandlords~138":"Duque Frederico — És uma tola. Tu, sobrinha, previne-te:\nSe passares do prazo, por minha honra,\nE na grandeza de minha palavra, morres. Saem o Duque Frederico e os Nobres.","celiaomypoorrosalindwhitherwiltthougowil~otthoumoregrievedthaniam~113":"Célia — Oh, minha pobre Rosalinda, aonde irás?\nQueres trocar de pai? Dar-te-ei o meu.\nOrdeno-te, não estejas mais aflita do que eu.","rosalindihavemorecause~rosalindihavemorecause~22":"Rosalinda — Tenho mais motivo.","celiathouhastnotcousinpritheebecheerfulk~hathbanishdmehisdaughter~83":"Célia — Não tens, prima;\nPeço-te, sê alegre: não sabes que o duque\nBaniu a mim, sua filha?","rosalindthathehathnot~rosalindthathehathnot~21":"Rosalinda — Isso ele não fez.","celianohathnotrosalindlacksthenthelovewh~ucanstillgoalongwiththee~338":"Célia — Não, não fez? Falta então a Rosalinda o amor\nQue te ensina que tu e eu somos uma só:\nSeremos separadas? nos apartaremos, doce menina?\nNão: que meu pai procure outra herdeira.\nPortanto planeja comigo como fugiremos,\nPara onde iremos e o que levaremos conosco;\nE não procures tomar a mudança só para ti,\nPara carregar sozinha tuas dores e deixar-me de fora;\nPois, por este céu, agora pálido por nossas tristezas,\nDiz o que puderes, irei contigo.","rosalindwhywhithershallwego~alindwhywhithershallwego~27":"Rosalinda — Ora, para onde iremos?","celiatoseekmyuncleintheforestofarden~yuncleintheforestofarden~36":"Célia — Procurar meu tio na floresta de Arden.","rosalindalaswhatdangerwillitbetousmaidsa~eththievessoonerthangold~100":"Rosalinda — Ai, que perigo será para nós,\nDonzelas como somos, viajar tão longe!\nA beleza provoca ladrões mais cedo que o ouro.","celiaillputmyselfinpoorandmeanattireandw~ngandneverstirassailants~119":"Célia — Vestir-me-ei com roupa pobre e humilde\nE com uma espécie de terra de sombra mancharei o rosto;\nFaze o mesmo: assim passaremos\nE nunca agitaremos assaltantes.","rosalindwereitnotbetterbecausethatiammor~aceitwiththeirsemblances~279":"Rosalinda — Não seria melhor,\nPorque sou mais que comumente alta,\nQue eu me vestisse em todos os pontos como um homem?\nUm galante alfanje na coxa,\nUma lança de caçar javali na mão; e — em meu coração\nJaza o medo escondido de mulher que houver —\nTeremos um exterior fanfarrão e marcial,\nComo muitos outros covardes de aparência varonil\nQue enfrentam o mundo com suas aparências.","celiawhatshallicalltheewhenthouartaman~icalltheewhenthouartaman~38":"Célia — Como te chamarei quando fores homem?","rosalindillhavenoworseanamethanjovesownp~edebutwhatwillyoubecalld~97":"Rosalinda — Não terei nome pior que o do próprio pajem de Júpiter;\nE portanto cuida de chamar-me Ganimedes.\nMas como serás chamada?","celiasomethingthathathareferencetomystat~tenolongerceliabutaliena~63":"Célia — Algo que tenha relação com meu estado:\nNão mais Célia, mas Aliena.","rosalindbutcousinwhatifweassaydtostealth~notbeacomforttoourtravel~105":"Rosalinda — Mas, prima, que tal se tentássemos furtar\nO bobo rústico da corte de teu pai?\nNão seria ele um conforto em nossa viagem?","celiahellgoalongoerthewideworldwithmelea~andnottobanishmentexeunt~227":"Célia — Ele irá comigo pelo vasto mundo;\nDeixa comigo o persuadi-lo. Vamos,\nE juntemos nossas joias e nossa riqueza,\nPlanejemos o tempo mais adequado e o caminho mais seguro\nPara nos ocultar da perseguição que será feita\nApós minha fuga. Agora vamos contentes\nÀ liberdade e não ao banimento. Saem.","theforestofarden~theforestofarden~16":"A Floresta de Arden.","enterdukesenioramiensandtwoorthreelordsl~rthreelordslikeforesters~52":"Entram o Duque Sênior, Amiens e dois ou três Nobres, vestidos de caçadores.","dukeseniornowmycomatesandbrothersinexile~rythingiwouldnotchangeit~595":"Duque Sênior — Agora, meus companheiros e irmãos no exílio,\nNão tornou o velho costume esta vida mais doce\nQue a da pompa pintada? Não estão estes bosques\nMais livres de perigo que a corte invejosa?\nAqui sentimos apenas a pena de Adão,\nA diferença das estações, como a presa gelada\nE a repreensão rude do vento do inverno,\nQue, quando morde e sopra sobre o meu corpo,\nAté eu me encolher de frio, sorrio e digo:\n“Isto não é lisonja: estes são conselheiros\nQue, sentidamente, me persuadem do que sou.”\nDoces são os usos da adversidade,\nQue, como o sapo, feio e venenoso,\nTraz contudo uma joia preciosa na cabeça;\nE esta nossa vida, isenta do convívio público,\nEncontra línguas nas árvores, livros nos riachos que correm,\nSermões nas pedras e bem em todas as coisas.\nNão a trocaria.","amienshappyisyourgracethatcantranslateth~osoquietandsosweetastyle~89":"Amiens — Feliz é vossa graça,\nQue pode traduzir a teimosia da fortuna\nNum estilo tão quieto e tão doce.","dukeseniorcomeshallwegoandkillusvenisona~etheirroundhaunchesgored~173":"Duque Sênior — Vamos, iremos matar-nos veação?\nE contudo me aflige que os pobres tolos malhados,\nSendo burgueses nativos desta cidade deserta,\nDevam em seus próprios confins, com setas de ponta bifurca,\nTer as ancas redondas traspassadas.","firstlordindeedmylordthemelancholyjaques~ookaugmentingitwithtears~624":"Primeiro Nobre — Na verdade, meu senhor,\nO melancólico Jaques se aflige com isso,\nE, nesse particular, jura que usurpais mais\nDo que vosso irmão que vos baniu.\nHoje o senhor de Amiens e eu\nEsgueiramo-nos por trás dele, enquanto jazia estendido\nSob um carvalho cuja raiz antiga espia\nSobre o riacho que murmura por este bosque:\nPara esse lugar um pobre cervo isolado,\nQue da mira do caçador levara um ferimento,\nVeio a definhar, e na verdade, meu senhor,\nO desgraçado animal soltou tais gemidos\nQue a descarga deles esticou-lhe o couro\nQuase a rebentar, e as grandes lágrimas redondas\nCorriam umas atrás das outras pelo seu nariz inocente\nEm perseguição piedosa; e assim o tolo peludo,\nMuito notado pelo melancólico Jaques,\nPôs-se à borda extrema do riacho veloz,\nAumentando-o com lágrimas.","dukeseniorbutwhatsaidjaquesdidhenotmoral~notmoralizethisspectacle~56":"Duque Sênior — Mas que disse Jaques?\nNão moralizou este espetáculo?","firstlordoyesintoathousandsimilesfirstfo~ndandnativedwellingplace~645":"Primeiro Nobre — Oh, sim, em mil comparações.\nPrimeiro, por seu choro no riacho que não precisava:\n“Pobre cervo”, disse ele, “fazes um testamento\nComo fazem os mundanos, dando o teu resto\nÀquilo que já tinha demais”; depois, estando ali sozinho,\nDeixado e abandonado por seus amigos de veludo,\n“É certo”, disse ele; “assim a miséria aparta\nO fluxo da companhia”; logo uma manada despreocupada,\nCheia de pasto, salta ao lado dele\nE nunca para para saudá-lo; “Sim”, diz Jaques,\n“Passai, gordos e untuosos cidadãos;\nÉ exatamente a moda: por que olhais\nPara aquele pobre falido arruinado ali?”\nAssim, com a mais veemente invectiva, ele trespassa\nO corpo do campo, da cidade, da corte,\nSim, e também desta nossa vida, jurando que nós\nSomos meros usurpadores, tiranos e, o que é pior,\nPor assustar os animais e matá-los\nNo lugar de morada que lhes foi designado e é nativo.","dukesenioranddidyouleavehiminthiscontemp~vehiminthiscontemplation~46":"Duque Sênior — E o deixastes nesta contemplação?","secondlordwedidmylordweepingandcommentin~entinguponthesobbingdeer~59":"Segundo Nobre — Deixamos, meu senhor, chorando e comentando\nSobre o cervo soluçante.","dukeseniorshowmetheplaceilovetocopehimin~tsforthenhesfullofmatter~77":"Duque Sênior — Mostrai-me o lugar:\nGosto de enfrentá-lo nesses acessos sombrios,\nPois então está cheio de matéria.","firstlordillbringyoutohimstraightexeunt~ngyoutohimstraightexeunt~39":"Primeiro Nobre — Levar-vos-ei a ele já. Saem.","dukefrederickcanitbepossiblethatnomansaw~nsentandsufferanceinthis~106":"Duque Frederico — Pode ser possível que ninguém as viu?\nNão pode ser: alguns vilões de minha corte\nTêm nisto consentimento e conivência.","firstlordicannothearofanythatdidseeherth~treasuredoftheirmistress~143":"Primeiro Nobre — Não ouço falar de ninguém que a tenha visto.\nAs damas, suas servas de câmara,\nViram-na deitada, e de manhã cedo\nAcharam o leito sem o tesouro de sua senhora.","secondlordmylordtheroynishclownatwhomsoo~thissurelyintheircompany~305":"Segundo Nobre — Meu senhor, o bufão ranhoso, de quem tantas vezes\nVossa graça costumava rir, também desapareceu.\nHespéria, dama de companhia da princesa,\nConfessa que ouviu em segredo\nVossa filha e sua prima louvarem muito\nAs qualidades e graças do lutador\nQue há pouco derrubou o nervudo Charles;\nE ela crê, para onde quer que tenham ido,\nQue aquele jovem está certamente em sua companhia.","dukefredericksendtohisbrotherfetchthatga~esefoolishrunawaysexeunt~185":"Duque Frederico — Mandai buscar o irmão dele; trazei aqui esse galante;\nSe ele estiver ausente, trazei-me o irmão;\nFarei que o encontre: fazei isto prontamente,\nE não deixeis que a busca e a inquirição esmoreçam\nPara trazer de volta essas tolas fugitivas. Saem.","beforeolivershouse~beforeolivershouse~18":"Diante da casa de Oliver.","enterorlandoandadammeeting~terorlandoandadammeeting~26":"Entram Orlando e Adão, encontrando-se.","orlandowhosthere~orlandowhosthere~16":"Orlando — Quem está aí?","adamwhatmyyoungmasteromygentlemasteromys~lyenvenomshimthatbearsit~454":"Adão — Como, meu jovem amo? Oh, meu gentil amo!\nOh, meu doce amo! Oh, tu, memória\nDo velho Sir Rowland! ora, que fazeis aqui?\nPor que sois virtuoso? por que o povo vos ama?\nE por que sois gentil, forte e valente?\nPor que fostes tão tolo a ponto de vencer\nO belo lutador do duque de humor instável?\nVosso louvor chegou rápido demais antes de vós.\nNão sabeis, amo, que a certos homens\nSuas graças servem apenas de inimigas?\nNão menos as vossas: vossas virtudes, gentil amo,\nSão traidoras santificadas e sagradas contra vós.\nOh, que mundo é este, quando o que é belo\nEnvenena quem o carrega!","orlandowhywhatsthematter~orlandowhywhatsthematter~24":"Orlando — Ora, que há?","adamounhappyyouthcomenotwithinthesedoors~bhoritfearitdonotenterit~391":"Adão — Oh, infeliz jovem!\nNão entreis por estas portas; sob este teto\nVive o inimigo de todas as vossas graças:\nVosso irmão — não, não irmão; contudo o filho —\nContudo não o filho, não o chamarei filho\nDaquele a quem eu ia chamar seu pai —\nOuviu vossos louvores, e esta noite pretende\nQueimar o alojamento onde costumais deitar-vos\nE vós dentro dele: se falhar nisso,\nTerá outros meios de vos eliminar.\nOuvi-o a ele e a suas tramas.\nEste não é lugar; esta casa não passa de um matadouro:\nAbominai-a, temei-a, não entreis nela.","orlandowhywhitheradamwouldstthouhavemego~radamwouldstthouhavemego~40":"Orlando — Ora, para onde, Adão, queres que eu vá?","adamnomatterwhithersoyoucomenothere~rwhithersoyoucomenothere~35":"Adão — Não importa para onde, contanto que não venhais aqui.","orlandowhatwouldstthouhavemegoandbegmyfo~tedbloodandbloodybrother~225":"Orlando — Como, queres que eu vá mendigar meu alimento?\nOu com uma espada vil e violenta imponha\nUma vida de ladrão na estrada comum?\nIsto devo fazer, ou não sei o que fazer:\nContudo isto não farei, faça o que puder;\nAntes me submeterei à malícia\nDe um sangue desviado e de um irmão sanguinário.","adambutdonotsoihavefivehundredcrownsthet~urbusinessandnecessities~573":"Adão — Mas não façais assim. Tenho quinhentas coroas,\nO salário poupado que economizei sob vosso pai,\nQue guardei para ser minha ama-de-leite\nQuando o serviço ficasse coxo em meus velhos membros\nE a idade desatendida fosse jogada em cantos:\nTomai isso, e Aquele que alimenta os corvos,\nSim, provê com previdência o pardal,\nSeja conforto de minha velhice! Aqui está o ouro;\nE tudo isto vos dou. Deixai-me ser vosso servo:\nEmbora pareça velho, sou ainda forte e vigoroso;\nPois em minha juventude nunca apliquei\nLicores quentes e rebeldes ao meu sangue,\nNem cortejei com fronte despudorada\nOs meios da fraqueza e debilidade;\nPor isso minha velhice é como um inverno vigoroso,\nGeado, mas benigno: deixai-me ir convosco;\nFarei o serviço de um homem mais jovem\nEm todos os vossos negócios e necessidades.","orlandoogoodoldmanhowwellintheeappearsth~ponsomesettledlowcontent~439":"Orlando — Oh, bom velho, quão bem aparece em ti\nO serviço constante do mundo antigo,\nQuando o serviço suava por dever, não por paga!\nNão és para a moda destes tempos,\nEm que ninguém quer suar senão por promoção,\nE, tendo-a, sufoca o serviço\nPelo próprio ter: não é assim contigo.\nMas, pobre velho, podas uma árvore podre,\nQue não pode dar sequer uma flor\nEm troca de todo o teu trabalho e lavoura.\nMas vem; iremos juntos,\nE antes que tenhamos gasto teu salário de jovem,\nTopraremos com algum humilde contentamento assentado.","adammastergoonandiwillfollowtheetothelas~notmymastersdebtorexeunt~275":"Adão — Amo, ide, e eu vos seguirei,\nAté o último suspiro, com verdade e lealdade.\nDos dezessete anos até agora quase oitenta\nAqui vivi, mas agora aqui não vivo mais.\nAos dezessete muitos buscam fortuna;\nMas aos oitenta é semana tarde demais:\nContudo a fortuna não pode recompensar-me melhor\nDo que morrer bem e sem dever ao meu amo. Saem.","sceneiv~sceneiv~7":"Cena IV","enterrosalindforganymedeceliaforalienaan~iaforalienaandtouchstone~51":"Entram Rosalinda como Ganimedes, Célia como Aliena, e Touchstone.","rosalindojupiterhowwearyaremyspirits~iterhowwearyaremyspirits~36":"Rosalinda — Oh, Júpiter, quão cansados estão meus ânimos!","touchstoneicarenotformyspiritsifmylegswe~ritsifmylegswerenotweary~50":"Touchstone — Não me importo com meus ânimos, se minhas pernas não estivessem cansadas.","rosalindicouldfindinmyhearttodisgracemym~ereforecouragegoodaliena~178":"Rosalinda — Tenho vontade de desonrar minhas roupas de homem e chorar como mulher; mas devo confortar o vaso mais fraco, pois gibão e calções devem mostrar-se corajosos para a anágua: portanto coragem, boa Aliena!","celiaiprayyoubearwithmeicannotgonofurthe~withmeicannotgonofurther~41":"Célia — Peço-vos, tende paciência comigo; não posso ir mais longe.","touchstoneformypartihadratherbearwithyou~ouhavenomoneyinyourpurse~119":"Touchstone — De minha parte, antes ter paciência convosco que carregar-vos; contudo eu não carregaria cruz alguma se vos carregasse, pois penso que não tendes dinheiro na bolsa.","rosalindwellthisistheforestofarden~llthisistheforestofarden~34":"Rosalinda — Pois bem, esta é a floresta de Arden.","touchstoneaynowamiinardenthemorefooliwhe~ttravellersmustbecontent~95":"Touchstone — Sim, agora estou em Arden; mais tolo eu; quando estava em casa, estava em lugar melhor: mas viajantes devem contentar-se.","rosalindaybesogoodtouchstone~lindaybesogoodtouchstone~28":"Rosalinda — Sim, sê assim, bom Touchstone.","entercorinandsilvius~entercorinandsilvius~20":"Entram Corin e Sílvio.","lookyouwhocomeshereayoungmanandanoldinso~gmanandanoldinsolemntalk~48":"Olhai, quem vem aí; um jovem e um velho em solene conversa.","corinthatisthewaytomakeherscornyoustill~aytomakeherscornyoustill~39":"Corin — Esse é o caminho para fazê-la desprezar-te sempre.","silviusocorinthatthouknewsthowidoloveher~tthouknewsthowidoloveher~40":"Sílvio — Oh, Corin, quem dera soubesses como a amo!","corinipartlyguessforihavelovederenow~guessforihavelovederenow~36":"Corin — Adivinho em parte; pois já amei antes.","silviusnocorinbeingoldthoucanstnotguesst~ubeendrawntobythyfantasy~223":"Sílvio — Não, Corin, sendo velho, não podes adivinhar,\nEmbora em tua juventude fosses um amante tão verdadeiro\nQuanto qualquer que suspirou sobre um travesseiro à meia-noite:\nMas se teu amor foi alguma vez como o meu —\nPois certo penso que nunca homem amou assim —\nA quantas ações as mais ridículas\nTe levou a tua fantasia?","corinintoathousandthatihaveforgotten~ousandthatihaveforgotten~36":"Corin — A mil que esqueci.","silviusothoudidstthenneerlovesoheartilyi~ovedophebephebephebeexit~295":"Sílvio — Oh, então nunca amaste tão cordialmente!\nSe não te lembras da mais leve tolice\nEm que o amor te fez cair,\nNão amaste:\nOu se não sentaste como eu agora,\nCansando teu ouvinte no louvor de tua senhora,\nNão amaste:\nOu se não saíste da companhia\nAbruptamente, como minha paixão agora me faz,\nNão amaste.\nOh, Febe, Febe, Febe! Sai.","rosalindalaspoorshepherdsearchingofthywo~ardadventurefoundmineown~75":"Rosalinda — Ai, pobre pastor! sondando tua ferida,\nPor dura aventura achei a minha.","touchstoneandimineirememberwheniwasinlov~atureinlovemortalinfolly~403":"Touchstone — E eu a minha. Lembro-me de que, quando estava apaixonado, quebrei minha espada numa pedra e mandei-a tomar isso por vir de noite a Joana Sorriso; e lembro-me do beijar o seu batedor de roupa e as tetas da vaca que suas bonitas mãos rachadas ordenharam; e lembro-me do cortejar uma vagem de ervilha em vez dela, da qual tirei duas ervilhas e, devolvendo-lhas, disse com lágrimas chorosas: “Usai-as por mim.” Nós, que somos verdadeiros amantes, caímos em estranhas cabriolas; mas, como tudo é mortal na natureza, assim tudo na natureza do amor é mortal em tolice.","rosalindthouspeakestwiserthanthouartware~stwiserthanthouartwareof~42":"Rosalinda — Falas mais sabiamente do que percebes.","touchstonenayishallneerbewareofmineownwi~llibreakmyshinsagainstit~67":"Touchstone — Não, nunca perceberei meu próprio engenho até quebrar as canelas nele.","rosalindjovejovethisshepherdspassionismu~ssionismuchuponmyfashion~55":"Rosalinda — Jove, Jove! a paixão deste pastor\nÉ muito parecida com a minha.","touchstoneandminebutitgrowssomethingstal~rowssomethingstalewithme~47":"Touchstone — E com a minha; mas já está um tanto passada para mim.","celiaiprayyouoneofyouquestionyondmanifhe~yfoodifaintalmosttodeath~83":"Célia — Peço-vos, um de vós interrogue aquele homem\nSe por ouro nos dará algum alimento:\nDesfaleço quase até a morte.","touchstonehollayouclown~touchstonehollayouclown~23":"Touchstone — Olá, tu, rústico!","rosalindpeacefoolhesnotthykinsman~eacefoolhesnotthykinsman~33":"Rosalinda — Paz, bobo: ele não é teu parente.","corinwhocalls~corinwhocalls~13":"Corin — Quem chama?","touchstoneyourbetterssir~touchstoneyourbetterssir~24":"Touchstone — Vossos superiores, senhor.","corinelsearetheyverywretched~nelsearetheyverywretched~28":"Corin — Então são muito desgraçados.","rosalindpeaceisaygoodeventoyoufriend~eisaygoodeventoyoufriend~36":"Rosalinda — Paz, digo. Boa noite, amigo.","corinandtoyougentlesirandtoyouall~oyougentlesirandtoyouall~33":"Corin — E a vós, gentil senhor, e a todos vós.","rosalindipritheeshepherdifthatloveorgold~pressdandfaintsforsuccor~168":"Rosalinda — Rogo-te, pastor, se amor ou ouro\nPode neste lugar deserto comprar hospitalidade,\nLeva-nos aonde possamos descansar e alimentar-nos:\nAqui está uma jovem donzela muito oprimida pela viagem\nE desfalece por socorro.","corinfairsiripityherandwishforhersakemor~icemostwelcomeshallyoube~408":"Corin — Belo senhor, tenho pena dela\nE desejo, por ela mais que por mim,\nQue minha fortuna pudesse mais aliviá-la;\nMas sou pastor de outro homem\nE não tosquio os velos que apascento:\nMeu amo é de índole mesquinha\nE pouco se importa de achar o caminho do céu\nFazendo obras de hospitalidade:\nAlém disso, seu casebre, seus rebanhos e limites de pasto\nEstão agora à venda, e em nosso aprisco agora,\nPor causa da ausência dele, não há nada\nDe que possais alimentar-vos; mas o que há, vinde ver.\nE por minha voz sereis muito bem-vindos.","rosalindwhatishethatshallbuyhisflockandp~allbuyhisflockandpasture~46":"Rosalinda — Quem é aquele que comprará seu rebanho e pasto?","corinthatyoungswainthatyousawherebuterew~lecaresforbuyinganything~76":"Corin — Aquele jovem pastor que vistes aqui há pouco,\nQue pouco se importa de comprar coisa alguma.","rosalindipraytheeifitstandwithhonestybuy~ushalthavetopayforitofus~102":"Rosalinda — Rogo-te, se isso é compatível com a honestidade,\nCompra tu o casebre, o pasto e o rebanho,\nE terás de nós com que pagar.","celiaandwewillmendthywagesilikethisplace~nglycouldwastemytimeinit~72":"Célia — E melhoraremos teu salário. Gosto deste lugar.\nE de bom grado poderia gastar nele o meu tempo.","corinassuredlythethingistobesoldgowithme~rgoldrightsuddenlyexeunt~160":"Corin — Com certeza a coisa está para ser vendida:\nVinde comigo: se gostardes, pelo que ouvirdes,\nDo solo, do lucro e deste gênero de vida,\nSerei vosso fidelíssimo pastor\nE a comprarei com vosso ouro bem depressa. Saem.","scenev~scenev~6":"Cena V","theforest~theforest~9":"A floresta.","enteramiensjaquesandothers~teramiensjaquesandothers~26":"Entram Amiens, Jaques e outros.","song~song~4":"Canção.","amiensunderthegreenwoodtreewholovestolie~butwinterandroughweather~163":"Amiens — Sob a árvore do bosque verde\nQuem ama deitar-se comigo,\nE voltar sua alegre nota\nPara a garganta do doce pássaro,\nVenha aqui, venha aqui, venha aqui:\nAqui verá\nNenhum inimigo\nSenão o inverno e o tempo bravio.","jaquesmoremoreipritheemore~quesmoremoreipritheemore~26":"Jaques — Mais, mais, peço-te, mais.","amiensitwillmakeyoumelancholymonsieurjaq~melancholymonsieurjaques~43":"Amiens — Isso vos fará melancólico, monsieur Jaques.","jaquesithankitmoreipritheemoreicansuckme~uckseggsmoreipritheemore~92":"Jaques — Agradeço-lhe. Mais, peço-te, mais. Posso sugar melancolia de uma canção, como a doninha suga ovos. Mais, peço-te, mais.","amiensmyvoiceisraggediknowicannotpleasey~gediknowicannotpleaseyou~42":"Amiens — Minha voz está rouca: sei que não posso agradar-vos.","jaquesidonotdesireyoutopleasemeidodesire~erstanzocallyouemstanzos~86":"Jaques — Não desejo que me agrades; desejo que cantes. Vamos, mais; outra estrofe: chamais a isso estrofes?","amienswhatyouwillmonsieurjaques~hatyouwillmonsieurjaques~31":"Amiens — O que quiserdes, monsieur Jaques.","jaquesnayicarenotfortheirnamestheyowemen~yowemenothingwillyousing~57":"Jaques — Não, não me importo com os nomes; nada me devem. Quereis cantar?","amiensmoreatyourrequestthantopleasemysel~equestthantopleasemyself~41":"Amiens — Mais a vosso pedido que para agradar a mim mesmo.","jaqueswellthenifeverithankanymanillthank~atwillnotholdyourtongues~223":"Jaques — Pois bem, se algum dia agradeço a algum homem, agradecerei a vós; mas o que chamam cumprimento é como o encontro de dois macacos, e quando um homem me agradece de coração, parece-me que lhe dei um tostão e ele me devolve o agradecimento de mendigo. Vamos, cantai; e vós que não quereis, calai a língua.","amienswellillendthesongsirscoverthewhile~hbeenallthisdaytolookyou~98":"Amiens — Pois bem, terminarei a canção. Senhores, cobri a mesa entretanto; o duque beberá sob esta árvore. Ele esteve o dia todo à vossa procura.","jaquesandihavebeenallthisdaytoavoidhimhe~oastofthemcomewarblecome~146":"Jaques — E eu estive o dia todo a evitá-lo. Ele é por demais discutidor para minha companhia: penso em tantos assuntos quanto ele, mas dou graças ao céu e não me gabo deles. Vamos, gorjeai, vamos.","amienswhodothambitionshunalltogetherhere~butwinterandroughweather~180":"Amiens — Quem foge da ambição\nJunto aqui conosco,\nE ama viver ao sol,\nBuscando o alimento que come\nE contente com o que consegue,\nVenha aqui, venha aqui, venha aqui:\nAqui verá\nNenhum inimigo\nSenão o inverno e o tempo bravio.","jaquesillgiveyouaversetothisnotethatimad~ayindespiteofmyinvention~72":"Jaques — Dar-vos-ei um verso para esta música que fiz ontem, a despeito de minha invenção.","amiensandillsingit~amiensandillsingit~18":"Amiens — E eu o cantarei.","jaquesthusitgoesifitdocometopassthatanym~lsasheanifhewillcometome~160":"Jaques — Assim vai: Se chegar a acontecer\nQue algum homem vire asno,\nDeixando riqueza e conforto,\nPara agradar a uma vontade teimosa,\nDucdame, ducdame, ducdame:\nAqui verá\nTolos grosseiros como ele,\nSe quiser vir a mim.","amienswhatsthatducdame~amienswhatsthatducdame~22":"Amiens — Que é esse “ducdame”?","jaquestisagreekinvocationtocallfoolsinto~stallthefirstbornofegypt~108":"Jaques — É uma invocação grega, para chamar tolos a um círculo. Vou dormir, se puder; se não puder, vou praguejar contra todos os primogênitos do Egito.","amiensandillgoseekthedukehisbanquetispre~spreparedexeuntseverally~60":"Amiens — E eu vou procurar o duque: seu banquete está preparado. Saem separadamente.","scenevi~scenevi~7":"Cena VI","adamdearmastericangonofurtheroidieforfoo~ygravefarewellkindmaster~91":"Adão — Caro amo, não posso ir mais longe. Oh, morro de fome! Aqui me deito e meço minha sepultura. Adeus, bondoso amo.","orlandowhyhownowadamnogreaterheartinthee~ertcheerlygoodadamexeunt~573":"Orlando — Ora, que é isso, Adão! não tens mais coragem? Vive um pouco; conforta-te um pouco; anima-te um pouco. Se esta floresta selvagem der alguma coisa bravia, ou serei alimento para ela ou a trarei como alimento para ti. Teu pensamento está mais perto da morte que tuas forças. Por mim, sê confortável; segura a morte um pouco à distância de um braço: estarei aqui contigo logo; e se não te trouxer algo para comer, dar-te-ei licença para morrer: mas se morreres antes que eu venha, zombas do meu esforço. Bem dito! pareces alegre, e estarei contigo depressa. Contudo jazes ao ar gelado: vem, levar-te-ei a algum abrigo; e não morrerás por falta de jantar, se viver alguma coisa neste deserto. Ânimo, bom Adão! Saem.","scenevii~scenevii~8":"Cena VII","atablesetoutenterdukesenioramiensandlord~miensandlordslikeoutlaws~52":"Uma mesa posta. Entram o Duque Sênior, Amiens e Nobres, vestidos de foras-da-lei.","dukeseniorithinkhebetransformdintoabeast~annowherefindhimlikeaman~69":"Duque Sênior — Penso que ele foi transformado em fera;\nPois em parte alguma o encontro como homem.","firstlordmylordheisbutevennowgonehencehe~washemerryhearingofasong~66":"Primeiro Nobre — Meu senhor, ele acabou de sair daqui:\nAqui estava alegre, ouvindo uma canção.","dukeseniorifhecompactofjarsgrowmusicalwe~ellhimiwouldspeakwithhim~109":"Duque Sênior — Se ele, composto de discórdias, torna-se musical,\nTeremos logo discórdia nas esferas.\nIde, procurai-o: dizei-lhe que desejo falar-lhe.","enterjaques~enterjaques~11":"Entra Jaques.","firstlordhesavesmylabourbyhisownapproach~mylabourbyhisownapproach~40":"Primeiro Nobre — Ele me poupa o trabalho com sua própria aproximação.","dukeseniorwhyhownowmonsieurwhatalifeisth~ompanywhatyoulookmerrily~97":"Duque Sênior — Ora, então, monsieur! que vida é esta,\nEm que vossos pobres amigos devem cortejar vossa companhia?\nComo, pareceis alegre!","jaquesafoolafoolimetafoolitheforestamotl~hyfoolmotleystheonlywear~713":"Jaques — Um bobo, um bobo! Encontrei um bobo na floresta,\nUm bobo de roupa de arlequim; mundo miserável!\nComo vivo de comida, encontrei um bobo\nQue se deitou e se aqueceu ao sol,\nE vituperou a Senhora Fortuna em bons termos,\nEm bons termos estudados, e contudo um bobo de arlequim.\n“Bom dia, bobo”, disse eu. “Não, senhor”, disse ele,\n“Não me chameis bobo até que o céu me envie fortuna.”\nE então tirou um relógio de sol da bolsa,\nE, olhando-o com olho sem brilho,\nDiz muito sabiamente: “São dez horas:\nAssim podemos ver”, disse ele, “como o mundo anda:\nHá apenas uma hora eram nove,\nE daqui a mais uma hora serão onze;\nE assim, de hora em hora, amadurecemos e amadurecemos,\nE depois, de hora em hora, apodrecemos e apodrecemos;\nE daí pende um conto.” Quando ouvi\nO bobo de arlequim moralizar assim sobre o tempo,\nMeus pulmões começaram a cantar como o galo,\nPorque bobos fossem tão profundamente contemplativos,\nE ri sem intervalo\nUma hora pelo seu relógio. Oh, nobre bobo!\nDigno bobo! O arlequim é a única veste.","dukeseniorwhatfoolisthis~dukeseniorwhatfoolisthis~24":"Duque Sênior — Que bobo é este?","jaquesoworthyfoolonethathathbeenacourtie~mambitiousforamotleycoat~264":"Jaques — Oh, digno bobo! Um que foi cortesão,\nE diz que, se as damas são jovens e belas,\nTêm o dom de sabê-lo: e em seu cérebro,\nQue é seco como o biscoito que sobra\nApós uma viagem, tem lugares estranhos entulhados\nDe observação, a qual ele solta\nEm formas mutiladas. Oh, quem me dera ser um bobo!\nSou ambicioso de um casaco de arlequim.","dukeseniorthoushalthaveone~keseniorthoushalthaveone~26":"Duque Sênior — Terás um.","jaquesitismyonlysuitprovidedthatyouweedy~tientlyreceivemymedicine~576":"Jaques — É meu único pedido;\nDesde que vós capineis vossos melhores juízos\nDe toda opinião que cresce viçosa neles\nDe que sou sábio. Devo ter liberdade\nCom isso, uma carta tão larga como o vento,\nPara soprar em quem me aprouver; pois assim têm os bobos;\nE aqueles que mais se ferirem com minha tolice,\nEsses mais devem rir. E por quê, senhor, devem assim?\nO “por quê” é claro como o caminho da igreja paroquial:\nQuem é atingido muito sabiamente por um bobo\nFaz muito tolamente, ainda que doa,\nEm não parecer insensível à zombaria: se não,\nA tolice do sábio é dissecada\nAté pelos olhares dispersos do bobo.\nInvesti-me do meu arlequim; dai-me licença\nPara dizer o que penso, e eu de lado a lado\nLimparei o corpo imundo do mundo infectado,\nSe quiserem receber pacientemente meu remédio.","dukeseniorfieontheeicantellwhatthouwould~cantellwhatthouwouldstdo~44":"Duque Sênior — Vergonha sobre ti! Posso dizer o que farias.","jaqueswhatforacounterwouldidobutgood~racounterwouldidobutgood~36":"Jaques — Como, por uma moeda, que faria eu senão o bem?","dukeseniormostmischievousfoulsininchidin~gorgeintothegeneralworld~221":"Duque Sênior — O mais danoso e imundo pecado, em repreender o pecado:\nPois tu mesmo foste um libertino,\nTão sensual quanto o próprio aguilhão bruto;\nE todas as chagas em relevo e males com cabeça\nQue apanhaste com a licença de pé livre\nQuererias vomitar sobre o mundo em geral.","jaqueswhywhocriesoutonpridethatcantherei~dofanymanbutwhocomeshere~565":"Jaques — Ora, quem brada contra o orgulho,\nPode nisso acusar qualquer pessoa em particular?\nNão flui ele tão imenso quanto o mar,\nAté que os próprios meios cansados vazem?\nQue mulher da cidade nomeio,\nQuando digo que a mulher da cidade carrega\nO custo de príncipes em ombros indignos?\nQuem pode entrar e dizer que me refiro a ela,\nQuando uma como ela é tal qual sua vizinha?\nOu que é aquele da mais baixa profissão\nQue diz que sua pompa não é por minha conta,\nPensando que me refiro a ele, mas nisso ajusta\nSua tolice ao metal de minha fala?\nPois então; como então? e então? Vejamos em que\nMinha língua o ofendeu: se lhe faz justiça,\nEntão ele mesmo se ofendeu; se está livre,\nPor que então minha censura como ganso selvagem voa,\nSem ser reclamada por homem algum. Mas quem vem aí?","enterorlandowithhissworddrawn~orlandowithhissworddrawn~29":"Entra Orlando, com a espada desembainhada.","orlandoforbearandeatnomore~landoforbearandeatnomore~26":"Orlando — Para, e não comas mais.","jaqueswhyihaveeatnoneyet~jaqueswhyihaveeatnoneyet~24":"Jaques — Ora, ainda não comi nada.","orlandonorshaltnottillnecessitybeserved~nottillnecessitybeserved~39":"Orlando — Nem comerás, até que a necessidade seja servida.","jaquesofwhatkindshouldthiscockcomeof~kindshouldthiscockcomeof~36":"Jaques — De que espécie deve ser este galo?","dukeseniorartthouthusboldendmanbythydist~ivilitythouseemstsoempty~107":"Duque Sênior — És assim ousado, homem, por tua aflição,\nOu então um rude desprezador das boas maneiras,\nQue em civilidade pareces tão vazio?","orlandoyoutouchdmyveinatfirstthethornypo~iandmyaffairsareanswered~201":"Orlando — Tocastes minha veia de início: a ponta espinhosa\nDa aflição nua tirou-me a aparência\nDa civilidade polida: contudo fui criado em terra civilizada\nE conheço alguma educação. Mas para, digo:\nMorre quem tocar em qualquer destes frutos\nAté que eu e meus assuntos sejamos atendidos.","jaquesanyouwillnotbeansweredwithreasonim~sweredwithreasonimustdie~46":"Jaques — Se não quereis ser atendido pela razão, devo morrer.","dukeseniorwhatwouldyouhaveyourgentleness~rforcemoveustogentleness~85":"Duque Sênior — Que desejais? Vossa gentileza nos forçará\nMais do que vossa força nos move à gentileza.","orlandoialmostdieforfoodandletmehaveit~dieforfoodandletmehaveit~38":"Orlando — Quase morro de fome; e deixai-me tê-la.","dukeseniorsitdownandfeedandwelcometoourt~feedandwelcometoourtable~44":"Duque Sênior — Sentai-vos e comei, e sede bem-vindo à nossa mesa.","orlandospeakyousogentlypardonmeiprayyoui~hopeiblushandhidemysword~463":"Orlando — Falais tão gentilmente? Perdoai-me, rogo-vos:\nPensei que tudo aqui era selvagem;\nE por isso pus o semblante\nDe ordem severa. Mas quem quer que sejais\nQue neste deserto inacessível,\nSob a sombra de ramos melancólicos,\nPerdeis e negligenciais as horas rastejantes do tempo,\nSe alguma vez vistes dias melhores,\nSe alguma vez estivestes onde sinos dobraram para a igreja,\nSe alguma vez sentastes à festa de algum homem bom,\nSe alguma vez de vossas pálpebras enxugastes uma lágrima\nE sabeis o que é ter piedade e ser objeto de piedade,\nQue a gentileza seja minha forte coação:\nNesta esperança coro, e escondo a espada.","dukeseniortrueisitthatwehaveseenbetterda~ourwantingmaybeministerd~247":"Duque Sênior — Verdade é que vimos dias melhores,\nE fomos chamados à igreja por sino sagrado\nE sentamos à festa de homens bons e enxugamos os olhos\nDas gotas que a piedade sagrada engendrou:\nE por isso sentai-vos em gentileza\nE tomai por ordem o auxílio que temos\nQue possa ser ministrado à vossa necessidade.","orlandothenbutforbearyourfoodalittlewhil~dhungeriwillnottouchabit~219":"Orlando — Então retende vosso alimento só um pouco,\nEnquanto, como uma corça, vou achar meu filhote\nE dar-lhe comida. Há um velho pobre,\nQue após mim muitos passos cansados\nCoxeou por puro amor: até que ele seja primeiro saciado,\nOprimido de dois fracos males, idade e fome,\nNão tocarei num bocado.","dukeseniorgofindhimoutandwewillnothingwa~othingwastetillyoureturn~56":"Duque Sênior — Ide buscá-lo,\nE nada desperdiçaremos até que volteis.","orlandoithankyeandbeblestforyourgoodcomf~stforyourgoodcomfortexit~47":"Orlando — Agradeço-vos; e sejais abençoados por vosso bom conforto! Sai.","dukeseniorthouseestwearenotallaloneunhap~nthescenewhereinweplayin~122":"Duque Sênior — Vês que não somos os únicos infelizes:\nEste vasto e universal teatro\nApresenta espetáculos mais lastimosos que a cena\nEm que representamos.","jaquesalltheworldsastageandallthemenandw~ssanstastesanseverything~970":"Jaques — O mundo inteiro é um palco,\nE todos os homens e mulheres meros atores:\nTêm suas saídas e suas entradas;\nE um homem em seu tempo representa muitos papéis,\nSendo seus atos sete idades. De início o bebê,\nChoramingando e vomitando nos braços da ama.\nE depois o colegial lamurioso, com sua mochila\nE rosto matinal reluzente, arrastando-se como caracol\nRelutante para a escola. E depois o amante,\nSuspirando como fornalha, com uma balada lastimosa\nFeita à sobrancelha de sua amada. Depois um soldado,\nCheio de estranhos juramentos e barbado como o leopardo,\nCioso de honra, súbito e rápido na briga,\nBuscando a bolha da reputação\nAté na boca do canhão. E depois o juiz,\nDe belo ventre redondo forrado de bom capão,\nCom olhos severos e barba de corte formal,\nCheio de sábios ditados e exemplos modernos;\nE assim representa o seu papel. A sexta idade passa\nAo magro e pantufado pantalão,\nCom óculos no nariz e bolsa ao lado,\nSeus calções de jovem, bem guardados, um mundo largos demais\nPara a canela encolhida; e sua grande voz viril,\nVoltando de novo ao agudo infantil, apita\nE assobia em seu som. A última cena de todas,\nQue encerra esta estranha história cheia de eventos,\nÉ a segunda infância e puro esquecimento,\nSem dentes, sem olhos, sem gosto, sem tudo.","reenterorlandowithadam~reenterorlandowithadam~22":"Entra de novo Orlando, com Adão.","dukeseniorwelcomesetdownyourvenerablebur~ableburthenandlethimfeed~57":"Duque Sênior — Bem-vindo. Pousai vosso venerável fardo,\nE deixai-o comer.","orlandoithankyoumostforhim~landoithankyoumostforhim~26":"Orlando — Agradeço-vos muitíssimo por ele.","adamsohadyouneediscarcecanspeaktothankyo~speaktothankyouformyself~50":"Adão — E bem precisais:\nMal posso falar para agradecer-vos por mim.","dukeseniorwelcomefalltoiwillnottroubleyo~memusicandgoodcousinsing~108":"Duque Sênior — Bem-vindo; servi-vos: não vos incomodarei\nPor ora, interrogando-vos sobre vossa fortuna.\nDai-nos música; e, bom primo, canta.","amiensblowblowthouwinterwindthouartnotso~memberdnotheighhosingetc~381":"Amiens — Sopra, sopra, vento de inverno.\nNão és tão cruel\nQuanto a ingratidão do homem;\nTeu dente não é tão afiado,\nPorque não és visto,\nEmbora teu sopro seja rude.\nHei-ho! canta, hei-ho! ao verde azevinho:\nA maior parte da amizade é fingimento, a maior parte do amor mera tolice:\nEntão, hei-ho, ao azevinho!\nEsta vida é a mais alegre.\nGela, gela, céu amargo,\nQue não mordes tão de perto\nQuanto os benefícios esquecidos:\nEmbora faças as águas se empenarem,\nTua picada não é tão aguda\nQuanto a do amigo não lembrado.\nHei-ho! canta, etc.","dukeseniorifthatyouwerethegoodsirrowland~fortunesunderstandexeunt~349":"Duque Sênior — Se fôsseis o filho do bom Sir Rowland,\nComo sussurrastes fielmente que éreis,\nE como meu olho testemunha sua efígie\nMuito verdadeiramente pintada e viva em vosso rosto,\nSede verdadeiramente bem-vindo aqui: sou o duque\nQue amava vosso pai: o resto de vossa fortuna,\nIde à minha caverna e contai-me. Bom velho,\nSois muito bem-vindo, como é vosso amo.\nApoiai-o pelo braço. Dai-me a mão,\nE deixai-me entender toda a vossa fortuna. Saem.","enterdukefredericklordsandoliver~efredericklordsandoliver~32":"Entram o Duque Frederick, Nobres e Oliver.","dukefredericknotseehimsincesirsirthatcan~ofwhatwethinkagainstthee~410":"Duque Frederick — Não o vê desde então? Senhor, senhor, isso não pode ser:\nE se eu não fosse feito, em maior parte, de clemência,\nNão iria buscar um argumento ausente\nPara a minha vingança, tendo-te aqui presente. Mas cuida disso:\nDescobre teu irmão, onde quer que ele esteja;\nProcura-o com lanterna; traze-o morto ou vivo\nDentro de doze meses, ou não voltes mais\nA buscar o teu sustento em nosso território.\nTuas terras e tudo o que chamas de teu\nQue valha o confisco, confiscamos para nossas mãos,\nAté que possas, pela boca de teu irmão, livrar-te\nDo que pensamos contra ti.","oliverothatyourhighnessknewmyheartinthis~erlovedmybrotherinmylife~68":"Oliver — Oh, se Vossa Alteza conhecesse meu coração nisto!\nNunca amei meu irmão em toda a minha vida.","dukefrederickmorevillainthouwellpushhimo~tlyandturnhimgoingexeunt~148":"Duque Frederick — Tanto mais vilão és tu. Pois bem, ponham-no porta afora;\nE que meus oficiais, para tais casos,\nFaçam o inventário de sua casa e de suas terras:\nFaçam-no sem demora e mandem-no embora. Saem.","enterorlandowithapaper~enterorlandowithapaper~22":"Entra Orlando, com um papel.","orlandohangtheremyverseinwitnessofmylove~teandunexpressivesheexit~359":"Orlando — Fica aí pendurado, meu verso, em testemunho do meu amor:\nE tu, três vezes coroada rainha da noite, contempla\nCom teu casto olhar, de tua pálida esfera lá no alto,\nO nome da tua caçadora, que governa toda a minha vida.\nÓ Rosalinda! estas árvores serão os meus livros\nE em suas cascas gravarei meus pensamentos;\nPara que todo olho que olhar nesta floresta\nVeja tua virtude testemunhada por toda parte.\nCorre, corre, Orlando; esculpe em cada árvore\nA bela, a casta e inexprimível ela. Sai.","entercorinandtouchstone~entercorinandtouchstone~23":"Entram Corin e Touchstone.","corinandhowlikeyouthisshepherdslifemaste~erdslifemastertouchstone~51":"Corin — E então, que tal lhe parece esta vida de pastor, Mestre Touchstone?","touchstonetrulyshepherdinrespectofitself~philosophyintheeshepherd~390":"Touchstone — Em verdade, pastor, em si mesma é uma boa vida, mas por ser vida de pastor, não vale nada. Por ser solitária, gosto muito dela; mas por ser reclusa, é uma vida vilíssima. Agora, por ser nos campos, agrada-me bastante; mas por não ser na corte, é tediosa. Como é uma vida frugal, vejam só, cai bem ao meu humor; mas como nela não há mais fartura, vai muito contra o meu estômago. Tens alguma filosofia em ti, pastor?","corinnomorebutthatiknowthemoreonesickens~rcomesofaverydullkindred~322":"Corin — Nada além de saber que quanto mais se adoece, pior se está; que quem carece de dinheiro, meios e contentamento está sem três bons amigos; que a propriedade da chuva é molhar e a do fogo, queimar; que bom pasto engorda ovelhas, e que uma grande causa da noite é a falta do sol; e que quem não aprendeu juízo nem pela natureza nem pela arte pode queixar-se da boa criação ou vem de parentela muito estúpida.","touchstonesuchaoneisanaturalphilosopherw~rwasteverincourtshepherd~62":"Touchstone — Esse é um filósofo natural. Estiveste alguma vez na corte, pastor?","corinnotruly~corinnotruly~12":"Corin — Não, na verdade.","touchstonethenthouartdamned~chstonethenthouartdamned~27":"Touchstone — Então estás condenado.","corinnayihope~corinnayihope~13":"Corin — Ora, espero que não.","touchstonetrulythouartdamnedlikeanillroa~llroastedeggallononeside~59":"Touchstone — Na verdade, estás condenado como ovo mal assado, de um lado só.","corinfornotbeingatcourtyourreason~otbeingatcourtyourreason~33":"Corin — Por não ter estado na corte? Diga a razão.","touchstonewhyifthouneverwastatcourtthoun~tinaparlousstateshepherd~180":"Touchstone — Ora, se nunca estiveste na corte, nunca viste boas maneiras; se nunca viste boas maneiras, tuas maneiras devem ser más; e a maldade é pecado, e pecado é condenação. Estás em perigoso estado, pastor.","corinnotawhittouchstonethosethataregoodm~ifcourtierswereshepherds~234":"Corin — Nem um pouco, Touchstone: o que são boas maneiras na corte é tão ridículo no campo quanto o comportamento do campo é digno de zombaria na corte. O senhor me disse que na corte não se saúda, mas se beija a mão: essa cortesia seria suja, se os cortesãos fossem pastores.","touchstoneinstancebrieflycomeinstance~tancebrieflycomeinstance~37":"Touchstone — Um exemplo, e rápido; vamos, um exemplo.","corinwhywearestillhandlingourewesandthei~eirfellsyouknowaregreasy~62":"Corin — Ora, estamos sempre mexendo em nossas ovelhas, e o velo delas, o senhor sabe, é gorduroso.","touchstonewhydonotyourcourtiershandsswea~wabetterinstanceisaycome~131":"Touchstone — Ora, as mãos dos cortesãos não suam? E a gordura de um carneiro não é tão sadia quanto o suor de um homem? Raso, raso. Um exemplo melhor, digo eu; vamos.","corinbesidesourhandsarehard~inbesidesourhandsarehard~27":"Corin — Além disso, nossas mãos são calejadas.","touchstoneyourlipswillfeelthemthesooners~amoresounderinstancecome~75":"Touchstone — Teus lábios as sentirão mais depressa. Raso de novo. Um exemplo mais sólido, vamos.","corinandtheyareoftentarredoverwiththesur~andsareperfumedwithcivet~115":"Corin — E muitas vezes estão cobertas de alcatrão, da cirurgia de nossas ovelhas: e o senhor quer que beijemos alcatrão? As mãos do cortesão são perfumadas com algália.","touchstonemostshallowmanthouwormsmeatinr~tmendtheinstanceshepherd~171":"Touchstone — Homem rasíssimo! tu, pasto de vermes, comparado a um bom pedaço de carne de verdade! Aprende com os sábios e pondera: a algália é de origem mais baixa que o alcatrão, o próprio fluxo imundo de um gato. Melhora o exemplo, pastor.","corinyouhavetoocourtlyawitformeillrest~ocourtlyawitformeillrest~38":"Corin — O senhor tem um espírito cortesão demais para mim: vou descansar.","touchstonewiltthourestdamnedgodhelpthees~incisionintheethouartraw~80":"Touchstone — Queres descansar condenado? Deus te ajude, homem raso! Deus te faça uma incisão! és cru.","corinsiriamatruelaboureriearnthatieatget~yewesgrazeandmylambssuck~171":"Corin — Senhor, sou um trabalhador honesto: ganho o que como, consigo o que visto, não devo ódio a ninguém, não invejo a felicidade de ninguém, alegro-me com o bem alheio, contento-me com o meu mal, e o maior de meus orgulhos é ver minhas ovelhas pastando e meus cordeiros mamando.","touchstonethatisanothersimplesininyoutob~elsehowthoushouldstscape~319":"Touchstone — Esse é mais um simples pecado teu: juntar as ovelhas e os carneiros e pretender ganhar a vida pela cópula do gado; ser alcoviteiro de um capão-guia, e trair uma cordeirinha de doze meses entregando-a a um carneiro velho, de cabeça torta e cornudo, em casamento fora de toda razão. Se não fores condenado por isso, o próprio diabo não terá pastores; não vejo de outro modo como poderias escapar.","corinherecomesyoungmasterganymedemynewmi~edemynewmistresssbrother~54":"Corin — Aí vem o jovem Mestre Ganimedes, irmão da minha nova patroa.","enterrosalindwithapaperreading~osalindwithapaperreading~30":"Entra Rosalind, lendo um papel.","rosalindfromtheeasttowesternindnojewelis~mindbutthefairofrosalind~200":"Rosalind — Do Oriente ao Ocidente das Índias,\nNenhuma joia iguala Rosalinda.\nSeu valor, montado no vento,\nPor todo o mundo leva Rosalinda.\nOs mais belos retratos traçados\nSão negros ante Rosalinda.\nQue nenhuma beleza fique na memória\nSalvo a beleza de Rosalinda.","touchstoneillrhymeyousoeightyearstogethe~butterwomensranktomarket~118":"Touchstone — Rimarei assim por oito anos seguidos, excetuados jantares, ceias e horas de sono: é o verdadeiro trote das vendedeiras de manteiga rumo ao mercado.","rosalindoutfool~rosalindoutfool~15":"Rosalind — Fora, bobo!","touchstoneforatasteifahartdolackahindlet~ouinfectyourselfwiththem~356":"Touchstone — Só para provar: Se o cervo sente falta da corça,\nQue procure Rosalinda.\nSe o gato atrás da sua espécie anda,\nAssim fará Rosalinda.\nRoupa de inverno deve ser forrada,\nAssim deve a esbelta Rosalinda.\nQuem ceifa deve enfeixar e atar;\nEntão à carroça com Rosalinda.\nA noz mais doce tem casca mais azeda,\nTal noz é Rosalinda.\nQuem a mais doce rosa quer achar\nHá de achar o espinho do amor e Rosalinda. Este é o verdadeiro galope falso dos versos: por que te contagias com eles?","rosalindpeaceyoudullfoolifoundthemonatre~ullfoolifoundthemonatree~41":"Rosalind — Cala-te, bobo estúpido! Achei-os numa árvore.","touchstonetrulythetreeyieldsbadfruit~ulythetreeyieldsbadfruit~36":"Touchstone — Na verdade, a árvore dá mau fruto.","rosalindillgraffitwithyouandthenishallgr~herightvirtueofthemedlar~160":"Rosalind — Vou enxertá-la contigo, e depois a enxertarei com uma nespereira: assim será o fruto mais precoce da região; pois apodrecerás antes de estar meio maduro, e essa é a verdadeira virtude da nêspera.","touchstoneyouhavesaidbutwhetherwiselyorn~elyornolettheforestjudge~58":"Touchstone — Já falaste; mas se com sabedoria ou não, deixe que a floresta julgue.","enterceliawithawriting~enterceliawithawriting~22":"Entra Celia, com um escrito.","rosalindpeaceherecomesmysisterreadingsta~ysisterreadingstandaside~47":"Rosalind — Silêncio! Aí vem minha irmã, lendo: ponhamo-nos de lado.","celiareadswhyshouldthisadesertbeforitisu~anditoliveanddieherslave~720":"Celia — Lê. Por que seria um deserto isto aqui?\nPor não ter gente? Não:\nLínguas pendurarei em cada árvore,\nQue mostrarão sentenças civilizadas:\nUmas, quão breve é a vida do homem,\nQue corre a sua errante peregrinação,\nPois o alongar de um palmo\nEncerra a soma de sua idade;\nOutras, de votos violados\nEntre as almas de amigo e amigo:\nMas nos mais belos ramos,\nOu ao fim de cada sentença,\nEscreverei Rosalinda,\nEnsinando a quem ler a conhecer\nA quintessência de cada espírito\nQue o Céu quis mostrar em miniatura.\nPor isso o Céu encarregou a Natureza\nDe que um só corpo fosse enchido\nDe todas as graças em largo acréscimo:\nA Natureza logo destilou\nA face de Helena, mas não o seu coração,\nA majestade de Cleópatra,\nA melhor parte de Atalanta,\nA modéstia da triste Lucrécia.\nAssim Rosalinda, de tantas partes,\nFoi pelo sínodo celeste concebida,\nDe muitas faces, olhos e corações,\nPara ter os traços mais prezados.\nO Céu quis que ela tivesse estes dons,\nE eu viver e morrer seu escravo.","rosalindomostgentlepulpiterwhattediousho~edhavepatiencegoodpeople~121":"Rosalind — Oh, gentilíssimo pregador! que tediosa homilia de amor cansou tua paróquia, sem que ninguém gritasse “Tende paciência, boa gente!”","celiahownowbackfriendsshepherdgooffalitt~ffalittlegowithhimsirrah~57":"Celia — Ora essa! de volta, amigos! Pastor, afaste-se um pouco. Vá com ele, rapaz.","touchstonecomeshepherdletusmakeanhonoura~exeuntcorinandtouchstone~124":"Touchstone — Vamos, pastor, façamos uma retirada honrosa; embora não com armas e bagagens, ao menos com alforje e alforjada. Saem Corin e Touchstone.","celiadidstthouheartheseverses~didstthouheartheseverses~29":"Celia — Ouviste estes versos?","rosalindoyesiheardthemallandmoretooforso~etthantheverseswouldbear~87":"Rosalind — Oh, sim, ouvi todos, e mais ainda; pois alguns tinham mais pés do que os versos podiam suportar.","celiathatsnomatterthefeetmightbearthever~hefeetmightbeartheverses~43":"Celia — Não importa: os pés poderiam suportar os versos.","rosalindaybutthefeetwerelameandcouldnotb~orestoodlamelyintheverse~101":"Rosalind — Sim, mas os pés eram mancos e não conseguiam sustentar-se sem o verso, e por isso ficavam mancando no verso.","celiabutdidstthouhearwithoutwonderinghow~dandcarveduponthesetrees~84":"Celia — Mas ouviste sem espanto como teu nome foi pendurado e gravado nestas árvores?","rosalindiwassevenoftheninedaysoutofthewo~twhichicanhardlyremember~168":"Rosalind — Sete dos nove dias de espanto já tinham passado antes de tu chegares; pois olha o que encontrei numa palmeira. Nunca fui tão rimada desde os tempos de Pitágoras, quando eu era um rato irlandês, coisa de que mal me lembro.","celiatrowyouwhohathdonethis~iatrowyouwhohathdonethis~27":"Celia — Imaginas quem fez isto?","rosalindisitaman~rosalindisitaman~16":"Rosalind — É um homem?","celiaandachainthatyouonceworeabouthisnec~uthisneckchangeyoucolour~56":"Celia — E uma corrente, que tu usaste um dia, ao pescoço dele. Mudas de cor?","rosalindipritheewho~rosalindipritheewho~19":"Rosalind — Peço-te, quem?","celiaolordlorditisahardmatterforfriendst~arthquakesandsoencounter~98":"Celia — Oh Senhor, Senhor! é difícil para amigos se encontrarem; mas montanhas podem ser removidas por terremotos, e assim se encontrar.","rosalindnaybutwhoisit~rosalindnaybutwhoisit~21":"Rosalind — Não, mas quem é?","celiaisitpossible~celiaisitpossible~17":"Celia — É possível?","rosalindnayipritheenowwithmostpetitionar~ryvehemencetellmewhoitis~63":"Rosalind — Não, peço-te agora, com a mais suplicante veemência, diz-me quem é.","celiaowonderfulwonderfulandmostwonderful~afterthatoutofallhooping~96":"Celia — Oh maravilha, maravilha, e a mais maravilhosa maravilha! e mais uma vez maravilha, e depois disso, fora de todo alarido!","rosalindgoodmycomplexiondostthouthinktho~ththatmaydrinkthytidings~373":"Rosalind — Valha-me minha pele! pensas que, embora eu esteja trajada como homem, tenho gibão e calções na disposição? Uma polegada mais de demora é um mar do Sul de descobertas; peço-te, dize-me quem é depressa, e fala logo. Quisera que gaguejasses, para que despejasses esse homem escondido de tua boca, como o vinho sai de uma garrafa de gargalo estreito, ou demais de uma vez, ou nada. Peço-te, tira a rolha da tua boca para que eu beba tuas novas.","celiasoyoumayputamaninyourbelly~youmayputamaninyourbelly~31":"Celia — Assim podes pôr um homem no teu ventre.","rosalindisheofgodsmakingwhatmannerofmani~ahatorhischinworthabeard~77":"Rosalind — É feitura de Deus? Que espécie de homem? Sua cabeça vale um chapéu, ou seu queixo vale uma barba?","celianayhehathbutalittlebeard~nayhehathbutalittlebeard~29":"Celia — Não, ele tem apenas uma barbinha.","rosalindwhygodwillsendmoreifthemanwillbe~nottheknowledgeofhischin~113":"Rosalind — Ora, Deus lhe mandará mais, se o homem for agradecido: deixa-me esperar o crescimento da barba, contanto que não me retardes o conhecimento do queixo.","celiaitisyoungorlandothattrippedupthewre~yourheartbothinaninstant~78":"Celia — É o jovem Orlando, que derrubou ao mesmo tempo os calcanhares do lutador e o teu coração.","rosalindnaybutthedeviltakemockingspeaksa~gspeaksadbrowandtruemaid~56":"Rosalind — Não, ao diabo a zombaria: fala, fronte séria e donzela verdadeira.","celiaifaithcoztishe~celiaifaithcoztishe~19":"Celia — Pela minha fé, prima, é ele.","rosalindorlando~rosalindorlando~15":"Rosalind — Orlando?","celiaorlando~celiaorlando~12":"Celia — Orlando.","rosalindalasthedaywhatshallidowithmydoub~imagainanswermeinoneword~216":"Rosalind — Ai de mim! que farei com meu gibão e meus calções? Que fazia ele quando o viste? Que disse? Como parecia? Como estava vestido? Que faz ele aqui? Perguntou por mim? Onde mora? Como se despediu de ti? e quando o verás de novo? Responde-me numa palavra.","celiayoumustborrowmegargantuasmouthfirst~thantoanswerinacatechism~141":"Celia — Primeiro hás de me emprestar a boca de Gargântua: é palavra grande demais para qualquer boca do tamanho das desta época. Dizer sim e não a essas particularidades é mais do que responder num catecismo.","rosalindbutdothheknowthatiaminthisforest~yashedidthedayhewrestled~95":"Rosalind — Mas ele sabe que estou nesta floresta e em trajes de homem? Tem o mesmo viço que tinha no dia em que lutou?","celiaitisaseasytocountatomiesastoresolve~eratreelikeadroppedacorn~155":"Celia — É tão fácil contar átomos quanto resolver as proposições de um amante; mas prova um pouco de como o encontrei, e saboreia com bom cuidado. Encontrei-o sob uma árvore, como uma bolota caída.","rosalinditmaywellbecalledjovestreewhenit~henitdropsforthsuchfruit~59":"Rosalind — Bem pode chamar-se árvore de Júpiter, quando deixa cair tal fruto.","celiagivemeaudiencegoodmadam~agivemeaudiencegoodmadam~28":"Celia — Dá-me audiência, boa senhora.","rosalindproceed~rosalindproceed~15":"Rosalind — Prossegue.","celiatherelayhestretchedalonglikeawounde~dalonglikeawoundedknight~47":"Celia — Lá jazia ele, estendido ao comprido, como um cavaleiro ferido.","rosalindthoughitbepitytoseesuchasightitw~htitwellbecomestheground~59":"Rosalind — Embora seja pena ver tal visão, assenta bem ao chão.","celiacryhollatothytongueipritheeitcurvet~ewasfurnishedlikeahunter~78":"Celia — Grita “alto lá” à tua língua, peço-te; ela cabriola fora de hora. Estava vestido de caçador.","rosalindoominoushecomestokillmyheart~noushecomestokillmyheart~36":"Rosalind — Oh, agouro! vem matar o meu coração.","celiaiwouldsingmysongwithoutaburdenthoub~nthoubringestmeoutoftune~58":"Celia — Eu cantaria minha canção sem refrão: tu me desafinas.","rosalinddoyounotknowiamawomanwhenithinki~hinkimustspeaksweetsayon~59":"Rosalind — Não sabes que sou mulher? quando penso, tenho de falar. Doce, continua.","celiayoubringmeoutsoftcomeshenothere~gmeoutsoftcomeshenothere~36":"Celia — Tu me atrapalhas. Quieta! não vem ele para cá?","enterorlandoandjaques~enterorlandoandjaques~21":"Entram Orlando e Jaques.","rosalindtisheslinkbyandnotehim~ndtisheslinkbyandnotehim~30":"Rosalind — É ele: esgueiremo-nos e observemo-lo.","jaquesithankyouforyourcompanybutgoodfait~sliefhavebeenmyselfalone~70":"Jaques — Agradeço a sua companhia; mas, em boa fé, preferia ter ficado sozinho.","orlandoandsohadibutyetforfashionsakeitha~hankyoutooforyoursociety~62":"Orlando — E eu também; mas ainda assim, por cortesia, agradeço também a sua sociedade.","jaquesgodbewiyouletsmeetaslittleaswecan~uletsmeetaslittleaswecan~39":"Jaques — Deus o acompanhe: encontremo-nos o menos que pudermos.","orlandoidodesirewemaybebetterstrangers~rewemaybebetterstrangers~38":"Orlando — Desejo que possamos ser melhores estranhos.","jaquesiprayyoumarnomoretreeswithwritingl~inglovesongsintheirbarks~60":"Jaques — Peço-lhe, não estrague mais árvores escrevendo canções de amor em suas cascas.","orlandoiprayyoumarnomoreofmyverseswithre~readingthemillfavouredly~62":"Orlando — Peço-lhe, não estrague mais os meus versos lendo-os de modo tão desagradável.","jaquesrosalindisyourlovesname~srosalindisyourlovesname~29":"Jaques — Rosalinda é o nome do seu amor?","orlandoyesjust~orlandoyesjust~14":"Orlando — Sim, exatamente.","jaquesidonotlikehername~jaquesidonotlikehername~23":"Jaques — Não gosto do nome dela.","orlandotherewasnothoughtofpleasingyouwhe~gyouwhenshewaschristened~57":"Orlando — Não se pensava em agradar ao senhor quando ela foi batizada.","jaqueswhatstatureissheof~jaqueswhatstatureissheof~24":"Jaques — Que estatura ela tem?","orlandojustashighasmyheart~landojustashighasmyheart~26":"Orlando — Exatamente a altura do meu coração.","jaquesyouarefullofprettyanswershaveyouno~sandconnedthemoutofrings~97":"Jaques — O senhor está cheio de respostas bonitas. Não andou em convívio com mulheres de ourives, e lhes arrancou anéis com lábia?","orlandonotsobutiansweryourightpaintedclo~havestudiedyourquestions~79":"Orlando — Não é assim; mas respondo-lhe como pano pintado, de onde o senhor estudou suas perguntas.","jaquesyouhaveanimblewitithinktwasmadeofa~stheworldandallourmisery~130":"Jaques — O senhor tem espírito ligeiro: creio que foi feito dos calcanhares de Atalanta. Quer sentar-se comigo? e nós dois vamos injuriar nossa senhora, o mundo, e toda a nossa miséria.","orlandoiwillchidenobreatherintheworldbut~ainstwhomiknowmostfaults~72":"Orlando — Não repreenderei nenhum vivente do mundo senão a mim mesmo, de quem conheço mais defeitos.","jaquestheworstfaultyouhaveistobeinlove~faultyouhaveistobeinlove~38":"Jaques — O pior defeito que o senhor tem é estar apaixonado.","orlandotisafaultiwillnotchangeforyourbes~rbestvirtueiamwearyofyou~60":"Orlando — É um defeito que não trocaria pela sua melhor virtude. Estou cansado do senhor.","jaquesbymytrothiwasseekingforafoolwhenif~ingforafoolwhenifoundyou~47":"Jaques — Por minha fé, eu procurava um bobo quando o encontrei.","orlandoheisdrownedinthebrooklookbutinand~okbutinandyoushallseehim~54":"Orlando — Está afogado no riacho: olhe lá dentro e o verá.","jaquesthereishallseemineownfigure~reishallseemineownfigure~33":"Jaques — Ali verei minha própria figura.","orlandowhichitaketobeeitherafooloraciphe~tobeeitherafooloracipher~41":"Orlando — Que tomo por ser ou um bobo ou um zero.","jaquesilltarrynolongerwithyoufarewellgoo~ufarewellgoodsigniorlove~52":"Jaques — Não me demoro mais com o senhor: adeus, bom Senhor Amor.","orlandoiamgladofyourdepartureadieugoodmo~ieurmelancholyexitjaques~66":"Orlando — Alegro-me com a sua partida: adeus, bom Monsieur Melancolia. Sai Jaques.","rosalindasidetoceliaiwillspeaktohimlikea~withhimdoyouhearforester~104":"Rosalind — À parte, para Celia. Vou falar-lhe como um lacaio atrevido e, sob esse traje, pregar-lhe peças. Está ouvindo, guarda-florestal?","orlandoverywellwhatwouldyou~andoverywellwhatwouldyou~27":"Orlando — Muito bem: que deseja?","rosalindiprayyouwhatistoclock~indiprayyouwhatistoclock~29":"Rosalind — Peço-lhe, que horas são?","orlandoyoushouldaskmewhattimeodaytheresn~theresnoclockintheforest~57":"Orlando — Deveria perguntar-me que hora do dia: não há relógio na floresta.","rosalindthenthereisnotrueloverinthefores~footoftimeaswellasaclock~125":"Rosalind — Então não há verdadeiro amante na floresta; do contrário, suspirar a cada minuto e gemer a cada hora denunciaria o pé preguiçoso do Tempo tão bem quanto um relógio.","orlandoandwhynottheswiftfootoftimehadnot~mehadnotthatbeenasproper~56":"Orlando — E por que não o pé veloz do Tempo? Não teria sido tão apropriado?","rosalindbynomeanssirtimetravelsindiversp~ndwhohestandsstillwithal~153":"Rosalind — De modo algum, senhor: o Tempo viaja em diversos passos com diversas pessoas. Dir-lhe-ei com quem o Tempo anda a passo, com quem trota, com quem galopa e com quem fica parado.","orlandoipritheewhodothhetrotwithal~itheewhodothhetrotwithal~34":"Orlando — Peço-lhe, com quem ele trota?","rosalindmarryhetrotshardwithayoungmaidbe~eemsthelengthofsevenyear~166":"Rosalind — Pois bem, trota duro com uma jovem donzela entre o contrato de seu casamento e o dia em que é solenizado: se o intervalo for apenas de uma semana, o passo do Tempo é tão duro que parece durar sete anos.","orlandowhoamblestimewithal~landowhoamblestimewithal~26":"Orlando — Com quem o Tempo anda a passo?","rosalindwithapriestthatlackslatinandaric~urythesetimeambleswithal~257":"Rosalind — Com um padre que não sabe latim e um homem rico que não tem gota, pois um dorme facilmente porque não pode estudar, e o outro vive alegremente porque não sente dor, faltando a um o fardo do estudo magro e desgastante, e ao outro o fardo da pesada e tediosa penúria; com estes o Tempo anda a passo.","orlandowhodothhegallopwithal~ndowhodothhegallopwithal~28":"Orlando — Com quem ele galopa?","rosalindwithathieftothegallowsforthoughh~hinkshimselftoosoonthere~91":"Rosalind — Com um ladrão a caminho da forca, pois por mais suavemente que ande, pensa que chega cedo demais.","orlandowhostaysitstillwithal~ndowhostaysitstillwithal~28":"Orlando — Com quem ele fica parado?","rosalindwithlawyersinthevacationfortheys~yperceivenothowtimemoves~96":"Rosalind — Com advogados nas férias, pois dormem entre um período e outro e então não percebem como o Tempo se move.","orlandowheredwellyouprettyyouth~wheredwellyouprettyyouth~31":"Orlando — Onde mora, belo jovem?","rosalindwiththisshepherdessmysisterherei~likefringeuponapetticoat~85":"Rosalind — Com esta pastora, minha irmã; aqui nas orlas da floresta, como franja numa anágua.","orlandoareyounativeofthisplace~oareyounativeofthisplace~30":"Orlando — É natural daqui?","rosalindastheconythatyouseedwellwhereshe~eedwellwheresheiskindled~49":"Rosalind — Como o coelho que o senhor vê morar onde nasceu.","orlandoyouraccentissomethingfinerthanyou~haseinsoremovedadwelling~73":"Orlando — Seu sotaque é um tanto mais fino do que se poderia adquirir em morada tão afastada.","rosalindihavebeentoldsoofmanybutindeedan~taxedtheirwholesexwithal~289":"Rosalind — Já me disseram isso muitos: mas, na verdade, quem me ensinou a falar foi um velho tio religioso, que na juventude fora homem da cidade; alguém que conhecia bem demais o galanteio, pois nele se apaixonou. Ouvi-o ler muitos sermões contra o amor, e agradeço a Deus não ser mulher, para ser tocada por tantas ofensas levianas quantas ele em geral atribuía a todo o sexo delas.","orlandocanyourememberanyoftheprincipalev~helaidtothechargeofwomen~71":"Orlando — Lembra-se de alguns dos principais males que ele imputava às mulheres?","rosalindtherewerenoneprincipaltheywereal~fellowfaultcametomatchit~129":"Rosalind — Não havia principais; eram todos iguais entre si como moedinhas de meio centavo, cada falta parecendo monstruosa até que a falta companheira viesse igualá-la.","orlandoipritheerecountsomeofthem~pritheerecountsomeofthem~32":"Orlando — Peço-lhe, relate algumas delas.","rosalindnoiwillnotcastawaymyphysicbutont~hequotidianofloveuponhim~310":"Rosalind — Não, não desperdiçarei meu remédio senão com os que estão doentes. Há um homem que assombra a floresta e maltrata nossas árvores novas gravando “Rosalinda” em suas cascas; pendura odes em espinheiros e elegias em sarças, todas, em verdade, deificando o nome de Rosalinda: se eu pudesse encontrar esse mercador de fantasias, dar-lhe-ia um bom conselho, pois parece ter sobre si a febre quotidiana do amor.","orlandoiamhethatissoloveshakediprayyoute~iprayyoutellmeyourremedy~54":"Orlando — Sou eu esse que está assim sacudido de amor: peço-lhe, diga-me o seu remédio.","rosalindthereisnoneofmyunclesmarksuponyo~iamsureyouarenotprisoner~113":"Rosalind — Não há em você nenhuma das marcas do meu tio: ele me ensinou a reconhecer um homem apaixonado; e dessa gaiola de juncos tenho certeza de que o senhor não é prisioneiro.","orlandowhatwerehismarks~orlandowhatwerehismarks~23":"Orlando — Quais eram as marcas dele?","rosalindaleancheekwhichyouhavenotablueey~eemingtheloverofanyother~443":"Rosalind — Face magra, que o senhor não tem, olho azul e fundo, que o senhor não tem, um espírito intratável, que o senhor não tem, barba descuidada, que o senhor não tem; mas nisso eu o perdoo, pois a simples barba que tem é renda de filho caçula: depois, as meias deveriam estar sem ligas, o gorro sem fita, a manga desabotoada, o sapato desatado e tudo em você demonstrando um desleixo desolado; mas o senhor não é tal homem; é antes muito esmerado em seus trajes, como quem ama a si mesmo mais do que parece amante de outrem.","orlandofairyouthiwouldicouldmaketheebeli~ouldmaketheebelieveilove~48":"Orlando — Belo jovem, quisera poder fazer-te crer que amo.","rosalindmebelieveityoumayassoonmakeherth~ereinrosalindissoadmired~249":"Rosalind — Eu crer! mais depressa poderá fazê-lo crer aquela que amas; a qual, garanto, está mais disposta a crer do que a confessar que crê: esse é um dos pontos em que as mulheres sempre desmentem a própria consciência. Mas, em boa verdade, és tu quem pendura os versos nas árvores, nos quais Rosalinda é tão admirada?","orlandoisweartotheeyouthbythewhitehandof~mthathethatunfortunatehe~74":"Orlando — Juro-te, jovem, pela mão branca de Rosalinda, que sou esse mesmo, esse infeliz.","rosalindbutareyousomuchinloveasyourrhyme~hinloveasyourrhymesspeak~46":"Rosalind — Mas estás tão apaixonado quanto dizem tuas rimas?","orlandoneitherrhymenorreasoncanexpressho~rreasoncanexpresshowmuch~45":"Orlando — Nem rima nem razão podem exprimir quanto.","rosalindloveismerelyamadnessanditellyoud~professcuringitbycounsel~206":"Rosalind — O amor é pura loucura e, digo-te, merece tanto uma casa escura e um chicote quanto os loucos; e a razão de não serem assim castigados e curados é que a loucura é tão comum que os açoitadores também estão apaixonados. Contudo, professo curá-lo por conselho.","orlandodidyouevercureanyso~landodidyouevercureanyso~26":"Orlando — Curaste alguém assim alguma vez?","rosalindyesoneandinthismannerhewastoimag~allnotbeonespotofloveint~668":"Rosalind — Sim, um, e desta maneira. Ele devia imaginar-me seu amor, sua senhora; e eu o mandava todo dia me cortejar: ocasião em que eu, sendo apenas um jovem lunático, me entristecia, era efeminado, mutável, ansioso e caprichoso, orgulhoso, fantasioso, macaqueador, superficial, inconstante, cheio de lágrimas, cheio de sorrisos, com algo para cada paixão e nada de verdade para nenhuma, como rapazes e mulheres são na maior parte gado dessa cor; ora gostava dele, ora o detestava; ora o acolhia, ora o repudiava; ora chorava por ele, ora cuspia nele; até que arrastei meu pretendente de seu louco humor de amor para um vivo humor de loucura; que era renegar a corrente plena do mundo e viver num canto puramente monástico. E assim o curei; e dessa maneira me encarrego de lavar o seu fígado tão limpo quanto o coração de uma ovelha sadia, de modo que não haja nele uma só mancha de amor.","orlandoiwouldnotbecuredyouth~ndoiwouldnotbecuredyouth~28":"Orlando — Não quereria ser curado, jovem.","rosalindiwouldcureyouifyouwouldbutcallme~everydaytomycoteandwoome~79":"Rosalind — Eu o curaria, se ao menos me chamasse de Rosalinda e viesse todo dia à minha choupana me cortejar.","orlandonowbythefaithofmyloveiwilltellmew~loveiwilltellmewhereitis~48":"Orlando — Pois bem, pela fé do meu amor, virei: diz-me onde fica.","rosalindgowithmetoitandillshowityouandby~heforestyoulivewillyougo~92":"Rosalind — Vem comigo e eu te mostrarei, e pelo caminho me dirás onde na floresta moras. Vamos?","orlandowithallmyheartgoodyouth~owithallmyheartgoodyouth~30":"Orlando — De todo o coração, bom jovem.","rosalindnayyoumustcallmerosalindcomesist~omesisterwillyougoexeunt~57":"Rosalind — Não, tens de me chamar Rosalinda. Vamos, irmã, vens? Saem.","entertouchstoneandaudreyjaquesbehind~oneandaudreyjaquesbehind~36":"Entram Touchstone e Audrey; Jaques atrás.","touchstonecomeapacegoodaudreyiwillfetchu~ysimplefeaturecontentyou~109":"Touchstone — Vem depressa, boa Audrey: irei buscar as tuas cabras, Audrey. E então, Audrey? sou já o teu homem? Minha simples feição te contenta?","audreyyourfeatureslordwarrantuswhatfeatu~ordwarrantuswhatfeatures~43":"Audrey — Sua feição! Deus nos guarde! que feição!","touchstoneiamherewiththeeandthygoatsasth~nestovidwasamongthegoths~85":"Touchstone — Estou aqui contigo e com tuas cabras, como o mais caprichoso poeta, o honesto Ovídio, estava entre os godos.","jaquesasideoknowledgeillinhabitedworseth~thanjoveinathatchedhouse~62":"Jaques — À parte. Oh saber mal alojado, pior que Júpiter numa casa de palha!","touchstonewhenamansversescannotbeunderst~egodshadmadetheepoetical~188":"Touchstone — Quando os versos de um homem não podem ser entendidos, nem o bom espírito de um homem secundado pelo precoce filho Entendimento, isso fere um homem mais de morte que uma grande conta num quartinho. Em verdade, quisera que os deuses te tivessem feito poética.","audreyidonotknowwhatpoeticalisisithonest~eedandwordisitatruething~67":"Audrey — Não sei o que é “poética”: é honesta em obra e palavra? é coisa verdadeira?","touchstonenotrulyforthetruestpoetryisthe~esaidasloverstheydofeign~129":"Touchstone — Não, em verdade; pois a poesia mais verdadeira é a que mais finge; e os amantes são dados à poesia, e o que juram em poesia pode-se dizer que, como amantes, fingem.","audreydoyouwishthenthatthegodshadmademep~thegodshadmademepoetical~47":"Audrey — Quer então que os deuses me tivessem feito poética?","touchstoneidotrulyforthouswearesttometho~vesomehopethoudidstfeign~100":"Touchstone — Quero, em verdade; pois juras-me que és honesta: ora, se fosses poeta, eu poderia ter alguma esperança de que fingisses.","audreywouldyounothavemehonest~ywouldyounothavemehonest~29":"Audrey — Não me quereria honesta?","touchstonenotrulyunlessthouwerthardfavou~tohavehoneyasaucetosugar~94":"Touchstone — Não, em verdade, a menos que fosses feia; pois honestidade unida à beleza é pôr mel como molho no açúcar.","jaquesasideamaterialfool~jaquesasideamaterialfool~24":"Jaques — À parte. Um bobo substancial!","audreywelliamnotfairandthereforeipraythe~ipraythegodsmakemehonest~56":"Audrey — Bem, não sou bonita; e por isso rogo aos deuses que me façam honesta.","touchstonetrulyandtocastawayhonestyupona~oodmeatintoanuncleandish~82":"Touchstone — Em verdade, e lançar a honestidade a uma porca imunda seria pôr boa carne em prato sujo.","audreyiamnotaslutthoughithankthegodsiamf~oughithankthegodsiamfoul~43":"Audrey — Não sou uma porca, embora agradeça aos deuses por ser feia.","touchstonewellpraisedbethegodsforthyfoul~oftheforestandtocoupleus~225":"Touchstone — Bem, louvados sejam os deuses por tua feiura! a porcaria pode vir depois. Mas seja como for, casarei contigo, e para isso estive com o Sir Oliver Martext, vigário da aldeia vizinha, que prometeu encontrar-me neste lugar da floresta e unir-nos.","jaquesasideiwouldfainseethismeeting~iwouldfainseethismeeting~35":"Jaques — À parte. Bem gostaria de ver este encontro.","audreywellthegodsgiveusjoy~dreywellthegodsgiveusjoy~26":"Audrey — Bem, que os deuses nos deem alegria!","touchstoneamenamanmayifhewereofafearfulh~towantherecomessiroliver~597":"Touchstone — Amém. Um homem poderia, se tivesse coração medroso, vacilar nesta empresa; pois aqui não temos templo senão o bosque, nem assembleia senão bichos de chifres. Mas que importa? Coragem! Se chifres são odiosos, são necessários. Diz-se: “muitos homens não conhecem o fim de seus bens”: certo; muitos homens têm bons chifres, e não conhecem o fim deles. Pois bem, esse é o dote da esposa; não é coisa que ele mesmo tenha ganhado. Chifres? Assim é. Só os pobres? Não, não; o veado mais nobre os tem tão enormes quanto o ordinário. É então bem-aventurado o solteiro? Não: assim como uma cidade murada é mais digna que uma aldeia, assim a fronte de um homem casado é mais honrosa que a testa nua de um solteiro; e quanto a defesa é melhor que nenhuma habilidade, tanto um chifre é mais precioso que a falta dele. Aí vem Sir Oliver.","entersirolivermartext~entersirolivermartext~21":"Entra Sir Oliver Martext.","sirolivermartextyouarewellmetwillyoudisp~lwegowithyoutoyourchapel~93":"Sir Oliver Martext, bem-encontrado: despachar-nos-á aqui sob esta árvore, ou iremos com o senhor à sua capela?","sirolivermartextistherenoneheretogivethe~renoneheretogivethewoman~45":"Sir Oliver Martext — Não há ninguém aqui para dar a mulher?","touchstoneiwillnottakeherongiftofanyman~nottakeherongiftofanyman~39":"Touchstone — Não a tomarei como dádiva de homem algum.","sirolivermartexttrulyshemustbegivenorthe~orthemarriageisnotlawful~59":"Sir Oliver Martext — Em verdade, ela tem de ser dada, ou o casamento não é legítimo.","jaquesadvancingproceedproceedillgiveher~proceedproceedillgiveher~39":"Jaques — Adiantando-se. Prossiga, prossiga, eu a darei.","touchstonegoodevengoodmasterwhatyecallth~dheresirnaypraybecovered~150":"Touchstone — Boa noite, bom Mestre Como-se-chama: como vai, senhor? Muito bem-encontrado: Deus lhe pague pela última companhia: estou muito contente em vê-lo: um simples brinquedo entre mãos aqui, senhor: não, peço, cubra-se.","jaqueswillyoubemarriedmotley~eswillyoubemarriedmotley~28":"Jaques — Quer casar-se, arlequim?","touchstoneastheoxhathhisbowsirthehorsehi~sowedlockwouldbenibbling~124":"Touchstone — Assim como o boi tem o seu jugo, senhor, o cavalo o seu freio e o falcão os seus guizos, assim o homem tem seus desejos; e como os pombos se bicam, assim o matrimônio quer ficar bicando.","jaquesandwillyoubeingamanofyourbreedingb~dlikegreentimberwarpwarp~238":"Jaques — E o senhor, sendo homem de sua criação, quer casar-se debaixo de um arbusto como um mendigo? Vá à igreja, e tenha um bom padre que lhe saiba dizer o que é o casamento: este sujeito apenas os juntará como se juntam painéis de madeira; depois um de vocês se revelará um painel encolhido e, como madeira verde, empenará, empenará.","touchstoneasideiamnotinthemindbutiwerebe~mehereaftertoleavemywife~168":"Touchstone — À parte. Não deixo de pensar que seria melhor ser casado por ele do que por outro: pois não é provável que me case bem; e não sendo bem casado, será uma boa desculpa para eu deixar depois minha mulher.","jaquesgothouwithmeandletmecounselthee~ithmeandletmecounselthee~37":"Jaques — Vem comigo, e deixa-me aconselhar-te.","touchstonecomesweetaudreywemustbemarried~aquestouchstoneandaudrey~208":"Touchstone — Vem, doce Audrey:\nTemos de casar, ou viver em devassidão.\nAdeus, bom Mestre Oliver: não— Ó doce Oliver,\nÓ valente Oliver,\nNão me deixes atrás de ti: mas— Some daqui,\nVai-te, digo,\nNão vou ao casamento contigo. Saem Jaques, Touchstone e Audrey.","sirolivermartexttisnomatterneerafantasti~loutmeoutofmycallingexit~87":"Sir Oliver Martext — Não importa: nenhum desses velhacos fantasiosos me fará troça para fora de minha profissão. Sai.","enterrosalindandcelia~enterrosalindandcelia~21":"Entram Rosalind e Celia.","rosalindnevertalktomeiwillweep~ndnevertalktomeiwillweep~30":"Rosalind — Não fales comigo; vou chorar.","celiadoipritheebutyethavethegracetoconsi~thattearsdonotbecomeaman~67":"Celia — Chora, peço-te; mas tem ao menos a decência de considerar que lágrimas não ficam bem num homem.","rosalindbuthaveinotcausetoweep~ndbuthaveinotcausetoweep~30":"Rosalind — Mas não tenho motivo para chorar?","celiaasgoodcauseasonewoulddesiretherefor~woulddesirethereforeweep~45":"Celia — Tão bom motivo quanto se poderia desejar; portanto, chora.","rosalindhisveryhairisofthedissemblingcol~isofthedissemblingcolour~43":"Rosalind — Até o cabelo dele é da cor da dissimulação.","celiasomethingbrownerthanjudassmarryhisk~ssesarejudassownchildren~65":"Celia — Um pouco mais escuro que o de Judas; pois, os beijos dele são filhos do próprio Judas.","rosalindifaithhishairisofagoodcolour~thhishairisofagoodcolour~36":"Rosalind — Por minha fé, o cabelo dele é de boa cor.","celiaanexcellentcolouryourchestnutwaseve~tnutwasevertheonlycolour~54":"Celia — Uma cor excelente: o castanho foi sempre a única cor.","rosalindandhiskissingisasfullofsanctitya~ityasthetouchofholybread~60":"Rosalind — E o beijar dele é tão cheio de santidade quanto o toque do pão bento.","celiahehathboughtapairofcastlipsofdianaa~eryiceofchastityisinthem~114":"Celia — Ele comprou de Diana um par de lábios dispensados: uma freira da irmandade do inverno não beija com mais religião; o próprio gelo da castidade está neles.","rosalindbutwhydidheswearhewouldcomethism~methismorningandcomesnot~57":"Rosalind — Mas por que jurou que viria esta manhã, e não vem?","celianaycertainlythereisnotruthinhim~ainlythereisnotruthinhim~36":"Celia — Ora, certamente não há verdade nele.","rosalinddoyouthinkso~rosalinddoyouthinkso~20":"Rosalind — Pensas assim?","celiayesithinkheisnotapickpursenorahorse~redgobletorawormeatennut~119":"Celia — Sim; penso que não é batedor de carteiras nem ladrão de cavalos, mas, quanto à sua veracidade em amor, tenho-o por tão oco quanto um cálice tampado ou uma noz carunchada.","rosalindnottrueinlove~rosalindnottrueinlove~21":"Rosalind — Não é verdadeiro no amor?","celiayeswhenheisinbutithinkheisnotin~heisinbutithinkheisnotin~36":"Celia — Sim, quando está nele; mas creio que não está.","rosalindyouhaveheardhimsweardownrighthew~rdhimsweardownrighthewas~42":"Rosalind — Ouviste-o jurar às claras que estava.","celiawasisnotisbesidestheoathofaloverisn~orestonthedukeyourfather~153":"Celia — “Estava” não é “está”: além disso, o juramento de um amante não é mais forte que a palavra de um taberneiro; ambos confirmam contas falsas. Ele acompanha aqui na floresta o duque, teu pai.","rosalindimetthedukeyesterdayandhadmuchqu~thereissuchamanasorlando~172":"Rosalind — Encontrei o duque ontem e conversei muito com ele: perguntou-me de que linhagem eu era; disse-lhe que de tão boa quanto a dele; então riu e deixou-me ir. Mas por que falamos de pais, quando existe um homem como Orlando?","celiaothatsabravemanhewritesbraveversess~dfollyguideswhocomeshere~255":"Celia — Oh, esse é um homem galante! escreve versos galantes, diz palavras galantes, jura juramentos galantes e os quebra galantemente, de través, atravessado no coração de sua amada; como um justador novato, que esporeia o cavalo só de um lado, quebra sua lança como um nobre ganso: mas tudo é galante o que a juventude monta e a loucura guia. Quem vem aí?","entercorin~entercorin~10":"Entra Corin.","corinmistressandmasteryouhaveoftinquired~erdessthatwashismistress~159":"Corin — Senhora e senhor, muitas vezes perguntastes\nPelo pastor que se queixava de amor,\nQue vistes sentado junto a mim na relva,\nLouvando a orgulhosa e desdenhosa pastora\nQue era a sua amada.","celiawellandwhatofhim~celiawellandwhatofhim~21":"Celia — Pois bem, e que há com ele?","corinifyouwillseeapageanttrulyplaydbetwe~onductyouifyouwillmarkit~152":"Corin — Se quiserdes ver um espetáculo bem representado,\nEntre a palidez de verdadeiro amor\nE o rubor ardente de desprezo e altivo desdém,\nIde dali um pouco e eu vos conduzirei,\nSe quiserdes observar.","rosalindocomeletusremovethesightoflovers~syactorintheirplayexeunt~125":"Rosalind — Oh, vem, vamos nós:\nA vista dos amantes alimenta os que amam.\nLeva-nos a esta visão, e dirás\nQue serei um ator ativo em sua peça. Saem.","anotherpartoftheforest~anotherpartoftheforest~22":"Outra parte da floresta.","entersilviusandphebe~entersilviusandphebe~20":"Entram Silvius e Phebe.","silviussweetphebedonotscornmedonotphebes~iesandlivesbybloodydrops~245":"Silvius — Doce Phebe, não me desprezes; não, Phebe;\nDize que não me amas, mas não o digas\nCom amargura. O carrasco comum,\nCujo coração a vista habitual da morte endurece,\nNão deixa cair o machado sobre o pescoço humilhado\nSem antes pedir perdão: serás mais severa\nQue aquele que morre e vive de gotas de sangue?","enterrosalindceliaandcorinbehind~alindceliaandcorinbehind~32":"Entram Rosalind, Celia e Corin, atrás.","phebeiwouldnotbethyexecutioneriflytheefo~forceineyesthatcandohurt~646":"Phebe — Não quero ser teu carrasco:\nFujo de ti, pois não quero te ferir.\nDizes-me que há assassínio em meu olhar:\nÉ bonito, por certo, e muito provável,\nQue os olhos, que são as coisas mais frágeis e macias,\nQue fecham suas portas covardes a átomos,\nSejam chamados tiranos, açougueiros, assassinos!\nAgora olho-te de cenho franzido com todo o coração;\nE se meus olhos podem ferir, que agora te matem:\nAgora finge um desmaio; ora, cai agora;\nOu se não podes, oh, que vergonha, que vergonha,\nNão mintas dizendo que meus olhos são assassinos!\nAgora mostra a ferida que meu olhar te fez:\nArranha-te só com um alfinete, e fica\nAlguma cicatriz; apoia-te apenas num junco,\nE a marca e a impressão profunda\nTua palma guarda por um momento; mas agora meus olhos,\nQue dardejei contra ti, não te ferem,\nNem, tenho certeza, há força nos olhos\nQue possa fazer mal.","silviusodearphebeifeverasthatevermaybene~ethatloveskeenarrowsmake~137":"Silvius — Ó cara Phebe,\nSe algum dia — e pode ser que esse dia esteja perto —\nEncontrares numa face fresca o poder da paixão,\nEntão saberás as feridas invisíveis\nQue as agudas flechas do amor fazem.","phebebuttillthattimecomenotthounearmeand~hattimeishallnotpitythee~118":"Phebe — Mas até esse tempo\nNão te aproximes de mim: e quando esse tempo vier,\nAflige-me com teus escárnios, não tenhas pena de mim;\nPois até esse tempo não terei pena de ti.","rosalindandwhyiprayyouwhomightbeyourmoth~otheeshepherdfareyouwell~998":"Rosalind — E por que, peço-te? Quem poderia ser tua mãe,\nQue insultas, exultas, e tudo de uma vez,\nSobre os desgraçados? Que importa que não tenhas beleza —\nPois, por minha fé, não vejo em ti mais\nDo que o que sem vela pode ir no escuro para a cama —\nDeves por isso ser orgulhosa e sem piedade?\nOra, que quer isto dizer? Por que me olhas?\nNão vejo em ti mais que no comum\nDa mercadoria barata da natureza. Pela minha vidinha,\nCreio que ela pretende enredar também os meus olhos!\nNão, em fé, orgulhosa senhora, não esperes por isso:\nNão são tuas sobrancelhas de tinta, teu cabelo de seda negra,\nTeus globos de azeviche, nem tua face de nata,\nQue podem domar meu espírito ao teu culto.\nPastor tolo, por que a segues,\nComo o úmido vento sul soprando com ventania e chuva?\nÉs mil vezes um homem mais bem-feito\nDo que ela mulher: são tolos como tu\nQue enchem o mundo de crianças mal-apessoadas:\nNão é o espelho dela, mas tu, quem a lisonjeia;\nE por tua causa ela se vê mais bem-feita\nDo que qualquer de seus traços poderia mostrar.\nMas, senhora, conhece-te a ti mesma: de joelhos,\nE agradece ao céu, em jejum, o amor de um bom homem:\nPois devo dizer-te amigavelmente ao ouvido,\nVende quando puderes: não és para todos os mercados:\nPede perdão ao homem; ama-o; aceita a oferta dele:\nFeio é o mais feio, sendo feio e escarnecedor.\nAssim toma-a para ti, pastor: passem bem.","phebesweetyouthiprayyouchideayeartogethe~aryouchidethanthismanwoo~77":"Phebe — Doce jovem, peço-te, repreende-me um ano inteiro:\nAntes ouvir-te repreender que este homem cortejar.","rosalindhesfalleninlovewithyourfoulnessa~rwordswhylookyousouponme~159":"Rosalind — Ele se apaixonou pela tua feiura e ela se apaixonará pela minha ira. Se assim for, tão depressa quanto ela te responder com olhares carrancudos, eu a temperarei com palavras amargas. Por que me olhas assim?","phebefornoillwillibearyou~hebefornoillwillibearyou~25":"Phebe — Por nenhuma má vontade que te tenha.","rosalindiprayyoudonotfallinlovewithmefor~untrosalindceliaandcorin~313":"Rosalind — Peço-te, não te apaixones por mim,\nPois sou mais falsa que votos feitos no vinho:\nAlém disso, não gosto de ti. Se queres saber minha casa,\nFica no bosquezinho de oliveiras aqui perto.\nVens, irmã? Pastor, insiste com ela com força.\nVem, irmã. Pastora, olha-o melhor,\nE não sejas orgulhosa: ainda que o mundo todo pudesse ver,\nNenhum seria tão enganado na vista quanto ele.\nVamos, ao nosso rebanho. Saem Rosalind, Celia e Corin.","phebedeadshepherdnowifindthysawofmightwh~thatlovednotatfirstsight~74":"Phebe — Pastor morto, agora acho poderoso o teu dito:\n“Quem amou, que não amou à primeira vista?”","silviussweetphebe~silviussweetphebe~17":"Silvius — Doce Phebe —","phebehawhatsaystthousilvius~behawhatsaystthousilvius~27":"Phebe — Ah, que dizes, Silvius?","silviussweetphebepityme~silviussweetphebepityme~23":"Silvius — Doce Phebe, tem piedade de mim.","phebewhyiamsorryfortheegentlesilvius~orryfortheegentlesilvius~36":"Phebe — Ora, tenho pena de ti, gentil Silvius.","silviuswhereversorrowisreliefwouldbeifyo~ygriefwerebothextermined~114":"Silvius — Onde há tristeza, deveria haver alívio:\nSe te entristeces com minha dor de amor,\nDando-me amor por tua tristeza, minha dor\nE ela serão ambas extintas.","phebethouhastmyloveisnotthatneighbourly~loveisnotthatneighbourly~39":"Phebe — Tens o meu amor: não é isso ser boa vizinha?","silviusiwouldhaveyou~silviusiwouldhaveyou~20":"Silvius — Quereria ter-te a ti.","phebewhythatwerecovetousnesssilviustheti~adnessthatthouartemployd~259":"Phebe — Ora, isso seria cobiça.\nSilvius, houve tempo em que te odiei,\nE contudo não é que te tenha amor;\nMas já que sabes falar tão bem de amor,\nA tua companhia, que antes me era enfadonha,\nSuportarei, e te empregarei também:\nMas não esperes outra recompensa\nAlém da tua própria alegria de seres empregado.","silviussoholyandsoperfectismyloveandiins~dsmileandthatillliveupon~194":"Silvius — Tão santo e tão perfeito é o meu amor,\nE eu em tamanha pobreza de graça,\nQue julgarei farta colheita\nRespigar as espigas quebradas após o homem\nQue ceifa a colheita principal: deixa cair de vez em quando\nUm sorriso disperso, e disso viverei.","phebeknowstnowtheyouththatspoketomeerewh~uththatspoketomeerewhile~43":"Phebe — Conheces agora o jovem que há pouco falou comigo?","silviusnotverywellbutihavemethimoftandhe~oldcarlotoncewasmasterof~103":"Silvius — Não muito bem, mas já o encontrei muitas vezes;\nE ele comprou a choupana e as terras\nQue o velho camponês um dia possuiu.","phebethinknotilovehimthoughiaskforhimtis~altbearitwiltthousilvius~900":"Phebe — Não penses que o amo, embora pergunte por ele:\nÉ apenas um rapaz impertinente; mas fala bem;\nMas que me importam palavras? Contudo as palavras valem\nQuando quem as diz agrada a quem as ouve.\nÉ um jovem bonito: não muito bonito:\nMas, decerto, é orgulhoso, e contudo o orgulho lhe assenta:\nDará um homem bem-feito: a melhor coisa nele\nÉ a tez; e mais depressa do que a língua\nFazia ofensa, seu olhar a curava.\nNão é muito alto; mas para a sua idade é alto:\nA perna é só assim assim; e contudo é boa:\nHavia um belo rubor em seus lábios,\nUm pouco mais maduro e mais vivo rubor\nDo que o misturado em sua face; era justamente a diferença\nEntre o vermelho constante e o damasco mesclado.\nHá mulheres, Silvius, que, tendo-o observado\nPor partes como eu fiz, teriam quase\nSe apaixonado por ele; mas, de minha parte,\nNão o amo nem o odeio; e contudo\nTenho mais motivo para odiá-lo que para amá-lo:\nPois que tinha ele a ver em me repreender?\nDisse que meus olhos eram negros e meu cabelo negro:\nE, agora me lembro, zombou de mim:\nAdmira-me por que não respondi na mesma:\nMas tanto faz; omitir não é quitar.\nEscreverei a ele uma carta muito zombeteira,\nE tu a levarás: levarás, Silvius?","silviusphebewithallmyheart~lviusphebewithallmyheart~26":"Silvius — Phebe, de todo o coração.","phebeillwriteitstraightthemattersinmyhea~ortgowithmesilviusexeunt~109":"Phebe — Escrevo-a logo;\nO assunto está em minha cabeça e em meu coração:\nSerei amarga com ele e extremamente breve.\nVem comigo, Silvius. Saem."}$tr$::jsonb, 591)
