insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_hamlet', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"acti":"Ato I","actii":"Ato II","actiii":"Ato III"}$tr$::jsonb, $tr${"scenei~scenei~6":"Cena I","elsinoreaplatformbeforethecastle~aplatformbeforethecastle~32":"Elsinore. Uma plataforma diante do castelo.","franciscoathispostentertohimbernardo~ispostentertohimbernardo~36":"Francisco em seu posto. Entra Bernardo.","bernardowhosthere~bernardowhosthere~17":"Bernardo — Quem está aí?","francisconayanswermestandandunfoldyourse~mestandandunfoldyourself~42":"Francisco — Não, responda-me você: alto, e identifique-se.","bernardolonglivetheking~bernardolonglivetheking~23":"Bernardo — Viva o rei!","franciscobernardo~franciscobernardo~17":"Francisco — Bernardo?","bernardohe~bernardohe~10":"Bernardo — Ele mesmo.","franciscoyoucomemostcarefullyuponyourhou~ostcarefullyuponyourhour~41":"Francisco — Você chega pontualíssimo à sua hora.","bernardotisnowstrucktwelvegettheetobedfr~lvegettheetobedfrancisco~47":"Bernardo — Já soaram as doze; vá para a cama, Francisco.","franciscoforthisreliefmuchthankstisbitte~tercoldandiamsickatheart~62":"Francisco — Muito obrigado pela rendição: faz um frio cortante, \n e eu estou com o coração doente.","bernardohaveyouhadquietguard~ardohaveyouhadquietguard~28":"Bernardo — Teve uma guarda tranquila?","francisconotamousestirring~ancisconotamousestirring~26":"Francisco — Nem um rato se mexeu.","bernardowellgoodnightifyoudomeethoratioa~fmywatchbidthemmakehaste~85":"Bernardo — Bem, boa noite. \n Se encontrar Horácio e Marcelo, \n meus companheiros de vigília, diga-lhes que se apressem.","franciscoithinkihearthemstandhowhosthere~hearthemstandhowhosthere~40":"Francisco — Acho que os ouço. Alto lá! Quem vem?","enterhoratioandmarcellus~enterhoratioandmarcellus~24":"Entram Horácio e Marcelo.","horatiofriendstothisground~ratiofriendstothisground~26":"Horácio — Amigos desta terra.","marcellusandliegementothedane~llusandliegementothedane~29":"Marcelo — E vassalos do Dinamarquês.","franciscogiveyougoodnight~ranciscogiveyougoodnight~25":"Francisco — Boa noite a vocês.","marcellusofarewellhonestsoldierwhohathre~oldierwhohathrelievedyou~49":"Marcelo — Oh, adeus, honesto soldado: \n quem o rendeu?","franciscobernardohasmyplacegiveyougoodni~lacegiveyougoodnightexit~47":"Francisco — Bernardo tomou meu lugar. \n Boa noite a vocês. Sai.","marcellushollabernardo~marcellushollabernardo~22":"Marcelo — Olá! Bernardo!","bernardosaywhatishoratiothere~rdosaywhatishoratiothere~29":"Bernardo — Diga, \n o quê, Horácio está aí?","horatioapieceofhim~horatioapieceofhim~18":"Horácio — Um pedaço dele.","bernardowelcomehoratiowelcomegoodmarcell~atiowelcomegoodmarcellus~42":"Bernardo — Bem-vindo, Horácio; bem-vindo, bom Marcelo.","marcelluswhathasthisthingappeardagainton~thingappeardagaintonight~44":"Marcelo — E então, essa coisa apareceu de novo esta noite?","bernardoihaveseennothing~bernardoihaveseennothing~24":"Bernardo — Não vi nada.","marcellushoratiosaystisbutourfantasyandw~proveoureyesandspeaktoit~230":"Marcelo — Horácio diz que é só fantasia nossa, \n e não deixa que a crença o domine \n quanto a essa visão terrível, vista duas vezes por nós: \n por isso lhe roguei que viesse conosco \n vigiar os minutos desta noite; \n para que, se essa aparição vier outra vez, \n ele confirme nossos olhos e lhe fale.","horatiotushtushtwillnotappear~iotushtushtwillnotappear~29":"Horácio — Bah, bah, não vai aparecer.","bernardositdownawhileandletusonceagainas~ywhatwehavetwonightsseen~108":"Bernardo — Sente-se um pouco; \n e deixe que mais uma vez assaltemos seus ouvidos, \n tão fortificados contra a nossa história, \n com o que vimos por duas noites.","horatiowellsitwedownandletushearbernardo~shearbernardospeakofthis~51":"Horácio — Pois bem, sentemo-nos, \n e ouçamos Bernardo falar disto.","bernardolastnightofallwhenyondsamestarth~elfthebellthenbeatingone~156":"Bernardo — Na noite passada, \n quando aquela mesma estrela, a oeste do polo, \n já tinha feito seu curso para iluminar aquela parte do céu \n onde agora arde, Marcelo e eu, \n o sino então batendo uma hora...","enterghost~enterghost~10":"Entra o Fantasma.","marcelluspeacebreaktheeofflookwhereitcom~offlookwhereitcomesagain~47":"Marcelo — Silêncio, cale-se; veja, aí vem ele de novo!","bernardointhesamefigurelikethekingthatsd~gurelikethekingthatsdead~43":"Bernardo — Na mesma figura, igual ao rei que morreu.","marcellusthouartascholarspeaktoithoratio~ascholarspeaktoithoratio~40":"Marcelo — Você é letrado; fale com ele, Horácio.","bernardolooksitnotlikethekingmarkithorat~likethekingmarkithoratio~42":"Bernardo — Não se parece com o rei? Repare, Horácio.","horatiomostlikeitharrowsmewithfearandwon~rrowsmewithfearandwonder~43":"Horácio — Muitíssimo: enche-me de medo e de assombro.","bernardoitwouldbespoketo~bernardoitwouldbespoketo~24":"Bernardo — Quer que lhe falem.","marcellusquestionithoratio~rcellusquestionithoratio~26":"Marcelo — Interrogue-o, Horácio.","horatiowhatartthouthatusurpstthistimeofn~byheavenichargetheespeak~151":"Horácio — Quem és tu, que usurpas esta hora da noite, \n juntamente com essa bela e guerreira forma \n na qual a majestade da Dinamarca sepultada \n outrora marchava? Pelo céu, eu te conjuro: fala!","marcellusitisoffended~marcellusitisoffended~21":"Marcelo — Ele se ofendeu.","bernardoseeitstalksaway~bernardoseeitstalksaway~23":"Bernardo — Vejam, ele se afasta a passos largos!","horatiostayspeakspeakichargetheespeakexi~chargetheespeakexitghost~46":"Horácio — Pára! Fala, fala! Eu te conjuro, fala! Sai o Fantasma.","marcellustisgoneandwillnotanswer~stisgoneandwillnotanswer~32":"Marcelo — Foi-se, e não quer responder.","bernardohownowhoratioyoutrembleandlookpa~anfantasywhatthinkyouont~90":"Bernardo — Então, Horácio! Você treme e está pálido: \n não é isto algo mais do que fantasia? \n Que pensa disso?","horatiobeforemygodimightnotthisbelievewi~dtrueavouchofmineowneyes~82":"Horácio — Perante meu Deus, eu não poderia crer nisto \n sem o testemunho sensível e verdadeiro \n dos meus próprios olhos.","marcellusisitnotliketheking~cellusisitnotliketheking~27":"Marcelo — Não se parece com o rei?","horatioasthouarttothyselfsuchwastheverya~olacksontheicetisstrange~158":"Horácio — Como você se parece consigo mesmo: \n era essa a mesma armadura que ele vestia \n quando combateu o ambicioso norueguês; \n assim franziu ele o cenho quando, num colérico parlamento, \n derrotou os polacos de trenó sobre o gelo. \n É estranho.","marcellusthustwicebeforeandjumpatthisdea~talkhathhegonebyourwatch~81":"Marcelo — Assim, duas vezes antes, e justo nesta hora morta, \n passou ele com marcial passada por nossa guarda.","horatioinwhatparticularthoughttoworkikno~trangeeruptiontoourstate~114":"Horácio — Em que pensamento particular trabalhar, não sei; \n mas no conjunto e alcance de minha opinião, \n isto pressagia alguma estranha erupção em nosso Estado.","marcellusgoodnowsitdownandtellmehethatkn~daywhoistthatcaninformme~348":"Marcelo — Ora, sente-se, e diga-me, quem souber, \n por que esta guarda tão estrita e vigilante \n fatiga assim todas as noites os súditos da terra, \n e por que tal fundição diária de canhões de bronze, \n e comércio estrangeiro de apetrechos de guerra; \n por que tal recrutamento de carpinteiros navais, cuja dura tarefa \n não separa o domingo do resto da semana; \n o que pode estar para vir, que esta pressa suada \n faz da noite companheira de labor do dia: \n quem é que pode me informar?","horatiothatcaniatleastthewhispergoessoou~thasteandromageintheland~943":"Horatio — Isso posso eu;\nAo menos, é o que corre em sussurros. Nosso último rei,\nCuja imagem ainda agora nos apareceu,\nFoi, como sabeis, por Fortinbras da Noruega,\nAguilhoado a isso por um orgulho muito rival,\nDesafiado ao combate; no qual nosso valente Hamlet —\nPois assim o estimava este lado do mundo conhecido —\nMatou esse Fortinbras; o qual, por pacto selado,\nBem ratificado por lei e heráldica,\nPerdeu, com a vida, todas aquelas terras suas\nQue possuía, em favor do vencedor:\nEm contrapartida, uma porção equivalente\nFoi empenhada por nosso rei; a qual teria passado\nÀ herança de Fortinbras,\nSe ele tivesse sido o vencedor; assim, pelo mesmo pacto\nE teor do artigo estabelecido,\nA dele coube a Hamlet. Ora, senhor, o jovem Fortinbras,\nDe têmpera não provada, quente e cheio de ardor,\nNas orlas da Noruega, aqui e ali,\nRecrutou à força uma lista de resolutos sem lei,\nPor comida e sustento, para alguma empresa\nQue tem estômago nela; a qual não é outra —\nComo bem se mostra ao nosso Estado —\nSenão recuperar de nós, por mão forte\nE termos compulsórios, aquelas terras ditas\nAssim perdidas por seu pai: e isto, tomo eu,\nÉ o motivo principal de nossos preparativos,\nA fonte desta nossa vigília e a causa principal\nDesta pressa e agitação na terra.","bernardoithinkitbenootherbuteensowellmay~isthequestionofthesewars~142":"Bernardo — Penso que não é outra coisa senão isso mesmo:\nBem pode combinar que esta figura portentosa\nVenha armada por nossa guarda; tão semelhante ao rei\nQue foi e é a causa destas guerras.","horatioamoteitistotroublethemindseyeinth~eholdlowhereitcomesagain~515":"Horatio — É um argueiro a turvar o olho da mente.\nNo mais alto e vitorioso estado de Roma,\nPouco antes de cair o poderosíssimo Júlio,\nAs sepulturas ficaram sem moradores e os mortos amortalhados\nGuinchavam e balbuciavam nas ruas romanas:\nEstrelas com caudas de fogo e orvalhos de sangue,\nDesastres no sol; e a estrela úmida\nEm cuja influência assenta o império de Netuno\nEsteve doente quase até o dia do juízo, com eclipse:\nE mesmo semelhante prenúncio de fatos ferozes,\nComo arautos que sempre precedem os destinos\nE prólogo ao presságio que se aproxima,\nCéu e terra juntos demonstraram\nAos nossos climas e compatriotas. —\nMas silêncio, vede! eis que vem de novo!","reenterghost~reenterghost~12":"Entra de novo o Fantasma.","illcrossitthoughitblastmestayillusionift~yandspeakstopitmarcellus~359":"Cruzar-lhe-ei o caminho, ainda que me fulmine. Fica, ilusão!\nSe tens algum som, ou uso de voz,\nFala-me:\nSe há alguma coisa boa a fazer,\nQue te traga alívio e a mim graça,\nFala-me: Canta o galo.\nSe és sabedor do destino de tua pátria,\nQue, felizmente, sabido de antemão, se possa evitar,\nOh, fala!\nOu se acumulaste em vida\nTesouro extorquido no ventre da terra,\nPelo qual, dizem, vós, espíritos, muitas vezes andais na morte,\nFala disso: fica, e fala! Detém-no, Marcellus.","marcellusshallistrikeatitwithmypartisan~strikeatitwithmypartisan~39":"Marcellus — Devo feri-lo com minha alabarda?","horatiodoifitwillnotstand~oratiodoifitwillnotstand~25":"Horatio — Fere, se não quiser parar.","bernardotishere~bernardotishere~15":"Bernardo — Está aqui!","horatiotishere~horatiotishere~14":"Horatio — Está aqui!","marcellustisgoneexitghostwedoitwrongbein~ainblowsmaliciousmockery~137":"Marcellus — Foi-se! Sai o Fantasma.\nFazemos mal, sendo ele tão majestoso,\nEm oferecer-lhe a mostra de violência;\nPois é, como o ar, invulnerável,\nE nossos golpes vãos, zombaria maligna.","bernardoitwasabouttospeakwhenthecockcrew~uttospeakwhenthecockcrew~40":"Bernardo — Estava prestes a falar, quando o galo cantou.","horatioandthenitstartedlikeaguiltythingu~esentobjectmadeprobation~294":"Horatio — E então estremeceu como culpado\nAnte uma convocação temerosa. Ouvi dizer\nQue o galo, que é a trombeta da manhã,\nCom sua garganta altiva e de som estridente\nDesperta o deus do dia; e, a seu aviso,\nSeja no mar ou no fogo, na terra ou no ar,\nO espírito errante e vagabundo corre\nPara o seu confinamento: e da verdade disto\nO objeto aqui presente deu prova.","marcellusitfadedonthecrowingofthecocksom~wdandsograciousisthetime~286":"Marcellus — Desvaneceu-se ao cantar do galo.\nDizem alguns que, sempre ao aproximar-se a estação\nEm que se celebra o nascimento de nosso Salvador,\nA ave da aurora canta a noite inteira:\nE então, dizem, nenhum espírito ousa vagar;\nAs noites são sadias; então nenhum planeta fere,\nNenhuma fada enfeitiça, nem bruxa tem poder de encantar,\nTão santo e tão gracioso é o tempo.","horatiosohaveiheardanddoinpartbelieveitb~inourlovesfittingourduty~297":"Horatio — Assim também ouvi e em parte acredito.\nMas olhai, a manhã, vestida de manto castanho,\nCaminha sobre o orvalho daquele alto monte do oriente:\nEncerremos a vigília; e, por meu conselho,\nComuniquemos o que vimos esta noite\nAo jovem Hamlet; pois, por minha vida,\nEste espírito, mudo para nós, falará a ele.\nConsentis que o informemos disto,\nComo necessário ao nosso afeto, conveniente ao nosso dever?","marcellusletsdotiprayandithismorningknow~immostconvenientlyexeunt~81":"Marcellus — Façamo-lo, peço; e eu sei esta manhã\nOnde o encontraremos mais comodamente. Saem.","sceneii~sceneii~7":"Cena II","aroomofstateinthecastle~aroomofstateinthecastle~23":"Uma sala de estado no castelo.","enterkingqueenhamletpoloniuslaertesvolti~neliuslordsandattendants~71":"Entram o Rei, a Rainha, Hamlet, Polonius, Laertes, Voltimand, Cornelius, Nobres e Criados.","kingthoughyetofhamletourdearbrothersdeat~yourhastecommendyourduty~1335":"Rei — Embora ainda esteja verde na memória a morte\nDe Hamlet, nosso caro irmão, e nos conviesse\nTrazer os corações em luto e todo o nosso reino\nContraído numa só fronte de dor,\nContudo a discrição tanto lutou com a natureza\nQue pensamos nele com a mais sábia tristeza,\nJuntamente com a lembrança de nós mesmos.\nPor isso a que foi nossa irmã, agora nossa rainha,\nA herdeira imperial deste Estado guerreiro,\nTomamos por esposa, como que com alegria derrotada —\nCom um olho auspicioso e outro em pranto,\nCom júbilo no funeral e lamento no casamento,\nEm igual balança pesando deleite e dor —\nNisto não excluímos\nVossas melhores sabedorias, que livremente acompanharam\nEste negócio. Por tudo, nossos agradecimentos.\nAgora segue-se, para que saibais, que o jovem Fortinbras,\nTendo fraca suposição de nosso valor,\nOu pensando que, pela morte de nosso caro irmão,\nNosso Estado esteja desconjuntado e desordenado,\nAliado ao sonho de sua vantagem,\nNão deixou de nos importunar com mensagens,\nExigindo a entrega daquelas terras\nPerdidas por seu pai, com todos os laços da lei,\nA nosso valentíssimo irmão. Tanto quanto a ele.\nAgora quanto a nós e a esta hora de reunião:\nO negócio é este: escrevemos aqui\nÀ Noruega, tio do jovem Fortinbras —\nQue, impotente e acamado, mal ouve\nDo intento deste seu sobrinho — para suprimir\nSeu avanço ulterior nisto; pois que as levas,\nAs listas e todas as proporções, são feitas\nEntre os súditos dele: e aqui vos despachamos,\nBom Cornelius, e a vós, Voltimand,\nComo portadores desta saudação ao velho Noruega;\nSem vos dar poder pessoal maior\nDe tratar com o rei do que o alcance\nDestes artigos aqui expostos permite.\nAdeus, e que vossa pressa recomende vosso dever.","corneliusvoltimandinthatandallthingswill~lthingswillweshowourduty~53":"Cornelius\nVoltimand — Nisto e em tudo mostraremos nosso dever.","kingwedoubtitnothingheartilyfarewellexeu~atwouldstthouhavelaertes~359":"Rei — Disso nada duvidamos: adeus, de coração. Saem Voltimand e Cornelius.\nE agora, Laertes, que novas tendes?\nFalastes-nos de algum pedido; qual é, Laertes?\nNão podeis falar com razão ao Dinamarquês\nE perder a voz: que pedirias, Laertes,\nQue não fosse oferta minha, não teu pedido?\nA cabeça não é mais natural ao coração,\nA mão mais instrumento da boca,\nDo que o trono da Dinamarca é a teu pai.\nQue desejas, Laertes?","laertesmydreadlordyourleaveandfavourtore~urgraciousleaveandpardon~227":"Laertes — Meu temido senhor,\nVossa licença e favor para voltar à França;\nDe onde, embora de bom grado viesse à Dinamarca,\nPara mostrar meu dever em vossa coroação,\nAgora, devo confessar, cumprido esse dever,\nMeus pensamentos e desejos voltam-se de novo para a França\nE se curvam à vossa graciosa licença e perdão.","kinghaveyouyourfathersleavewhatsayspolon~ersleavewhatsayspolonius~43":"Rei — Tens a licença de teu pai? Que diz Polonius?","poloniushehathmylordwrungfrommemyslowlea~seechyougivehimleavetogo~130":"Polonius — Ele, meu senhor, arrancou de mim minha lenta licença\nPor laboriosa súplica, e por fim\nSelei sobre a vontade dele meu duro consentimento:\nRogo-vos, dai-lhe licença para partir.","kingtakethyfairhourlaertestimebethineand~owmycousinhamletandmyson~97":"Rei — Toma tua bela hora, Laertes; o tempo seja teu,\nE tuas melhores graças o gastem a teu gosto!\nMas agora, meu primo Hamlet, e meu filho —","hamletasidealittlemorethankinandlessthan~rethankinandlessthankind~44":"Hamlet — À parte. Um pouco mais que parente, e menos que afim.","kinghowisitthatthecloudsstillhangonyou~tthecloudsstillhangonyou~38":"Rei — Como é que as nuvens ainda pairam sobre ti?","hamletnotsomylordiamtoomuchithesun~omylordiamtoomuchithesun~34":"Hamlet — Não é assim, meu senhor; estou demais ao sol.","queengoodhamletcastthynightedcolouroffan~gthroughnaturetoeternity~203":"Rainha — Bom Hamlet, despe essa cor noturna,\nE que teu olho olhe como amigo para a Dinamarca.\nNão busques para sempre, com as pálpebras baixas,\nTeu nobre pai no pó:\nSabes que é comum; tudo o que vive deve morrer,\nPassando pela natureza à eternidade.","hamletaymadamitiscommon~hamletaymadamitiscommon~23":"Hamlet — Sim, senhora, é comum.","queenifitbewhyseemsitsoparticularwiththe~msitsoparticularwiththee~41":"Rainha — Se é,\nPor que parece tão particular em ti?","hamletseemsmadamnayitisiknownotseemstisn~rappingsandthesuitsofwoe~368":"Hamlet — Parece, senhora! não, é; não conheço “parece”.\nNão é só meu manto de tinta, boa mãe,\nNem os trajes costumeiros de negro solene,\nNem o ventoso suspiro de fôlego forçado,\nNão, nem o rio fecundo no olho,\nNem o abatido semblante do rosto,\nJunto com todas as formas, humores, feitios de dor,\nQue podem verdadeiramente denotar-me: estes sim parecem,\nPois são ações que um homem poderia representar:\nMas tenho em mim aquilo que ultrapassa a aparência;\nEstes são apenas os adornos e as vestes do luto.","kingtissweetandcommendableinyournatureha~tcourtiercousinandourson~1031":"Rei — É doce e louvável em tua natureza, Hamlet,\nDar esses deveres de luto a teu pai:\nMas deves saber que teu pai perdeu um pai;\nEsse pai perdeu o seu, e o sobrevivente obrigado,\nPor obrigação filial, por algum tempo,\nA prestar obsequioso luto: mas persistir\nEm obstinada aflição é um proceder\nDe teimosia ímpia; é dor indigna de homem;\nMostra uma vontade muito incorreta para com o céu,\nUm coração desfortificado, uma mente impaciente,\nUm entendimento simples e sem instrução:\nPois o que sabemos que deve ser e é tão comum\nQuanto a mais vulgar coisa aos sentidos,\nPor que em nossa birrenta oposição\nTomá-lo a peito? Ora! é falta para com o céu,\nFalta contra os mortos, falta para com a natureza,\nAbsurdíssima para a razão; cujo tema comum\nÉ a morte dos pais, e que sempre clamou,\nDesde o primeiro cadáver até o que morreu hoje,\n“Isto deve ser.” Rogamos-te, joga por terra\nEste pranto sem proveito, e pensa em nós\nComo em um pai: pois que o mundo tome nota,\nÉs o mais próximo de nosso trono;\nE com não menor nobreza de amor\nQue aquela com que o mais caro pai trata o filho\nEu me dirijo a ti. Quanto ao teu intento\nDe voltar à escola em Wittenberg,\nÉ sumamente contrário ao nosso desejo:\nE rogamos-te que te dobres a ficar\nAqui, no ânimo e conforto de nosso olhar,\nNosso primeiro cortesão, primo e nosso filho.","queenletnotthymotherloseherprayershamlet~ywithusgonottowittenberg~76":"Rainha — Não deixes tua mãe perder suas preces, Hamlet:\nPeço-te, fica conosco; não vás a Wittenberg.","hamletishallinallmybestobeyyoumadam~linallmybestobeyyoumadam~35":"Hamlet — Obedecer-vos-ei no melhor que puder, senhora.","kingwhytisalovingandafairreplybeasoursel~meawayexeuntallbuthamlet~292":"Rei — Ora, é uma resposta amorosa e bela:\nSê como nós mesmos na Dinamarca. Senhora, vinde;\nEste gentil e espontâneo acordo de Hamlet\nSenta sorrindo em meu coração: em honra do qual,\nNenhum brinde jovial que a Dinamarca beba hoje\nDeixará de ser dito ao céu pelo grande canhão,\nE o brinde do rei os céus repetirão,\nRe-falando o trovão terrestre. Vamos. Saem todos, exceto Hamlet.","hamletothatthistootoosolidfleshwouldmelt~eartforimustholdmytongue~1038":"Hamlet — Oh, que esta carne tão, tão sólida se derretesse,\nSe dissolvesse e se resolvesse em orvalho!\nOu que o Eterno não tivesse fixado\nSeu cânone contra o autoassassínio! Ó Deus! Deus!\nQuão cansativos, rançosos, chatos e inúteis\nParecem-me todos os usos deste mundo!\nQue horror! ah, que horror! é um jardim por capinar,\nQue vai à semente; coisas rançosas e grosseiras por natureza\nPossuem-no inteiramente. Que se chegasse a isto!\nMorto há só dois meses: não, nem tanto, nem dois:\nTão excelente rei; que era, comparado a este,\nHipérion a um sátiro; tão amoroso com minha mãe\nQue não permitia aos ventos do céu\nVisitar-lhe o rosto com demasiada aspereza. Céu e terra!\nDevo lembrar? ora, ela se pendurava nele,\nComo se o crescer do apetite aumentasse\nCom o que o alimentava: e contudo, em um mês —\nNão me deixeis pensar nisso — Fragilidade, teu nome é mulher! —\nUm mês pequeno, antes que aqueles sapatos estivessem velhos\nCom que seguiu o corpo do meu pobre pai,\nComo Níobe, toda lágrimas: — ora ela, ela mesma —\nOh, Deus! um bicho, que carece de discurso da razão,\nTeria chorado mais tempo — casou-se com meu tio,\nIrmão de meu pai, mas não mais parecido com meu pai\nDo que eu com Hércules: em um mês:\nAntes que o sal das mais injustas lágrimas\nTivesse deixado o rubor nos seus olhos esfolados,\nCasou-se. Oh, velocidade maldosíssima, correr\nCom tal destreza a lençóis incestuosos!\nNão é nem pode vir a bem:\nMas rebenta, meu coração; pois devo calar a língua.","enterhoratiomarcellusandbernardo~atiomarcellusandbernardo~32":"Entram Horatio, Marcellus e Bernardo.","horatiohailtoyourlordship~oratiohailtoyourlordship~25":"Horatio — Salve, senhoria!","hamletiamgladtoseeyouwellhoratiooridofor~horatiooridoforgetmyself~49":"Hamlet — Folgo em ver-vos bem:\nHoratio — ou esqueço-me de mim mesmo.","horatiothesamemylordandyourpoorservantev~rdandyourpoorservantever~42":"Horatio — O mesmo, meu senhor, e vosso pobre servo sempre.","hamletsirmygoodfriendillchangethatnamewi~ttenberghoratiomarcellus~89":"Hamlet — Senhor, meu bom amigo; trocarei convosco esse nome:\nE que fazeis longe de Wittenberg, Horatio?\nMarcellus?","marcellusmygoodlord~marcellusmygoodlord~19":"Marcellus — Meu bom senhor —","hamletiamverygladtoseeyougoodevensirbutw~ithmakeyoufromwittenberg~71":"Hamlet — Estou muito contente em ver-vos. Boa noite, senhor.\nMas então, em fé, que fazeis longe de Wittenberg?","horatioatruantdispositiongoodmylord~antdispositiongoodmylord~35":"Horatio — Uma disposição de vadio, bom senhor meu.","hamletiwouldnothearyourenemysaysonorshal~utodrinkdeepereyoudepart~193":"Hamlet — Não ouviria vosso inimigo dizê-lo,\nNem fareis a meu ouvido essa violência\nDe fazê-lo crer em vosso próprio relato\nContra vós mesmo: sei que não sois vadio.\nMas qual é vosso assunto em Elsinore?\nEnsinar-vos-emos a beber fundo antes de partirdes.","horatiomylordicametoseeyourfathersfunera~etoseeyourfathersfuneral~41":"Horatio — Meu senhor, vim ver o funeral de vosso pai.","hamletipraytheedonotmockmefellowstudenti~wastoseemymotherswedding~71":"Hamlet — Peço-te, não zombes de mim, colega de estudos;\nCreio que foi para ver o casamento de minha mãe.","horatioindeedmylorditfollowdhardupon~dmylorditfollowdhardupon~36":"Horatio — Em verdade, meu senhor, seguiu-se logo depois.","hamletthriftthrifthoratiothefuneralbaked~thermethinksiseemyfather~171":"Hamlet — Economia, economia, Horatio! as carnes assadas do funeral\nServiram, frias, às mesas do casamento.\nQuisera ter encontrado meu mais caro inimigo no céu\nAntes de ter visto aquele dia, Horatio!\nMeu pai! — parece-me ver meu pai.","horatiowheremylord~horatiowheremylord~18":"Horatio — Onde, meu senhor?","hamletinmymindseyehoratio~amletinmymindseyehoratio~25":"Hamlet — No olho da minha mente, Horatio.","horatioisawhimoncehewasagoodlyking~whimoncehewasagoodlyking~34":"Horatio — Vi-o uma vez; era um belo rei.","hamlethewasamantakehimforallinallishalln~lnotlookuponhislikeagain~62":"Hamlet — Era um homem, tomando-o em tudo,\nJamais verei outro igual.","horatiomylordithinkisawhimyesternight~ithinkisawhimyesternight~37":"Horatio — Meu senhor, penso que o vi ontem à noite.","hamletsawwho~hamletsawwho~12":"Hamlet — Viste? quem?","horatiomylordthekingyourfather~omylordthekingyourfather~30":"Horatio — Meu senhor, o rei vosso pai.","hamletthekingmyfather~hamletthekingmyfather~21":"Hamlet — O rei meu pai!","horatioseasonyouradmirationforawhilewith~gentlementhismarveltoyou~111":"Horatio — Temperai vossa admiração por um momento\nCom ouvido atento, até que eu possa relatar,\nSob o testemunho destes cavalheiros,\nEsta maravilha a vós.","hamletforgodsloveletmehear~mletforgodsloveletmehear~26":"Hamlet — Por amor de Deus, deixai-me ouvir.","horatiotwonightstogetherhadthesegentleme~thesehandsarenotmorelike~574":"Horatio — Por duas noites seguidas, estes cavalheiros,\nMarcellus e Bernardo, em sua guarda,\nNo ermo profundo e meio da noite,\nForam assim abordados. Uma figura como vosso pai,\nArmada exatamente da cabeça aos pés,\nAparece diante deles, e com marcha solene\nPassa lenta e majestosa ao lado deles: três vezes caminhou\nDiante de seus olhos oprimidos e surpresos de medo,\nÀ distância de seu bastão; enquanto eles, destilados\nQuase em geleia pelo ato do medo,\nFicam mudos e não lhe falam. Isto a mim\nComunicaram em pavoroso segredo;\nE eu com eles na terceira noite montei a guarda:\nOnde, como tinham relatado, tanto o tempo,\nA forma da coisa, cada palavra verdadeira e boa,\nA aparição vem: conheci vosso pai;\nEstas mãos não são mais semelhantes.","hamletbutwherewasthis~hamletbutwherewasthis~21":"Hamlet — Mas onde foi isto?","marcellusmylordupontheplatformwherewewat~theplatformwherewewatchd~43":"Marcellus — Meu senhor, na plataforma onde montávamos guarda.","hamletdidyounotspeaktoit~hamletdidyounotspeaktoit~24":"Hamlet — Não lhe falastes?","horatiomylordididbutanswermadeitnoneyeto~ayandvanishdfromoursight~201":"Horatio — Meu senhor, falei;\nMas resposta não deu nenhuma: contudo, uma vez pareceu-me\nQue levantou a cabeça e se dispôs\nA mover-se, como se quisesse falar;\nMas nesse instante o galo da manhã cantou alto,\nE ao som encolheu-se e foi-se às pressas,\nE desvaneceu-se de nossa vista.","hamlettisverystrange~hamlettisverystrange~20":"Hamlet — É muito estranho.","horatioasidolivemyhonourdlordtistrueandw~nourdutytoletyouknowofit~84":"Horatio — Pela minha vida, honrado senhor, é verdade;\nE julgamos estar escrito em nosso dever\nFazer-vos saber disso.","hamletindeedindeedsirsbutthistroublesmeh~meholdyouthewatchtonight~61":"Hamlet — Em verdade, em verdade, senhores, mas isto me perturba.\nMontais a guarda esta noite?","marcellusbernardowedomylord~cellusbernardowedomylord~27":"Marcellus\nBernardo — Sim, meu senhor.","hamletarmdsayyou~hamletarmdsayyou~16":"Hamlet — Armado, dizeis?","marcellusbernardoarmdmylord~cellusbernardoarmdmylord~27":"Marcellus\nBernardo — Armado, meu senhor.","hamletfromtoptotoe~hamletfromtoptotoe~18":"Hamlet — Do alto à ponta dos pés?","marcellusbernardomylordfromheadtofoot~ardomylordfromheadtofoot~37":"Marcellus\nBernardo — Meu senhor, da cabeça aos pés.","hamletthensawyounothisface~mletthensawyounothisface~26":"Hamlet — Então não lhe vistes o rosto?","horatiooyesmylordheworehisbeaverup~smylordheworehisbeaverup~34":"Horatio — Oh, sim, meu senhor; usava a viseira levantada.","hamletwhatlookdhefrowningly~letwhatlookdhefrowningly~27":"Hamlet — Ora, olhava carrancudo?","horatioacountenancemoreinsorrowthaninang~emoreinsorrowthaninanger~42":"Horatio — Um semblante mais de tristeza que de ira.","hamletpaleorred~hamletpaleorred~15":"Hamlet — Pálido ou corado?","horationayverypale~horationayverypale~18":"Horatio — Não, muito pálido.","hamletandfixdhiseyesuponyou~letandfixdhiseyesuponyou~27":"Hamlet — E fixou os olhos em vós?","horatiomostconstantly~horatiomostconstantly~21":"Horatio — Muito constantemente.","hamletiwouldihadbeenthere~amletiwouldihadbeenthere~25":"Hamlet — Quisera eu ter estado lá.","horatioitwouldhavemuchamazedyou~itwouldhavemuchamazedyou~31":"Horatio — Muito vos teria espantado.","hamletverylikeverylikestayditlong~ylikeverylikestayditlong~33":"Hamlet — Muito provável, muito provável. Ficou muito tempo?","horatiowhileonewithmoderatehastemighttel~tehastemighttellahundred~49":"Horatio — Enquanto alguém com pressa moderada contaria cem.","marcellusbernardolongerlonger~llusbernardolongerlonger~29":"Marcellus\nBernardo — Mais, mais.","horationotwhenisawt~horationotwhenisawt~19":"Horatio — Não quando eu o vi.","hamlethisbeardwasgrizzledno~lethisbeardwasgrizzledno~27":"Hamlet — A barba era grisalha — não?","horatioitwasasihaveseenitinhislifeasable~itinhislifeasablesilverd~47":"Horatio — Era, como a vi em vida dele,\nUm negro prateado.","hamletiwillwatchtonightperchancetwillwal~tperchancetwillwalkagain~46":"Hamlet — Vigiarei esta noite;\nTalvez ande de novo.","horatioiwarrantitwill~horatioiwarrantitwill~21":"Horatio — Garanto que andará.","hamletifitassumemynoblefatherspersonills~evenandtwelveillvisityou~314":"Hamlet — Se assumir a figura de meu nobre pai,\nFalar-lhe-ei, ainda que o próprio inferno se abra\nE me mande calar. Peço a todos vós,\nSe até agora ocultastes esta visão,\nQue continue guardada em vosso silêncio;\nE o que mais acontecer esta noite,\nDai-lhe entendimento, mas não língua:\nRetribuirei vossa afeição. Assim, passai bem:\nNa plataforma, entre onze e doze,\nVisitar-vos-ei.","allourdutytoyourhonour~allourdutytoyourhonour~22":"Todos — Nosso dever à vossa honra.","hamletyourlovesasminetoyoufarewellexeunt~rwhelmthemtomenseyesexit~206":"Hamlet — Vossa afeição, como a minha por vós: adeus. Saem todos, exceto Hamlet.\nO espírito de meu pai em armas! nem tudo vai bem;\nSuspeito de alguma vilania: viesse logo a noite!\nAté lá, fica quieta, minh’alma: atos vis se erguerão,\nAinda que toda a terra os cubra, aos olhos dos homens. Sai.","sceneiii~sceneiii~8":"Cena III","aroominpoloniushouse~aroominpoloniushouse~20":"Uma sala na casa de Polonius.","enterlaertesandophelia~enterlaertesandophelia~22":"Entram Laertes e Ophelia.","laertesmynecessariesareembarkdfarewellan~sleepbutletmehearfromyou~117":"Laertes — Minhas coisas necessárias estão embarcadas: adeus:\nE, irmã, enquanto os ventos dão proveito\nE há escolta de auxílio, não durmas,\nMas deixa-me ter notícias tuas.","opheliadoyoudoubtthat~opheliadoyoudoubtthat~21":"Ophelia — Duvidas disso?","laertesforhamletandthetriflingofhisfavou~upplianceofaminutenomore~171":"Laertes — Quanto a Hamlet e ao brincar de seu favor,\nTem-no por moda e um capricho do sangue,\nUma violeta na juventude da primeira natureza,\nPrecoce, não permanente, doce, não duradoura,\nO perfume e passatempo de um minuto;\nNada mais.","ophelianomorebutso~ophelianomorebutso~18":"Ophelia — Nada mais que isso?","laertesthinkitnomorefornaturecrescentdoe~rebelsthoughnoneelsenear~1159":"Laertes — Não penses em mais:\nPois a natureza, ao crescer, não cresce só\nEm músculos e volume, mas, à medida que este templo se alarga,\nO serviço interior da mente e da alma\nCresce largo com ele. Talvez ele te ame agora,\nE agora nenhuma mancha nem astúcia macule\nA virtude de sua vontade: mas deves temer,\nPesada a sua grandeza, que a vontade dele não é só dele;\nPois ele mesmo está sujeito ao seu nascimento:\nNão pode, como as pessoas sem valia, esculpir\nPor si a sua escolha; pois da escolha dele depende\nA segurança e a saúde de todo este Estado;\nE por isso a escolha dele deve ser circunscrita\nÀ voz e ao consentimento daquele corpo\nDe que ele é a cabeça. Então se ele diz que te ama,\nConvém à tua sabedoria acreditá-lo apenas até onde\nEle, em seu ato e posição particular,\nPossa dar cumprimento à sua palavra; o que não vai além\nDo que vai a voz principal da Dinamarca.\nPesa então que perda tua honra pode sofrer,\nSe com ouvido crédulo demais escutas suas canções,\nOu perdes o coração, ou abres teu casto tesouro\nÀ sua importunação indomada.\nTeme-o, Ophelia, teme-o, minha cara irmã,\nE mantém-te na retaguarda de tua afeição,\nFora do alcance e do perigo do desejo.\nA donzela mais cautelosa é pródiga bastante,\nSe desvela a sua beleza à lua:\nA própria virtude não escapa aos golpes caluniosos:\nO verme rói os filhos da primavera,\nMuito amiúde antes que seus botões se abram,\nE na manhã e no orvalho líquido da juventude\nOs contágios do mal são os mais iminentes.\nSê cautelosa então; a melhor segurança está no temor:\nA juventude se rebela contra si mesma, ainda que ninguém esteja perto.","opheliaishalltheeffectofthisgoodlessonke~adsandrecksnothisownrede~237":"Ophelia — Guardarei o efeito desta boa lição\nComo sentinela do meu coração. Mas, bom irmão meu,\nNão faças como certos pastores sem graça,\nQue me mostram o caminho íngreme e espinhoso do céu;\nEnquanto, como libertino inchado e descuidado,\nEles mesmos trilham a senda florida do prazer,\nE não fazem caso do próprio conselho.","laertesofearmenotistaytoolongbutheremyfa~longbutheremyfathercomes~49":"Laertes — Oh, não temas por mim.\nDemoro-me demais: mas aqui vem meu pai.","enterpolonius~enterpolonius~13":"Entra Polônio.","adoubleblessingisadoublegraceoccasionsmi~onsmilesuponasecondleave~59":"Uma dupla bênção é uma dupla graça;\nA ocasião sorri a uma segunda despedida.","poloniusyetherelaertesaboardaboardforsha~blessingseasonthisinthee~930":"Polonius — Ainda aqui, Laertes! a bordo, a bordo, que vergonha!\nO vento está no ombro da tua vela,\nE és esperado. Toma; minha bênção contigo!\nE estes poucos preceitos na tua memória\nVê que os grave. Não dês língua aos teus pensamentos,\nNem ato a nenhum pensamento desproporcionado.\nSê familiar, mas de modo algum vulgar.\nOs amigos que tens, e cuja adoção está provada,\nPrende-os à tua alma com aros de aço;\nMas não calejes a palma com o trato\nDe cada camarada recém-chocado e sem penas. Cuida\nDe entrar numa briga, mas, estando nela,\nPorta-te de modo que o adversário se acautele de ti.\nDá a todo homem teu ouvido, mas a poucos tua voz;\nToma o juízo de cada um, mas reserva o teu.\nCaro seja teu traje quanto a bolsa puder comprar,\nMas não exprimido em extravagância; rico, não berrante;\nPois o vestuário muitas vezes proclama o homem,\nE os da França, de melhor posição e estado,\nSão nisso de gosto muito seleto e generoso.\nNem tomador nem emprestador sejas;\nPois o empréstimo muitas vezes perde a si e ao amigo,\nE o tomar embota o gume da economia.\nIsto acima de tudo: sê fiel a ti mesmo,\nE seguir-se-á, como a noite ao dia,\nQue não poderás então ser falso com homem algum.\nAdeus: minha bênção tempere isto em ti!","laertesmosthumblydoitakemyleavemylord~mblydoitakemyleavemylord~37":"Laertes — Muito humildemente me despeço, meu senhor.","poloniusthetimeinvitesyougoyourservantst~tesyougoyourservantstend~43":"Polonius — O tempo te convida; vai; teus criados aguardam.","laertesfarewellopheliaandrememberwellwha~erwellwhatihavesaidtoyou~55":"Laertes — Adeus, Ophelia; e lembra-te bem\nDo que te disse.","opheliatisinmymemorylockdandyouyourselfs~rselfshallkeepthekeyofit~58":"Ophelia — Está trancado em minha memória,\nE tu mesmo guardarás a chave.","laertesfarewellexit~laertesfarewellexit~19":"Laertes — Adeus. Sai.","poloniuswhatistopheliahehathsaidtoyou~stopheliahehathsaidtoyou~37":"Polonius — O que é, Ophelia, que ele te disse?","opheliasopleaseyousomethingtouchingthelo~ingtouchingthelordhamlet~48":"Ophelia — Se vos apraz, algo sobre o Senhor Hamlet.","poloniusmarrywellbethoughttistoldmehehat~tweenyougivemeupthetruth~287":"Polonius — Ora, bem lembrado:\nDizem-me que ele muito amiúde, ultimamente,\nTem dado tempo privado a ti; e tu mesma\nTens sido de tua audiência muito livre e generosa:\nSe for assim, como assim me é dito,\nE isso a título de cautela, devo dizer-te,\nNão compreendes a ti mesma tão claramente\nQuanto convém a minha filha e à tua honra.\nQue há entre vós? dá-me a verdade.","opheliahehathmylordoflatemademanytenders~endersofhisaffectiontome~58":"Ophelia — Ele tem, meu senhor, ultimamente feito muitas ofertas\nDe sua afeição por mim.","poloniusaffectionpoohyouspeaklikeagreeng~ehistendersasyoucallthem~112":"Polonius — Afeição! bah! falas como uma menina verde,\nNão peneirada em tão perigosa circunstância.\nAcreditas nas suas ofertas, como as chamas?","opheliaidonotknowmylordwhatishouldthink~owmylordwhatishouldthink~39":"Ophelia — Não sei, meu senhor, o que devo pensar.","poloniusmarryillteachyouthinkyourselfaba~itthusyoulltendermeafool~187":"Polonius — Pois bem, ensinar-te-ei: pensa em ti como criança;\nQue tomaste estas ofertas por pagamento verdadeiro,\nQue não são de lei. Oferece-te mais caro;\nOu — para não quebrar o fôlego da pobre frase,\nCorrendo-a assim — oferecer-me-ás um tolo.","opheliamylordhehathimportunedmewithlovei~hloveinhonourablefashion~58":"Ophelia — Meu senhor, ele tem me importunado com amor\nDe modo honroso.","poloniusayfashionyoumaycallitgotogoto~hionyoumaycallitgotogoto~37":"Polonius — Sim, “modo” podes chamar; vamos, vamos.","opheliaandhathgivencountenancetohisspeec~stalltheholyvowsofheaven~79":"Ophelia — E tem dado crédito à sua fala, meu senhor,\nCom quase todos os santos votos do céu.","poloniusayspringestocatchwoodcocksidokno~otichargeyoucomeyourways~709":"Polonius — Sim, laços para apanhar galinholas. Bem sei,\nQuando o sangue arde, quão pródiga a alma\nEmpresta votos à língua: estes lampejos, filha,\nQue dão mais luz que calor, extintos em ambos,\nMesmo na sua promessa, enquanto se fazem,\nNão deves tomar por fogo. Desde agora\nSê um pouco mais escassa de tua presença virginal;\nPõe tuas conversas em preço mais alto\nQue o de um convite a parlamentar. Quanto ao Senhor Hamlet,\nCrê tanto dele: que é jovem,\nE com mais larga corda pode andar\nDo que a que te pode ser dada: em suma, Ophelia,\nNão creias em seus votos; pois são corretores,\nNão da cor que suas vestes mostram,\nMas puros suplicantes de pedidos profanos,\nRespirando como vínculos santificados e pios,\nPara melhor enganar. Isto vale para tudo:\nNão quereria, em termos claros, daqui por diante,\nQue difamasses assim qualquer momento de lazer\nDando palavras ou conversa ao Senhor Hamlet.\nCuida disso, ordeno-te: segue teu caminho.","opheliaishallobeymylordexeunt~iaishallobeymylordexeunt~29":"Ophelia — Obedecerei, meu senhor. Saem.","sceneiv~sceneiv~7":"Cena IV","theplatform~theplatform~11":"A plataforma.","enterhamlethoratioandmarcellus~amlethoratioandmarcellus~30":"Entram Hamlet, Horatio e Marcellus.","hamlettheairbitesshrewdlyitisverycold~itesshrewdlyitisverycold~37":"Hamlet — O ar morde com astúcia; está muito frio.","horatioitisanippingandaneagerair~tisanippingandaneagerair~32":"Horatio — É um ar cortante e mordaz.","hamletwhathournow~hamletwhathournow~17":"Hamlet — Que hora é agora?","horatioithinkitlacksoftwelve~tioithinkitlacksoftwelve~28":"Horatio — Penso que faltam para as doze.","hamletnoitisstruck~hamletnoitisstruck~18":"Hamlet — Não, já soaram.","horatioindeedihearditnotthenitdrawsneart~inwhatdoesthismeanmylord~146":"Horatio — Verdade? não ouvi: então se aproxima a hora\nEm que o espírito costumava andar. Fanfarra de trombetas, e tiros de canhão, dentro.\nQue significa isto, meu senhor?","hamletthekingdothwaketonightandtakeshisr~outthetriumphofhispledge~177":"Hamlet — O rei vela esta noite e faz seu brinde,\nFaz festança, e o fanfarrão novato cambaleia;\nE, enquanto esvazia seus goles de vinho do Reno,\nO tambor e a trombeta assim rugem\nO triunfo de seu brinde.","horatioisitacustom~horatioisitacustom~18":"Horatio — É um costume?","hamletaymarryistbuttomymindthoughiamnati~eofadoubttohisownscandal~840":"Hamlet — Sim, por certo, é:\nMas a meu ver, embora eu seja daqui nativo\nE nascido para o costume, é um costume\nMais honrado na quebra que na observância.\nEsta farra de cabeça pesada a leste e a oeste\nFaz-nos difamados e censurados por outras nações:\nChamam-nos beberrões, e com frase suína\nSujam nosso título; e de fato isso tira\nDe nossas realizações, ainda que executadas no auge,\nO tutano e a medula de nossa reputação.\nAssim, amiúde acontece a homens em particular,\nQue por alguma mácula viciosa da natureza neles,\nComo, em seu nascimento — no qual não têm culpa,\nPois a natureza não pode escolher sua origem —\nPelo excesso de algum temperamento,\nMuitas vezes derrubando as paliçadas e fortes da razão,\nOu por algum hábito que fermenta demais\nA forma das maneiras aprazíveis, que esses homens,\nLevando, digo, a marca de um só defeito,\nSendo libré da natureza, ou estrela da fortuna —\nSuas outras virtudes — sejam puras como a graça,\nInfinitas quanto o homem possa suportar —\nReceberão, no juízo geral, corrupção\nDaquela falta particular: a gota de mal\nFaz toda a nobre substância de uma dúvida\nSua própria vergonha.","horatiolookmylorditcomes~horatiolookmylorditcomes~24":"Horatio — Olhai, meu senhor, ele vem!","hamletangelsandministersofgracedefendusb~ldwedoghostbeckonshamlet~670":"Hamlet — Anjos e ministros da graça, defendei-nos!\nSejas espírito de saúde ou duende condenado,\nTragas contigo ares do céu ou rajadas do inferno,\nSejam tuas intenções perversas ou caridosas,\nVens em forma tão questionável\nQue te falarei: chamar-te-ei Hamlet,\nRei, pai, real Dinamarquês: oh, responde-me!\nNão me deixes estourar na ignorância; mas dize\nPor que teus ossos canonizados, sepultados na morte,\nRomperam suas mortalhas; por que o sepulcro,\nEm que te vimos quietamente depositado,\nAbriu suas pesadas mandíbulas de mármore,\nPara te lançar de volta. Que pode isto significar,\nQue tu, cadáver morto, de novo em aço completo,\nRevisitas assim os clarões da lua,\nTornando horrenda a noite; e nós, tolos da natureza,\nTão horrivelmente a sacudir nossa disposição\nCom pensamentos além do alcance de nossas almas?\nDize, por quê? para quê? que devemos fazer? O Fantasma acena a Hamlet.","horatioitbeckonsyoutogoawaywithitasifits~tmentdiddesiretoyoualone~72":"Horatio — Acena-vos para ir com ele,\nComo se desejasse comunicar-vos\nAlgo a vós sós.","marcelluslookwithwhatcourteousactionitwa~edgroundbutdonotgowithit~82":"Marcellus — Olhai com que gesto cortês\nVos chama a um terreno mais afastado:\nMas não vades com ele.","horationobynomeans~horationobynomeans~18":"Horatio — Não, de modo algum.","hamletitwillnotspeaktheniwillfollowit~otspeaktheniwillfollowit~37":"Hamlet — Não quer falar; então o seguirei.","horatiodonotmylord~horatiodonotmylord~18":"Horatio — Não, meu senhor.","hamletwhywhatshouldbethefearidonotsetmyl~smeforthagainillfollowit~139":"Hamlet — Ora, que há de temer?\nNão dou à minha vida o valor de uma agulha;\nE quanto à minha alma, que pode ele fazer-lhe,\nSendo coisa imortal como ele mesmo?\nEle me acena de novo: seguirei.","horatiowhatifittemptyoutowardthefloodmyl~seaandhearsitroarbeneath~325":"Horatio — E se vos tentar para o mar, meu senhor,\nOu para o cume assustador do penhasco\nQue se debruça sobre a base no mar,\nE ali assumir alguma outra forma horrível,\nQue possa privar vossa soberania da razão\nE arrastar-vos à loucura? pensai nisso:\nO próprio lugar põe fantasias de desespero,\nSem mais motivo, em todo cérebro\nQue olha tantas braças abaixo para o mar\nE o ouve rugir lá embaixo.","hamletitwavesmestillgoonillfollowthee~mestillgoonillfollowthee~37":"Hamlet — Ainda me acena.\nVai; seguir-te-ei.","marcellusyoushallnotgomylord~ellusyoushallnotgomylord~28":"Marcellus — Não ireis, meu senhor.","hamletholdoffyourhands~hamletholdoffyourhands~22":"Hamlet — Tirai as mãos.","horatioberuledyoushallnotgo~atioberuledyoushallnotgo~27":"Horatio — Deixai-vos guiar; não ireis.","hamletmyfatecriesoutandmakeseachpettyart~theeexeuntghostandhamlet~192":"Hamlet — Meu destino clama,\nE faz cada pequena artéria deste corpo\nTão robusta quanto o nervo do leão de Neméia.\nAinda sou chamado. Soltai-me, cavalheiros.\nPelo céu, farei um fantasma de quem me detiver!\nDigo, afastai-vos! Vai; seguir-te-ei. Saem o Fantasma e Hamlet.","horatiohewaxesdesperatewithimagination~desperatewithimagination~38":"Horatio — Torna-se desesperado pela imaginação.","marcellusletsfollowtisnotfitthustoobeyhi~owtisnotfitthustoobeyhim~41":"Marcellus — Sigamo-lo; não convém obedecer-lhe assim.","horatiohaveaftertowhatissuewillthiscome~rtowhatissuewillthiscome~39":"Horatio — Vamos atrás. A que fim chegará isto?","marcellussomethingisrotteninthestateofde~otteninthestateofdenmark~45":"Marcellus — Algo está podre no estado da Dinamarca.","horatioheavenwilldirectit~oratioheavenwilldirectit~25":"Horatio — O céu o dirigirá.","marcellusnayletsfollowhimexeunt~usnayletsfollowhimexeunt~31":"Marcellus — Não, sigamo-lo. Saem.","scenev~scenev~6":"Cena V","anotherpartoftheplatform~anotherpartoftheplatform~24":"Outra parte da plataforma.","enterghostandhamlet~enterghostandhamlet~19":"Entram o Fantasma e Hamlet.","hamletwherewiltthouleadmespeakillgonofur~eadmespeakillgonofurther~44":"Hamlet — Onde me levarás? fala; não irei mais longe.","ghostmarkme~ghostmarkme~11":"Fantasma — Escuta-me.","hamletiwill~hamletiwill~11":"Hamlet — Escutarei.","ghostmyhourisalmostcomewhenitosulphurous~flamesmustrenderupmyself~77":"Fantasma — Minha hora está quase chegada,\nEm que às chamas sulfurosas e atormentadoras\nDevo entregar-me.","hamletalaspoorghost~hamletalaspoorghost~19":"Hamlet — Ai, pobre fantasma!","ghostpitymenotbutlendthyserioushearingto~earingtowhatishallunfold~56":"Fantasma — Não me lastimes, mas empresta teu ouvido sério\nAo que vou revelar.","hamletspeakiamboundtohear~amletspeakiamboundtohear~25":"Hamlet — Fala; estou obrigado a ouvir.","ghostsoartthoutorevengewhenthoushalthear~revengewhenthoushalthear~40":"Fantasma — Assim estás a vingar, quando ouvires.","hamletwhat~hamletwhat~10":"Hamlet — O quê?","ghostiamthyfathersspiritdoomdforacertain~dsteverthydearfatherlove~507":"Fantasma — Sou o espírito de teu pai,\nCondenado por certo tempo a andar de noite,\nE de dia confinado a jejuar em fogos,\nAté que os crimes torpes cometidos em meus dias de natureza\nSejam queimados e expurgados. Se não me fosse proibido\nContar os segredos de minha casa-prisão,\nPoderia revelar um conto cuja mais leve palavra\nDilaceraria tua alma, congelaria teu sangue jovem,\nFaria teus dois olhos, como estrelas, saltar das órbitas,\nTeus cabelos atados e entrelaçados se separarem\nE cada fio em particular se eriçar,\nComo espinhos no porco-espinho irritado:\nMas esta eterna revelação não deve ser feita\nA ouvidos de carne e sangue. Escuta, escuta, oh, escuta!\nSe alguma vez amaste teu caro pai —","hamletogod~hamletogod~10":"Hamlet — Ó Deus!","ghostrevengehisfoulandmostunnaturalmurde~ulandmostunnaturalmurder~41":"Fantasma — Vinga seu assassínio torpe e mais desnaturado.","hamletmurder~hamletmurder~12":"Hamlet — Assassínio!","ghostmurdermostfoulasinthebestitisbutthi~tfoulstrangeandunnatural~68":"Fantasma — Assassínio torpíssimo, como o é no melhor dos casos;\nMas este o mais torpe, estranho e desnaturado.","hamlethastemetoknowtthatiwithwingsasswif~flovemaysweeptomyrevenge~91":"Hamlet — Apressa-me a sabê-lo, para que eu, com asas tão velozes\nQuanto a meditação ou os pensamentos de amor,\nPossa varrer à minha vingança.","ghostifindtheeaptanddullershouldstthoube~herslifenowwearshiscrown~307":"Fantasma — Acho-te disposto;\nE mais obtuso serias que a erva gorda\nQue se enraíza no ócio no cais do Letes,\nSe não te agitasses nisto. Agora, Hamlet, ouve:\nEspalha-se que, dormindo em meu pomar,\nUma serpente me picou; assim todo o ouvido da Dinamarca\nÉ por um falso relato de minha morte\nGrosseiramente enganado: mas sabe, nobre jovem,\nQue a serpente que picou a vida de teu pai\nAgora usa a coroa dele.","hamletomypropheticsoulmyuncle~tomypropheticsoulmyuncle~29":"Hamlet — Ó minha alma profética!\nMeu tio!","ghostaythatincestuousthatadulteratebeast~dieuhamletremembermeexit~1577":"Fantasma — Sim, aquela besta incestuosa, adúltera,\nCom bruxaria de seu engenho, com dons traiçoeiros —\nOh, engenho e dons perversos, que têm o poder\nDe tão bem seduzir! — conquistou à sua lascívia vergonhosa\nA vontade de minha rainha de tanta aparência de virtude:\nÓ Hamlet, que queda foi essa!\nDe mim, cujo amor era de tal dignidade\nQue ia de mãos dadas com o voto\nQue lhe fiz no casamento, e decair\nPara um miserável cujos dons naturais eram pobres\nAnte os meus!\nMas a virtude, assim como nunca se comoverá,\nAinda que a lascívia a corteje em forma celeste,\nAssim a luxúria, ainda que ligada a um anjo radiante,\nSaciar-se-á em leito celestial,\nE se alimentará de lixo.\nMas, silêncio! parece-me sentir o ar da manhã;\nSeja eu breve. Dormindo em meu pomar,\nMeu costume sempre à tarde,\nNa minha hora segura teu tio esgueirou-se,\nCom suco de maldito heléboro num frasco,\nE nos pórticos dos meus ouvidos derramou\nA destilação leprosa; cujo efeito\nTem tal inimizade com o sangue do homem\nQue, veloz como o mercúrio, corre através\nDos portões e vielas naturais do corpo,\nE com súbito vigor coalha\nE talha, como gotas ácidas no leite,\nO sangue fino e sadio: assim fez ao meu;\nE uma instantânea sarna recobriu,\nComo de leproso, com crosta vil e repugnante,\nTodo o meu corpo liso.\nAssim fui eu, dormindo, por mão de irmão\nDe vida, de coroa, de rainha, de uma vez despachado:\nCeifado ainda em flor de meu pecado,\nSem sacramento, despreparado, sem extrema-unção,\nSem contas feitas, mas enviado ao meu ajuste\nCom todas as minhas imperfeições sobre a cabeça:\nOh, horrível! Oh, horrível! horribilíssimo!\nSe tens natureza em ti, não o suportes;\nNão deixes o leito real da Dinamarca ser\nUm divã para a luxúria e o incesto maldito.\nMas, como quer que persigas este ato,\nNão manches tua mente, nem deixes tua alma tramar\nAlgo contra tua mãe: deixa-a ao céu\nE àqueles espinhos que em seu seio se alojam,\nPara a picar e ferroar. Adeus de uma vez!\nO vaga-lume mostra que a manhã está perto,\nE começa a empalidecer seu fogo ineficaz:\nAdeus, adeus! Hamlet, lembra-te de mim. Sai.","hamletoallyouhostofheavenoearthwhatelsea~ieuremembermeihaveswornt~652":"Hamlet — Ó vós todos, hoste do céu! Ó terra! que mais?\nE ajuntarei o inferno? Oh, que horror! Aguenta, aguenta, meu coração;\nE vós, meus nervos, não envelheçais de repente,\nMas sustentai-me firme. Lembrar-me de ti!\nSim, pobre fantasma, enquanto a memória tiver assento\nNeste globo transtornado. Lembrar-me de ti!\nSim, da tábua da minha memória\nApagarei todos os registros triviais e tolos,\nTodos os ditos dos livros, todas as formas, todas as impressões passadas,\nQue a juventude e a observação ali copiaram;\nE teu mandamento, sozinho, viverá\nNo livro e volume do meu cérebro,\nSem mistura de matéria mais baixa: sim, pelo céu!\nOh, mulher perniciosíssima!\nOh, vilão, vilão, vilão sorridente e maldito!\nMinhas tábuas — convém que eu o anote,\nQue alguém pode sorrir, e sorrir, e ser um vilão;\nAo menos tenho certeza de que pode ser assim na Dinamarca: Escrevendo.\nAssim, tio, aí estás. Agora a minha palavra;\nÉ “Adeus, adeus! lembra-te de mim.”\nJurei-o.","marcellushoratiowithinmylordmylord~oratiowithinmylordmylord~34":"Marcellus\nHoratio — Dentro. Meu senhor, meu senhor —","marcelluswithinlordhamlet~arcelluswithinlordhamlet~25":"Marcellus — Dentro. Senhor Hamlet —","horatiowithinheavensecurehim~tiowithinheavensecurehim~28":"Horatio — Dentro. O céu o proteja!","hamletsobeit~hamletsobeit~12":"Hamlet — Assim seja!","horatiowithinhillohohomylord~tiowithinhillohohomylord~28":"Horatio — Dentro. Ei, ho, ho, meu senhor!","hamlethillohohoboycomebirdcome~hillohohoboycomebirdcome~30":"Hamlet — Ei, ho, ho, rapaz! vem, ave, vem.","marcellushowistmynoblelord~rcellushowistmynoblelord~26":"Marcellus — Como está, meu nobre senhor?","horatiowhatnewsmylord~horatiowhatnewsmylord~21":"Horatio — Que novas, meu senhor?","hamletowonderful~hamletowonderful~16":"Hamlet — Oh, maravilhosas!","horatiogoodmylordtellit~horatiogoodmylordtellit~23":"Horatio — Bom senhor meu, contai-as.","hamletnoyoullrevealit~hamletnoyoullrevealit~21":"Hamlet — Não; vós as revelareis.","horationotimylordbyheaven~orationotimylordbyheaven~25":"Horatio — Eu não, meu senhor, pelo céu.","marcellusnorimylord~marcellusnorimylord~19":"Marcellus — Nem eu, meu senhor.","hamlethowsayyouthenwouldheartofmanonceth~ethinkitbutyoullbesecret~61":"Hamlet — Que dizeis, então; coração de homem alguma vez o pensaria?\nMas guardareis segredo?","horatiomarcellusaybyheavenmylord~arcellusaybyheavenmylord~32":"Horatio\nMarcellus — Sim, pelo céu, meu senhor.","hamlettheresneeravillaindwellinginallden~nmarkbuthesanarrantknave~63":"Hamlet — Não há vilão morando em toda a Dinamarca\nQue não seja um completo patife.","horatiothereneedsnoghostmylordcomefromth~fromthegravetotellusthis~58":"Horatio — Não precisa um fantasma, meu senhor, sair da sepultura\nPara nos dizer isto.","hamletwhyrightyouareitherightandsowithou~poorpartlookyouillgopray~212":"Hamlet — Ora, certo; tendes razão;\nE assim, sem mais circunstância alguma,\nJulgo conveniente apertarmos as mãos e partirmos:\nVós, como vosso negócio e desejo vos indicarem;\nPois todo homem tem negócio e desejo,\nTal qual seja; e quanto à minha pobre parte,\nVede, vou rezar.","horatiothesearebutwildandwhirlingwordsmy~ldandwhirlingwordsmylord~44":"Horatio — São apenas palavras selvagens e turbilhonantes, meu senhor.","hamletimsorrytheyoffendyouheartilyyesfai~heartilyyesfaithheartily~50":"Hamlet — Sinto muito que vos ofendam, de coração;\nSim, em fé, de coração.","horatiotheresnooffencemylord~tiotheresnooffencemylord~28":"Horatio — Não há ofensa, meu senhor.","hamletyesbysaintpatrickbutthereishoratio~iersgivemeonepoorrequest~235":"Hamlet — Sim, por São Patrício, há sim, Horatio,\nE muita ofensa também. Quanto a esta visão aqui,\nÉ um fantasma honesto, isso posso dizer-vos:\nQuanto ao vosso desejo de saber o que se passa entre nós,\nDominai-o como puderdes. E agora, bons amigos,\nJá que sois amigos, eruditos e soldados,\nConcedei-me um pobre pedido.","horatiowhatistmylordwewill~ratiowhatistmylordwewill~26":"Horatio — Qual é, meu senhor? Nós o faremos.","hamletnevermakeknownwhatyouhaveseentonig~wnwhatyouhaveseentonight~42":"Hamlet — Nunca torneis público o que vistes esta noite.","horatiomarcellusmylordwewillnot~marcellusmylordwewillnot~31":"Horatio\nMarcellus — Meu senhor, não o faremos.","hamletnaybutsweart~hamletnaybutsweart~18":"Hamlet — Não, mas jurai.","horatioinfaithmylordnoti~horatioinfaithmylordnoti~24":"Horatio — Em fé,\nMeu senhor, eu não.","marcellusnorimylordinfaith~rcellusnorimylordinfaith~26":"Marcellus — Nem eu, meu senhor, em fé.","hamletuponmysword~hamletuponmysword~17":"Hamlet — Sobre a minha espada.","marcelluswehaveswornmylordalready~wehaveswornmylordalready~33":"Marcellus — Já juramos, meu senhor.","hamletindeeduponmyswordindeed~tindeeduponmyswordindeed~29":"Hamlet — Sim, sobre a minha espada, sim.","ghostbeneathswear~ghostbeneathswear~17":"Fantasma — Embaixo. Jurai.","hamletahhaboysaystthousoartthoutheretrue~ecellarageconsenttoswear~96":"Hamlet — Ah, ha, rapaz! é o que dizes? estás aí, bom companheiro?\nVamos — ouvis este sujeito no porão —\nConsenti em jurar.","horatioproposetheoathmylord~atioproposetheoathmylord~27":"Horatio — Proponde o juramento, meu senhor.","hamletnevertospeakofthisthatyouhaveseens~ouhaveseenswearbymysword~53":"Hamlet — Nunca falar disto que vistes,\nJurai pela minha espada.","hamlethicetubiquethenwellshiftourgroundc~uhaveheardswearbymysword~137":"Hamlet — Hic et ubique? então mudaremos de lugar.\nVinde cá, cavalheiros,\nE ponde de novo as mãos sobre a minha espada:\nNunca falar disto que ouvistes,\nJurai pela minha espada.","hamletwellsaidoldmolecanstworkitheearths~ncemoreremovegoodfriends~83":"Hamlet — Bem dito, velha toupeira! sabes trabalhar na terra tão depressa?\nUm digno sapador! Mais uma vez mudemos, bons amigos.","horatioodayandnightbutthisiswondrousstra~butthisiswondrousstrange~43":"Horatio — Ó dia e noite, mas isto é maravilhosamente estranho!","hamletandthereforeasastrangergiveitwelco~yourmostneedhelpyouswear~527":"Hamlet — E por isso, como a um estranho, dai-lhe boas-vindas.\nHá mais coisas no céu e na terra, Horatio,\nDo que sonha a vossa filosofia.\nMas vinde;\nAqui, como antes, jamais, que a graça vos valha,\nPor mais estranho ou esquisito que eu me comporte,\nComo talvez daqui por diante julgue conveniente\nAssumir uma disposição extravagante,\nJamais, em tais momentos, ao ver-me,\nCom os braços cruzados assim, ou este balançar de cabeça,\nOu pronunciando alguma frase duvidosa,\nComo “Bem, bem, nós sabemos”, ou “Poderíamos, se quiséssemos”,\nOu “Se quiséssemos falar”, ou “Há quem pudesse, se lhe fosse dado”,\nOu outro modo ambíguo de insinuar, deixeis perceber\nQue sabeis algo de mim: isto não fazer,\nQue a graça e a misericórdia vos valham em vossa maior necessidade,\nJurai.","hamletrestrestperturbedspirittheyswearso~comeletsgotogetherexeunt~303":"Hamlet — Descansa, descansa, espírito perturbado! Eles juram. Assim, cavalheiros,\nCom todo o meu amor me recomendo a vós:\nE o que um homem tão pobre quanto Hamlet\nPuder fazer para exprimir seu amor e amizade por vós,\nSe Deus quiser, não faltará. Entremos juntos;\nE sempre os dedos nos lábios, peço-vos.\nO tempo está fora dos eixos: ó maldita sina,\nQue eu tenha nascido para endireitá-lo!\nNão, vinde, vamos juntos. Saem.","enterpoloniusandreynaldo~enterpoloniusandreynaldo~24":"Entram Polonius e Reynaldo.","poloniusgivehimthismoneyandthesenotesrey~neyandthesenotesreynaldo~45":"Polonius — Dá-lhe este dinheiro e estas notas, Reynaldo.","reynaldoiwillmylord~reynaldoiwillmylord~19":"Reynaldo — Darei, meu senhor.","poloniusyoushalldomarvellouswiselygoodre~makeinquireofhisbehavior~89":"Polonius — Farás maravilhosamente bem, bom Reynaldo,\nAntes de o visitares, em informar-te\nSobre o comportamento dele.","reynaldomylordididintendit~ynaldomylordididintendit~26":"Reynaldo — Meu senhor, era essa a minha intenção.","poloniusmarrywellsaidverywellsaidlookyou~himdoyoumarkthisreynaldo~364":"Polonius — Pois bem dito; muito bem dito. Olha, senhor,\nInforma-te primeiro de que dinamarqueses há em Paris;\nE como, e quem, com que meios, e onde moram,\nQue companhia, a que despesa; e descobrindo\nPor esse rodeio e curso de perguntas\nQue eles conhecem meu filho, aproxima-te mais\nDo que tuas perguntas particulares tocariam:\nFinge, por assim dizer, algum conhecimento distante dele;\nAssim: “Conheço o pai dele e seus amigos,\nE em parte a ele:” notas isto, Reynaldo?","reynaldoayverywellmylord~reynaldoayverywellmylord~24":"Reynaldo — Sim, muito bem, meu senhor.","poloniusandinparthimbutyoumaysaynotwellb~stknowntoyouthandliberty~246":"Polonius — “E em parte a ele; mas” podes dizer “não bem:\nMas, se é o que digo, é muito desregrado;\nDado a isto e àquilo:” e aí atribui-lhe\nQue falsidades quiseres; mas, nenhuma tão grosseira\nQue o desonre; toma cuidado com isso;\nMas, senhor, aqueles deslizes levianos, selvagens e comuns\nQue são companheiros notórios e bem conhecidos\nDa juventude e da liberdade.","reynaldoasgamingmylord~reynaldoasgamingmylord~22":"Reynaldo — Como o jogo, meu senhor.","poloniusayordrinkingfencingswearingquarr~ingdrabbingyoumaygosofar~67":"Polonius — Sim, ou a bebida, a esgrima, os palavrões, as brigas,\nO frequentar mulheres: podes ir até aí.","reynaldomylordthatwoulddishonourhim~ordthatwoulddishonourhim~35":"Reynaldo — Meu senhor, isso o desonraria.","poloniusfaithnoasyoumayseasonitinthechar~medbloodofgeneralassault~255":"Polonius — Em fé, não; desde que o tempereis na acusação.\nNão deves lançar-lhe outro escândalo,\nQue ele é aberto à incontinência;\nNão é essa minha intenção: mas sopra suas faltas com tal arte\nQue pareçam as manchas da liberdade,\nO lampejo e a irrupção de uma mente fogosa,\nUma selvageria em sangue não domado,\nDe assalto geral.","reynaldobutmygoodlord~reynaldobutmygoodlord~21":"Reynaldo — Mas, meu bom senhor —","poloniuswhereforeshouldyoudothis~whereforeshouldyoudothis~32":"Polonius — Por que deves fazer isto?","reynaldoaymylordiwouldknowthat~doaymylordiwouldknowthat~30":"Reynaldo — Sim, meu senhor,\nQuisera saber isso.","poloniusmarrysirheresmydriftandibelievei~eadditionofmanandcountry~347":"Polonius — Pois bem, senhor, aqui está meu intento;\nE creio que é um ardil de engenho:\nTu lançando estas leves máculas sobre meu filho,\nComo coisa um pouco suja no trabalho,\nNota bem,\nTeu interlocutor, aquele que queres sondar,\nTendo visto alguma vez nos crimes mencionados\nO jovem de quem falas culpado, fica certo\nDe que fechará contigo desta maneira:\n“Bom senhor,” ou assim, ou “amigo,” ou “cavalheiro,”\nSegundo a frase ou o tratamento\nDe homem e de país.","reynaldoverygoodmylord~reynaldoverygoodmylord~22":"Reynaldo — Muito bem, meu senhor.","poloniusandthensirdoeshethishedoeswhatwa~ysomethingwheredidileave~98":"Polonius — E então, senhor, ele faz isto — ele faz — que ia eu dizer? Pela missa, ia dizer algo: onde parei?","reynaldoatclosesintheconsequenceatfriend~atfriendorsoandgentleman~56":"Reynaldo — Em “fecha na conclusão,” em “amigo ou assim,” e “cavalheiro.”","poloniusatclosesintheconsequenceaymarryh~mysonyouhavemehaveyounot~456":"Polonius — Em “fecha na conclusão,” sim, por certo;\nFecha assim: “Conheço o cavalheiro;\nVi-o ontem, ou anteontem,\nOu então, ou então; com tal, ou tal; e, como dizeis,\nAli estava jogando; ali apanhado em sua bebedeira;\nAli brigando no tênis:” ou talvez,\n“Vi-o entrar em tal casa de venda,”\nIsto é, um bordel, ou assim por diante.\nVês agora;\nTua isca de falsidade apanha esta carpa da verdade:\nE assim nós, de sabedoria e alcance,\nCom guinchos e com ensaios de viés,\nPor indiretas achamos o rumo direto:\nAssim, por minha lição e conselho anteriores,\nFarás com meu filho. Entendes-me, não é?","reynaldomylordihave~reynaldomylordihave~19":"Reynaldo — Meu senhor, entendo.","poloniusgodbewiyoufareyouwell~iusgodbewiyoufareyouwell~29":"Polonius — Deus te acompanhe; passa bem.","reynaldogoodmylord~reynaldogoodmylord~18":"Reynaldo — Bom senhor meu!","poloniusobservehisinclinationinyourself~hisinclinationinyourself~39":"Polonius — Observa tu mesmo a inclinação dele.","reynaldoishallmylord~reynaldoishallmylord~20":"Reynaldo — Observarei, meu senhor.","poloniusandlethimplyhismusic~niusandlethimplyhismusic~28":"Polonius — E deixa-o tocar a sua música.","reynaldowellmylord~reynaldowellmylord~18":"Reynaldo — Bem, meu senhor.","poloniusfarewellexitreynaldo~niusfarewellexitreynaldo~28":"Polonius — Adeus! Sai Reynaldo.","enterophelia~enterophelia~12":"Entra Ophelia.","hownowopheliawhatsthematter~nowopheliawhatsthematter~27":"Então, Ophelia! que há?","opheliaomylordmylordihavebeensoaffrighte~ordihavebeensoaffrighted~41":"Ophelia — Oh, meu senhor, meu senhor, assustei-me tanto!","poloniuswithwhatithenameofgod~iuswithwhatithenameofgod~29":"Polonius — Com quê, em nome de Deus?","opheliamylordasiwassewinginmyclosetlordh~ofhorrorshecomesbeforeme~262":"Ophelia — Meu senhor, quando eu costurava em meu quarto,\nO Senhor Hamlet, com o gibão todo desabotoado;\nSem chapéu na cabeça; as meias sujas,\nSem ligas, caídas até o tornozelo como grilhões;\nPálido como sua camisa; os joelhos batendo um no outro;\nE com um olhar tão lastimável no sentido\nComo se tivesse sido solto do inferno\nPara falar de horrores — ele surge diante de mim.","poloniusmadforthylove~poloniusmadforthylove~21":"Polonius — Louco de amor por ti?","opheliamylordidonotknowbuttrulyidofearit~notknowbuttrulyidofearit~40":"Ophelia — Meu senhor, não sei;\nMas, em verdade, receio que sim.","poloniuswhatsaidhe~poloniuswhatsaidhe~18":"Polonius — Que disse ele?","opheliahetookmebythewristandheldmehardth~lastbendedtheirlightonme~452":"Ophelia — Tomou-me pelo pulso e apertou-me forte;\nDepois afastou-se até o comprimento de todo o braço;\nE, com a outra mão assim sobre a testa,\nPôs-se a examinar meu rosto\nComo se fosse desenhá-lo. Muito ficou assim;\nPor fim, sacudindo um pouco meu braço\nE três vezes movendo a cabeça assim, para cima e para baixo,\nSoltou um suspiro tão lastimável e profundo\nQue parecia despedaçar todo o seu corpo\nE acabar seu ser: feito isso, ele me larga:\nE, com a cabeça voltada por cima do ombro,\nPareceu achar o caminho sem os olhos;\nPois saiu porta afora sem a ajuda deles,\nE, até o fim, voltou-me a sua luz.","poloniuscomegowithmeiwillgoseekthekingth~venhimanyhardwordsoflate~233":"Polonius — Vem, vai comigo: irei procurar o rei.\nEste é o verdadeiro êxtase do amor,\nCuja propriedade violenta destrói a si mesma\nE leva a vontade a empreendimentos desesperados\nTantas vezes quanto qualquer paixão sob o céu\nQue aflige nossas naturezas. Lamento.\nOra, deste-lhe algumas palavras duras ultimamente?","ophelianomygoodlordbutasyoudidcommandidi~rsanddeniedhisaccesstome~78":"Ophelia — Não, meu bom senhor, mas, como ordenastes,\nRejeitei suas cartas e neguei-lhe\nO acesso a mim.","poloniusthathathmadehimmadiamsorrythatwi~hanhatetoutterloveexeunt~345":"Polonius — Isso o enlouqueceu.\nLamento não o ter observado com melhor atenção e juízo:\nTemi que apenas brincasse,\nE quisesse arruinar-te; mas maldito seja meu ciúme!\nPelo céu, é tão próprio de nossa idade\nPassar além de nós mesmos em nossas opiniões\nQuanto é comum aos mais jovens\nFaltar discrição. Vem, vamos ao rei:\nIsto deve ser sabido; o que, guardado em segredo, poderia causar\nMais dor em ocultar do que ódio em declarar amor. Saem.","aroominthecastle~aroominthecastle~16":"Uma sala no castelo.","enterkingqueenrosencrantzguildensternand~uildensternandattendants~50":"Entram o Rei, a Rainha, Rosencrantz, Guildenstern e Criados.","kingwelcomedearrosencrantzandguildenster~opendlieswithinourremedy~617":"Rei — Bem-vindos, caros Rosencrantz e Guildenstern!\nAlém de que muito desejávamos ver-vos,\nA necessidade que temos de vos empregar provocou\nNossa pressa em mandar chamar. Algo ouvistes\nDa transformação de Hamlet; assim a chamo,\nPois nem o homem exterior nem o interior\nSe assemelha ao que era. O que possa ser,\nAlém da morte de seu pai, que assim o pôs\nTão fora do entendimento de si mesmo,\nNão consigo imaginar: peço-vos a ambos,\nQue, tendo sido criados com ele desde tão tenra idade,\nE sendo tão vizinhos de sua juventude e comportamento,\nVos digneis de deter-vos aqui em nossa corte\nPor algum pouco tempo: para assim, com vossa companhia,\nAtraí-lo aos prazeres, e colher,\nTanto quanto da ocasião puderdes respigar,\nSe algo, desconhecido de nós, o aflige assim,\nQue, revelado, esteja ao alcance de nosso remédio.","queengoodgentlemenhehathmuchtalkdofyouan~sasfitsakingsremembrance~257":"Rainha — Bons cavalheiros, ele muito tem falado de vós;\nE certa estou de que não há dois homens vivos\nA quem ele mais se apegue. Se vos aprouver\nMostrar-nos tanta fidalguia e boa vontade\nQuanto a de gastar algum tempo conosco,\nPara o auxílio e proveito de nossa esperança,\nVossa visita receberá tais agradecimentos\nQuais convêm à lembrança de um rei.","rosencrantzbothyourmajestiesmightbytheso~ntocommandthantoentreaty~113":"Rosencrantz — Ambas as vossas majestades\nPoderiam, pelo poder soberano que tendes sobre nós,\nPôr vossos temidos desejos mais em comando\nQue em rogo.","guildensternbutwebothobeyandheregiveupou~yatyourfeettobecommanded~104":"Guildenstern — Mas ambos obedecemos,\nE aqui nos entregamos, com plena inclinação\nDe depor nosso serviço livremente a vossos pés,\nPara sermos comandados.","kingthanksrosencrantzandgentleguildenste~ntzandgentleguildenstern~42":"Rei — Obrigado, Rosencrantz e gentil Guildenstern.","queenthanksguildensternandgentlerosencra~segentlemenwherehamletis~138":"Rainha — Obrigada, Guildenstern e gentil Rosencrantz:\nE rogo-vos que visiteis logo\nMeu filho tão mudado. Ide, alguns de vós,\nE levai estes cavalheiros aonde está Hamlet.","guildensternheavensmakeourpresenceandour~spleasantandhelpfultohim~72":"Guildenstern — Que os céus tornem nossa presença e nossas práticas\nAgradáveis e úteis a ele!","queenayamenexeuntrosencrantzguildenstern~ensternandsomeattendants~57":"Rainha — Sim, amém! Saem Rosencrantz, Guildenstern e alguns Criados.","poloniustheambassadorsfromnorwaymygoodlo~odlordarejoyfullyreturnd~60":"Polonius — Os embaixadores da Noruega, meu bom senhor,\nVoltaram jubilosos.","kingthoustillhastbeenthefatherofgoodnews~tbeenthefatherofgoodnews~40":"Rei — Tu sempre foste o pai das boas novas.","poloniushaveimylordiassuremygoodliegeiho~verycauseofhamletslunacy~210":"Polonius — Fui, meu senhor? Asseguro ao meu bom soberano,\nQue guardo meu dever, como guardo minha alma,\nTanto a meu Deus quanto a meu gracioso rei:\nE creio, ou senão este meu cérebro\nNão segue o rastro da política tão seguro\nQuanto costumava, que descobri\nA própria causa da loucura de Hamlet.","kingospeakofthatthatdoilongtohear~kofthatthatdoilongtohear~33":"Rei — Oh, fala disso; isso anseio por ouvir.","poloniusgivefirstadmittancetotheambassad~thefruittothatgreatfeast~80":"Polonius — Dai primeiro audiência aos embaixadores;\nMinhas novas serão a sobremesa desse grande banquete.","kingthyselfdogracetothemandbringtheminex~ceofallyoursonsdistemper~122":"Rei — Tu mesmo faze-lhes as honras e traze-os. Sai Polonius.\nEle me diz, minha cara Gertrudes, que descobriu\nA cabeça e a fonte de todo o mal-estar de teu filho.","queenidoubtitisnootherbutthemainhisfathe~thandouroerhastymarriage~69":"Rainha — Receio que não seja outra senão a principal;\nA morte de seu pai e nosso casamento apressado demais.","kingwellweshallsifthim~kingwellweshallsifthim~22":"Rei — Bem, vamos peneirá-lo.","reenterpoloniuswithvoltimandandcornelius~ithvoltimandandcornelius~40":"Entra de novo Polonius, com Voltimand e Cornelius.","welcomemygoodfriendssayvoltimandwhatfrom~whatfromourbrothernorway~56":"Bem-vindos, meus bons amigos!\nDize, Voltimand, que nos diz nosso irmão da Noruega?","voltimandmostfairreturnofgreetingsanddes~wanceasthereinaresetdown~714":"Voltimand — Mui bela retribuição de saudações e desejos.\nAo nosso primeiro pedido, mandou suprimir\nAs levas de seu sobrinho; que a ele pareciam\nSer preparativo contra o polaco;\nMas, melhor examinadas, verdadeiramente achou\nQue eram contra Vossa Alteza: do que, agastado\nPor ter sido assim, sua doença, idade e impotência,\nFalsamente enganadas, manda ordens de prisão\nContra Fortinbras; o qual, em suma, obedece;\nRecebe repreensão da Noruega, e por fim\nFaz voto perante o tio de nunca mais\nTentar armas contra Vossa Majestade.\nDo que o velho Noruega, vencido de alegria,\nDá-lhe três mil coroas de renda anual,\nE sua comissão de empregar aqueles soldados,\nAssim levantados como antes, contra o polaco:\nCom um pedido, aqui mais mostrado, Entregando um papel.\nQue vos aprouvesse dar tranquila passagem\nPor vossos domínios para esta empresa,\nSob as condições de segurança e permissão\nQue ali estão estabelecidas.","kingitlikesuswellandatourmoreconsiderdti~untvoltimandandcornelius~197":"Rei — Agrada-nos bem;\nE em nosso tempo mais ponderado, bem lido,\nResponderemos e pensaremos neste negócio.\nEntretanto agradecemos o vosso trabalho bem-feito:\nIde ao vosso repouso; à noite banquetearemos juntos:\nMuito bem-vindos de volta! Saem Voltimand e Cornelius.","poloniusthisbusinessiswellendedmyliegean~ngelsebutmadbutletthatgo~339":"Polonius — Este negócio está bem concluído.\nMeu soberano, e senhora, discorrer\nSobre o que deve ser a majestade, o que é o dever,\nPor que o dia é dia, a noite noite, e o tempo tempo,\nSeria nada senão gastar noite, dia e tempo.\nPortanto, visto que a brevidade é a alma do espírito,\nE a prolixidade os membros e floreios exteriores,\nSerei breve: vosso nobre filho está louco:\nLouco o chamo; pois, para definir a verdadeira loucura,\nQue é senão ser nada mais do que louco?\nMas deixemos isso.","queenmorematterwithlessart~eenmorematterwithlessart~26":"Rainha — Mais matéria, com menos arte.","poloniusmadamisweariusenoartatallthathei~ellentwhitebosomtheseetc~552":"Polonius — Senhora, juro que não uso arte alguma.\nQue ele está louco, é verdade: é verdade que é pena;\nE pena é que seja verdade: uma figura tola;\nMas adeus a ela, pois não usarei arte.\nLouco, então, concedamos que esteja: e agora resta\nQue descubramos a causa deste efeito,\nOu antes, digamos, a causa deste defeito,\nPois este efeito defeituoso vem de uma causa:\nAssim resta, e o resto assim.\nPonderai.\nTenho uma filha — tenho enquanto ela for minha —\nQue, em seu dever e obediência, notai,\nMe deu isto: agora colhei e conjecturai. Lê. “À celestial e ídolo de minha alma, a mais embelezada Ophelia,” — Essa é uma frase ruim, uma frase vil; “embelezada” é uma frase vil: mas ouvireis. Assim: Lê. “Em seu excelente seio branco, estes, etc.”","queencamethisfromhamlettoher~ncamethisfromhamlettoher~28":"Rainha — Veio isto de Hamlet para ela?","poloniusgoodmadamstayawhileiwillbefaithf~ndplaceallgiventomineear~405":"Polonius — Boa senhora, esperai um momento; serei fiel. Lê. “Duvida que as estrelas sejam fogo;\nDuvida que o sol se mova;\nDuvida que a verdade seja mentirosa;\nMas nunca duvides que eu amo. “Ó cara Ophelia, sou mau nestes versos; não tenho arte de contar meus gemidos: mas que te amo melhor, ó mais que melhor, crê-o. Adeus. “Teu para sempre, mui cara senhora, enquanto esta máquina for dele, Hamlet.” Isto, por obediência, minha filha me mostrou,\nE além disso, as suas solicitações,\nComo se deram no tempo, nos meios e no lugar,\nTodas deu ao meu ouvido.","kingbuthowhathshereceivedhislove~owhathshereceivedhislove~32":"Rei — Mas como ela\nRecebeu o amor dele?","poloniuswhatdoyouthinkofme~loniuswhatdoyouthinkofme~26":"Polonius — Que pensais de mim?","kingasofamanfaithfulandhonourable~manfaithfulandhonourable~33":"Rei — Como de um homem fiel e honrado.","poloniusiwouldfainprovesobutwhatmightyou~wheravesandallwemournfor~682":"Polonius — Gostaria de o provar. Mas que poderíeis pensar,\nQuando eu vi este amor ardente a voar —\nComo o percebi, devo dizer-vos isto,\nAntes que minha filha me contasse — que poderíeis,\nOu minha cara majestade, a rainha aqui, pensar,\nSe eu tivesse feito de escrivaninha ou caderno de notas,\nOu dado ao meu coração um piscar mudo e calado,\nOu olhado este amor com vista ociosa;\nQue poderíeis pensar? Não, fui direto ao trabalho,\nE à minha jovem senhora assim falei:\n“O Senhor Hamlet é príncipe, fora de tua estrela;\nIsto não deve ser:” e então preceitos lhe dei,\nQue se trancasse à sua visita,\nNão admitisse mensageiros, não recebesse presentes.\nO que feito, ela colheu os frutos de meu conselho;\nE ele, repelido — para encurtar a história —\nCaiu numa tristeza, depois num jejum,\nDaí numa vigília, daí numa fraqueza,\nDaí num desatino e, por esse declive,\nNa loucura em que agora delira,\nE que todos lamentamos.","kingdoyouthinktisthis~kingdoyouthinktisthis~21":"Rei — Pensais que é isto?","queenitmaybeverylikely~queenitmaybeverylikely~22":"Rainha — Pode ser, muito provavelmente.","poloniushaththerebeensuchatimeidfainknow~ssowhenitprovedotherwise~93":"Polonius — Houve algum tempo — gostaria de saber —\nEm que eu tenha dito positivamente “É assim,”\nE se provou de outro modo?","kingnotthatiknow~kingnotthatiknow~16":"Rei — Não que eu saiba.","poloniuspointingtohisheadandshouldertake~hidindeedwithinthecentre~150":"Polonius — Apontando para a cabeça e o ombro. Tirai isto disto, se isto for de outro modo:\nSe as circunstâncias me guiarem, acharei\nOnde a verdade se esconde, ainda que estivesse de fato escondida\nNo centro da terra.","kinghowmaywetryitfurther~kinghowmaywetryitfurther~24":"Rei — Como podemos prová-lo mais?","poloniusyouknowsometimeshewalksfourhours~rstogetherhereinthelobby~62":"Polonius — Sabeis, às vezes ele passeia quatro horas seguidas\nAqui no vestíbulo.","queensohedoesindeed~queensohedoesindeed~19":"Rainha — Assim faz, de fato.","poloniusatsuchatimeillloosemydaughtertoh~tebutkeepafarmandcarters~180":"Polonius — Numa dessas horas soltarei minha filha para ele:\nVós e eu fiquemos atrás de uma tapeçaria então;\nObservai o encontro: se ele não a ama\nE não perdeu a razão por isso,\nQue eu não seja assistente de um Estado,\nMas cuide de uma fazenda e carroceiros.","kingwewilltryit~kingwewilltryit~15":"Rei — Tentaremos.","queenbutlookwheresadlythepoorwretchcomes~hepoorwretchcomesreading~47":"Rainha — Mas olhai, eis que tristemente vem o pobre coitado, lendo.","poloniusawayidobeseechyoubothawayillboar~ntkingqueenandattendants~81":"Polonius — Afastai-vos, rogo-vos, ambos, afastai-vos:\nAbordá-lo-ei já. Saem o Rei, a Rainha e os Criados.","enterhamletreading~enterhamletreading~18":"Entra Hamlet, lendo.","ogivemeleavehowdoesmygoodlordhamlet~ehowdoesmygoodlordhamlet~35":"Oh, dai-me licença:\nComo vai meu bom Senhor Hamlet?","hamletwellgodamercy~hamletwellgodamercy~19":"Hamlet — Bem, Deus lhe pague.","poloniusdoyouknowmemylord~oloniusdoyouknowmemylord~25":"Polonius — Conheceis-me, meu senhor?","hamletexcellentwellyouareafishmonger~entwellyouareafishmonger~36":"Hamlet — Excelentemente bem; sois um peixeiro.","poloniusnotimylord~poloniusnotimylord~18":"Polonius — Eu não, meu senhor.","hamlettheniwouldyouweresohonestaman~wouldyouweresohonestaman~35":"Hamlet — Então quisera que fôsseis um homem tão honesto.","poloniushonestmylord~poloniushonestmylord~20":"Polonius — Honesto, meu senhor!","hamletaysirtobehonestasthisworldgoesisto~anpickedoutoftenthousand~70":"Hamlet — Sim, senhor; ser honesto, como vai este mundo, é ser um homem escolhido entre dez mil.","poloniusthatsverytruemylord~oniusthatsverytruemylord~27":"Polonius — Isso é muito verdade, meu senhor.","hamletforifthesunbreedmaggotsinadeaddogb~gcarrionhaveyouadaughter~78":"Hamlet — Pois se o sol gera vermes num cão morto, sendo um deus a beijar carniça — Tendes uma filha?","poloniusihavemylord~poloniusihavemylord~19":"Polonius — Tenho, meu senhor.","hamletlethernotwalkithesunconceptionisab~mayconceivefriendlooktot~91":"Hamlet — Não a deixeis andar ao sol: conceber é uma bênção: mas não como vossa filha pode conceber. Amigo, cuidai disso.","poloniusasidehowsayyoubythatstillharping~againwhatdoyoureadmylord~207":"Polonius — À parte. Que dizeis a isto? Sempre batendo na tecla de minha filha: contudo não me conheceu a princípio; disse que eu era um peixeiro: está muito adiantado, muito adiantado: e em verdade, na minha juventude sofri muita extremidade por amor; muito perto disto. Falar-lhe-ei de novo. Que lede, meu senhor?","hamletwordswordswords~hamletwordswordswords~21":"Hamlet — Palavras, palavras, palavras.","poloniuswhatisthemattermylord~iuswhatisthemattermylord~29":"Polonius — Qual é o assunto, meu senhor?","hamletbetweenwho~hamletbetweenwho~16":"Hamlet — Entre quem?","poloniusimeanthematterthatyoureadmylord~ematterthatyoureadmylord~39":"Polonius — Quero dizer, o assunto que lede, meu senhor.","hamletslanderssirforthesatiricalroguesay~eacrabyoucouldgobackward~340":"Hamlet — Calúnias, senhor: pois o velhaco satírico diz aqui que os velhos têm barbas grisalhas, que seus rostos são enrugados, seus olhos expelem espesso âmbar e goma de ameixeira e que têm abundante falta de juízo, junto com as coxas fraquíssimas: tudo o que, senhor, embora eu creia mui poderosa e potentemente, contudo não julgo honestidade tê-lo assim posto por escrito, pois vós mesmo, senhor, seríeis tão velho quanto eu, se como um caranguejo pudésseis andar para trás.","poloniusasidethoughthisbemadnessyetthere~youwalkoutoftheairmylord~79":"Polonius — À parte. Embora isto seja loucura, há método nela. Quereis sair do ar, meu senhor?","hamletintomygrave~hamletintomygrave~17":"Hamlet — Para minha sepultura.","poloniusindeedthatisoutotheairasidehowpr~sthumblytakemyleaveofyou~274":"Polonius — De fato, isso é sair do ar. À parte. Quão prenhes são por vezes suas respostas! uma felicidade em que a loucura muitas vezes acerta, e que a razão e a sanidade não conseguiriam parir tão prosperamente. Deixá-lo-ei, e logo arranjarei meios de encontro entre ele e minha filha. — Meu honrado senhor, muito humildemente me despeço de vós.","hamletyoucannotsirtakefrommeanythingthat~exceptmylifeexceptmylife~104":"Hamlet — Não podeis, senhor, tirar de mim coisa alguma de que eu mais de bom grado me separe: exceto minha vida, exceto minha vida, exceto minha vida.","poloniusfareyouwellmylord~oloniusfareyouwellmylord~25":"Polonius — Passai bem, meu senhor.","hamletthesetediousoldfools~mletthesetediousoldfools~26":"Hamlet — Esses velhos tolos enfadonhos!","enterrosencrantzandguildenstern~sencrantzandguildenstern~31":"Entram Rosencrantz e Guildenstern.","poloniusyougotoseekthelordhamlettherehei~ekthelordhamletthereheis~41":"Polonius — Ides procurar o Senhor Hamlet; ei-lo ali.","rosencrantztopoloniusgodsaveyousirexitpo~odsaveyousirexitpolonius~46":"Rosencrantz — A Polonius. Deus vos guarde, senhor! Sai Polonius.","guildensternmyhonouredlord~ildensternmyhonouredlord~26":"Guildenstern — Meu honrado senhor!","rosencrantzmymostdearlord~osencrantzmymostdearlord~25":"Rosencrantz — Meu caríssimo senhor!","hamletmyexcellentgoodfriendshowdostthoug~rantzgoodladshowdoyeboth~83":"Hamlet — Meus excelentes bons amigos! Como estás, Guildenstern? Ah, Rosencrantz! Bons rapazes, como estais ambos?","rosencrantzastheindifferentchildrenofthe~ferentchildrenoftheearth~45":"Rosencrantz — Como os filhos medianos da terra.","guildensternhappyinthatwearenotoverhappy~capwearenottheverybutton~74":"Guildenstern — Felizes, por não sermos demasiado felizes;\nNa touca da fortuna não somos o próprio botão.","hamletnorthesolesofhershoe~mletnorthesolesofhershoe~26":"Hamlet — Nem as solas de seu sapato?","rosencrantzneithermylord~rosencrantzneithermylord~24":"Rosencrantz — Nem uma coisa nem outra, meu senhor.","hamletthenyouliveaboutherwaistorinthemid~rinthemiddleofherfavours~55":"Hamlet — Então viveis em volta de sua cintura, ou no meio de seus favores?","guildensternfaithherprivateswe~nsternfaithherprivateswe~30":"Guildenstern — Em fé, somos suas partes íntimas.","hamletinthesecretpartsoffortuneomosttrue~eisastrumpetwhatsthenews~66":"Hamlet — Nas partes secretas da fortuna? Oh, verdadeiríssimo; ela é uma meretriz. Que novas há?","rosencrantznonemylordbutthattheworldsgro~thattheworldsgrownhonest~48":"Rosencrantz — Nenhuma, meu senhor, senão que o mundo se tornou honesto.","hamletthenisdoomsdaynearbutyournewsisnot~hesendsyoutoprisonhither~153":"Hamlet — Então está próximo o dia do juízo: mas vossa nova não é verdadeira. Deixai-me perguntar mais em particular: que merecestes, meus bons amigos, das mãos da fortuna, para que ela vos mande à prisão aqui?","guildensternprisonmylord~guildensternprisonmylord~24":"Guildenstern — Prisão, meu senhor!","hamletdenmarksaprison~hamletdenmarksaprison~21":"Hamlet — A Dinamarca é uma prisão.","rosencrantzthenistheworldone~ncrantzthenistheworldone~28":"Rosencrantz — Então o mundo é uma.","hamletagoodlyoneinwhichtherearemanyconfi~denmarkbeingoneotheworst~83":"Hamlet — Uma bela; na qual há muitos confinamentos, celas e calabouços, sendo a Dinamarca uma das piores.","rosencrantzwethinknotsomylord~crantzwethinknotsomylord~29":"Rosencrantz — Não pensamos assim, meu senhor.","hamletwhythentisnonetoyouforthereisnothi~makesitsotomeitisaprison~92":"Hamlet — Ora, então para vós não é; pois nada há de bom nem de mau, senão que o pensamento o faz assim: para mim é uma prisão.","rosencrantzwhythenyourambitionmakesitone~etistoonarrowforyourmind~63":"Rosencrantz — Ora, então a vossa ambição a faz uma; é estreita demais para a vossa mente.","hamletogodicouldbeboundedinanutshellandc~eitnotthatihavebaddreams~97":"Hamlet — Oh, Deus, eu poderia estar encerrado numa casca de noz e considerar-me rei de espaço infinito, se não fora que tenho maus sonhos.","guildensternwhichdreamsindeedareambition~smerelytheshadowofadream~98":"Guildenstern — Os quais sonhos são de fato a ambição, pois a própria substância do ambicioso é puramente a sombra de um sonho.","hamletadreamitselfisbutashadow~adreamitselfisbutashadow~30":"Hamlet — Um sonho em si é apenas uma sombra.","rosencrantztrulyandiholdambitionofsoairy~hatitisbutashadowsshadow~81":"Rosencrantz — Em verdade, e tenho a ambição por tão aérea e leve em qualidade que não passa de sombra de uma sombra.","hamletthenareourbeggarsbodiesandourmonar~tforbymyfayicannotreason~121":"Hamlet — Então nossos mendigos são corpos, e nossos monarcas e heróis espichados, as sombras dos mendigos. Vamos à corte? pois, por minha fé, não consigo raciocinar.","rosencrantzguildensternwellwaituponyou~ldensternwellwaituponyou~38":"Rosencrantz\nGuildenstern — Estaremos às vossas ordens.","hamletnosuchmatteriwillnotsortyouwiththe~hipwhatmakeyouatelsinore~161":"Hamlet — Nada disso: não vos colocarei entre o resto de meus criados, pois, para vos falar como homem honesto, sou assistido de modo medonho. Mas, na trilha batida da amizade, que fazeis em Elsinore?","rosencrantztovisityoumylordnootheroccasi~youmylordnootheroccasion~42":"Rosencrantz — Visitar-vos, meu senhor; nenhuma outra ocasião.","hamletbeggarthatiamiamevenpoorinthanksbu~lywithmecomecomenayspeak~188":"Hamlet — Mendigo que sou, sou pobre até em agradecimentos; mas agradeço-vos: e certo, caros amigos, meus agradecimentos valem caro demais um meio centavo. Não fostes mandados chamar? É por vossa própria inclinação? É uma visita livre? Vamos, sede justos comigo: vamos, vamos; falai.","guildensternwhatshouldwesaymylord~ernwhatshouldwesaymylord~33":"Guildenstern — Que diríamos, meu senhor?","hamletwhyanythingbuttothepurposeyouweres~ngandqueenhavesentforyou~166":"Hamlet — Ora, qualquer coisa, menos ao ponto. Fostes mandados chamar; e há uma espécie de confissão em vossos olhares que vossa modéstia não tem astúcia bastante para colorir: sei que o bom rei e a rainha vos mandaram chamar.","rosencrantztowhatendmylord~sencrantztowhatendmylord~26":"Rosencrantz — Com que fim, meu senhor?","hamletthatyoumustteachmebutletmeconjurey~hetheryouweresentfororno~228":"Hamlet — Isso é o que deveis me ensinar. Mas deixai-me conjurar-vos, pelos direitos de nossa camaradagem, pela consonância de nossa juventude, pela obrigação de nosso amor sempre conservado, e por tudo o que de mais caro um melhor proponente vos pudesse exigir, sede franco e direto comigo, fostes mandados chamar, ou não?","rosencrantzasidetoguildensternwhatsayyou~toguildensternwhatsayyou~40":"Rosencrantz — À parte, para Guildenstern. Que dizes?","hamletasidenaythenihaveaneyeofyouifyoulo~youifyoulovemeholdnotoff~54":"Hamlet — À parte. Não, então, tenho o olho em vós. — Se me amais, não vos esquiveis.","guildensternmylordweweresentfor~sternmylordweweresentfor~31":"Guildenstern — Meu senhor, fomos mandados chamar.","hamletiwilltellyouwhysoshallmyanticipati~oursmilingyouseemtosayso~731":"Hamlet — Dir-vos-ei por quê; assim minha antecipação evitará vossa revelação, e vosso segredo com o rei e a rainha não perderá pena alguma. Tenho ultimamente — mas por quê não sei — perdido toda a alegria, abandonado todo costume de exercícios; e de fato vai tão pesado com minha disposição que esta bela estrutura, a terra, parece-me um promontório estéril, este excelentíssimo dossel, o ar, vede, este soberbo firmamento pendente, este teto majestoso incrustado de fogo dourado, ora, não me parece outra coisa senão uma congregação imunda e pestilenta de vapores. Que obra-prima é o homem! quão nobre na razão! quão infinito em faculdades! na forma e no movimento quão expressivo e admirável! na ação quão semelhante a um anjo! na apreensão quão semelhante a um deus! a beleza do mundo! o paradigma dos animais! E contudo, para mim, que é esta quintessência do pó? o homem não me deleita: não, nem a mulher tampouco, embora por vosso sorriso pareçais dizê-lo.","rosencrantzmylordtherewasnosuchstuffinmy~snosuchstuffinmythoughts~48":"Rosencrantz — Meu senhor, não havia tal coisa em meus pensamentos.","hamletwhydidyoulaughthenwhenisaidmandeli~henisaidmandelightsnotme~49":"Hamlet — Por que rístes então, quando disse “o homem não me deleita”?","rosencrantztothinkmylordifyoudelightnoti~ycomingtoofferyouservice~154":"Rosencrantz — Por pensar, meu senhor, que, se não vos deleitais com o homem, que magra acolhida os atores receberão de vós: ultrapassamo-los no caminho; e para cá vêm eles, para vos oferecer serviço.","hamlethethatplaysthekingshallbewelcomehi~ltfortwhatplayersarethey~307":"Hamlet — Aquele que faz o rei será bem-vindo; sua majestade terá tributo de mim; o cavaleiro andante usará seu florete e escudo; o amante não suspirará de graça; o homem de humores terminará seu papel em paz; o palhaço fará rir aqueles cujos pulmões são fáceis de cócegas; e a dama dirá livremente o que pensa, ou o verso branco claudicará por isso. Que atores são?","rosencrantzeventhoseyouwerewonttotakedel~inthetragediansofthecity~68":"Rosencrantz — Justamente aqueles em que costumáveis deleitar-vos, os trágicos da cidade.","hamlethowchancesittheytraveltheirresiden~dprofitwasbetterbothways~84":"Hamlet — Como acontece que viajam? sua residência, tanto em reputação quanto em lucro, era melhor das duas maneiras.","rosencrantzithinktheirinhibitioncomesbyt~meansofthelateinnovation~66":"Rosencrantz — Penso que sua proibição vem por causa da recente inovação.","hamletdotheyholdthesameestimationtheydid~thecityaretheysofollowed~74":"Hamlet — Mantêm a mesma estima que tinham quando eu estava na cidade? são tão seguidos?","rosencrantznoindeedaretheynot~crantznoindeedaretheynot~29":"Rosencrantz — Não, na verdade, não são.","hamlethowcomesitdotheygrowrusty~owcomesitdotheygrowrusty~31":"Hamlet — Como é isso? estão enferrujando?","rosencrantznaytheirendeavourkeepsinthewo~anddarescarcecomethither~281":"Rosencrantz — Não, seu empenho mantém o passo costumeiro: mas há, senhor, um ninho de crianças, pequenos filhotes de falcão, que gritam no topo da questão, e são tiranicamente aplaudidas por isso: estas agora estão na moda, e de tal modo chocalham os palcos comuns — assim os chamam — que muitos que usam espadas temem as penas de ganso e mal ousam ir lá.","hamletwhataretheychildrenwhomaintainsemh~gainsttheirownsuccession~270":"Hamlet — Como, são crianças? quem as sustenta? como são pagas? Seguirão o ofício apenas enquanto puderem cantar? não dirão depois, se vierem a crescer e ser atores comuns — como é muito provável, se seus meios não forem melhores — que seus autores lhes fazem mal, ao os fazer clamar contra a própria sucessão?","rosencrantzfaiththerehasbeenmuchtodoonbo~wenttocuffsinthequestion~182":"Rosencrantz — Em fé, houve muita agitação de ambos os lados; e a nação não tem por pecado açulá-los à controvérsia: houve, por um tempo, nenhum dinheiro pago por argumento, a não ser que o poeta e o ator chegassem às vias de fato na questão.","hamletistpossible~hamletistpossible~17":"Hamlet — É possível?","guildensternotherehasbeenmuchthrowingabo~uchthrowingaboutofbrains~50":"Guildenstern — Oh, houve muito arremesso de miolos.","hamletdotheboyscarryitaway~mletdotheboyscarryitaway~26":"Hamlet — Os meninos levam a melhor?","rosencrantzaythattheydomylordherculesand~ordherculesandhisloadtoo~50":"Rosencrantz — Sim, é o que fazem, meu senhor; Hércules e sua carga também.","hamletitisnotverystrangeformineuncleiski~flourishoftrumpetswithin~254":"Hamlet — Não é muito estranho; pois meu tio é rei da Dinamarca, e aqueles que lhe faziam caretas enquanto meu pai vivia, dão vinte, quarenta, cinquenta, cem ducados cada um por seu retrato em miniatura. Pelo sangue de Deus, há nisto algo mais que natural, se a filosofia pudesse descobri-lo. Fanfarra de trombetas dentro.","guildensterntherearetheplayers~nsterntherearetheplayers~30":"Guildenstern — Aí estão os atores.","hamletgentlemenyouarewelcometoelsinoreyo~andauntmotheraredeceived~280":"Hamlet — Cavalheiros, sois bem-vindos a Elsinore. Vossas mãos, vamos: o acessório da boa acolhida é a moda e a cerimônia: deixai-me cumprimentar-vos neste estilo, para que minha cortesia aos atores, que, vos digo, deve mostrar-se bela por fora, não pareça mais acolhida do que a vossa. Sois bem-vindos: mas meu tio-pai e minha tia-mãe estão enganados.","guildensterninwhatmydearlord~densterninwhatmydearlord~28":"Guildenstern — Em quê, meu caro senhor?","hamletiambutmadnorthnorthwestwhenthewind~lyiknowahawkfromahandsaw~73":"Hamlet — Só estou louco a nor-noroeste: quando o vento é sul, sei distinguir um gavião de uma serra.","reenterpolonius~reenterpolonius~15":"Entra de novo Polonius.","poloniuswellbewithyougentlemen~uswellbewithyougentlemen~30":"Polonius — Bem esteja convosco, cavalheiros!","hamletharkyouguildensternandyoutooateach~toutofhisswaddlingclouts~105":"Hamlet — Ouvi, Guildenstern; e vós também: em cada ouvido um ouvinte: aquele grande bebê que vedes ali ainda não saiu de seus cueiros.","rosencrantzhappilyhesthesecondtimecometo~sayanoldmanistwiceachild~75":"Rosencrantz — Talvez tenha voltado a eles pela segunda vez; pois dizem que um velho é duas vezes criança.","hamletiwillprophesyhecomestotellmeofthep~ondaymorningtwassoindeed~92":"Hamlet — Profetizo que ele vem me falar dos atores; reparai. Dizeis certo, senhor: na manhã de segunda; foi assim mesmo.","poloniusmylordihavenewstotellyou~mylordihavenewstotellyou~32":"Polonius — Meu senhor, tenho novas para vos dar.","hamletmylordihavenewstotellyouwhenrosciu~nrosciuswasanactorinrome~57":"Hamlet — Meu senhor, tenho novas para vos dar. Quando Róscio era ator em Roma —","poloniustheactorsarecomehithermylord~ctorsarecomehithermylord~36":"Polonius — Os atores chegaram aqui, meu senhor.","hamletbuzbuz~hamletbuzbuz~12":"Hamlet — Zum, zum!","poloniusuponminehonour~poloniusuponminehonour~22":"Polonius — Por minha honra —","hamletthencameeachactoronhisass~hencameeachactoronhisass~31":"Hamlet — Então veio cada ator em seu burro —","poloniusthebestactorsintheworldeitherfor~ibertythesearetheonlymen~269":"Polonius — Os melhores atores do mundo, seja para tragédia, comédia, história, pastoral, pastoral-cômica, histórico-pastoral, trágico-histórica, trágico-cômico-histórico-pastoral, cena indivisível, ou poema ilimitado: Sêneca não pode ser pesado demais, nem Plauto leve demais. Quanto à lei da escrita e à liberdade, estes são os únicos homens.","hamletojephthahjudgeofisraelwhatatreasur~elwhatatreasurehadstthou~50":"Hamlet — Ó Jefté, juiz de Israel, que tesouro tinhas!","poloniuswhatatreasurehadhemylord~whatatreasurehadhemylord~32":"Polonius — Que tesouro tinha ele, meu senhor?","hamletwhyonefairdaughterandnomorethewhic~ewhichhelovedpassingwell~59":"Hamlet — Ora, “Uma bela filha e não mais,\nA qual ele amava acima de tudo.”","poloniusasidestillonmydaughter~usasidestillonmydaughter~30":"Polonius — À parte. Ainda em minha filha.","hamletaminotitherightoldjephthah~inotitherightoldjephthah~32":"Hamlet — Não tenho razão, velho Jefté?","poloniusifyoucallmejephthahmylordihavead~hterthatilovepassingwell~67":"Polonius — Se me chamais Jefté, meu senhor, tenho uma filha que amo acima de tudo.","hamletnaythatfollowsnot~hamletnaythatfollowsnot~23":"Hamlet — Não, isso não se segue.","poloniuswhatfollowsthenmylord~iuswhatfollowsthenmylord~29":"Polonius — Que se segue, então, meu senhor?","hamletwhyasbylotgodwotandthenyouknowitca~kwheremyabridgementcomes~136":"Hamlet — Ora, “Como por sorte, Deus o sabe,” e depois, sabeis, “Aconteceu, como era mais que provável,” — a primeira estrofe da pia canção vos mostrará mais; pois olhai, eis que vem meu abreviador.","enterfourorfiveplayers~enterfourorfiveplayers~22":"Entram quatro ou cinco Atores.","youarewelcomemasterswelcomealliamgladtos~itycomeapassionatespeech~454":"Sede bem-vindos, mestres; bem-vindos todos. Alegro-me em ver-te bem. Bem-vindos, bons amigos. Oh, meu velho amigo! teu rosto está franjado desde que te vi pela última vez: vens me desafiar a barba na Dinamarca? Ora, minha jovem dama e senhora! Por Nossa Senhora, vossa senhoria está mais perto do céu do que quando vos vi pela última vez, a altura de um tamanco. Prouvera a Deus que vossa voz, como moeda de ouro fora de circulação, não esteja rachada dentro do anel. Mestres, sois todos bem-vindos. Iremos direto ao assunto como falcoeiros franceses, voando em qualquer coisa que vemos: teremos uma fala já: vamos, dai-nos uma prova de vosso ofício; vamos, uma fala apaixonada.","firstplayerwhatspeechmylord~stplayerwhatspeechmylord~27":"Primeiro Ator — Que fala, meu senhor?","hamletiheardtheespeakmeaspeechoncebutitw~repriamseekssoproceedyou~1158":"Hamlet — Ouvi-te dizer-me uma fala uma vez, mas nunca foi representada; ou, se foi, não mais de uma vez; pois a peça, lembro-me, não agradou à multidão; era caviar para o povo: mas era — como a recebi, e outros, cujo juízo em tais matérias sobrepujava o meu — uma excelente peça, bem digerida nas cenas, composta com tanta modéstia quanto engenho. Lembro-me de que alguém disse que não havia saladas nos versos para dar sabor ao assunto, nem assunto na frase que pudesse acusar o autor de afetação; mas a chamou de método honesto, tão saudável quanto doce, e muito mais belo que fino. Uma fala nela amei sobretudo: era o relato de Eneias a Dido; e por volta dela especialmente, onde ele fala da matança de Príamo: se vive em vossa memória, começai neste verso: deixai-me ver, deixai-me ver — “O áspero Pirro, como a fera hircana,” — não é assim: — começa com Pirro: — “O áspero Pirro, ele cujas armas negras,\nNegras como seu propósito, à noite se assemelhavam\nQuando jazia encolhido no cavalo agourento,\nTem agora este temível e negro semblante manchado\nCom heráldica mais sinistra; da cabeça aos pés\nÉ agora todo goles; horrendamente adornado\nCom sangue de pais, mães, filhas, filhos,\nCozido e empastado pelas ruas ardentes,\nQue emprestam uma luz tirânica e maldita\nAo assassínio de seu senhor: assado em ira e fogo,\nE assim coberto de sangue coagulado,\nCom olhos como carbúnculos, o infernal Pirro\nProcura o velho avô Príamo.” Assim, prossegui.","poloniusforegodmylordwellspokenwithgooda~daccentandgooddiscretion~62":"Polonius — Por Deus, meu senhor, bem falado, com bom acento e boa discrição.","firstplayeranonhefindshimstrikingtooshor~heavenaslowastothefiends~971":"Primeiro Ator — “Logo o encontra\nGolpeando curto demais os gregos; sua espada antiga,\nRebelde ao braço, jaz onde cai,\nRepugnante ao comando: desigualmente combatendo,\nPirro investe contra Príamo; em fúria golpeia em vão;\nMas com o sopro e o vento de sua espada cruel\nO pai sem nervos cai. Então a insensível Ílion,\nParecendo sentir este golpe, com o topo em chamas\nCurva-se à base, e com um estrondo hediondo\nFaz prisioneiro o ouvido de Pirro: pois eis que a espada,\nQue descia sobre a cabeça leitosa\nDo reverendo Príamo, pareceu no ar parar:\nAssim, como um tirano pintado, Pirro ficou,\nE como neutro à sua vontade e matéria,\nNada fez.\nMas, como amiúde vemos, antes de alguma tempestade,\nUm silêncio nos céus, as nuvens paradas,\nOs ventos audazes mudos e o orbe abaixo\nQuieto como a morte, logo o pavoroso trovão\nRasga a região, assim, após a pausa de Pirro,\nA vingança despertada o põe de novo ao trabalho;\nE nunca os martelos dos Ciclopes caíram\nNa armadura de Marte forjada para prova eterna\nCom menos remorso do que a espada sangrenta de Pirro\nCai agora sobre Príamo.\nFora, fora, tu, meretriz Fortuna! Todos vós, deuses,\nEm sínodo geral tirai-lhe o poder;\nQuebrai todos os raios e aros de sua roda,\nE rolai o redondo cubo morro abaixo do céu,\nAté tão baixo quanto os demônios!”","poloniusthisistoolong~poloniusthisistoolong~21":"Polonius — Isto é longo demais.","hamletitshalltothebarberswithyourbeardpr~esleepssayoncometohecuba~102":"Hamlet — Irá ao barbeiro, com a vossa barba. Peço-te, continua: ele quer uma jiga ou um conto de obscenidades, ou dorme: continua: chega a Hécuba.","firstplayerbutwhoowhohadseenthemobledque~whohadseenthemobledqueen~42":"Primeiro Ator — “Mas quem, oh, quem tinha visto a rainha embuçada —”","hamletthemobledqueen~hamletthemobledqueen~20":"Hamlet — “A rainha embuçada?”","poloniusthatsgoodmobledqueenisgood~atsgoodmobledqueenisgood~34":"Polonius — Isso é bom; “rainha embuçada” é bom.","firstplayerrunbarefootupanddownthreateni~eavenandpassioninthegods~499":"Primeiro Ator — “Correr de pés descalços para cima e para baixo, ameaçando as chamas\nCom lágrimas cegantes; um trapo naquela cabeça\nOnde há pouco estava o diadema, e por manto,\nEm torno de seus flancos magros e exaustos de parir,\nUm cobertor, no alarme do medo apanhado;\nQuem isto tivesse visto, com a língua embebida em veneno,\nContra o estado da Fortuna teria pronunciado traição:\nMas se os próprios deuses a vissem então\nQuando viu Pirro fazer malicioso jogo\nEm picar com a espada os membros do marido,\nO súbito estouro de clamor que ela deu,\nA menos que as coisas mortais nada os movam,\nTeria feito leiteiros os olhos ardentes do céu,\nE paixão nos deuses.”","poloniuslookwhetherhehasnotturnedhiscolo~earsinseyesprayyounomore~73":"Polonius — Vede se não mudou de cor e tem lágrimas nos olhos. Peço-vos, não mais.","hamlettiswellillhavetheespeakouttherests~eirillreportwhileyoulive~231":"Hamlet — Está bem; hei de fazer-te dizer o resto logo. Bom senhor meu, quereis ver os atores bem alojados? Ouvis, que sejam bem tratados; pois são o resumo e as breves crônicas do tempo: depois de morto, mais vos valeria um mau epitáfio do que o mau relato deles enquanto viveis.","poloniusmylordiwillusethemaccordingtothe~emaccordingtotheirdesert~48":"Polonius — Meu senhor, tratá-los-ei conforme o seu merecimento.","hamletgodsbodykinsmanmuchbetteruseeverym~isinyourbountytakethemin~170":"Hamlet — Pelo corpinho de Deus, homem, muito melhor: tratai cada homem conforme o seu merecimento, e quem escaparia do açoite? Tratai-os conforme vossa própria honra e dignidade: quanto menos merecem, mais mérito há em vossa generosidade. Levai-os.","poloniuscomesirs~poloniuscomesirs~16":"Polonius — Vinde, senhores.","hamletfollowhimfriendswellhearaplaytomor~ouplaythemurderofgonzago~134":"Hamlet — Segui-o, amigos: ouviremos uma peça amanhã. Sai Polonius com todos os Atores, exceto o Primeiro. Ouves-me, velho amigo; podeis representar O Assassínio de Gonzago?","firstplayeraymylord~firstplayeraymylord~19":"Primeiro Ator — Sim, meu senhor.","hamletwellhattomorrownightyoucouldforane~nandinsertintcouldyounot~120":"Hamlet — Teremos amanhã à noite. Poderíeis, se preciso, estudar uma fala de uns doze ou dezesseis versos, que eu comporia e inseriria nela, não poderíeis?","hamletverywellfollowthatlordandlookyoumo~tyouarewelcometoelsinore~119":"Hamlet — Muito bem. Segui aquele senhor; e vede que não zombeis dele. Sai o Primeiro Ator. Meus bons amigos, deixo-vos até a noite: sois bem-vindos a Elsinore.","rosencrantzgoodmylord~rosencrantzgoodmylord~21":"Rosencrantz — Bom senhor meu!","hamletaysogodbewiyeexeuntrosencrantzandg~econscienceofthekingexit~1912":"Hamlet — Sim, assim, Deus vos acompanhe; Saem Rosencrantz e Guildenstern. Agora estou só.\nOh, que patife e escravo camponês sou eu!\nNão é monstruoso que este ator aqui,\nApenas numa ficção, num sonho de paixão,\nPudesse forçar de tal modo a alma à sua concepção\nQue, do trabalho dela, todo o seu rosto empalideceu,\nLágrimas nos olhos, desvario no aspecto,\nVoz quebrada, e toda a sua ação ajustando-se\nEm formas à sua concepção? e tudo por nada!\nPor Hécuba!\nQue é Hécuba para ele, ou ele para Hécuba,\nPara que chore por ela? Que faria ele,\nTivesse o motivo e a deixa para a paixão\nQue eu tenho? Afogaria o palco em lágrimas\nE fenderia o ouvido geral com fala horrenda,\nEnlouqueceria os culpados e apavoraria os livres,\nConfundiria os ignorantes, e espantaria de fato\nAs próprias faculdades de olhos e ouvidos.\nContudo eu,\nUm patife obtuso, de ânimo lodoso, definho,\nComo um sonhador, sem peso de minha causa,\nE nada posso dizer; não, nem por um rei,\nEm cuja propriedade e caríssima vida\nFoi cometida uma maldita destruição. Sou um covarde?\nQuem me chama vilão? me parte a crosta da cabeça?\nArranca-me a barba, e a sopra na minha cara?\nPuxa-me pelo nariz? me desmente na garganta,\nTão fundo quanto os pulmões? quem me faz isto?\nHa!\nPelas chagas de Deus, eu o aceitaria: pois não pode ser\nSenão que tenho fígado de pombo e me falta fel\nPara tornar a opressão amarga, ou antes disto\nTeria engordado todos os milhafres da região\nCom as entranhas deste escravo: vilão sanguinário, obsceno!\nSem remorso, traiçoeiro, lascivo, desnaturado vilão!\nOh, vingança!\nOra, que burro sou eu! Isto é soberbo,\nQue eu, filho de um caro pai assassinado,\nIncitado à vingança pelo céu e pelo inferno,\nDeva, como uma prostituta, desabafar o coração com palavras,\nE pôr-me a praguejar, como uma verdadeira rameira,\nUma criada de cozinha!\nQue vergonha! puf! À obra, meu cérebro! Ouvi dizer\nQue criaturas culpadas, sentadas a uma peça,\nForam pela própria arte da cena\nTão feridas na alma que logo\nProclamaram seus malfeitos;\nPois o assassínio, embora não tenha língua, falará\nCom o mais miraculoso órgão. Farei estes atores\nRepresentar algo semelhante ao assassínio de meu pai\nDiante de meu tio: observarei seus olhares;\nSondá-lo-ei até o vivo: se ele apenas empalidecer,\nSei meu rumo. O espírito que vi\nPode ser o diabo: e o diabo tem poder\nDe assumir uma forma agradável; sim, e talvez\nAproveitando-se de minha fraqueza e minha melancolia,\nPois é muito potente com tais espíritos,\nMe engana para me condenar: terei motivos\nMais relevantes que este: a peça é a coisa\nCom que apanharei a consciência do rei. Sai.","enterkingqueenpoloniusopheliarosencrantz~sencrantzandguildenstern~55":"Entram o Rei, a Rainha, Polônio, Ofélia, Rosencrantz e Guildenstern.","kingandcanyoubynodriftofcircumstancegetf~bulentanddangerouslunacy~134":"Rei — E não podeis, por nenhum rodeio ou circunstância,\narrancar-lhe a razão de tanta desordem,\nque lhe fere tão rudemente os dias de sossego\ncom uma loucura turbulenta e perigosa?","rosencrantzhedoesconfesshefeelshimselfdi~ausehewillbynomeansspeak~84":"Rosencrantz — Ele confessa sentir-se transtornado;\nmas, por que causa, não quer dizer de modo algum.","guildensternnordowefindhimforwardtobesou~confessionofhistruestate~126":"Guildenstern — Tampouco o achamos disposto a ser sondado;\ncom astuta loucura, mantém-se esquivo,\nquando queremos levá-lo a alguma confissão\nde seu verdadeiro estado.","queendidhereceiveyouwell~queendidhereceiveyouwell~24":"Rainha — Recebeu-vos bem?","rosencrantzmostlikeagentleman~crantzmostlikeagentleman~29":"Rosencrantz — Como um perfeito cavalheiro.","guildensternbutwithmuchforcingofhisdispo~hforcingofhisdisposition~46":"Guildenstern — Mas com grande violência contra o próprio humor.","rosencrantzniggardofquestionbutofourdema~emandsmostfreeinhisreply~61":"Rosencrantz — Avaro em perguntas; mas, às nossas indagações,\nmuito liberal nas respostas.","queendidyouassayhimtoanypastime~dyouassayhimtoanypastime~31":"Rainha — Tentastes atraí-lo\na algum passatempo?","rosencrantzmadamitsofelloutthatcertainpl~thisnighttoplaybeforehim~195":"Rosencrantz — Senhora, aconteceu que certos atores\nalcançamos pelo caminho; falamos-lhe deles,\ne pareceu haver nele uma espécie de alegria\nao ouvir isso. Estão aqui pela corte\ne, creio eu, já têm ordem\nde representar esta noite diante dele.","poloniustismosttrueandhebeseechdmetoentr~iestohearandseethematter~77":"Polônio — É a mais pura verdade;\ne ele me rogou que pedisse a Vossas Majestades\nque venham ouvir e ver a peça.","kingwithallmyheartanditdothmuchcontentme~purposeontothesedelights~126":"Rei — De todo o coração; e muito me contenta\nsaber que ele assim se inclina.\nBons senhores, dai-lhe ainda mais estímulo\ne encaminhai-lhe o propósito para esses deleites.","rosencrantzweshallmylordexeuntrosencrant~sencrantzandguildenstern~56":"Rosencrantz — Assim faremos, meu senhor. Saem Rosencrantz e Guildenstern.","kingsweetgertrudeleaveustooforwehaveclos~ornothatthushesuffersfor~285":"Rei — Doce Gertrudes, deixa-nos também;\npois mandamos chamar Hamlet em segredo,\npara que ele, como que por acaso, aqui\nse encontre com Ofélia.\nO pai dela e eu, espiões legítimos,\nnos colocaremos de modo que, vendo sem ser vistos,\npossamos julgar com franqueza o encontro deles,\ne concluir, pelo seu comportamento,\nse é a aflição do amor ou não\nque o faz sofrer assim.","queenishallobeyyouandforyourpartopheliai~ayagaintobothyourhonours~169":"Rainha — Obedecerei.\nE quanto a ti, Ofélia, desejo\nque tua beleza seja a ditosa causa\nda perturbação de Hamlet; assim espero que tuas virtudes\no reconduzam ao seu antigo caminho,\npara honra de ambos.","opheliamadamiwishitmayexitqueen~madamiwishitmayexitqueen~31":"Ofélia — Senhora, oxalá assim seja. Sai a Rainha.","poloniusopheliawalkyouheregracioussoplea~osugaroerthedevilhimself~237":"Polônio — Ofélia, passeia por aqui. Majestade, se for do vosso agrado,\nvamos nos ocultar. A Ofélia. Lê neste livro;\nque essa aparência de exercício piedoso dê cor\nà tua solidão. Somos muitas vezes culpados nisto—\ne já se provou demais—, que com cara de devoção\ne piedosos gestos adoçamos\no próprio diabo.","kingasideotistootruehowsmartalashthatspe~paintedwordoheavyburthen~181":"Rei — À parte. Oh, é verdade demais!\nQue açoite doloroso esse discurso dá à minha consciência!\nA face da meretriz, embelezada por arte de reboco,\nnão é mais feia para aquilo que a ajuda\ndo que o meu ato é para as minhas palavras tão pintadas.\nÓ pesado fardo!","poloniusihearhimcomingletswithdrawmylord~ordexeuntkingandpolonius~61":"Polônio — Ouço-o chegar; retiremo-nos, meu senhor. Saem o Rei e Polônio.","enterhamlet~enterhamlet~11":"Entra Hamlet.","hamlettobeornottobethatisthequestionwhet~sonsbeallmysinsrememberd~1167":"Hamlet — Ser ou não ser: eis a questão:\nse é mais nobre para a alma suportar\nas pedradas e flechadas da trágica fortuna,\nou tomar armas contra um mar de angústias\ne, combatendo-as, dar-lhes fim? Morrer: dormir;\nnada mais; e, com um sono, dizer que acabamos\na dor do coração e os mil choques naturais\nque a carne herda: é um desfecho\na desejar devotamente. Morrer, dormir;\ndormir: talvez sonhar; ah, aí está o obstáculo;\npois que sonhos podem vir nesse sono da morte,\nquando nos livrarmos deste invólucro mortal,\neis o que nos faz parar: eis a razão\nque dá à desgraça uma vida tão longa;\npois quem suportaria os açoites e desprezos do tempo,\na injúria do opressor, o desdém do orgulhoso,\nas dores do amor desprezado, a demora da lei,\na insolência dos cargos e as afrontas\nque o mérito paciente recebe dos indignos,\nquando ele mesmo poderia dar-se o seu repouso\ncom um simples punhal? Quem carregaria fardos,\ngemendo e suando sob uma vida cansada,\nnão fosse o pavor de algo depois da morte,\no país inexplorado, de cujas fronteiras\nnenhum viajante retorna, que embaraça a vontade\ne nos faz preferir suportar os males que temos\na voar para outros que não conhecemos?\nAssim a consciência faz de todos nós covardes;\ne assim a cor nativa da resolução\nse enfraquece sob o pálido tom do pensamento,\ne empresas de grande vulto e importância,\npor essa consideração, desviam o curso\ne perdem o nome de ação.—Silêncio agora!\nA bela Ofélia! Ninfa, em tuas orações\nsejam lembrados todos os meus pecados.","opheliagoodmylordhowdoesyourhonourforthi~ourhonourforthismanyaday~49":"Ofélia — Bom meu senhor,\ncomo tem passado Vossa Honra todos estes dias?","hamletihumblythankyouwellwellwell~mblythankyouwellwellwell~33":"Hamlet — Agradeço humildemente; bem, bem, bem.","opheliamylordihaveremembrancesofyourstha~eriprayyounowreceivethem~89":"Ofélia — Meu senhor, tenho lembranças vossas\nque há muito desejo devolver;\npeço-vos que as recebais agora.","hamletnonotiinevergaveyouaught~nonotiinevergaveyouaught~30":"Hamlet — Não, eu não;\nnunca te dei coisa alguma.","opheliamyhonourdlordyouknowrightwellyoud~rsproveunkindtheremylord~199":"Ofélia — Honrado senhor, bem sabeis que destes;\ne, com elas, palavras de hálito tão doce\nque tornavam os presentes mais ricos: perdido o perfume,\ntomai-as de volta; pois, para o nobre espírito,\nricos dons empobrecem quando o doador se mostra cruel.\nAqui, meu senhor.","hamlethahaareyouhonest~hamlethahaareyouhonest~22":"Hamlet — Ha, ha! És honesta?","opheliamylord~opheliamylord~13":"Ofélia — Meu senhor?","hamletareyoufair~hamletareyoufair~16":"Hamlet — És bela?","opheliawhatmeansyourlordship~liawhatmeansyourlordship~28":"Ofélia — Que quer dizer Vossa Senhoria?","hamletthatifyoubehonestandfairyourhonest~tnodiscoursetoyourbeauty~75":"Hamlet — Que, se és honesta e bela, tua honestidade não deve admitir trato com a tua beleza.","opheliacouldbeautymylordhavebettercommer~rcommercethanwithhonesty~57":"Ofélia — Poderia a beleza, meu senhor, ter melhor companhia do que a honestidade?","hamletaytrulyforthepowerofbeautywillsoon~esitproofididloveyouonce~194":"Hamlet — Sim, na verdade; pois o poder da beleza converterá a honestidade em alcoviteira mais depressa do que a força da honestidade poderá transformar a beleza à sua semelhança: isto já foi um paradoxo, mas agora o tempo o comprova. Eu te amei outrora.","opheliaindeedmylordyoumademebelieveso~mylordyoumademebelieveso~37":"Ofélia — De fato, meu senhor, fizestes-me acreditar nisso.","hamletyoushouldnothavebelievedmeforvirtu~llrelishofitilovedyounot~101":"Hamlet — Não devias ter acreditado em mim; pois a virtude não pode enxertar tanto o nosso velho tronco que não fique algum sabor dele: eu não te amei.","opheliaiwasthemoredeceived~heliaiwasthemoredeceived~26":"Ofélia — Tanto maior foi o meu engano.","hamletgettheetoanunnerywhywouldstthoubea~anunnerywheresyourfather~402":"Hamlet — Vai para um convento: por que queres ser criadora de pecadores? Eu mesmo sou razoavelmente honesto; e, contudo, poderia acusar-me de tais coisas que melhor seria minha mãe não me ter dado à luz: sou muito orgulhoso, vingativo, ambicioso, com mais ofensas a meu dispor do que pensamentos para contê-las, imaginação para dar-lhes forma ou tempo para praticá-las. Que devem fazer criaturas como eu, rastejando entre a terra e o céu? Somos todos velhacos consumados; não creias em nenhum de nós. Segue o teu caminho para um convento. Onde está teu pai?","opheliaathomemylord~opheliaathomemylord~19":"Ofélia — Em casa, meu senhor.","hamletletthedoorsbeshutuponhimthathemayp~rebutinsownhousefarewell~79":"Hamlet — Que se fechem as portas sobre ele, para que só faça o tolo em sua própria casa. Adeus.","opheliaohelphimyousweetheavens~aohelphimyousweetheavens~30":"Ofélia — Oh, ajudai-o, doces céus!","hamletifthoudostmarryillgivetheethisplag~ygoandquicklytoofarewell~250":"Hamlet — Se te casares, dar-te-ei esta praga como dote: sejas casta como o gelo, pura como a neve, não escaparás à calúnia. Vai para um convento, vai; adeus. Ou, se absolutamente queres casar, casa com um tolo; pois os homens sábios bem sabem que monstros fazeis deles. Para um convento, vai, e depressa. Adeus.","opheliaoheavenlypowersrestorehim~heavenlypowersrestorehim~32":"Ofélia — Ó poderes celestes, restituí-lhe a razão!","hamletihaveheardofyourpaintingstoowellen~stheyaretoanunnerygoexit~319":"Hamlet — Ouvi falar bastante também das vossas pinturas; Deus vos deu um rosto, e vós fazeis outro para vós mesmas: dançais, rebolais, falais com ceceio, dais apelidos às criaturas de Deus e fazeis da vossa lascívia ignorância. Basta, não quero mais nada disso; fez-me enlouquecer. Digo que não teremos mais casamentos: os que já são casados, menos um, viverão; os demais ficarão como estão. Para um convento, vai. Sai.","opheliaowhatanoblemindishereoerthrownthe~whatihaveseenseewhatisee~423":"Ofélia — Oh, que nobre espírito aqui foi derrubado!\nO olho, a língua, a espada do cortesão, do soldado, do erudito;\na esperança e a rosa do belo reino,\no espelho da elegância e o molde da compostura,\no observado de todos os observadores, inteiramente, inteiramente abatido!\nE eu, das damas a mais desolada e miserável,\nque sorvi o mel de seus votos musicais,\nvejo agora aquela nobre e soberana razão,\ncomo sinos doces desafinados, dissonantes e ásperos;\naquela forma e feição sem par da juventude em flor\narruinada pelo delírio: oh, ai de mim,\nter visto o que vi, ver o que vejo!","reenterkingandpolonius~reenterkingandpolonius~22":"Reentram o Rei e Polônio.","kinglovehisaffectionsdonotthatwaytendnor~ofhimselfwhatthinkyouont~482":"Rei — Amor! suas afeições não tendem para esse lado;\nnem o que falou, embora lhe faltasse um pouco de forma,\nparecia loucura. Há algo em sua alma\nsobre o qual sua melancolia choca;\ne temo que a eclosão e o desfecho\nsejam algum perigo: para preveni-lo,\nem rápida resolução\nassim decidi: ele irá com presteza à Inglaterra,\npara exigir o nosso tributo negligenciado:\nquem sabe os mares e as terras diferentes,\ncom seus objetos variados, expulsem\nesse algo assentado em seu coração,\nem que seu cérebro, a bater sem cessar, o põe\nfora do seu feitio. Que pensais disso?","poloniusitshalldowellbutyetdoibelievethe~yourwisdombestshallthink~395":"Polônio — Fará bem; mas ainda creio\nque a origem e o começo de sua dor\nnasceram de um amor desprezado. Então, Ofélia!\nNão precisas contar-nos o que disse o senhor Hamlet;\nouvimos tudo. Meu senhor, fazei como vos aprouver;\nmas, se julgardes conveniente, depois da peça\nque a rainha, sua mãe, a sós, o procure\npara que mostre sua mágoa: que ela seja franca com ele;\ne eu me postarei, se for do vosso agrado, ao alcance do ouvido\nde toda a sua conversa. Se ela nada descobrir,\nenviai-o à Inglaterra, ou confinai-o onde\nvossa sabedoria melhor julgar.","kingitshallbesomadnessingreatonesmustnot~smustnotunwatchdgoexeunt~56":"Rei — Assim será:\na loucura nos grandes não deve ficar sem vigia. Saem.","ahallinthecastle~ahallinthecastle~16":"Um salão no castelo.","enterhamletandplayers~enterhamletandplayers~21":"Entram Hamlet e os Atores.","hamletspeakthespeechiprayyouasipronounce~erodsherodprayyouavoidit~572":"Hamlet — Dizei o texto, peço-vos, como eu o declamei a vós, com fluência na língua; mas, se o ribombardes, como fazem muitos dos vossos atores, preferiria que o pregoeiro da cidade dissesse os meus versos. Nem serreis demais o ar com a mão, assim, mas usai de tudo com suavidade; pois no próprio torrente, tempestade e, por assim dizer, redemoinho da paixão, deveis adquirir e gerar uma temperança que lhe dê suavidade. Oh, ofende-me a alma ouvir um sujeito robusto e de peruca tilintar uma paixão em frangalhos, em puros trapos, para rachar os ouvidos da plateia, que na maior parte só é capaz de entender mímicas incompreensíveis e barulho: mandaria açoitar tal sujeito por exagerar Termagante; supera Herodes em Herodes: rogo-vos, evitai isso.","firstplayeriwarrantyourhonour~playeriwarrantyourhonour~29":"Primeiro Ator — Garanto a Vossa Honra.","hamletbenottootameneitherbutletyourowndi~atedhumanitysoabominably~801":"Hamlet — Não sejais também comedidos demais, mas deixai que a vossa discrição seja a vossa mestra: ajustai o gesto à palavra, a palavra ao gesto; com esta especial observância, de que não ultrapasseis a modéstia da natureza: pois tudo o que é exagerado afasta-se do propósito da representação, cujo fim, tanto no princípio como agora, foi e é erguer, por assim dizer, o espelho diante da natureza; mostrar à virtude seus próprios traços, ao escárnio sua própria imagem, e à própria idade e corpo do tempo sua forma e impressão. Ora, isto exagerado, ou feito de modo frouxo, embora faça rir os ignorantes, não pode deixar de afligir os judiciosos, cujo juízo deve pesar, a vosso ver, mais que um teatro inteiro dos outros. Oh, há atores que vi representar, e ouvi outros louvarem, e muito, para não falar profanamente, que, não tendo nem o sotaque de cristãos nem o andar de cristão, pagão ou homem, pavonearam-se e bramiram de tal modo que pensei que alguns aprendizes da natureza haviam feito homens e não os haviam feito bem, tão abominavelmente imitavam a humanidade.","firstplayerihopewehavereformedthatindiff~atindifferentlywithussir~56":"Primeiro Ator — Espero que entre nós tenhamos reformado isso razoavelmente, senhor.","hamletoreformitaltogetherandletthosethat~akeyoureadyexeuntplayers~329":"Hamlet — Oh, reformai-o por completo. E que os que fazem vossos palhaços não digam mais do que lhes foi escrito; pois há alguns que riem eles próprios, para fazer rir também certa quantidade de espectadores estéreis, ainda que, nesse meio-tempo, alguma questão necessária da peça deva então ser considerada: isso é vil, e mostra uma ambição lamentável no tolo que o pratica. Ide, preparai-vos. Saem os Atores.","enterpoloniusrosencrantzandguildenstern~sencrantzandguildenstern~39":"Entram Polônio, Rosencrantz e Guildenstern.","hownowmylordiwillthekinghearthispieceofw~ekinghearthispieceofwork~43":"Então, meu senhor! O rei quer ouvir esta obra?","poloniusandthequeentooandthatpresently~queentooandthatpresently~38":"Polônio — E a rainha também, e já.","hamletbidtheplayersmakehasteexitpolonius~llyoutwohelptohastenthem~66":"Hamlet — Mandai os atores se apressarem. Sai Polônio. Quereis vós dois ajudá-los a se apressar?","rosencrantzguildensternwewillmylordexeun~sencrantzandguildenstern~67":"Rosencrantz\nGuildenstern — Queremos, meu senhor. Saem Rosencrantz e Guildenstern.","hamletwhathohoratio~hamletwhathohoratio~19":"Hamlet — Olá! Horácio!","enterhoratio~enterhoratio~12":"Entra Horácio.","horatioheresweetlordatyourservice~resweetlordatyourservice~33":"Horácio — Aqui, doce senhor, às vossas ordens.","hamlethoratiothouarteenasjustamanaseermy~yconversationcopedwithal~63":"Hamlet — Horácio, és tão justo homem\nquanto jamais meu trato encontrou.","horatioomydearlord~horatioomydearlord~18":"Horácio — Oh, meu caro senhor—","hamletnaydonotthinkiflatterforwhatadvanc~oinincensureofhisseeming~1084":"Hamlet — Não, não penses que te adulo;\npois que progresso poderia esperar de ti,\nque não tens renda alguma além do teu bom ânimo\npara alimentar-te e vestir-te? Por que adular o pobre?\nNão: que a língua açucarada lamba a pompa absurda,\ne dobre as articulações ágeis do joelho\nonde o lucro possa seguir a bajulação. Ouves?\nDesde que minha cara alma foi senhora da sua escolha\ne pôde distinguir os homens, sua eleição\nselou-te para si; pois tens sido\ncomo quem, sofrendo tudo, nada sofre,\num homem que os golpes e as dádivas da fortuna\ntem recebido com igual gratidão; e bem-aventurados aqueles\ncujo sangue e juízo estão tão bem misturados\nque não são flauta para o dedo da fortuna\ntocar o registro que lhe aprouver. Dá-me esse homem\nque não é escravo da paixão, e hei de usá-lo\nno âmago do meu coração, sim, no coração do meu coração,\ncomo faço contigo.—Já é demais isto.—\nHá uma peça esta noite diante do rei;\numa cena dela aproxima-se das circunstâncias\nque te contei da morte de meu pai:\npeço-te, quando vires esse ato em curso,\ncom toda a atenção da tua alma\nobserva meu tio: se a sua culpa oculta\nnão sair do covil num só discurso,\nentão é um espectro maldito o que vimos,\ne minhas imaginações são tão imundas\nquanto a forja de Vulcano. Observa-o com cuidado;\npois eu fixarei os olhos em seu rosto,\ne depois juntaremos ambos os nossos juízos\npara julgar sua aparência.","horatiowellmylordifhestealaughtthewhilst~etectingiwillpaythetheft~90":"Horácio — Bem, meu senhor:\nse ele furtar algo enquanto a peça se representa\ne escapar à descoberta, pagarei o furto.","hamlettheyarecomingtotheplayimustbeidleg~yimustbeidlegetyouaplace~51":"Hamlet — Estão vindo para a peça; devo fingir-me ocioso:\narranja um lugar.","danishmarchaflourishenterkingqueenpoloni~ntzguildensternandothers~81":"Marcha dinamarquesa. Toque de trombetas. Entram o Rei, a Rainha, Polônio, Ofélia, Rosencrantz, Guildenstern e outros.","kinghowfaresourcousinhamlet~ghowfaresourcousinhamlet~27":"Rei — Como passa nosso primo Hamlet?","hamletexcellentifaithofthechameleonsdish~medyoucannotfeedcaponsso~85":"Hamlet — Excelentemente, na fé; da dieta do camaleão: como ar, empanturrado de promessas: não se engordam capões assim.","kingihavenothingwiththisanswerhamletthes~mletthesewordsarenotmine~56":"Rei — Nada tenho com essa resposta, Hamlet; essas palavras não são minhas.","hamletnonorminenowtopoloniusmylordyoupla~onceitheuniversityyousay~67":"Hamlet — Não, nem minhas agora. A Polônio. Meu senhor, representastes outrora na universidade, dizeis?","poloniusthatdidimylordandwasaccountedago~ndwasaccountedagoodactor~47":"Polônio — Representei, meu senhor; e fui tido por bom ator.","hamletwhatdidyouenact~hamletwhatdidyouenact~21":"Hamlet — Que papel fizestes?","poloniusididenactjuliuscaesariwaskilledi~thecapitolbrutuskilledme~64":"Polônio — Fiz Júlio César: fui morto no Capitólio; Brutus me matou.","hamletitwasabrutepartofhimtokillsocapita~lftherebetheplayersready~68":"Hamlet — Foi brutal da parte dele matar tão capital bezerro. Estão prontos os atores?","rosencrantzaymylordtheystayuponyourpatie~theystayuponyourpatience~43":"Rosencrantz — Sim, meu senhor; aguardam a vossa paciência.","queencomehithermydearhamletsitbyme~ithermydearhamletsitbyme~34":"Rainha — Vem cá, meu caro Hamlet, senta-te junto a mim.","hamletnogoodmotherheresmetalmoreattracti~heresmetalmoreattractive~42":"Hamlet — Não, boa mãe, aqui há ímã mais atraente.","poloniustothekingohodoyoumarkthat~othekingohodoyoumarkthat~33":"Polônio — Ao Rei. Oh, oh! Notais isso?","hamletladyshallilieinyourlaplyingdownato~plyingdownatopheliasfeet~51":"Hamlet — Senhora, posso deitar-me em vosso colo? Deitando-se aos pés de Ofélia.","ophelianomylord~ophelianomylord~15":"Ofélia — Não, meu senhor.","hamletimeanmyheaduponyourlap~etimeanmyheaduponyourlap~28":"Hamlet — Quero dizer, a cabeça em vosso colo?","opheliaaymylord~opheliaaymylord~15":"Ofélia — Sim, meu senhor.","hamletdoyouthinkimeantcountrymatters~hinkimeantcountrymatters~36":"Hamlet — Pensais que eu falava de assuntos de roça?","opheliaithinknothingmylord~heliaithinknothingmylord~26":"Ofélia — Não penso nada, meu senhor.","hamletthatsafairthoughttoliebetweenmaids~ghttoliebetweenmaidslegs~44":"Hamlet — Bela ideia, deitar-se entre as pernas das donzelas.","opheliawhatismylord~opheliawhatismylord~19":"Ofélia — O que é, meu senhor?","hamletnothing~hamletnothing~13":"Hamlet — Nada.","opheliayouaremerrymylord~opheliayouaremerrymylord~24":"Ofélia — Estais alegre, meu senhor.","hamletwhoi~hamletwhoi~10":"Hamlet — Quem, eu?","hamletogodyouronlyjigmakerwhatshouldaman~rdiedwithinthesetwohours~122":"Hamlet — Oh, Deus, vosso único fazedor de gigas. Que deve fazer um homem senão ser alegre? Pois, vede, como minha mãe parece contente, e meu pai morreu há menos de duas horas.","ophelianaytistwicetwomonthsmylord~ytistwicetwomonthsmylord~33":"Ofélia — Não, faz duas vezes dois meses, meu senhor.","hamletsolongnaythenletthedevilwearblackf~orothehobbyhorseisforgot~284":"Hamlet — Tanto tempo? Pois então que o diabo vista luto, que eu terei um traje de zibelina. Ó céus! Morrer há dois meses e ainda não esquecido? Então há esperança de que a memória de um grande homem sobreviva à vida meio ano: mas, por Nossa Senhora, ele terá de erguer igrejas; ou então sofrerá o esquecimento, como o cavalinho de pau, cujo epitáfio é “Pois, ó, pois, ó, o cavalinho de pau foi esquecido.”","hautboysplaythedumbshowenters~oysplaythedumbshowenters~29":"Tocam oboés. Entra a pantomima.","enterakingandaqueenverylovinglythequeene~eendacceptshisloveexeunt~517":"Entram um Rei e uma Rainha muito amorosamente; a Rainha o abraça, e ele a ela. Ela se ajoelha e faz demonstração de juramento a ele. Ele a ergue e inclina a cabeça sobre o pescoço dela; deita-se sobre um leito de flores; ela, vendo-o adormecido, deixa-o. Logo entra um sujeito, tira-lhe a coroa, beija-a e derrama veneno nos ouvidos do Rei, e sai. A Rainha volta; encontra o Rei morto e faz gestos apaixonados. O Envenenador, com dois ou três Mudos, entra de novo, fingindo lamentar com ela. O corpo morto é levado. O Envenenador corteja a Rainha com presentes: ela parece relutante e avessa por algum tempo, mas por fim aceita o amor dele. Saem.","opheliawhatmeansthismylord~heliawhatmeansthismylord~26":"Ofélia — Que significa isto, meu senhor?","hamletmarrythisismichingmallechoitmeansm~gmallechoitmeansmischief~47":"Hamlet — Ora, isto é miching mallecho, ou seja, dissimulada maldade; significa desgraça.","opheliabelikethisshowimportstheargumento~ortstheargumentoftheplay~48":"Ofélia — Provavelmente esta pantomima apresenta o argumento da peça.","enterprologue~enterprologue~13":"Entra o Prólogo.","hamletweshallknowbythisfellowtheplayersc~keepcounseltheylltellall~69":"Hamlet — Saberemos por este sujeito: os atores não sabem guardar segredo; contam tudo.","opheliawillhetelluswhatthisshowmeant~etelluswhatthisshowmeant~36":"Ofélia — Dirá ele o que significou esta pantomima?","hamletayoranyshowthatyoullshowhimbenotyo~hametotellyouwhatitmeans~86":"Hamlet — Sim, ou qualquer pantomima que lhe mostrardes: não tenhais vergonha de mostrar, que ele não terá vergonha de dizer o que significa.","opheliayouarenaughtyouarenaughtillmarkth~uarenaughtillmarktheplay~45":"Ofélia — Sois mau, sois mau: vou prestar atenção à peça.","prologueforusandforourtragedyherestoopin~yourhearingpatientlyexit~84":"Prólogo — Por nós e por nossa tragédia,\naqui inclinados à vossa clemência,\npedimos que ouçais com paciência. Sai.","hamletisthisaprologueortheposyofaring~prologueortheposyofaring~37":"Hamlet — É isto um prólogo, ou a divisa de um anel?","opheliatisbriefmylord~opheliatisbriefmylord~21":"Ofélia — É breve, meu senhor.","hamletaswomanslove~hamletaswomanslove~18":"Hamlet — Como o amor de mulher.","entertwoplayerskingandqueen~ertwoplayerskingandqueen~27":"Entram dois Atores, Rei e Rainha.","playerkingfullthirtytimeshathphoebuscart~mmutualinmostsacredbands~228":"Rei Ator — Trinta vezes já rodou o carro de Febo\nsobre a salgada lavagem de Netuno e o orbe de Telo,\ne trinta dúzias de luas, com emprestado brilho,\ntrezentas e sessenta vezes o mundo rodearam,\ndesde que o amor nos uniu os corações e Himeneu as mãos,\nem recíprocos laços sacratíssimos.","playerqueensomanyjourneysmaythesunandmoo~greatgreatlovegrowsthere~410":"Rainha Atriz — Quantas viagens ainda possam sol e lua\nfazer-nos contar antes que o amor acabe!\nMas, ai de mim, estais tão enfermo ultimamente,\ntão longe da alegria e do vosso antigo estado,\nque desconfio de vós. Contudo, embora desconfie,\nnão deve isso afligir-vos, meu senhor:\npois o temor e o amor das mulheres têm igual medida;\nou em ambos nada, ou em ambos excesso.\nOra, o que é meu amor, a prova já vos fez saber;\ne, como é a medida do meu amor, assim é a do meu temor:\nonde o amor é grande, as menores dúvidas são temor;\nonde pequenos temores crescem, cresce um grande amor.","playerkingfaithimustleavetheeloveandshor~skindforhusbandshaltthou~171":"Rei Ator — Na verdade, devo deixar-te, amor, e em breve;\nminhas forças vitais cessam suas funções:\ne tu viverás neste belo mundo que ficar,\nhonrada, amada; e talvez outro tão bondoso\npor marido tomarás—","playerqueenoconfoundtherestsuchlovemustn~econdbutwhokilldthefirst~127":"Rainha Atriz — Oh, maldito seja o resto!\nTal amor seria forçosamente traição em meu peito:\nmaldita seja eu num segundo marido!\nNinguém casa a segunda vez senão quem matou o primeiro.","hamletasidewormwoodwormwood~letasidewormwoodwormwood~27":"Hamlet — À parte. Absinto, absinto.","playerqueentheinstancesthatsecondmarriag~condhusbandkissesmeinbed~140":"Rainha Atriz — Os motivos que levam a segundas núpcias\nsão baixos cálculos de ganho, e nenhum de amor:\numa segunda vez mato meu marido já morto,\nquando o segundo marido me beija no leito.","playerkingidobelieveyouthinkwhatnowyousp~tswhenthyfirstlordisdead~1018":"Rei Ator — Creio que pensas o que agora dizes;\nmas o que decidimos, muitas vezes quebramos.\nO propósito não é senão escravo da memória,\nde violento nascimento, mas de pobre validade:\nque agora, como fruta verde, se prende à árvore,\nmas cai, sem ser sacudida, quando amadurece.\nÉ muito necessário que esqueçamos\npagar a nós mesmos o que a nós mesmos é dívida:\no que a nós mesmos, em paixão, propomos,\nfindada a paixão, perde-se o propósito.\nA violência, seja da dor, seja da alegria,\ndestrói com elas mesmas suas realizações:\nonde a alegria mais festeja, a dor mais se lamenta;\na dor se alegra, a alegria se aflige, por frágil acidente.\nEste mundo não é para sempre, nem é estranho\nque até os nossos amores mudem com as nossas fortunas;\npois é uma questão que ainda nos resta provar:\nse o amor guia a fortuna, ou a fortuna o amor.\nCaído o grande, vês fugir o seu favorito;\no pobre elevado faz de inimigos amigos.\nE até aqui o amor depende da fortuna;\npois quem não precisa nunca terá falta de amigo,\ne quem, na penúria, experimenta um amigo falso,\nlogo o tempera em seu inimigo.\nMas, para terminar em ordem onde comecei,\nnossas vontades e destinos correm tão opostos\nque nossos planos sempre são derrubados;\nnossos pensamentos são nossos, seus fins não são de nós:\nassim pensa que não casarás com segundo marido;\nmas morram teus pensamentos quando morrer teu primeiro senhor.","playerqueennorearthtomegivefoodnorheaven~eifonceawidoweveribewife~270":"Rainha Atriz — Que a terra me negue alimento, e o céu, luz!\nQue folguedo e repouso me sejam vedados dia e noite!\nQue em desespero se transformem minha confiança e esperança!\nQue a vida de eremita na prisão seja o meu limite!\nQue todo adverso que empalidece a face da alegria\nencontre o que eu queria bem e o destrua!\nAqui e além me persiga duradoura discórdia,\nse, uma vez viúva, eu voltar a ser esposa!","hamletifsheshouldbreakitnow~letifsheshouldbreakitnow~27":"Hamlet — E se ela agora o quebrar!","playerkingtisdeeplyswornsweetleavemehere~ediousdaywithsleepsleeps~111":"Rei Ator — É juramento profundo. Doce, deixa-me aqui um instante;\nmeu ânimo se embota, e de bom grado enganaria\no tedioso dia com o sono. Dorme.","playerqueensleeprockthybrainandnevercome~chancebetweenustwainexit~67":"Rainha Atriz — Que o sono embale teu cérebro;\ne nunca venha desgraça entre nós dois! Sai.","hamletmadamhowlikeyouthisplay~tmadamhowlikeyouthisplay~29":"Hamlet — Senhora, que tal achais esta peça?","queentheladydothprotesttoomuchmethinks~thprotesttoomuchmethinks~38":"Rainha — A dama protesta demais, parece-me.","hamletobutshellkeepherword~mletobutshellkeepherword~26":"Hamlet — Oh, mas ela manterá a palavra.","kinghaveyouheardtheargumentistherenooffe~umentistherenooffenceint~46":"Rei — Ouvistes o argumento? Não há ofensa nele?","hamletnonotheydobutjestpoisoninjestnooff~injestnooffenceitheworld~53":"Hamlet — Não, não, eles apenas gracejam, veneno por gracejo; nenhuma ofensa no mundo.","kingwhatdoyoucalltheplay~kingwhatdoyoucalltheplay~24":"Rei — Como chamais a peça?","hamletthemousetrapmarryhowtropicallythis~inceourwithersareunwrung~248":"Hamlet — A Ratoeira. Ora, como assim? Figuradamente. Esta peça é a imagem de um assassinato cometido em Viena: Gonzago é o nome do duque; sua mulher, Baptista: vereis daqui a pouco; é obra de velhacaria: mas que importa? A Vossa Majestade e a nós, que temos almas livres, não nos toca: que a besta ferida se encolha, nossos lombos estão intactos.","enterlucianus~enterlucianus~13":"Entra Lucianus.","thisisonelucianusnephewtotheking~elucianusnephewtotheking~32":"Este é um tal Lucianus, sobrinho do rei.","opheliayouareasgoodasachorusmylord~areasgoodasachorusmylord~34":"Ofélia — Sois tão bom quanto um coro, meu senhor.","hamleticouldinterpretbetweenyouandyourlo~uldseethepuppetsdallying~71":"Hamlet — Eu poderia interpretar entre vós e vosso amor, se pudesse ver os bonecos em namoro.","opheliayouarekeenmylordyouarekeen~uarekeenmylordyouarekeen~33":"Ofélia — Sois mordaz, meu senhor, sois mordaz.","hamletitwouldcostyouagroaningtotakeoffmy~agroaningtotakeoffmyedge~44":"Hamlet — Custar-vos-ia um gemido tirar-me o gume.","opheliastillbetterandworse~heliastillbetterandworse~26":"Ofélia — Cada vez melhor, e pior.","hamletsoyoumusttakeyourhusbandsbeginmurd~avendothbellowforrevenge~116":"Hamlet — Assim deveis tomar vossos maridos. Começa, assassino; ao diabo, deixa tuas caretas malditas e começa. Vamos: “o corvo que grasna clama por vingança.”","lucianusthoughtsblackhandsaptdrugsfitand~oisonintothesleepersears~263":"Lucianus — Pensamentos negros, mãos hábeis, drogas prontas e tempo propício;\nestação cúmplice, e nenhuma criatura a ver;\ntu, mistura fétida, de ervas da meia-noite colhidas,\npela maldição de Hécate três vezes ressecada, três vezes infectada,\ntua magia natural e propriedade funesta,\nusurpa imediatamente a vida sadia. Derrama o veneno nos ouvidos do adormecido.","hamlethepoisonshimithegardenforsestatehi~etstheloveofgonzagoswife~145":"Hamlet — Ele o envenena no jardim, por causa dos bens. Seu nome é Gonzago: a história existe e está escrita em italiano de boa escolha: vereis daqui a pouco como o assassino conquista o amor da mulher de Gonzago.","opheliathekingrises~opheliathekingrises~19":"Ofélia — O rei se levanta.","hamletwhatfrightedwithfalsefire~hatfrightedwithfalsefire~31":"Hamlet — O quê, assustado com fogo de mentira!","queenhowfaresmylord~queenhowfaresmylord~19":"Rainha — Como passa meu senhor?","poloniusgiveoertheplay~poloniusgiveoertheplay~22":"Polônio — Parai a peça.","kinggivemesomelightaway~kinggivemesomelightaway~23":"Rei — Dai-me alguma luz: vamos embora!","alllightslightslightsexeuntallbuthamleta~ntallbuthamletandhoratio~49":"Todos — Luzes, luzes, luzes! Saem todos, exceto Hamlet e Horácio.","hamletwhyletthestrickendeergoweepthehart~owshipinacryofplayerssir~244":"Hamlet — Ora, deixe o cervo ferido ir chorar,\no cervo ileso brincar;\npois uns devem velar, enquanto outros dormir:\nassim vai correndo o mundo. Não me valeria isto, senhor, e uma floresta de plumas—se o resto da minha sorte virar turco comigo—com duas rosas de Provença nos meus sapatos recortados, uma parte numa companhia de atores, senhor?","horatiohalfashare~horatiohalfashare~17":"Horácio — Meia parte.","hamletawholeoneiforthoudostknowodamondea~eignshereaveryverypajock~107":"Hamlet — Uma inteira, eu. Pois bem sabes, ó caro Damon,\nque este reino foi despojado\ndo próprio Jove; e agora reina aqui\num verdadeiro, verdadeiro—pavão.","horatioyoumighthaverhymed~oratioyoumighthaverhymed~25":"Horácio — Podíeis ter rimado.","hamletogoodhoratioilltaketheghostswordfo~ousandpounddidstperceive~68":"Hamlet — Oh, bom Horácio, aceito a palavra do espectro por mil libras. Percebeste?","horatioverywellmylord~horatioverywellmylord~21":"Horácio — Muito bem, meu senhor.","hamletuponthetalkofthepoisoning~ponthetalkofthepoisoning~31":"Hamlet — Quando se falou do envenenamento?","horatioididverywellnotehim~ratioididverywellnotehim~26":"Horácio — Observei-o muito bem.","hamletahhacomesomemusiccometherecordersf~sitnotperdycomesomemusic~110":"Hamlet — Ah, ha! Vamos, música! Vamos, as flautas!\nPois se ao rei não agrada a comédia,\nentão, sem dúvida, não lhe agrada, por Deus.\nVamos, música!","reenterrosencrantzandguildenstern~sencrantzandguildenstern~33":"Reentram Rosencrantz e Guildenstern.","guildensterngoodmylordvouchsafemeawordwi~dvouchsafemeawordwithyou~45":"Guildenstern — Bom meu senhor, concedei-me uma palavra convosco.","hamletsirawholehistory~hamletsirawholehistory~22":"Hamlet — Senhor, uma história inteira.","guildensternthekingsir~guildensternthekingsir~22":"Guildenstern — O rei, senhor—","hamletaysirwhatofhim~hamletaysirwhatofhim~20":"Hamlet — Sim, senhor, que há com ele?","guildensternisinhisretirementmarvellousd~entmarvellousdistempered~50":"Guildenstern — Está em seus aposentos maravilhosamente indisposto.","hamletwithdrinksir~hamletwithdrinksir~18":"Hamlet — De bebida, senhor?","guildensternnomylordratherwithcholer~nomylordratherwithcholer~36":"Guildenstern — Não, meu senhor, antes de cólera.","hamletyourwisdomshouldshowitselfmorerich~ungehimintofarmorecholer~134":"Hamlet — Vossa sabedoria se mostraria mais rica se o dissesse ao médico dele; pois eu, se o submetesse à purga, talvez o lançasse em cólera ainda muito maior.","guildensterngoodmylordputyourdiscoursein~tnotsowildlyfrommyaffair~82":"Guildenstern — Bom meu senhor, dai alguma ordem ao vosso discurso e não fujais tão selvagemente do meu assunto.","hamletiamtamesirpronounce~amletiamtamesirpronounce~25":"Hamlet — Estou manso, senhor: falai.","guildensternthequeenyourmotherinmostgrea~nofspirithathsentmetoyou~74":"Guildenstern — A rainha, vossa mãe, em grandíssima aflição de espírito, enviou-me a vós.","hamletyouarewelcome~hamletyouarewelcome~19":"Hamlet — Sois bem-vindo.","guildensternnaygoodmylordthiscourtesyisn~hallbetheendofmybusiness~179":"Guildenstern — Não, bom meu senhor, esta cortesia não é de boa raça. Se vos aprouver dar-me uma resposta sensata, cumprirei a ordem de vossa mãe; se não, vosso perdão e meu regresso serão o fim do meu negócio.","hamletsiricannot~hamletsiricannot~16":"Hamlet — Senhor, não posso.","guildensternwhatmylord~guildensternwhatmylord~22":"Guildenstern — O quê, meu senhor?","hamletmakeyouawholesomeanswermywitsdisea~othemattermymotheryousay~151":"Hamlet — Dar-vos uma resposta sensata; meu juízo está doente: mas, senhor, a resposta que eu puder dar, ireis comandá-la; ou, antes, como dizeis, minha mãe: portanto nada mais, mas ao assunto: minha mãe, dizeis—","rosencrantzthenthusshesaysyourbehaviorha~toamazementandadmiration~77":"Rosencrantz — Então ela diz assim: vosso comportamento a mergulhou em espanto e admiração.","hamletowonderfulsonthatcansoastonishamot~smothersadmirationimpart~100":"Hamlet — Oh, filho admirável, que sabe assombrar assim uma mãe! Mas não há sequência no encalço dessa admiração materna? Dizei.","rosencrantzshedesirestospeakwithyouinher~inherclosetereyougotobed~59":"Rosencrantz — Ela deseja falar convosco em seus aposentos, antes que vades dormir.","hamletweshallobeywereshetentimesourmothe~youanyfurthertradewithus~69":"Hamlet — Obedeceremos, fosse ela dez vezes nossa mãe. Tendes algum outro negócio conosco?","rosencrantzmylordyouoncedidloveme~tzmylordyouoncedidloveme~33":"Rosencrantz — Meu senhor, um dia já me amastes.","hamletsoidostillbythesepickersandstealer~ythesepickersandstealers~41":"Hamlet — E ainda amo, por estes meus ladrões e furtadores.","rosencrantzgoodmylordwhatisyourcauseofdi~nyyourgriefstoyourfriend~117":"Rosencrantz — Bom meu senhor, qual é a causa do vosso desassossego? Certamente fechais a porta à vossa própria liberdade, se negais as vossas mágoas ao vosso amigo.","hamletsirilackadvancement~amletsirilackadvancement~25":"Hamlet — Senhor, falta-me progresso.","rosencrantzhowcanthatbewhenyouhavethevoi~ryoursuccessionindenmark~84":"Rosencrantz — Como pode ser, se tendes o voto do próprio rei para a vossa sucessão na Dinamarca?","hamletaybutsirwhilethegrassgrowstheprove~eproverbissomethingmusty~58":"Hamlet — Sim, mas, senhor, “Enquanto a grama cresce”—o provérbio é um tanto mofado.","reenterplayerswithrecorders~nterplayerswithrecorders~27":"Reentram os Atores com flautas.","otherecordersletmeseeonetowithdrawwithyo~youwoulddrivemeintoatoil~104":"Oh, as flautas! Deixai-me ver uma. Para falar a sós convosco:—por que andais rodeando para ganhar o vento de mim, como se quisésseis empurrar-me para uma armadilha?","guildensternomylordifmydutybetooboldmylo~oldmyloveistoounmannerly~57":"Guildenstern — Oh, meu senhor, se meu dever é ousado demais, meu afeto é grosseiro demais.","hamletidonotwellunderstandthatwillyoupla~twillyouplayuponthispipe~53":"Hamlet — Não entendo bem isso. Quereis tocar esta flauta?","guildensternmylordicannot~uildensternmylordicannot~25":"Guildenstern — Meu senhor, não sei.","hamletiprayyou~hamletiprayyou~14":"Hamlet — Eu vos peço.","guildensternbelievemeicannot~densternbelievemeicannot~28":"Guildenstern — Crede-me, não sei.","hamletidobeseechyou~hamletidobeseechyou~19":"Hamlet — Eu vos suplico.","guildensterniknownotouchofitmylord~rniknownotouchofitmylord~34":"Guildenstern — Não conheço o toque, meu senhor.","hamlettisaseasyaslyinggoverntheseventage~clookyouthesearethestops~147":"Hamlet — É tão fácil quanto mentir: governai estes orifícios com os dedos e o polegar, dai-lhe sopro com a boca, e ela falará a mais eloquente música. Vede, estes são os furos.","guildensternbutthesecannoticommandtoanyu~fharmonyihavenottheskill~73":"Guildenstern — Mas estes não consigo dominar para que emitam harmonia alguma; não tenho a arte.","hamletwhylookyounowhowunworthyathingyoum~meyetyoucannotplayuponme~361":"Hamlet — Ora, vede agora que coisa indigna fazeis de mim! Quereis tocar em mim; quereis parecer conhecer os meus furos; quereis arrancar o coração do meu mistério; quereis sondar-me da minha nota mais baixa ao topo do meu registro: e há muita música, excelente voz, neste pequeno órgão; contudo não podeis fazê-lo falar. Pelo sangue de Deus, pensais que sou mais fácil de tocar que uma flauta? Chamai-me do instrumento que quiserdes, embora possais trastejar-me, não podeis tocar em mim.","godblessyousir~godblessyousir~14":"Deus vos abençoe, senhor!","poloniusmylordthequeenwouldspeakwithyoua~speakwithyouandpresently~51":"Polônio — Meu senhor, a rainha quer falar convosco, e já.","hamletdoyouseeyondercloudthatsalmostinsh~atsalmostinshapeofacamel~51":"Hamlet — Vedes aquela nuvem ali, quase em forma de camelo?","poloniusbythemassandtislikeacamelindeed~ssandtislikeacamelindeed~39":"Polônio — Pela missa, e é como um camelo, de fato.","hamletmethinksitislikeaweasel~tmethinksitislikeaweasel~29":"Hamlet — Parece-me uma doninha.","poloniusitisbackedlikeaweasel~iusitisbackedlikeaweasel~29":"Polônio — Tem o dorso de doninha.","hamletorlikeawhale~hamletorlikeawhale~18":"Hamlet — Ou de baleia?","poloniusverylikeawhale~poloniusverylikeawhale~22":"Polônio — Muito como uma baleia.","hamlettheniwillcometomymotherbyandbythey~ofmybentiwillcomebyandby~78":"Hamlet — Então irei à minha mãe daqui a pouco. Zombam de mim até o limite do meu gosto. Irei daqui a pouco.","poloniusiwillsayso~poloniusiwillsayso~18":"Polônio — Direi isso.","hamletbyandbyiseasilysaidexitpoloniuslea~lsnevermysoulconsentexit~469":"Hamlet — “Daqui a pouco” é fácil de dizer. Sai Polônio. Deixai-me, amigos. Saem todos, exceto Hamlet.\nÉ agora a verdadeira hora das bruxas da noite,\nquando os cemitérios se abrem e o próprio inferno exala\ncontágio a este mundo: agora eu poderia beber sangue quente\ne fazer tão amargos negócios que o dia\nestremeceria de olhar. Silêncio! Agora à minha mãe.\nÓ coração, não percas tua natureza; que jamais\na alma de Nero entre neste firme peito:\ndeixa-me ser cruel, não desnaturado:\nfalarei punhais a ela, mas não usarei nenhum;\nminha língua e minha alma sejam nisto hipócritas;\npor mais que ela seja repreendida em minhas palavras,\njamais, minha alma, consintas em selá-las! Sai.","enterkingrosencrantzandguildenstern~sencrantzandguildenstern~35":"Entram o Rei, Rosencrantz e Guildenstern.","kingilikehimnotnorstandsitsafewithustole~urlygrowoutofhislunacies~222":"Rei — Não gosto dele, nem é seguro para nós\ndeixar sua loucura andar à solta. Portanto, preparai-vos;\ndespacharei de imediato a vossa comissão,\ne ele irá convosco à Inglaterra:\nas condições do nosso estado não podem suportar\no risco tão perigoso que cresce a cada hora\nde suas loucuras.","guildensternwewillourselvesprovidemostho~veandfeeduponyourmajesty~121":"Guildenstern — Nós mesmos nos aprestaremos:\né temor santíssimo e religioso\nmanter a salvo os muitos, muitos corpos\nque vivem e se nutrem de Vossa Majestade.","rosencrantzthesingleandpeculiarlifeisbou~sighbutwithageneralgroan~454":"Rosencrantz — A vida singular e particular está obrigada,\ncom toda a força e armadura da mente,\na guardar-se do dano; mas muito mais\naquele espírito de cujo bem-estar dependem e repousam\nas vidas de muitos. O fim da majestade\nnão morre sozinho; como um abismo, arrasta\no que lhe está próximo: é uma roda maciça,\nfixada no cume do mais alto monte,\nem cujos enormes raios dez mil coisas menores\nestão encaixadas e unidas; a qual, quando cai,\ncada pequeno acessório, ínfima consequência,\nacompanha a ruína estrondosa. Nunca suspirou só\no rei, mas com um gemido geral.","kingarmyouiprayyoutothisspeedyvoyageforw~hichnowgoestoofreefooted~92":"Rei — Armai-vos, peço-vos, para esta rápida viagem;\npois poremos grilhões neste temor,\nque agora anda de pés demasiado livres.","rosencrantzguildensternwewillhasteusexeu~sencrantzandguildenstern~68":"Rosencrantz\nGuildenstern — Apressar-nos-emos. Saem Rosencrantz e Guildenstern.","poloniusmylordhesgoingtohismotherscloset~tobedandtellyouwhatiknow~300":"Polônio — Meu senhor, ele vai aos aposentos da mãe:\natrás da tapeçaria me esconderei,\npara ouvir o desenrolar; e garanto que ela o repreenderá a fundo:\ne, como dissestes, e sabiamente dito,\nconvém que mais audiência que uma mãe,\njá que a natureza as faz parciais, escute\na conversa, de um ponto vantajoso. Passai bem, meu soberano:\nvirei visitar-vos antes que vades dormir,\ne dir-vos-ei o que souber.","kingthanksdearmylordexitpoloniusomyoffen~aybewellretiresandkneels~1262":"Rei — Obrigado, caro senhor. Sai Polônio.\nOh, minha ofensa é fétida, cheira até o céu;\ntem sobre si a primeira e mais antiga maldição,\no assassinato de um irmão. Rezar não posso,\nembora a inclinação seja tão aguda quanto a vontade:\nminha culpa mais forte vence meu forte intento;\ne, como homem obrigado a duplo negócio,\nfico parado, em dúvida por onde começar,\ne ambos negligencio. Que seria se esta mão maldita\nfosse mais espessa que ela mesma, com sangue de irmão,\nnão há chuva bastante nos doces céus\npara lavá-la branca como a neve? Para que serve a clemência\nsenão para encarar o rosto da ofensa?\nE que há na oração senão esta dupla força:\nser prevenidos antes de cairmos,\nou perdoados, uma vez caídos? Então olharei para cima;\nminha falta passou. Mas, oh, que forma de prece\nme servirá? “Perdoa-me o meu torpe assassinato”?\nNão pode ser; pois ainda estou de posse\ndaquilo por que cometi o assassinato,\nminha coroa, minha própria ambição e minha rainha.\nPode-se ser perdoado e reter a ofensa?\nNas correntes corrompidas deste mundo,\na mão dourada da ofensa pode empurrar a justiça de lado,\ne muitas vezes se vê que o próprio prêmio do perverso\ncompra a lei: mas não é assim lá em cima;\nali não há trapaça, ali a ação jaz\nem sua verdadeira natureza; e nós mesmos somos obrigados,\naté os dentes e a fronte de nossas faltas,\na depor como prova. Que então? que resta?\nTentar o que o arrependimento puder: que não pode ele?\nMas que pode, quando não se pode arrepender?\nOh, estado miserável! Oh, peito negro como a morte!\nOh, alma presa em visgo, que, lutando por se libertar,\nmais te enredas! Ajudai, anjos! Fazei a prova!\nDobrai-vos, joelhos obstinados; e tu, coração de cordas de aço,\nsê macio como os tendões do recém-nascido!\nTudo pode correr bem. Retira-se e se ajoelha.","hamletnowmightidoitpatnowheisprayingandn~rolongsthysicklydaysexit~743":"Hamlet — Agora eu poderia fazê-lo, certeiro, agora que ele reza;\ne agora o farei. E assim ele vai para o céu;\ne assim estou vingado. Isso pede exame:\num vilão mata meu pai; e por isso,\neu, seu único filho, mando esse mesmo vilão\npara o céu.\nOh, isto é paga e salário, não vingança.\nEle tomou meu pai em plena carnalidade, cheio de pão,\ncom todos os crimes em plena flor, viçosos como maio;\ne como está a sua conta, quem sabe, salvo o céu?\nMas, pelas nossas circunstâncias e curso de pensamento,\né pesada para ele: e estou eu então vingado,\nse o tomo na purificação de sua alma,\nquando está pronto e preparado para a sua passagem?\nNão!\nPara cima, espada; e conhece mais horrenda ocasião:\nquando ele estiver bêbado e adormecido, ou em sua ira,\nou no prazer incestuoso de seu leito;\nno jogo, a blasfemar, ou em algum ato\nque não tenha sabor de salvação;\nentão derruba-o, para que seus calcanhares escoiceiem o céu,\ne sua alma seja tão danada e negra\nquanto o inferno, para onde vai. Minha mãe espera:\nesta purga apenas prolonga teus dias doentios. Sai.","kingrisingmywordsflyupmythoughtsremainbe~ughtsnevertoheavengoexit~82":"Rei — Levantando-se. Minhas palavras sobem, meus pensamentos ficam embaixo:\npalavras sem pensamentos nunca chegam ao céu. Sai.","thequeenscloset~thequeenscloset~15":"Os aposentos da Rainha.","enterqueenandpolonius~enterqueenandpolonius~21":"Entram a Rainha e Polônio.","poloniushewillcomestraightlookyoulayhome~ereprayyouberoundwithhim~183":"Polônio — Ele virá logo. Vede que o repreendais a fundo:\ndizei-lhe que suas travessuras têm sido largas demais para suportar,\ne que Vossa Graça se interpôs e o abrigou\nde muito furor. Aqui mesmo me aboletarei.\nPeço-vos, sede franca com ele.","hamletwithinmothermothermother~withinmothermothermother~30":"Hamlet — Dentro. Mãe, mãe, mãe!","queenillwarrantyoufearmenotwithdrawihear~oniushidesbehindthearras~76":"Rainha — Garanto-vos,\nnão temais por mim: retirai-vos, ouço-o chegar. Polônio se esconde atrás da tapeçaria.","hamletnowmotherwhatsthematter~tnowmotherwhatsthematter~29":"Hamlet — Então, mãe, que há?","queenhamletthouhastthyfathermuchoffended~astthyfathermuchoffended~40":"Rainha — Hamlet, ofendeste muito teu pai.","hamletmotheryouhavemyfathermuchoffended~havemyfathermuchoffended~39":"Hamlet — Mãe, ofendestes muito meu pai.","queencomecomeyouanswerwithanidletongue~ouanswerwithanidletongue~38":"Rainha — Vamos, vamos, respondes com língua ociosa.","hamletgogoyouquestionwithawickedtongue~uestionwithawickedtongue~38":"Hamlet — Vamos, vamos, interrogais com língua perversa.","queenwhyhownowhamlet~queenwhyhownowhamlet~20":"Rainha — Ora, que é isso, Hamlet!","hamletwhatsthematternow~hamletwhatsthematternow~23":"Hamlet — Que há agora?","queenhaveyouforgotme~queenhaveyouforgotme~20":"Rainha — Esqueceste quem sou?","hamletnobytheroodnotsoyouarethequeenyour~twerenotsoyouaremymother~93":"Hamlet — Não, pela cruz, não:\nsois a rainha, mulher do irmão de vosso marido;\ne—prouvera que não fosse!—sois minha mãe.","queennaythenillsetthosetoyouthatcanspeak~etthosetoyouthatcanspeak~40":"Rainha — Pois bem, porei diante de ti quem saiba falar.","hamletcomecomeandsityoudownyoushallnotbu~mayseetheinmostpartofyou~102":"Hamlet — Vamos, vamos, sentai-vos; não saireis daqui;\nnão partireis até que eu vos ponha um espelho\nonde possais ver a parte mais íntima de vós.","queenwhatwiltthoudothouwiltnotmurdermehe~iltnotmurdermehelphelpho~48":"Rainha — Que farás? Não me vais assassinar?\nSocorro, socorro, ó!","poloniusbehindwhathohelphelphelp~behindwhathohelphelphelp~32":"Polônio — Atrás da tapeçaria. Ora! Socorro, socorro, socorro!","hamletdrawinghownowaratdeadforaducatdead~akesapassthroughthearras~65":"Hamlet — Desembainhando. Então! Um rato? Morto, por um ducado, morto! Atravessa a tapeçaria com um golpe.","poloniusbehindoiamslainfallsanddies~indoiamslainfallsanddies~35":"Polônio — Atrás da tapeçaria. Oh, estou morto! Cai e morre.","queenomewhathastthoudone~queenomewhathastthoudone~24":"Rainha — Ai de mim, que fizeste?","hamletnayiknownotisittheking~etnayiknownotisittheking~28":"Hamlet — Não sei:\nera o rei?","queenowhatarashandbloodydeedisthis~arashandbloodydeedisthis~34":"Rainha — Oh, que ato temerário e sangrento!","hamletabloodydeedalmostasbadgoodmotheras~ngandmarrywithhisbrother~71":"Hamlet — Ato sangrento! Quase tão mau, boa mãe,\nquanto matar um rei e casar com o irmão dele.","queenaskillaking~queenaskillaking~16":"Rainha — Quanto matar um rei!","hamletayladytwasmywordliftsupthearrasand~ofandbulwarkagainstsense~327":"Hamlet — Sim, senhora, foi o que eu disse. Ergue a tapeçaria e descobre Polônio.\nTu, miserável, temerário, intrometido tolo, adeus!\nTomei-te por alguém melhor: toma o teu destino;\ndescobres que ser demasiado solícito tem seu perigo.\nDeixai de torcer as mãos: quieta! Sentai-vos,\ne deixai-me torcer-vos o coração; pois assim farei,\nse for feito de matéria penetrável,\nse o costume maldito não o tiver tão bronzeado\nque seja à prova e baluarte contra o sentimento.","queenwhathaveidonethatthoudarestwagthyto~ueinnoisesorudeagainstme~66":"Rainha — Que fiz eu, que ousas mover a língua\nem tão rude ruído contra mim?","hamletsuchanactthatblursthegraceandblush~oomisthoughtsickattheact~370":"Hamlet — Um ato tal\nque mancha a graça e o rubor do pudor,\nchama a virtude de hipócrita, tira a rosa\nda bela fronte de um amor inocente\ne ali põe uma bolha, faz os votos de casamento\ntão falsos quanto os juramentos de jogadores de dados: oh, um ato tal\nque do corpo do contrato arranca\na própria alma, e faz da doce religião\numa rapsódia de palavras: a face do céu enrubesce;\nsim, esta sólida massa composta,\nde semblante triste, como no dia do juízo,\nfica doente de pensar no ato.","queenaymewhatactthatroarssoloudandthunde~oudandthundersintheindex~52":"Rainha — Ai de mim, que ato,\nque ruge tão alto e troveja no prefácio?","hamletlookhereuponthispictureandonthisth~burnandreasonpanderswill~1191":"Hamlet — Olhai aqui, para este retrato e para este,\na imagem fingida de dois irmãos.\nVede que graça se assentava nesta fronte;\nos cachos de Hiperião; a fronte do próprio Jove;\num olho como o de Marte, para ameaçar e comandar;\numa postura como a do arauto Mercúrio\nrecém-pousado num monte que beija o céu;\numa combinação e uma forma, de fato,\nonde cada deus parecia pôr seu selo,\npara dar ao mundo a garantia de um homem:\neste era vosso marido. Vede agora o que segue:\naqui está vosso marido; como espiga mofada,\narruinando o irmão sadio. Tendes olhos?\nPudestes deixar de pastar nesta bela montanha\npara engordar neste pântano? Ha! Tendes olhos?\nNão podeis chamá-lo amor; pois na vossa idade\no ardor do sangue é manso, é humilde,\ne espera pelo juízo: e que juízo\ndesceria disto para isto? Sentidos, certo, tendes,\nou não poderíeis ter movimento; mas certo é que esse sentido\nestá paralisado; pois a loucura não erraria assim,\nnem o sentido jamais foi tão escravo do delírio\nque não reservasse alguma parcela de escolha\npara servir numa tal diferença. Que demônio foi\nque assim vos enganou na cabra-cega?\nOlhos sem tato, tato sem vista,\nouvidos sem mãos ou olhos, olfato sem tudo,\nou apenas uma parte doentia de um só sentido verdadeiro\nnão poderia assim estupidificar-se.\nOh, vergonha! Onde está teu rubor? Inferno rebelde,\nse podes amotinar-te nos ossos de uma matrona,\npara a juventude inflamada seja a virtude como cera\ne derreta em seu próprio fogo: não proclames vergonha\nquando o ardor compulsivo dá a carga,\npois o próprio gelo arde tão ativamente\ne a razão alcovita a vontade.","queenohamletspeaknomorethouturnstmineeye~aswillnotleavetheirtinct~115":"Rainha — Oh, Hamlet, não fales mais:\nvoltas meus olhos para dentro da minha própria alma;\ne ali vejo manchas tão negras e entranhadas\nque não largarão a sua tinta.","hamletnaybuttoliveintheranksweatofanense~akingloveoverthenastysty~100":"Hamlet — Não, mas viver\nno suor fétido de um leito engordurado,\ncozida em corrupção, a mimar e fazer amor\nsobre o sórdido chiqueiro—","queenospeaktomenomorethesewordslikedagge~ineearsnomoresweethamlet~74":"Rainha — Oh, não me fales mais;\nestas palavras, como punhais, entram em meus ouvidos;\nchega, doce Hamlet!","hamletamurdererandavillainaslavethatisno~stoleandputitinhispocket~178":"Hamlet — Um assassino e um vilão;\num escravo que não vale a vigésima parte do décimo\ndo vosso antecessor; um bufão dos reis;\num batedor de bolsas do império e do poder,\nque de uma prateleira roubou o precioso diadema\ne o meteu no bolso!","queennomore~queennomore~11":"Rainha — Chega!","hamletakingofshredsandpatches~takingofshredsandpatches~29":"Hamlet — Um rei de trapos e remendos—","savemeandhoveroermewithyourwingsyouheave~twouldyourgraciousfigure~76":"Salvai-me e pairai sobre mim com vossas asas,\nguardas celestiais! Que quer vossa graciosa figura?","queenalashesmad~queenalashesmad~15":"Rainha — Ai, ele está louco!","hamletdoyounotcomeyourtardysontochidetha~ngofyourdreadcommandosay~111":"Hamlet — Não vindes repreender vosso filho tardio,\nque, perdido no tempo e na paixão, deixa passar\na execução urgente de vosso temível comando?\nOh, dizei!","ghostdonotforgetthisvisitationisbuttowhe~estworksspeaktoherhamlet~180":"Espectro — Não esqueças: esta visita\né só para aguçar teu propósito quase embotado.\nMas olha, o assombro se assenta sobre tua mãe:\noh, interpõe-te entre ela e sua alma em luta:\na imaginação nos corpos mais fracos opera mais forte:\nfala-lhe, Hamlet.","hamlethowisitwithyoulady~hamlethowisitwithyoulady~24":"Hamlet — Como estais, senhora?","queenalashowistwithyouthatyoudobendyoure~patiencewhereondoyoulook~292":"Rainha — Ai, como estás tu,\nque fixas o olhar no vazio\ne com o ar incorpóreo manténs conversa?\nPor teus olhos teus espíritos espreitam selvagens;\ne, como soldados adormecidos no alarme,\nteus cabelos assentados, como vida em excrescências,\nsaltam e ficam em pé. Oh, gentil filho,\nsobre o calor e a chama da tua perturbação\nespalha fresca paciência. Para que olhas?","hamletonhimonhimlookyouhowpaleheglareshi~urtearsperchanceforblood~219":"Hamlet — Para ele, para ele! Vede como lívido ele fita!\nSua forma e sua causa juntas, pregando a pedras,\nas fariam compreender. Não olheis para mim;\npara que com esse gesto piedoso não converteis\nmeus severos intentos: então o que tenho a fazer\nperderá a verdadeira cor; lágrimas, talvez, em vez de sangue.","queentowhomdoyouspeakthis~ueentowhomdoyouspeakthis~25":"Rainha — A quem falas isso?","hamletdoyouseenothingthere~mletdoyouseenothingthere~26":"Hamlet — Não vedes nada ali?","queennothingatallyetallthatisisee~ingatallyetallthatisisee~33":"Rainha — Nada absolutamente; no entanto vejo tudo o que há.","hamletnordidyounothinghear~mletnordidyounothinghear~26":"Hamlet — Nem ouvistes nada?","queennonothingbutourselves~eennonothingbutourselves~26":"Rainha — Não, nada senão a nós mesmos.","hamletwhylookyoutherelookhowitstealsaway~woutattheportalexitghost~112":"Hamlet — Ora, olhai ali! Olhai como se esgueira!\nMeu pai, em seu traje como quando vivia!\nOlhai, lá vai ele, agora mesmo, pela porta! Sai o Espectro.","queenthistheverycoinageofyourbrainthisbo~onecstasyisverycunningin~76":"Rainha — Isto é pura cunhagem do teu cérebro:\nesta criação sem corpo o delírio\né muito hábil em fazer.","hamletecstasymypulseasyoursdothtemperate~ndwooforleavetodohimgood~568":"Hamlet — Delírio!\nMeu pulso, como o vosso, marca o compasso com temperança\ne faz música igualmente sadia: não é loucura\no que proferi: submetei-me à prova,\ne repetirei o assunto com as mesmas palavras; o que a loucura\nevitaria. Mãe, por amor da graça,\nnão ponhais na alma esse unguento lisonjeiro,\nde que não vossa transgressão, mas minha loucura fala:\napenas cobrirá de pele e película o lugar ulceroso,\nenquanto a corrupção podre, minando por dentro,\ninfecta sem ser vista. Confessai-vos ao céu;\narrependei-vos do passado; evitai o que vem;\ne não espalheis adubo sobre as ervas daninhas\npara torná-las mais viçosas. Perdoai-me esta minha virtude;\npois na gordura destes tempos obesos\na própria virtude deve pedir perdão ao vício,\nsim, curvar-se e suplicar licença para lhe fazer o bem.","queenohamletthouhastcleftmyheartintwain~uhastcleftmyheartintwain~39":"Rainha — Oh, Hamlet, partiste meu coração em dois.","hamletothrowawaytheworserpartofitandlive~ehindonewordmoregoodlady~773":"Hamlet — Oh, lançai fora a pior parte dele\ne vivei mais pura com a outra metade.\nBoa noite: mas não vades ao leito de meu tio;\nassumi uma virtude, se não a tendes.\nEsse monstro, o costume, que devora todo o sentimento,\ndemônio dos hábitos, é anjo ao menos nisto:\nque para o uso de ações belas e boas\ntambém dá uma veste ou libré\nque facilmente se põe. Abstende-vos esta noite,\ne isso emprestará certa facilidade\nà próxima abstinência: a seguinte mais fácil;\npois o hábito quase pode mudar o cunho da natureza\ne ou dominar o demônio, ou expulsá-lo\ncom maravilhosa potência. Mais uma vez, boa noite:\ne quando desejardes ser abençoada,\neu vos pedirei a bênção. Quanto a este senhor, Apontando para Polônio.\narrependo-me: mas o céu assim aprouve,\npunir-me com isto e isto comigo,\nde modo que eu seja o seu flagelo e ministro.\nEu o removerei e responderei bem\npela morte que lhe dei. Assim, de novo, boa noite.\nDevo ser cruel, só para ser bondoso:\nassim o mal começa e o pior fica por vir.\nUma palavra mais, boa senhora.","queenwhatshallido~queenwhatshallido~17":"Rainha — Que farei?","hamletnotthisbynomeansthatibidyoudoletth~pandbreakyourownneckdown~511":"Hamlet — Isto, de modo algum, que vos mando fazer:\ndeixai o rei inchado tentar-vos de novo ao leito;\nbeliscar-vos libertino a face; chamar-vos seu ratinho;\ne deixai que ele, por um par de beijos fedidos,\nou por mexer-vos o pescoço com seus dedos malditos,\nvos faça desenrolar todo este assunto,\nque não estou de fato em loucura,\nmas louco por astúcia. Seria bom que o soubesse;\npois quem, sendo apenas rainha, bela, sóbria, sábia,\nesconderia de um sapo, de um morcego, de um gato velho\ncoisas de tão caro interesse? Quem o faria?\nNão, a despeito do bom senso e do segredo,\nabri o cesto no alto da casa,\ndeixai os pássaros voar e, como o famoso macaco,\npara fazer a experiência, entrai rastejando no cesto\ne quebrai vosso próprio pescoço na queda.","queenbethouassuredifwordsbemadeofbreatha~athewhatthouhastsaidtome~94":"Rainha — Fica certo de que, se palavras são feitas de sopro,\ne o sopro de vida, não tenho vida para soprar\no que me disseste.","hamletimusttoenglandyouknowthat~musttoenglandyouknowthat~31":"Hamlet — Devo ir à Inglaterra; sabeis disso?","queenalackihadforgottissoconcludedon~adforgottissoconcludedon~36":"Rainha — Ai,\neu esquecera: assim ficou decidido.","hamlettheresletterssealdandmytwoschoolfe~hamletdragginginpolonius~555":"Hamlet — Há cartas seladas: e meus dois colegas de escola,\nem quem confiarei como em víboras de presas,\nlevam o mandado; devem varrer meu caminho\ne conduzir-me à velhacaria. Que funcione;\npois é o divertimento ver o engenheiro\nlançado pelo ar com a própria bomba: e será duro\nse eu não cavar uma jarda abaixo das minas deles\ne os fizer voar até a lua: oh, é doçura suprema\nquando, numa só linha, dois ardis se encontram de frente.\nEste homem me fará partir:\narrastarei as entranhas para a sala vizinha.\nMãe, boa noite. Na verdade, este conselheiro\nestá agora quietíssimo, secretíssimo e gravíssimo,\nele que em vida foi um tolo e tagarela velhaco.\nVamos, senhor, para pôr fim a vós.\nBoa noite, mãe. Saem separadamente; Hamlet arrastando Polônio."}$tr$::jsonb, 755)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- william-shakespeare_henry-v (198 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_henry-v', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"prologue":"Prólogo","acti":"Ato I","actii":"Ato II"}$tr$::jsonb, $tr${"enterchorus~enterchorus~11":"Entra o CORO.","chorusoforamuseoffirethatwouldascendtheb~kindlytojudgeourplayexit~1140":"CORO — Ó, por uma Musa de fogo, que ascendesse\nAo mais luminoso céu da invenção,\nUm reino por palco, príncipes por atores\nE monarcas por testemunhas da cena grandiosa!\nEntão o guerreiro Henrique, qual ele mesmo,\nTomaria o porte de Marte; e a seus calcanhares,\nPresos como cães de caça, a fome, a espada e o fogo\nAgachar-se-iam, à espera de serviço. Mas perdão, nobres senhores,\nPelos espíritos rasteiros e sem altura que ousaram\nTrazer a este tablado indigno\nTão grande assunto: pode este rinque de rinhas conter\nOs vastos campos da França? Ou podemos nós apertar\nNeste O de madeira os próprios elmos\nQue espantaram o ar em Azincourt?\nÓ, perdão! Pois um algarismo torto pode\nAtestar em pouco espaço um milhão;\nE deixai que nós, zeros dessa grande conta,\nAtuemos sobre as vossas forças imaginárias.\nSuponde que dentro do cinto destes muros\nEstão agora confinadas duas poderosas monarquias,\nCujas frontes altaneiras, contíguas,\nO perigoso e estreito oceano separa:\nCompletai nossas imperfeições com vossos pensamentos;\nDividi um só homem em mil partes\nE criai um poder imaginário;\nPensai, quando falarmos de cavalos, que os vedes\nImprimindo seus orgulhosos cascos na terra que os recebe;\nPois são vossos pensamentos que agora devem adornar nossos reis,\nLevá-los daqui para ali; saltando sobre os tempos,\nTransformando a realização de muitos anos\nNuma ampulheta: para o que suprir,\nAdmiti-me, o Coro, a esta história;\nQue, à maneira de prólogo, rogo à vossa humilde paciência\nQue ouça com brandura, julgue com bondade a nossa peça. Sai.","scenei~scenei~6":"Cena I","londonanantechamberinthekingspalace~echamberinthekingspalace~35":"Londres. Uma antecâmara no palácio do Rei.","enterthearchbishopofcanterburyandthebish~terburyandthebishopofely~47":"Entram o Arcebispo de Cantuária e o Bispo de Ely.","canterburymylordilltellyouthatselfbillis~shitoutoffartherquestion~181":"Cantuária — Meu senhor, vou dizer-vos: insiste-se naquele mesmo projeto de lei,\nque no décimo primeiro ano do reinado do último rei\nesteve prestes a passar, e de fato teria passado contra nós,\nnão fosse o tumulto e a inquietação dos tempos\nque o empurraram para fora de maior exame.","elybuthowmylordshallweresistitnow~mylordshallweresistitnow~33":"Ely — Mas como, meu senhor, haveremos de resistir-lhe agora?","canterburyitmustbethoughtonifitpassagain~bytheyearthusrunsthebill~462":"Cantuária — É preciso pensar nisso. Se passar contra nós,\nperdemos a melhor metade do que possuímos:\npois todas as terras temporais que homens devotos\npor testamento deram à Igreja\nquereriam tirar-nos; avaliadas assim:\no bastante para manter, em honra do Rei,\nquinze condes completos e quinze centenas de cavaleiros,\nseis mil e duzentos bons escudeiros;\ne, para socorro dos leprosos e da velhice fraca,\ndas almas indigentes e desfalecidas, incapazes de labor do corpo,\ncem asilos muito bem providos;\ne, além disso, para os cofres do Rei,\nmil libras por ano: assim reza o projeto.","elythiswoulddrinkdeep~elythiswoulddrinkdeep~21":"Ely — Isso beberia fundo.","canterburytwoulddrinkthecupandall~ytwoulddrinkthecupandall~33":"Cantuária — Beberia o cálice e tudo.","elybutwhatprevention~elybutwhatprevention~20":"Ely — Mas que prevenção?","canterburythekingisfullofgraceandfairreg~fullofgraceandfairregard~43":"Cantuária — O Rei é cheio de graça e de bom critério.","elyandatrueloveroftheholychurch~trueloveroftheholychurch~31":"Ely — E verdadeiro amigo da santa Igreja.","canterburythecoursesofhisyouthpromisedit~andallatonceasinthisking~432":"Cantuária — O curso de sua juventude não o prometia.\nMal o sopro deixou o corpo de seu pai,\nsua licenciosidade, mortificada nele,\npareceu morrer também; sim, naquele exato momento\na reflexão, como um anjo, veio\ne açoitou para fora dele o Adão ofensor,\ndeixando-lhe o corpo como um paraíso,\npara envolver e conter espíritos celestes.\nNunca se fez tão súbito estudioso;\nnunca veio reforma em tal torrente,\ncom tão impetuosa correnteza, a lavar as faltas;\nnem jamais teimosia de cabeça de Hidra\ntão cedo e de uma vez perdeu seu assento\ncomo neste rei.","elyweareblessedinthechange~yweareblessedinthechange~26":"Ely — Somos abençoados pela mudança.","canterburyhearhimbutreasonindivinityanda~mopenhauntsandpopularity~717":"Cantuária — Ouvi-o apenas raciocinar em teologia,\ne, tomado de admiração, com um voto íntimo\ndesejaríeis que o rei se fizesse prelado;\nouvi-o debater os negócios do Estado,\ndiríeis que fora todo o seu estudo;\nescutai seu discurso sobre a guerra, e ouvireis\numa batalha temível reproduzida em música;\nvoltai-o para qualquer causa de governo,\ne o nó górdio dela ele desatará,\ntão familiar como sua liga: de modo que, quando fala,\no ar, libertino privilegiado, silencia,\ne o mudo espanto espreita nos ouvidos dos homens\npara furtar-lhe as doces e melífluas sentenças;\nde modo que a arte e a parte prática da vida\ndevem ser a mestra desta teoria:\no que é maravilha como Sua Graça a pôde colher,\nvisto que seu pendor era por passatempos vãos,\nsuas companhias iletradas, rudes e rasas,\nsuas horas preenchidas de bagunças, banquetes, folguedos,\ne jamais se notou nele qualquer estudo,\nqualquer retiro, qualquer afastamento\ndos antros públicos e da popularidade.","elythestrawberrygrowsunderneaththenettle~nyetcresciveinhisfaculty~245":"Ely — O morango cresce debaixo da urtiga,\ne as bagas sadias prosperam e amadurecem melhor\nvizinhas de frutos de qualidade mais baixa:\ne assim o príncipe obscureceu sua contemplação\nsob o véu da licenciosidade; a qual, sem dúvida,\ncresceu como a relva de verão, mais depressa de noite,\ninvisível, mas crescendo em sua faculdade.","canterburyitmustbesoformiraclesareceased~anshowthingsareperfected~97":"Cantuária — Deve ser assim; pois os milagres cessaram;\ne portanto temos de admitir os meios\npelos quais as coisas se aperfeiçoam.","elybutmygoodlordhownowformitigationofthi~ismajestyinclinetoitorno~91":"Ely — Mas, meu bom senhor,\ne quanto à mitigação deste projeto\ninsistido pelos comuns? Sua Majestade\ninclina-se a ele, ou não?","canterburyheseemsindifferentorrathersway~ispredecessorspartwithal~304":"Cantuária — Mostra-se indiferente,\nou antes pendendo mais para o nosso lado\ndo que favorecendo os proponentes contra nós;\npois fiz uma oferta a Sua Majestade,\nem nossa convocação espiritual,\ne em atenção às causas agora em curso,\nque expus a Sua Graça por inteiro,\nrelativas à França, de dar uma soma maior\ndo que jamais de uma só vez o clero\ncedeu a seus predecessores.","elyhowdidthisofferseemreceivedmylord~sofferseemreceivedmylord~36":"Ely — Como pareceu recebida essa oferta, meu senhor?","canterburywithgoodacceptanceofhismajesty~dwardhisgreatgrandfather~251":"Cantuária — Com boa acolhida de Sua Majestade;\nsalvo que não houve tempo bastante para ouvir,\ncomo percebi que Sua Graça de bom grado faria,\nas particularidades e os trâmites claros\nde seus verdadeiros títulos a certos ducados\ne em geral à coroa e ao trono da França,\nderivados de Eduardo, seu bisavô.","elywhatwastheimpedimentthatbrokethisoff~pedimentthatbrokethisoff~39":"Ely — Que impedimento interrompeu isso?","canterburythefrenchambassadoruponthatins~himhearingisitfouroclock~110":"Cantuária — O embaixador francês, naquele instante,\npediu audiência; e a hora, penso, chegou\nde lhe dar ouvidos: são quatro horas?","elyitis~elyitis~7":"Ely — São.","canterburythengoweintoknowhisembassywhic~efrenchmanspeakawordofit~101":"Cantuária — Então entremos, para saber de sua embaixada;\nque eu poderia declarar com palpite certeiro\nantes que o francês dissesse palavra dela.","elyillwaituponyouandilongtohearitexeunt~ouandilongtohearitexeunt~39":"Ely — Acompanho-vos, e anseio por ouvi-la. Saem.","sceneii~sceneii~7":"Cena II","thesamethepresencechamber~hesamethepresencechamber~25":"O mesmo lugar. A sala de audiência.","enterkinghenrygloucesterbedfordexeterwar~estmorelandandattendants~69":"Entram o Rei Henrique, Gloucester, Bedford, Exeter, Warwick, Westmoreland e Séquito.","kinghenrywhereismygraciouslordofcanterbu~graciouslordofcanterbury~42":"Rei Henrique — Onde está meu gracioso Senhor de Cantuária?","exeternothereinpresence~exeternothereinpresence~23":"Exeter — Não está aqui presente.","kinghenrysendforhimgooduncle~henrysendforhimgooduncle~28":"Rei Henrique — Mandai chamá-lo, bom tio.","westmorelandshallwecallintheambassadormy~llintheambassadormyliege~45":"Westmoreland — Devemos chamar o embaixador, meu soberano?","kinghenrynotyetmycousinwewouldberesolved~htsconcerningusandfrance~115":"Rei Henrique — Ainda não, meu primo: queremos ser esclarecidos,\nantes de ouvi-lo, de algumas coisas de peso\nque ocupam nossos pensamentos, a respeito de nós e da França.","canterburygodandhisangelsguardyoursacred~neandmakeyoulongbecomeit~68":"Cantuária — Que Deus e seus anjos guardem vosso sagrado trono\ne vos façam longamente digno dele!","kinghenrysurewethankyoumylearnedlordwepr~hdaspureassinwithbaptism~839":"Rei Henrique — Certamente, agradecemos.\nMeu douto senhor, rogamos-vos que prossigais\ne, com justiça e religião, exponhais\npor que a lei sálica que eles têm na França\ndeve ou não deve impedir-nos em nossa pretensão:\ne Deus não permita, meu caro e fiel senhor,\nque molde, torça ou dobre a vossa leitura,\nou onere sutilmente vossa alma entendida\nao abrir títulos mal engendrados, cujo direito\nnão condiz em suas cores naturais com a verdade;\npois Deus sabe quantos, agora em saúde,\nderramarão o sangue em aprovação\ndaquilo a que vossa reverência nos incitar.\nPortanto, cuidai como empenhais a nossa pessoa,\ncomo despertais nossa espada de guerra adormecida:\nordenamos-vos, em nome de Deus, cuidado;\npois jamais dois reinos tais disputaram\nsem muita queda de sangue; cujas gotas inocentes\nsão cada uma um infortúnio, uma queixa dolorosa\ncontra aquele cujos agravos dão fio às espadas\nque fazem tal desperdício da breve mortalidade.\nSob este conjuro falai, meu senhor;\npois ouviremos, notaremos e creremos de coração\nque o que falardes está em vossa consciência lavado,\npuro como o pecado pelo batismo.","canterburythenhearmegracioussovereignand~romyouandyourprogenitors~2153":"Cantuária — Então ouvi-me, gracioso soberano, e vós, pares,\nque deveis a vós mesmos, vossas vidas e serviços\na este trono imperial. Não há impedimento\na opor à pretensão de Vossa Alteza à França\nsenão este, que eles apresentam de Faramundo,\n“In terram Salicam mulieres ne succedant”:\n“Nenhuma mulher sucederá em terra sálica”:\na qual terra sálica os franceses injustamente glosam\ncomo sendo o reino da França, e Faramundo\no fundador desta lei e exclusão feminina.\nContudo os seus próprios autores afirmam fielmente\nque a terra sálica está na Alemanha,\nentre os rios Sala e Elba;\nonde Carlos Magno, tendo subjugado os saxões,\ndeixou e estabeleceu certos franceses;\nos quais, desdenhando as mulheres alemãs\npor alguns costumes desonestos de sua vida,\nestabeleceram então esta lei: a saber, nenhuma fêmea\nseria herdeira em terra sálica:\na qual terra sálica, como eu disse, entre Elba e Sala,\nchama-se hoje na Alemanha Meissen.\nEntão bem se vê que a lei sálica\nnão foi concebida para o reino da França;\nnem os franceses possuíram a terra sálica\naté quatrocentos e vinte e um anos\ndepois do falecimento do rei Faramundo,\nvãmente suposto fundador desta lei;\nque morreu no ano da nossa redenção\nde quatrocentos e vinte e seis; e Carlos Magno\nsubjugou os saxões e assentou os franceses\nalém do rio Sala, no ano\nde oitocentos e cinco. Além disso, dizem seus escritores,\no rei Pepino, que depôs Childerico,\ncomo herdeiro geral, sendo descendente\nde Blithild, que era filha do rei Clotário,\nfez pretensão e título à coroa da França.\nHugo Capeto também, que usurpou a coroa\nde Carlos, duque de Lorena, único herdeiro varão\nda verdadeira linha e estirpe de Carlos Magno,\npara achar seu título com algumas aparências de verdade,\nembora, em pura verdade, fosse corrupto e nulo,\napresentou-se como herdeiro da Senhora Lingare,\nfilha de Carlos Magno, que era filho\nde Luís, o imperador, e Luís filho\nde Carlos Magno. Também o rei Luís Décimo,\nque era único herdeiro do usurpador Capeto,\nnão pôde ter sossego na consciência,\nusando a coroa da França, até se satisfazer\nde que a bela rainha Isabel, sua avó,\nera descendente direta da Senhora Ermengare,\nfilha de Carlos, o dito duque de Lorena:\npelo qual casamento a linha de Carlos Magno\nfoi reunida à coroa da França.\nDe modo que, tão claro como o sol de verão,\no título do rei Pepino e a pretensão de Hugo Capeto,\na satisfação do rei Luís, tudo parece\nsustentar-se em direito e título da parte feminina:\nassim fazem os reis da França até hoje;\nnão obstante queiram erguer esta lei sálica\npara impedir Vossa Alteza de reclamar pela linha feminina,\ne prefiram esconder-se numa rede\na dar amplo impedimento a seus títulos tortos,\nusurpados de vós e de vossos progenitores.","kinghenrymayiwithrightandconsciencemaket~dconsciencemakethisclaim~48":"Rei Henrique — Posso, com direito e consciência, fazer esta pretensão?","canterburythesinuponmyheaddreadsovereign~utofworkandcoldforaction~605":"Cantuária — O pecado recaia sobre minha cabeça, temido soberano!\nPois no Livro dos Números está escrito:\nquando o homem morrer, que a herança\npasse à filha. Gracioso senhor,\nlevantai-vos pelo que é vosso; desfraldai vossa bandeira sangrenta;\nvoltai o olhar a vossos poderosos antepassados:\nide, meu temido senhor, ao túmulo de vosso bisavô,\nde quem reclamais; invocai seu espírito guerreiro,\ne o de vosso tio-avô, Eduardo, o Príncipe Negro,\nque em solo francês representou uma tragédia,\ndesbaratando todo o poderio da França,\nenquanto seu poderosíssimo pai, sobre um monte,\nficava sorrindo a ver o filhote de seu leão\nforragear no sangue da nobreza francesa.\nOh, nobres ingleses, que puderam enfrentar\ncom metade de suas forças todo o orgulho da França\ne deixar a outra metade a rir ao lado,\ntoda sem serviço e fria de ação!","elyawakeremembranceofthesevaliantdeadand~oitsandmightyenterprises~246":"Ely — Despertai a memória desses valentes mortos\ne com vosso braço potente renovai seus feitos:\nsois herdeiro deles; sentais-vos em seu trono;\no sangue e a coragem que os tornaram renomados\ncorrem em vossas veias; e meu três vezes poderoso soberano\nestá na própria manhã de maio de sua juventude,\nmaduro para proezas e poderosas empresas.","exeteryourbrotherkingsandmonarchsoftheea~heformerlionsofyourblood~110":"Exeter — Vossos irmãos reis e monarcas da terra\ntodos esperam que vos ergais,\ncomo fizeram os leões anteriores do vosso sangue.","westmorelandtheyknowyourgracehathcausean~liondinthefieldsoffrance~202":"Westmoreland — Sabem que Vossa Graça tem causa, meios e força;\nassim os tem Vossa Alteza; nunca rei da Inglaterra\nteve nobres mais ricos e súditos mais leais,\ncujos corações deixaram os corpos aqui na Inglaterra\ne jazem acampados nos campos da França.","canterburyolettheirbodiesfollowmydearlie~ngintoanyofyourancestors~200":"Cantuária — Oh, que os corpos os sigam, meu caro soberano,\ncom sangue, espada e fogo, para ganhar vosso direito;\nem auxílio do que nós, do estado espiritual,\nlevantaremos para Vossa Alteza soma tão grande\ncomo nunca o clero de uma só vez\ntrouxe a qualquer de vossos antepassados.","kinghenrywemustnotonlyarmtoinvadethefren~duponuswithalladvantages~126":"Rei Henrique — Não devemos apenas armar-nos para invadir os franceses,\nmas dispor nossas proporções para defender\ncontra o escocês, que fará incursão sobre nós\ncom todas as vantagens.","canterburytheyofthosemarchesgracioussove~romthepilferingborderers~109":"Cantuária — Os habitantes dessas marcas, gracioso soberano,\nserão muralha suficiente para defender\nnosso interior dos saqueadores da fronteira.","kinghenrywedonotmeanthecoursingsnatchers~ledattheillneighbourhood~429":"Rei Henrique — Não nos referimos só aos assaltantes de correria,\nmas tememos o principal intento do escocês,\nque sempre foi um vizinho volúvel para nós;\npois lereis que meu bisavô\nnunca foi com suas forças à França\nsem que o escocês sobre seu reino desguarnecido\nviesse derramando-se, como a maré numa brecha,\ncom ampla e transbordante plenitude de sua força,\nfustigando a terra já respigada com ataques ardentes,\ncingindo com cerco penoso castelos e cidades;\nde modo que a Inglaterra, vazia de defesa,\ntremeu e estremeceu com a má vizinhança.","canterburyshehathbeenthenmorefeardthanha~reckandsumlesstreasuries~378":"Cantuária — Foi então mais temida que ferida, meu soberano;\npois ouvi-a apenas exemplificada por si mesma:\nquando toda a sua cavalaria esteve na França\ne ela, viúva enlutada de seus nobres,\nnão só se defendeu bem\ncomo tomou e encurralou, qual animal extraviado,\no Rei dos Escoceses; a quem enviou à França,\npara encher a fama do rei Eduardo de reis prisioneiros\ne tornar sua crônica tão rica de louvor\nquanto o lodo e o fundo do mar\nde naufrágios afundados e tesouros incontáveis.","westmorelandbuttheresasayingveryoldandtr~ndhavocmorethanshecaneat~255":"Westmoreland — Mas há um dito muito antigo e verdadeiro:\n“Se queres a França ganhar,\npela Escócia hás de começar”:\npois, uma vez que a águia Inglaterra está na caça,\nao seu ninho desguarnecido o escocês-doninha\nvem se esgueirando e assim suga os seus ovos principescos,\nfazendo de rato na ausência do gato,\npara rasgar e devastar mais do que possa comer.","exeteritfollowsthenthecatmuststayathomey~andnaturalcloselikemusic~320":"Exeter — Segue-se então que o gato deve ficar em casa:\ncontudo essa é uma necessidade esmagada,\npois temos fechaduras para guardar o necessário\ne belas armadilhas para pegar os ladrões miúdos.\nEnquanto a mão armada luta no estrangeiro,\na cabeça avisada se defende em casa;\npois o governo, embora alto, baixo e mais baixo,\ndividido em partes, mantém-se em um só acordo,\nconcordando num final pleno e natural,\ncomo a música.","canterburythereforedothheavendividethest~nameofhardinessandpolicy~1227":"Cantuária — Por isso o céu divide\no estado do homem em diversas funções,\npondo o esforço em contínuo movimento;\nao qual se fixa, como alvo ou meta,\na obediência: assim trabalham as abelhas,\ncriaturas que por uma regra da natureza ensinam\no ato da ordem a um reino povoado.\nTêm um rei e oficiais de várias espécies;\nonde alguns, como magistrados, corrigem em casa,\noutros, como mercadores, aventuram comércio no estrangeiro,\noutros, como soldados, armados de seus ferrões,\nfazem saque sobre os botões aveludados do verão,\no qual despojo levam, em alegre marcha, para casa,\nà tenda real de seu imperador;\no qual, ocupado em sua majestade, observa\nos pedreiros cantantes a construir tetos de ouro,\nos cidadãos civis a amassar o mel,\nos pobres carregadores mecânicos a apinhar\nsuas pesadas cargas em seu estreito portão,\no juiz de olhos tristes, com seu zumbido rabugento,\na entregar a pálidos executores\no zangão preguiçoso e bocejante. Disto infiro\nque muitas coisas, tendo plena referência\na um só acordo, podem operar contrariamente:\ncomo muitas flechas, soltas por vários rumos,\nchegam a um só alvo; como muitos caminhos se encontram numa cidade;\ncomo muitos riachos frescos se encontram num só mar salgado;\ncomo muitas linhas se fecham no centro do mostrador;\nassim muitos milhares de ações, uma vez em marcha,\nterminam num só propósito, e todas bem levadas\nsem derrota. Portanto, à França, meu soberano.\nDividi vossa ditosa Inglaterra em quatro;\ndos quais levai um quarto à França,\ne com isso fareis tremer toda a Gália.\nSe nós, com três vezes tais forças deixadas em casa,\nnão pudermos defender nossas portas do cão,\nque sejamos mordidos e perca nossa nação\no nome de ousadia e prudência.","kinghenrycallinthemessengerssentfromthed~rshippdwithawaxenepitaph~463":"Rei Henrique — Chamai os mensageiros enviados pelo Delfim. Saem alguns do Séquito.\nAgora estamos bem resolvidos; e, com a ajuda de Deus\ne a vossa, nobres nervos de nosso poder,\nsendo a França nossa, a dobraremos ao nosso respeito,\nou a quebraremos toda em pedaços: ou ali nos sentaremos,\ngovernando em largo e amplo império\nsobre a França e todos os seus ducados quase régios,\nou deporemos estes ossos numa urna indigna,\nsem túmulo, sem lembrança sobre eles:\nou nossa história, de boca cheia,\nfalará livremente de nossos feitos, ou então nossa sepultura,\ncomo mudo turco, terá boca sem língua,\nnão honrada com epitáfio de cera.","enterambassadorsoffrance~enterambassadorsoffrance~24":"Entram os Embaixadores da França.","nowarewewellpreparedtoknowthepleasureofo~gisfromhimnotfromtheking~103":"Agora estamos bem preparados para saber a vontade\nde nosso belo primo Delfim; pois ouvimos\nque vossa saudação é dele, não do rei.","firstambassadormaytpleaseyourmajestytogi~hinsmeaningandourembassy~143":"Primeiro Embaixador — Se aprouver a Vossa Majestade dar-nos licença\npara transmitir livremente o que temos a cargo;\nou devemos mostrar-vos com parcimônia, de longe,\no sentido do Delfim e nossa embaixada?","kinghenrywearenotyrantbutachristiankingu~esstellusthedauphinsmind~172":"Rei Henrique — Não somos tirano, mas rei cristão;\na cuja graça nossa paixão é tão sujeita\nquanto nossos desgraçados acorrentados em nossas prisões:\nportanto, com franca e desenfreada clareza,\ndizei-nos o pensamento do Delfim.","ambassadorthustheninfewyourhighnesslatel~fyouthisthedauphinspeaks~450":"Embaixador — Assim, pois, em poucas palavras.\nVossa Alteza, enviando há pouco à França,\nreclamou certos ducados, no direito\nde vosso grande predecessor, o rei Eduardo Terceiro.\nEm resposta a essa pretensão, o príncipe nosso senhor\ndiz que cheirais demais à vossa juventude,\ne manda que saibais que nada há na França\nque se possa ganhar com uma ágil galharda;\nnão podeis folgar até ganhar ducados ali.\nEnvia-vos, portanto, mais condizente com vosso espírito,\neste tonel de tesouro; e, em troca disso,\ndeseja que deixeis os ducados que reclamais\nnão ouvirem mais de vós. Isto fala o Delfim.","kinghenrywhattreasureuncle~nghenrywhattreasureuncle~26":"Rei Henrique — Que tesouro, tio?","exetertennisballsmyliege~exetertennisballsmyliege~24":"Exeter — Bolas de tênis, meu soberano.","kinghenrywearegladthedauphinissopleasant~youwellexeuntambassadors~1386":"Rei Henrique — Folgamos que o Delfim seja tão gracejador conosco;\nagradecemos-vos o presente e o vosso trabalho:\nquando tivermos ajustado nossas raquetes a estas bolas,\njogaremos, na França, com a graça de Deus, uma partida\nque lançará a coroa de seu pai ao azar.\nDizei-lhe que fez uma aposta com tal brigão\nque todas as quadras da França serão perturbadas\npor jogadas. E o entendemos bem,\ncomo vem sobre nós com nossos dias mais soltos,\nsem medir que uso deles fizemos.\nNunca estimamos este pobre trono da Inglaterra;\ne por isso, vivendo longe dele, entregamo-nos\na bárbara licença; como é sempre comum\nque os homens sejam mais alegres quando longe de casa.\nMas dizei ao Delfim que manterei meu estado,\nserei como rei e mostrarei a vela da minha grandeza\nquando me erguer em meu trono da França:\npois que pus de lado minha majestade\ne labutei como homem de dias de trabalho,\nmas ali me erguerei com glória tão plena\nque ofuscarei todos os olhos da França,\nsim, cegarei o Delfim ao olhar para nós.\nE dizei ao gracejador príncipe que este seu escárnio\nconverteu suas bolas em balas de canhão; e sua alma\nresponderá duramente pela vingança desperdiçadora\nque voará com elas: pois muitos milhares de viúvas\neste seu escárnio escarnecerá de seus caros maridos;\nescarnecerá mães de seus filhos, castelos abaixo;\ne alguns ainda nem foram gerados nem nasceram\nque terão causa de maldizer o desdém do Delfim.\nMas tudo isto jaz na vontade de Deus,\na quem apelo; e em cujo nome\ndizei ao Delfim que avanço,\npara vingar-me como puder e estender\nminha mão legítima numa causa bem consagrada.\nAssim, ide em paz; e dizei ao Delfim\nque seu gracejo cheirará apenas a engenho raso,\nquando milhares chorarem mais do que riram dele.\nConduzi-os com salvo-conduto. Passai bem. Saem os Embaixadores.","exeterthiswasamerrymessage~eterthiswasamerrymessage~26":"Exeter — Foi uma mensagem alegre.","kinghenrywehopetomakethesenderblushatitt~tbebroughtexeuntflourish~445":"Rei Henrique — Esperamos fazer o remetente corar com ela.\nPortanto, meus senhores, não percais hora propícia\nque possa dar impulso à nossa expedição;\npois não temos agora pensamento em nós senão a França,\nsalvo os que a Deus, que vêm antes de nossos negócios.\nPortanto, que nossas proporções para estas guerras\nsejam logo reunidas e tudo seja pensado\nque possa, com razoável presteza, acrescentar\nmais penas às nossas asas; pois, com Deus à frente,\nrepreenderemos este Delfim à porta de seu pai.\nPortanto, que cada homem agora exercite o pensamento,\npara que esta bela ação seja posta em marcha. Saem. Toque de trombetas.","prologue~prologue~8":"Prólogo","flourishenterchorus~flourishenterchorus~19":"Toque de trombetas. Entra o Coro.","chorusnowalltheyouthofenglandareonfirean~tondoweshiftoursceneexit~1438":"Coro — Agora toda a juventude da Inglaterra está em chamas,\ne o ócio de seda jaz no guarda-roupa:\nagora prosperam os armeiros, e o pensamento da honra\nreina sozinho no peito de todo homem:\nvendem agora o pasto para comprar o cavalo,\nseguindo o espelho de todos os reis cristãos,\ncom calcanhares alados, como Mercúrios ingleses.\nPois agora se assenta a Expectativa no ar\ne esconde uma espada, do punho até a ponta,\nsob coroas imperiais, coroas e coronetas,\nprometidas a Harry e seus seguidores.\nOs franceses, avisados por boa informação\ndesse tão terrível preparativo,\ntremem de medo e, com pálida astúcia,\nprocuram desviar os propósitos ingleses.\nÓ Inglaterra! Modelo da tua grandeza interior,\ncomo corpo pequeno com um coração poderoso,\nque não poderias fazer, o que a honra te faria fazer,\nse todos os teus filhos fossem leais e naturais!\nMas vê a tua falta! A França achou em ti\num ninho de peitos ocos, que ela enche\nde coroas traiçoeiras; e três homens corrompidos,\num, Ricardo, Conde de Cambridge, e o segundo,\nHenrique, Lorde Scroop de Masham, e o terceiro,\nSir Thomas Grey, cavaleiro, de Northumberland,\npor ouro da França—oh, culpa de fato!—\nconfirmaram conspiração com a temível França;\ne por suas mãos este primor dos reis deve morrer,\nse o inferno e a traição cumprirem suas promessas,\nantes de tomar navio para a França, em Southampton.\nAlongai vossa paciência; e digeriremos\no abuso da distância; forçamos uma peça:\na soma está paga; os traidores estão de acordo;\no rei partiu de Londres; e a cena\né agora transportada, gentis senhores, para Southampton.\nAli é agora o teatro, ali deveis sentar-vos:\ne de lá à França vos conduziremos em segurança\ne vos traremos de volta, encantando os mares estreitos\npara vos dar gentil passagem; pois, se pudermos,\nnão ofenderemos um só estômago com a nossa peça.\nMas, até que o rei saia, e não antes,\npara Southampton mudamos nossa cena. Sai.","londonastreet~londonastreet~13":"Londres. Uma rua.","entercorporalnymandlieutenantbardolph~nymandlieutenantbardolph~37":"Entram o Cabo Nym e o Tenente Bardolph.","bardolphwellmetcorporalnym~rdolphwellmetcorporalnym~26":"Bardolph — Bem encontrado, Cabo Nym.","nymgoodmorrowlieutenantbardolph~morrowlieutenantbardolph~31":"Nym — Bom dia, Tenente Bardolph.","bardolphwhatareancientpistolandyoufriend~ntpistolandyoufriendsyet~44":"Bardolph — Ora, o Alferes Pistol e vós já sois amigos?","nymformyparticarenotisaylittlebutwhentim~sswordwillandtheresanend~232":"Nym — Por mim, não me importo: falo pouco; mas quando chegar a ocasião, haverá sorrisos; mas isso será como for. Não ouso lutar; mas piscarei o olho e estenderei meu ferro: é um ferro simples; mas que importa? Serve para tostar queijo e aguenta o frio como a espada de qualquer outro homem; e fim de conversa.","bardolphiwillbestowabreakfasttomakeyoufr~letitbesogoodcorporalnym~107":"Bardolph — Pagarei um desjejum para fazer-vos amigos; e seremos os três irmãos de juramento rumo à França: que seja assim, bom Cabo Nym.","nymfaithiwilllivesolongasimaythatsthecer~tthatistherendezvousofit~123":"Nym — Na verdade, viverei enquanto puder, isso é certo; e quando não puder mais viver, farei como puder: esse é o meu fim, esse é o ponto de encontro disso.","bardolphitiscertaincorporalthatheismarri~ryouweretrothplighttoher~107":"Bardolph — É certo, cabo, que ele casou com Nell Quickly; e certamente ela vos fez injustiça; pois éreis noivo prometido dela.","nymicannottellthingsmustbeastheymaymenma~nclusionswellicannottell~208":"Nym — Não sei dizer: as coisas hão de ser como puderem: os homens podem dormir, e podem ter as gargantas consigo nessa hora; e alguns dizem que as facas têm fio. Há de ser como for: embora a paciência seja égua cansada, ainda assim ela segue a passo. É preciso haver conclusões. Bem, não sei dizer.","enterpistolandhostess~enterpistolandhostess~21":"Entram Pistol e a Hospedeira.","bardolphherecomesancientpistolandhiswife~herehownowminehostpistol~85":"Bardolph — Aí vem o Alferes Pistol e sua mulher: bom cabo, tende paciência aqui. Então, meu anfitrião Pistol!","pistolbasetikecallstthoumehostnowbythish~orshallmynellkeeplodgers~87":"Pistol — Vil cão, chamas-me anfitrião?\nAgora, por esta mão, juro, desprezo o termo;\nnem minha Nell terá hóspedes.","hostessnobymytrothnotlongforwecannotlodg~ulteryandmurdercommitted~247":"Hospedeira — Não, por minha fé, não por muito tempo; pois não podemos alojar e dar pensão a uma dúzia ou catorze gentis damas que vivem honestamente da picada de suas agulhas sem que logo se pense que mantemos um bordel. Nym e Pistol sacam as espadas. Ai, que dia, Senhora, se ele não sacou agora! Veremos adultério voluntário e assassinato cometidos.","bardolphgoodlieutenantgoodcorporaloffern~corporaloffernothinghere~50":"Bardolph — Bom tenente! Bom cabo! Nada de ataques aqui.","nympish~nympish~7":"Nym — Bah!","pistolpishfortheeicelanddogthouprickeard~houprickeardcuroficeland~52":"Pistol — Bah para ti, cão da Islândia! Cachorro de orelha em pé da Islândia!","hostessgoodcorporalnymshowthyvalourandpu~yvalourandputupyoursword~52":"Hospedeira — Bom Cabo Nym, mostra tua valentia e guarda a espada.","nymwillyoushogoffiwouldhaveyousolus~hogoffiwouldhaveyousolus~35":"Nym — Quereis ir andando? Quero-vos a sós.","pistolsolusegregiousdogovipervilethesolu~ndflashingfirewillfollow~248":"Pistol — “A sós”, cão insigne! Ó víbora vil!\nO “a sós” em tua face tão maravilhosa;\no “a sós” em teus dentes e em tua garganta,\ne em teus pulmões odiosos, sim, em teu bucho, por Deus,\ne, o que é pior, dentro de tua boca imunda!\nDevolvo o “a sós” em tuas entranhas;\npois posso atacar, e o cão da pistola de Pistol está armado,\ne o fogo flamejante virá em seguida.","nymiamnotbarbasonyoucannotconjuremeihave~mayandthatsthehumourofit~223":"Nym — Não sou Barbason; não podeis conjurar-me. Tenho o humor de vos bater razoavelmente bem. Se vos tornardes ofensivo comigo, Pistol, vos esfregarei com meu florete, como puder, em bons termos: se quiserdes ir embora, eu vos picaria um pouco as tripas, em bons termos, como puder: e esse é o humor disso.","pistolobraggartvileanddamnedfuriouswight~athisnearthereforeexhale~91":"Pistol — Ó fanfarrão vil e maldito vulto furioso!\nA sepultura se abre, e a morte caduca está perto;\nportanto, expira.","bardolphhearmehearmewhatisayhethatstrike~ehiltsasiamasoldierdraws~94":"Bardolph — Ouvi-me, ouvi o que digo: quem desferir o primeiro golpe, eu o enfio até o punho, como sou soldado. Saca a espada.","pistolanoathofmicklemightandfuryshallaba~ivethyspiritsaremosttall~95":"Pistol — Um juramento de grande poder; e a fúria vai abrandar.\nDá-me o teu punho, a tua pata dianteira me dá:\nteu ânimo é dos mais altos.","nymiwillcutthythroatonetimeorotherinfair~termsthatisthehumourofit~64":"Nym — Cortarei tua garganta, uma vez ou outra, em bons termos: esse é o humor disso.","pistolcoupleagorgethatistheworditheedefy~andpaucatheresenoughgoto~269":"Pistol — “Couple a gorge!”\nEssa é a palavra. De novo te desafio.\nÓ cão de Creta, pensas conquistar minha esposa?\nNão; ao hospital vai,\ne do tonel de salga da infâmia\ntraze a milhafre leprosa da raça de Créssida,\nDoll Tearsheet de nome, e sua esposa:\neu tenho, e hei de manter, a antiga Quickly\ncomo a única mulher; e—pauca, basta isso.\nVai.","entertheboy~entertheboy~11":"Entra o Menino.","boyminehostpistolyoumustcometomymasteran~armingpanfaithhesveryill~156":"Menino — Anfitrião Pistol, deveis ir ter com meu amo, e vós também, hospedeira: está muito doente e quer ir para a cama. Bom Bardolph, põe tua cara entre os lençóis dele e faz o ofício de esquentador de cama. Na verdade, ele está muito mal.","bardolphawayyourogue~bardolphawayyourogue~20":"Bardolph — Fora, patife!","hostessbymytrothhellyieldthecrowapudding~entlyexeunthostessandboy~125":"Hospedeira — Por minha fé, qualquer dia desses ele dará ao corvo uma morcela. O rei lhe matou o coração. Bom marido, vem para casa já. Saem a Hospedeira e o Menino.","bardolphcomeshallimakeyoutwofriendswemus~stocutoneanothersthroats~109":"Bardolph — Vamos, devo fazer-vos amigos, os dois? Temos de ir juntos para a França: por que diabos guardaríamos facas para cortar a garganta um do outro?","pistolletfloodsoerswellandfiendsforfoodh~llandfiendsforfoodhowlon~45":"Pistol — Que as águas inundem, e demônios uivem por comida!","nymyoullpaymetheeightshillingsiwonofyoua~llingsiwonofyouatbetting~48":"Nym — Pagareis os oito xelins que vos ganhei na aposta?","pistolbaseistheslavethatpays~olbaseistheslavethatpays~28":"Pistol — Vil é o escravo que paga.","nymthatnowiwillhavethatsthehumourofit~llhavethatsthehumourofit~37":"Nym — Isso agora hei de ter: esse é o humor disso.","pistolasmanhoodshallcompoundpushhomethey~compoundpushhometheydraw~44":"Pistol — Como a hombridade acertar: avança. Sacam as espadas.","bardolphbythisswordhethatmakesthefirstth~lkillhimbythisswordiwill~70":"Bardolph — Por esta espada, quem der a primeira estocada, eu o mato; por esta espada, eu o farei.","pistolswordisanoathandoathsmusthavetheir~oathsmusthavetheircourse~46":"Pistol — Espada é juramento, e juramentos devem seguir seu curso.","bardolphcorporalnymandthouwiltbefriendsb~ieswithmetoopritheeputup~98":"Bardolph — Cabo Nym, se quiseres ser amigo, sê amigo: se não quiseres, pois então sê inimigo também de mim. Peço-te, guarda a espada.","nymishallhavemyeightshillingsiwonfromyou~ingsiwonfromyouatbetting~49":"Nym — Terei meus oito xelins que vos ganhei na aposta?","pistolanobleshaltthouhaveandpresentpayan~swillaccruegivemethyhand~214":"Pistol — Um nobre terás, e pagamento à vista;\ne licor também te darei,\ne a amizade unirá, e a irmandade:\nviverei por Nym, e Nym viverá por mim;\nnão é justo? Pois serei cantineiro\ndo acampamento, e os lucros virão.\nDá-me a mão.","nymishallhavemynoble~nymishallhavemynoble~20":"Nym — Terei meu nobre?","pistolincashmostjustlypaid~stolincashmostjustlypaid~26":"Pistol — Em dinheiro, muito justamente pago.","nymwellthenthatsthehumouroft~ellthenthatsthehumouroft~28":"Nym — Bem, então, esse é o humor disso.","reenterhostess~reenterhostess~14":"Reentra a Hospedeira.","hostessaseveryoucomeofwomencomeinquickly~obeholdsweetmencometohim~145":"Hospedeira — Se algum dia nascestes de mulher, vinde depressa a Sir John. Ah, pobre coração! Está tão sacudido por uma terçã quotidiana ardente que é lamentabilíssimo de ver. Doces homens, vinde a ele.","nymthekinghathrunbadhumoursontheknightth~heknightthatstheevenofit~54":"Nym — O rei atirou maus humores sobre o cavaleiro; esse é o fim disso.","pistolnymthouhastspoketherighthisheartis~tisfractedandcorroborate~61":"Pistol — Nym, falaste certo;\no coração dele está fraturado e corroborado.","nymthekingisagoodkingbutitmustbeasitmayh~sessomehumoursandcareers~68":"Nym — O rei é bom rei: mas há de ser como for; ele passa por alguns humores e carreiras.","pistolletuscondoletheknightforlambkinswe~lambkinswewillliveexeunt~54":"Pistol — Condoamo-nos do cavaleiro; pois, cordeirinhos, viveremos. Saem.","southamptonacouncilchamber~uthamptonacouncilchamber~26":"Southampton. Uma sala de conselho.","enterexeterbedfordandwestmoreland~erbedfordandwestmoreland~33":"Entram Exeter, Bedford e Westmoreland.","bedfordforegodhisgraceisboldtotrustthese~boldtotrustthesetraitors~48":"Bedford — Por Deus, Sua Graça é ousada de confiar nestes traidores.","exetertheyshallbeapprehendedbyandby~hallbeapprehendedbyandby~35":"Exeter — Serão presos daqui a pouco.","westmorelandhowsmoothandeventheydobearth~hfaithandconstantloyalty~112":"Westmoreland — Quão serenos e plácidos se comportam!\nComo se a lealdade se assentasse em seus peitos,\ncoroada de fé e constante fidelidade.","bedfordthekinghathnoteofallthattheyinten~ptionwhichtheydreamnotof~74":"Bedford — O rei tem nota de tudo o que pretendem,\npor uma interceptação com que nem sonham.","exeternaybutthemanthatwashisbedfellowwho~slifetodeathandtreachery~149":"Exeter — Pois que o homem que foi seu companheiro de leito,\na quem ele embotou e saciou com graciosos favores,\ndevesse, por uma bolsa estrangeira, vender assim\na vida de seu soberano à morte e à traição.","trumpetssoundenterkinghenryscroopcambrid~mbridgegreyandattendants~59":"Soam trombetas. Entram o Rei Henrique, Scroop, Cambridge, Grey e Séquito.","kinghenrynowsitsthewindfairandwewillaboa~ehaveinheadassembledthem~255":"Rei Henrique — Agora o vento sopra favorável, e embarcaremos.\nMeu Senhor de Cambridge, e meu bondoso Senhor de Masham,\ne vós, meu gentil cavaleiro, dai-me vossas ideias:\nnão pensais que as forças que levamos conosco\nabrirão passagem através do poderio da França,\nfazendo a execução e o ato\npara que as reunimos?","scroopnodoubtmyliegeifeachmandohisbest~yliegeifeachmandohisbest~38":"Scroop — Sem dúvida, meu soberano, se cada homem fizer o seu melhor.","kinghenryidoubtnotthatsincewearewellpers~sandconquesttoattendonus~175":"Rei Henrique — Disso não duvido; pois estamos bem persuadidos\nde que não levamos conosco daqui coração\nque não cresça em justo acordo com o nosso,\nnem deixamos para trás um só que não deseje\nsucesso e conquista a nos acompanhar.","cambridgeneverwasmonarchbetterfeardandlo~eetshadeofyourgovernment~150":"Cambridge — Nunca monarca foi melhor temido e amado\ndo que Vossa Majestade: não há, penso, súdito\nque se assente em mágoa do coração e inquietude\nsob a doce sombra de vosso governo.","greytruethosethatwereyourfathersenemiesh~rtscreateofdutyandofzeal~110":"Grey — É verdade: os que foram inimigos de vosso pai\nembeberam seus fígados em mel e vos servem\ncom corações criados de dever e de zelo.","kinghenrywethereforehavegreatcauseofthan~totheweightandworthiness~148":"Rei Henrique — Temos, pois, grande causa de gratidão;\ne esqueceremos o ofício de nossa mão\nantes que a paga de serviço e mérito,\nsegundo o peso e o valor.","scroopsoserviceshallwithsteeledsinewstoi~urgraceincessantservices~106":"Scroop — Assim o serviço labutará com tendões de aço,\ne o labor se refrescará com esperança,\npara prestar a Vossa Graça serviços incessantes.","kinghenrywejudgenolessuncleofexeterenlar~hismoreadvicewepardonhim~159":"Rei Henrique — Não julgamos menos. Tio de Exeter,\nsoltai o homem preso ontem,\nque injuriou nossa pessoa: consideramos\nque foi o excesso de vinho que o levou a isso;\ne, em vista de sua maior ponderação, o perdoamos.","scroopthatsmercybuttoomuchsecuritylethim~ufferancemoreofsuchakind~104":"Scroop — Isso é misericórdia, mas segurança demais:\nque seja punido, soberano, para que o exemplo\nnão gere, pela sua impunidade, outros do mesmo gênero.","kinghenryoletusyetbemerciful~henryoletusyetbemerciful~28":"Rei Henrique — Oh, sejamos ainda assim misericordiosos.","cambridgesomayyourhighnessandyetpunishto~rhighnessandyetpunishtoo~41":"Cambridge — Assim possa Vossa Alteza, e contudo punir também.","greysiryoushowgreatmercyifyougivehimlife~thetasteofmuchcorrection~69":"Grey — Senhor,\nmostrais grande clemência, se lhe dais a vida,\ndepois de provar muita correção.","kinghenryalasyourtoomuchloveandcareofmea~oarethelatecommissioners~368":"Rei Henrique — Ai de mim, vosso excessivo amor e cuidado por mim\nsão pesadas súplicas contra este pobre desgraçado!\nSe pequenas faltas, nascidas de desordem do humor,\nnão forem toleradas, como estenderemos nosso olhar\nquando crimes capitais, mastigados, engolidos e digeridos,\naparecerem diante de nós? Soltaremos ainda esse homem,\nembora Cambridge, Scroop e Grey, em seu caro cuidado\ne terna preservação de nossa pessoa,\no quisessem punido. E agora às nossas causas francesas:\nquem são os comissários recentes?","cambridgeionemylordyourhighnessbademeask~hnessbademeaskforittoday~50":"Cambridge — Eu um, meu senhor:\nVossa Alteza mandou-me pedi-la hoje.","scroopsodidyoumemyliege~scroopsodidyoumemyliege~23":"Scroop — Assim me mandastes, meu soberano.","greyandimyroyalsovereign~greyandimyroyalsovereign~24":"Grey — E a mim, meu real soberano.","kinghenrythenrichardearlofcambridgethere~yourbloodoutofappearance~385":"Rei Henrique — Então, Ricardo, Conde de Cambridge, eis a vossa;\neis a vossa, Lorde Scroop de Masham; e, senhor cavaleiro,\nGrey de Northumberland, esta mesma é vossa:\nlede-as; e sabei que conheço o vosso valor.\nMeu Senhor de Westmoreland, e tio Exeter,\nembarcaremos esta noite. Ora, então, cavalheiros!\nQue vedes nesses papéis que perdeis\ntanta cor? Vede como mudam!\nSuas faces são papel. Ora, que lestes ali,\nque tão acovardou e caçou vosso sangue\npara fora da vista?","cambridgeidoconfessmyfaultanddosubmitmet~mitmetoyourhighnessmercy~58":"Cambridge — Confesso a minha falta;\ne submeto-me à clemência de Vossa Alteza.","greyandscrooptowhichweallappeal~scrooptowhichweallappeal~31":"Grey e Scroop — À qual todos apelamos.","kinghenrythemercythatwasquickinusbutlate~quitthemoftheirpractices~2255":"Rei Henrique — A clemência que em nós vivia há pouco\nfoi suprimida e morta pelo vosso próprio conselho:\nnão deveis ousar, por vergonha, falar de clemência;\npois vossas próprias razões voltam-se contra vossos peitos,\ncomo cães sobre seus donos, a vos morder.\nVede, meus príncipes e meus nobres pares,\nestes monstros ingleses! Meu Senhor de Cambridge aqui,\nsabeis quão pronto foi o nosso amor em concordar\nem fornecer-lhe todos os apanágios\npertencentes à sua honra; e este homem\npor umas poucas coroas leves conspirou levianamente\ne jurou às tramas da França\nmatar-nos aqui em Hampton: ao que\neste cavaleiro, não menos obrigado a nós por benesses\ndo que Cambridge, igualmente jurou. Mas, oh,\nque direi a ti, Lorde Scroop? Tu, cruel,\ningrata, selvagem e desumana criatura!\nTu, que levavas a chave de todos os meus conselhos,\nque conhecias o próprio fundo da minha alma,\nque quase poderias ter-me cunhado em ouro,\nquisesses tramar contra mim para teu proveito!\nSerá possível que paga estrangeira\npudesse extrair de ti uma centelha de mal\nque molestasse meu dedo? É tão estranho\nque, embora a verdade disso se mostre tão grosseira\ncomo preto e branco, meu olho mal a vê.\nTraição e assassinato sempre andaram juntos,\ncomo dois diabos de jugo jurados ao propósito um do outro,\noperando tão grosseiramente em causa natural\nque a admiração não gritou contra eles:\nmas tu, contra toda proporção, trouxeste\no espanto para servir à traição e ao assassinato:\ne qualquer que fosse o demônio astuto\nque operou em ti tão preposterosamente\nganhou o voto no inferno por excelência:\ne outros demônios que sugerem por traições\nremendam e atamancam a danação\ncom retalhos, cores e formas trazidas\nde reluzentes aparências de piedade;\nmas aquele que te temperou mandou-te erguer,\nnão te deu razão por que fizesses traição,\nsenão para te investir com o nome de traidor.\nSe esse mesmo demônio que assim te iludiu\nandasse pelo mundo inteiro com seu passo de leão,\npoderia voltar ao vasto Tártaro\ne dizer às legiões: “Jamais posso ganhar\numa alma tão fácil como a daquele inglês.”\nOh, como infectaste com ciúme\na doçura da confiança! Mostram-se os homens devotados?\nOra, assim te mostraste tu: parecem graves e doutos?\nOra, assim tu: vêm de família nobre?\nOra, assim tu: parecem religiosos?\nOra, assim tu: ou são parcos na dieta,\nlivres de grosseira paixão, seja de alegria ou de cólera,\nconstantes de espírito, sem desviar-se com o sangue,\nornados e adornados com modesto trato,\nsem operar com o olho sem o ouvido,\ne só em juízo purificado confiando em ambos?\nTal e tão finamente peneirado te mostraste:\ne assim tua queda deixou uma espécie de mancha,\npara marcar o homem mais cheio de qualidades e mais dotado\ncom alguma suspeita. Chorarei por ti;\npois esta tua revolta, parece-me, é como\noutra queda do homem. Suas faltas estão à vista:\nprendei-os para responder à lei;\ne Deus os absolva de suas tramas!","exeteriarresttheeofhightreasonbythenameo~eyknightofnorthumberland~188":"Exeter — Prendo-te por alta traição, com o nome de Ricardo, Conde de Cambridge.\nPrendo-te por alta traição, com o nome de Henrique, Lorde Scroop de Masham.\nPrendo-te por alta traição, com o nome de Thomas Grey, cavaleiro, de Northumberland.","scroopourpurposesgodjustlyhathdiscoverda~ughmybodypaythepriceofit~134":"Scroop — Deus justamente descobriu nossos propósitos;\ne arrependo-me de minha falta mais que de minha morte;\na qual peço a Vossa Alteza que perdoe,\nembora meu corpo pague o preço dela.","cambridgeformethegoldoffrancedidnotseduc~chinggodandyoutopardonme~193":"Cambridge — De minha parte, o ouro da França não me seduziu;\nembora o admitisse como motivo\npara efetuar mais cedo o que eu pretendia:\nmas graças a Deus pela prevenção;\nda qual, em meu sofrimento, de coração me regozijarei,\nsuplicando a Deus e a vós que me perdoeis.","greyneverdidfaithfulsubjectmorerejoiceat~notmybodypardonsovereign~167":"Grey — Nunca súdito fiel mais se regozijou\ncom a descoberta de traição perigosíssima\ndo que eu me alegro nesta hora comigo mesmo,\nimpedido de uma empresa maldita:\nperdoai, soberano, minha falta, mas não meu corpo.","kinghenrygodquityouinhismercyhearyoursen~difnotkingoffranceexeunt~993":"Rei Henrique — Deus vos absolva em sua misericórdia! Ouvi a sentença.\nConspirastes contra nossa real pessoa,\nunidos a um inimigo declarado, e de seus cofres\nrecebestes o sinal de ouro de nossa morte;\ncom o que teríeis vendido vosso rei ao massacre,\nseus príncipes e seus pares à servidão,\nseus súditos à opressão e ao desprezo\ne todo o seu reino à desolação.\nQuanto à nossa pessoa, não buscamos vingança;\nmas devemos zelar de tal modo pela segurança do nosso reino,\ncuja ruína buscastes, que às suas leis\nvos entregamos. Ide, pois, daqui,\npobres miseráveis, à vossa morte:\ndo gosto da qual, Deus em sua misericórdia vos dê\npaciência para suportar e verdadeiro arrependimento\nde todas as vossas caras ofensas! Levai-os daqui. Saem Cambridge, Scroop e Grey, sob guarda.\nAgora, senhores, à França; a empresa da qual\nserá para vós, como para nós, igualmente gloriosa.\nNão duvidamos de uma guerra bela e afortunada,\npois que Deus tão graciosamente trouxe à luz\nesta perigosa traição à espreita em nosso caminho\npara estorvar nossos começos. Não duvidamos agora\nde que todo obstáculo esteja aplainado em nosso caminho.\nAvante, então, caros compatriotas: entreguemos\nnosso poderio nas mãos de Deus,\npondo-o logo em expedição.\nAlegremente ao mar; avancem os sinais de guerra:\nnenhum rei da Inglaterra, se não rei da França. Saem.","sceneiii~sceneiii~8":"Cena III","londonbeforeatavern~londonbeforeatavern~19":"Londres. Diante de uma taverna.","enterpistolhostessnymbardolphandboy~hostessnymbardolphandboy~35":"Entram Pistol, a Hospedeira, Nym, Bardolph e o Menino.","hostesspritheehoneysweethusbandletmebrin~dletmebringtheetostaines~54":"Hospedeira — Peço-te, doce marido, deixa-me levar-te a Staines.","pistolnoformymanlyheartdothyearnbardolph~dandwemustyearntherefore~136":"Pistol — Não; pois meu coração viril se aflige.\nBardolph, alegra-te: Nym, desperta tuas veias fanfarronas:\nMenino, eriça a coragem; pois Falstaff está morto,\ne por isso devemos nos afligir.","bardolphwouldiwerewithhimwheresomeerheis~iseitherinheavenorinhell~62":"Bardolph — Quisera estar com ele, onde quer que esteja, quer no céu, quer no inferno!","hostessnaysurehesnotinhellhesinarthursbo~ndallwasascoldasanystone~685":"Hospedeira — Não, certamente, ele não está no inferno: está no seio de Arthur, se alguma vez homem foi ao seio de Arthur. Teve um fim tão belo e partiu como se fosse uma criança de crisma; partiu bem entre as doze e a uma, justo na virada da maré: pois depois que o vi mexer nos lençóis e brincar com flores e sorrir para as pontas dos dedos, soube que só havia um caminho; pois o nariz dele estava afilado como uma pena, e ele balbuciava sobre campos verdes. “Então, Sir John!”, disse eu: “ora, homem! Anima-te.” Então ele gritou: “Deus, Deus, Deus!” três ou quatro vezes. Eu, para consolá-lo, disse-lhe que não pensasse em Deus; esperava que ainda não fosse preciso afligir-se com tais pensamentos. Então ele mandou-me pôr mais roupa nos pés: meti a mão na cama e os senti, e estavam frios como pedra; depois senti até os joelhos, e estavam frios como pedra, e assim para cima e para cima, e tudo estava frio como pedra.","nymtheysayhecriedoutofsack~mtheysayhecriedoutofsack~26":"Nym — Dizem que gritou por vinho seco.","hostessaythatadid~hostessaythatadid~17":"Hospedeira — Sim, isso ele fez.","bardolphandofwomen~bardolphandofwomen~18":"Bardolph — E por mulheres.","hostessnaythatadidnot~hostessnaythatadidnot~21":"Hospedeira — Não, isso não fez.","boyyesthatadidandsaidtheyweredevilsincar~dtheyweredevilsincarnate~44":"Menino — Fez sim; e disse que eram demônios encarnados.","hostessacouldneverabidecarnationtwasacol~ntwasacolourheneverliked~55":"Hospedeira — Nunca pôde suportar encarnado; era uma cor de que nunca gostou.","boyasaidoncethedevilwouldhavehimaboutwom~ilwouldhavehimaboutwomen~42":"Menino — Disse uma vez que o diabo o levaria por causa das mulheres.","hostessadidinsomesortindeedhandlewomenbu~talkdofthewhoreofbabylon~86":"Hospedeira — De certo modo, sim, lidou com mulheres; mas então estava reumático e falava da prostituta da Babilônia.","boydoyounotrememberasawafleastickuponbar~acksoulburninginhellfire~90":"Menino — Não vos lembrais de que viu uma pulga pousada no nariz de Bardolph e disse que era uma alma negra ardendo no fogo do inferno?","bardolphwellthefuelisgonethatmaintainedt~herichesigotinhisservice~80":"Bardolph — Pois bem, o combustível que mantinha esse fogo acabou: é toda a riqueza que ganhei a seu serviço.","nymshallweshogthekingwillbegonefromsouth~illbegonefromsouthampton~46":"Nym — Vamos andando? O rei partirá de Southampton.","pistolcomeletsawaymylovegivemethylipsloo~tosucktheverybloodtosuck~307":"Pistol — Vamos, partamos. Meu amor, dá-me teus lábios.\nCuida de meus bens e de meus móveis:\nque os sentidos governem; a palavra é “Pagar na hora”:\nnão confies em ninguém;\npois juramentos são palhas, a fé dos homens é bolacha,\ne agarra-firme é o único cão, meu patinho:\nportanto, Caveto seja teu conselheiro.\nVai, limpa teus cristais. Companheiros de jugo em armas,\nvamos à França; como sanguessugas, meus rapazes,\npara sugar, sugar, o próprio sangue sugar!","boyandthatsbutunwholesomefoodtheysay~utunwholesomefoodtheysay~36":"Menino — E isso é alimento pouco saudável, dizem.","pistoltouchhersoftmouthandmarch~ouchhersoftmouthandmarch~31":"Pistol — Toca-lhe a boca macia, e marchemos.","bardolphfarewellhostesskissingher~arewellhostesskissingher~33":"Bardolph — Adeus, hospedeira. Beijando-a.","nymicannotkissthatisthehumourofitbutadie~tisthehumourofitbutadieu~41":"Nym — Não posso beijar, esse é o humor disso; mas adeus.","pistollethousewiferyappearkeepcloseithee~earkeepcloseitheecommand~47":"Pistol — Que apareça a economia doméstica: fica em casa, eu te ordeno.","hostessfarewelladieuexeunt~stessfarewelladieuexeunt~26":"Hospedeira — Adeus; adeus. Saem.","sceneiv~sceneiv~7":"Cena IV","francethekingspalace~francethekingspalace~20":"França. O palácio do Rei.","flourishenterthefrenchkingthedauphinthed~gnetheconstableandothers~84":"Toque de trombetas. Entram o Rei da França, o Delfim, os Duques de Berri e Bretanha, o Condestável e outros.","frenchkingthuscomestheenglishwithfullpow~ctedenglishuponourfields~458":"Rei da França — Assim vem o inglês com pleno poder sobre nós;\ne mais que cuidadosamente nos cumpre\nresponder com realeza em nossas defesas.\nPortanto, os Duques de Berri e de Bretanha,\nde Brabante e de Orleans, partirão,\ne vós, Príncipe Delfim, com toda presteza,\npara guarnecer e reparar nossas cidades de guerra\ncom homens de coragem e meios defensivos;\npois a Inglaterra faz suas aproximações tão ferozes\nquanto as águas ao sorvedouro de um abismo.\nConvém-nos então ser tão previdentes\nquanto o medo nos possa ensinar com exemplos recentes\ndeixados pelos fatais e negligenciados ingleses\nem nossos campos.","dauphinmymostredoubtedfatheritismostmeet~uththatfearattendshernot~508":"Delfim — Meu temidíssimo pai,\né mais que justo que nos armemos contra o inimigo;\npois a própria paz não deveria embotar tanto um reino,\nainda que nem guerra nem querela conhecida estivessem em questão,\nsem que defesas, revistas, preparativos\nfossem mantidos, reunidos e recolhidos,\ncomo se uma guerra estivesse esperada.\nPortanto, digo, convém que saiamos todos\na ver as partes doentes e fracas da França:\ne façamo-lo sem mostra de medo;\nnão, com nada mais do que se ouvíssemos que a Inglaterra\nestivesse ocupada com uma dança de moriscos de Pentecostes:\npois, meu bom soberano, ela é tão ociosamente governada,\nseu cetro tão fantasticamente portado\npor um jovem vão, volúvel, raso e caprichoso,\nque o medo não a acompanha.","constableopeaceprincedauphinyouaretoomuc~tspringandbemostdelicate~402":"Condestável — Oh, paz, Príncipe Delfim!\nEstais muito enganado quanto a este rei:\ninterrogai Vossa Graça os embaixadores recentes,\ncom que grande dignidade ouviu sua embaixada,\nquão bem provido de nobres conselheiros,\nquão modesto em objeções, e ao mesmo tempo\nquão terrível em constante resolução,\ne achareis que suas vaidades passadas\neram só o exterior do romano Brutus,\ncobrindo discrição com um manto de loucura;\ncomo os jardineiros com esterco escondem as raízes\nque primeiro brotarão e serão mais delicadas.","dauphinwelltisnotsomylordhighconstablebu~withscantingalittlecloth~246":"Delfim — Bem, não é assim, meu lorde alto condestável;\nmas, ainda que o pensemos, não importa:\nem casos de defesa, é melhor julgar\no inimigo mais poderoso do que parece:\nassim as proporções de defesa se preenchem;\no que, de projeção fraca e mesquinha,\ncomo um avarento, estraga o manto por economizar\num pouco de pano.","frenchkingthinkwekingharrystrongandprinc~vemightinessandfateofhim~576":"Rei da França — Pensemos forte o Rei Harry;\ne, príncipes, vede que vos armeis fortemente para enfrentá-lo.\nA parentela dele já se fartou de carne sobre nós;\ne ele é criado dessa linhagem sangrenta\nque nos assombrou em nossos caminhos familiares:\ntestemunha nossa vergonha demasiado memorável\nquando a batalha de Crécy foi fatalmente travada\ne todos os nossos príncipes cativados pela mão\ndaquele nome negro, Eduardo, Príncipe Negro de Gales;\nenquanto seu pai como montanha, em pé sobre um monte,\nno alto do ar, coroado pelo sol dourado,\nviu a sua semente heroica e sorriu ao vê-lo\nmutilar a obra da natureza e desfigurar\nos moldes que, por Deus e por pais franceses,\nhaviam sido feitos em vinte anos. Este é um rebento\ndessa estirpe vitoriosa; e temamos\na grandeza nativa e o destino dele.","enteramessenger~enteramessenger~15":"Entra um Mensageiro.","messengerambassadorsfromharrykingofengla~eadmittancetoyourmajesty~72":"Mensageiro — Embaixadores de Harry, Rei da Inglaterra,\npedem admissão a Vossa Majestade.","frenchkingwellgivethempresentaudiencegoa~aseishotlyfollowdfriends~117":"Rei da França — Dar-lhes-emos audiência imediata. Ide, e trazei-os. Saem o Mensageiro e alguns Lordes.\nVedes que esta caça é seguida com ardor, amigos.","dauphinturnheadandstoppursuitforcowarddo~vileasinasselfneglecting~229":"Delfim — Voltai a cabeça e detende a perseguição; pois cães covardes\nmais latem quando o que parecem ameaçar\ncorre longe diante deles. Bom soberano meu,\napanhai os ingleses curto, e fazei-os saber\nde que monarquia sois a cabeça:\no amor-próprio, meu soberano, não é pecado tão vil\nquanto a negligência de si.","reenterlordswithexeterandtrain~rlordswithexeterandtrain~30":"Reentram os Lordes, com Exeter e comitiva.","frenchkingfromourbrotherengland~ingfromourbrotherengland~31":"Rei da França — De nosso irmão da Inglaterra?","exeterfromhimandthushegreetsyourmajestyh~enativeandtruechallenger~654":"Exeter — Dele; e assim ele saúda Vossa Majestade.\nQuer que, em nome de Deus Todo-Poderoso,\nvos despojeis e ponhais de lado\nas glórias emprestadas que, por dádiva do céu,\npor lei da natureza e das nações, pertencem\na ele e a seus herdeiros; a saber, a coroa\ne todas as honras de amplo alcance que pertencem\npor costume e ordenação dos tempos\nà coroa da França. Para que saibais\nque não é pretensão sinistra nem desastrada,\ntirada das tocas de vermes de dias há muito desvanecidos,\nnem rastelada do pó do velho esquecimento,\nenvia-vos esta linha memorabilíssima,\nem cada ramo verdadeiramente demonstrativa;\nquerendo que examineis esta genealogia:\ne quando o encontrardes igualmente derivado\ndo mais famoso dos famosos antepassados,\nEduardo Terceiro, manda-vos então renunciar\nvossa coroa e reino, indiretamente detidos\ndaquele que é o natural e verdadeiro reclamante.","frenchkingorelsewhatfollows~nchkingorelsewhatfollows~27":"Rei da França — Ou então o quê se segue?","exeterbloodyconstraintforifyouhidethecro~presslyibringgreetingtoo~551":"Exeter — Coação sangrenta; pois se esconderdes a coroa\nmesmo em vossos corações, ali a rastelará:\nportanto vem em fera tempestade,\nem trovão e terremoto, como um Jove,\nde modo que, se o pedido falhar, ele compelirá;\ne manda-vos, pelas entranhas do Senhor,\nentregar a coroa e ter misericórdia\ndas pobres almas para quem esta faminta guerra\nabre suas vastas mandíbulas; e sobre vossa cabeça\nfazendo recair as lágrimas das viúvas, os gritos dos órfãos,\no sangue dos mortos, os gemidos das donzelas que se consomem\npor maridos, pais e noivos amados,\nque serão engolidos nesta controvérsia.\nEsta é a sua pretensão, sua ameaça e minha mensagem;\na menos que o Delfim esteja aqui presente,\na quem expressamente trago saudação também.","frenchkingforuswewillconsiderofthisfurth~acktoourbrotherofengland~100":"Rei da França — Quanto a nós, consideraremos isto mais adiante:\namanhã levareis nosso pleno intento\nde volta a nosso irmão da Inglaterra.","dauphinforthedauphinistandhereforhimwhat~rhimwhattohimfromengland~56":"Delfim — Quanto ao Delfim,\nestou aqui por ele: que há para ele da Inglaterra?","exeterscornanddefianceslightregardcontem~condaccentofhisordinance~339":"Exeter — Escárnio e desafio: pouco caso, desprezo,\ne tudo o que não desdiga\ndo poderoso remetente, é no que vos avalia.\nAssim diz meu rei; e se a alteza de vosso pai\nnão adoçar, concedendo todas as exigências por inteiro,\no amargo escárnio que enviastes a Sua Majestade,\nele vos chamará a tão ardente resposta disso\nque as cavernas e abóbadas ventrais da França\nrepreenderão vossa ofensa e devolverão vosso escárnio\nno segundo eco de sua artilharia.","dauphinsayifmyfatherrenderfairreturnitis~senthimwiththeparisballs~157":"Delfim — Dizei, se meu pai der resposta justa,\né contra a minha vontade; pois nada desejo\nsenão discórdia com a Inglaterra: para esse fim,\ncomo condizente com sua juventude e vaidade,\npresenteei-o com as bolas de Paris.","exeterhellmakeyourparislouvreshakeforitw~wnlossesifhestayinfrance~274":"Exeter — Ele fará vosso Louvre de Paris tremer por isso,\nfosse a corte soberana da poderosa Europa:\ne, ficai certo, achareis uma diferença,\ncomo nós, seus súditos, achamos com espanto,\nentre a promessa de seus dias mais verdes\ne estes que agora domina: agora pesa o tempo\naté o último grão: o que lereis\nem vossas próprias perdas, se ele ficar na França.","frenchkingtomorrowshallyouknowourmindatf~hallyouknowourmindatfull~43":"Rei da França — Amanhã sabereis plenamente nosso parecer.","exeterdispatchuswithallspeedlestthatourk~sfootedinthislandalready~106":"Exeter — Despachai-nos com toda a pressa, para que nosso rei\nnão venha ele mesmo aqui questionar nossa demora;\npois já tem pé firmado nesta terra.","frenchkingyoushallbesoondispatchdwithfai~onsequenceflourishexeunt~133":"Rei da França — Sereis logo despachados com boas condições:\numa noite é pouco fôlego e pequena pausa\npara responder a matérias de tal consequência. Toque de trombetas. Saem."}$tr$::jsonb, 198)
