insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('william-shakespeare_julius-caesar', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"acti":"Ato I","actii":"Ato II","actiii":"Ato III"}$tr$::jsonb, $tr${"scenei~scenei~6":"Cena I","romeastreet~romeastreet~11":"Roma. Uma rua.","enterflaviusmarullusandcertaincommoners~ullusandcertaincommoners~39":"Entram Flávio, Marulo e alguns Plebeus.","flaviushencehomeyouidlecreaturesgetyouho~ionspeakwhattradeartthou~168":"FLÁVIO — Fora! Para casa, vadios, para casa! \n É feriado hoje? Como! Não sabeis \n que, sendo artesãos, não deveis andar \n em dia de trabalho sem o sinal \n de vosso ofício? Fala, qual é o teu?","firstcommonerwhysiracarpenter~commonerwhysiracarpenter~29":"PRIMEIRO PLEBEU — Ora, senhor, carpinteiro.","marulluswhereisthyleatherapronandthyrule~lonyousirwhattradeareyou~93":"MARULO — Onde está teu avental de couro e a régua? \n Que fazes tu com a tua melhor roupa? \n E vós, senhor, qual é o vosso ofício?","secondcommonertrulysirinrespectofafinewo~butasyouwouldsayacobbler~72":"SEGUNDO PLEBEU — Na verdade, senhor, comparado a um bom artífice, sou apenas, como direis, um remendão.","marullusbutwhattradeartthouanswermedirec~eartthouanswermedirectly~43":"MARULO — Mas qual é o teu ofício? Responde direto.","secondcommoneratradesirthatihopeimayusew~deedsiramenderofbadsoles~91":"SEGUNDO PLEBEU — Um ofício, senhor, que espero poder exercer com a consciência tranquila; a saber, senhor, consertador de almas ruins.","marulluswhattradethouknavethounaughtykna~hounaughtyknavewhattrade~51":"MARULO — Que ofício, patife? Patife safado, que ofício?","secondcommonernayibeseechyousirbenotoutw~ifyoubeoutsiricanmendyou~72":"SEGUNDO PLEBEU — Ora, rogo-vos, senhor, não vos descomponhais comigo; mas, se vos descomponhais, senhor, eu posso vos remendar.","marulluswhatmeanestthoubythatmendmethous~hatmendmethousaucyfellow~50":"MARULO — Que queres dizer com isso? Remendar-me, insolente!","secondcommonerwhysircobbleyou~dcommonerwhysircobbleyou~29":"SEGUNDO PLEBEU — Ora, senhor, vos sapatear.","flaviusthouartacobblerartthou~usthouartacobblerartthou~29":"FLÁVIO — És então um sapateiro, não é?","secondcommonertrulysirallthatilivebyiswi~rhavegoneuponmyhandiwork~230":"SEGUNDO PLEBEU — Na verdade, senhor, tudo de que vivo é do furador: não me meto em assuntos de nenhum artesão, nem em assuntos de mulheres, mas só com furador. Sou, de fato, senhor, um cirurgião de sapatos velhos; quando correm grande perigo, eu os restabeleço. Homens tão distintos quanto os que já pisaram em couro de boi andaram sobre a minha obra.","flaviusbutwhereforeartnotinthyshoptodayw~dthesemenaboutthestreets~77":"FLÁVIO — Mas por que não estás hoje em tua loja? \n Por que levas estes homens pelas ruas?","secondcommonertrulysirtowearouttheirshoe~andtorejoiceinhistriumph~124":"SEGUNDO PLEBEU — Na verdade, senhor, para gastar-lhes os sapatos e arranjar mais trabalho para mim. Mas, de fato, senhor, fazemos feriado para ver César e nos regozijar com o seu triunfo.","marulluswhereforerejoicewhatconquestbrin~stlightonthisingratitude~777":"MARULO — Regozijar por quê? Que conquista ele traz? \n Que tributários o seguem até Roma, \n para ornar, em cadeias, o seu carro? \n Vós, blocos, vós, pedras, vós, piores que coisas sem sentido! \n Ó corações duros, ó homens cruéis de Roma, \n não conhecíeis Pompeu? Muitas vezes, e muitas, \n subistes a muros e ameias, \n a torres e janelas, sim, aos topos das chaminés, \n com vossos filhos nos braços, e ali ficastes \n o dia inteiro, em paciente expectativa, \n para ver o grande Pompeu passar pelas ruas de Roma: \n e quando víeis apenas surgir o seu carro, \n não lançáveis um grito universal, \n que o Tibre estremecia sob as margens, \n ao ouvir o eco de vossas vozes \n ressoando em suas côncavas ribanceiras? \n E agora vestis as vossas melhores roupas? \n E agora escolheis para vós um feriado? \n E agora espalhais flores no caminho \n daquele que vem em triunfo sobre o sangue de Pompeu? \n Fora daqui! \n Correi a vossas casas, caí de joelhos, \n rogai aos deuses que suspendam a praga \n que há de cair, fatal, sobre esta ingratidão.","flaviusgogogoodcountrymenandforthisfault~dthemdeckdwithceremonies~360":"FLÁVIO — Ide, ide, bons compatriotas, e, por esta falta, \n reuni todos os pobres de vossa espécie; \n levai-os às margens do Tibre e chorai vossas lágrimas \n no leito do rio, até que a corrente mais baixa \n beije as margens mais altas de todas. Saem todos os Plebeus. \n Vede se o seu metal mais vil não se comoveu; \n desaparecem mudos em sua culpa. \n Descei vós por aquele lado, rumo ao Capitólio; \n eu irei por este: despi as imagens, \n se as achardes ornadas de cerimônias.","marullusmaywedosoyouknowitisthefeastoflu~owitisthefeastoflupercal~46":"MARULO — Podemos fazê-lo? \n Sabeis que é a festa das Lupercais.","flaviusitisnomatterletnoimagesbehungwith~servilefearfulnessexeunt~274":"FLÁVIO — Não importa; que nenhuma imagem \n fique ornada com troféus de César. Eu irei \n e afastarei o vulgo das ruas: \n fazei o mesmo onde o virdes aglomerado. \n Estas penas que crescem, arrancadas da asa de César, \n o farão voar a altura comum, \n ele que, de outro modo, subiria além da vista dos homens \n e nos manteria a todos em servil temor. Saem.","sceneii~sceneii~7":"Cena II","apublicplace~apublicplace~12":"Um lugar público.","flourishentercaesarantonyforthecoursecal~wingamongthemasoothsayer~125":"Toque de trombetas. Entram César; Antônio, trajado para a corrida; Calpúrnia, Pórcia, Décio, Cícero, Brutus, Cássio e Casca; uma grande multidão os segue, e entre ela um Adivinho.","caesarcalpurnia~caesarcalpurnia~15":"César — Calpúrnia!","cascapeacehocaesarspeaks~cascapeacehocaesarspeaks~24":"Casca — Silêncio, ó! César fala.","calpurniaheremylord~calpurniaheremylord~19":"Calpúrnia — Aqui, meu senhor.","caesarstandyoudirectlyinantoniuswaywhenh~dothrunhiscourseantonius~65":"César — Põe-te bem no caminho de Antônio,\nquando ele correr a sua carreira. Antônio!","antonycaesarmylord~antonycaesarmylord~18":"Antônio — César, meu senhor?","caesarforgetnotinyourspeedantoniustotouc~hakeofftheirsterilecurse~121":"César — Não te esqueças, Antônio, em tua pressa,\nde tocar Calpúrnia; pois dizem nossos anciãos\nque as estéreis, tocadas nesta santa corrida,\nsacodem de si a maldição da esterilidade.","antonyishallrememberwhencaesarsaysdothis~arsaysdothisitisperformd~52":"Antônio — Lembrar-me-ei:\nquando César diz “faze isto”, está feito.","caesarsetonandleavenoceremonyoutflourish~avenoceremonyoutflourish~40":"César — Avante; e não omitais cerimônia alguma. Toque de trombetas.","soothsayercaesar~soothsayercaesar~16":"Adivinho — César!","caesarhawhocalls~caesarhawhocalls~16":"César — Ha! Quem chama?","cascabideverynoisebestillpeaceyetagain~oisebestillpeaceyetagain~38":"Casca — Que todo ruído se cale: silêncio ainda uma vez!","caesarwhoisitinthepressthatcallsonmeihea~speakcaesaristurndtohear~104":"César — Quem é na multidão que me chama?\nOuço uma voz, mais aguda que toda a música,\ngritar “César!” Fala; César voltou-se para ouvir.","soothsayerbewaretheidesofmarch~ayerbewaretheidesofmarch~30":"Adivinho — Cuidado com os idos de março.","caesarwhatmanisthat~caesarwhatmanisthat~19":"César — Que homem é esse?","brutusasoothsayerbidsyoubewaretheidesofm~syoubewaretheidesofmarch~44":"Brutus — Um adivinho manda-vos ter cuidado com os idos de março.","caesarsethimbeforemeletmeseehisface~mbeforemeletmeseehisface~35":"César — Colocai-o diante de mim; deixai-me ver-lhe o rosto.","cassiusfellowcomefromthethronglookuponca~mthethronglookuponcaesar~44":"Cássio — Companheiro, sai da turba; olha para César.","caesarwhatsaystthoutomenowspeakonceagain~houtomenowspeakonceagain~40":"César — Que dizes a mim agora? Fala outra vez.","caesarheisadreamerletusleavehimpasssenne~llexceptbrutusandcassius~72":"César — É um sonhador; deixemo-lo: passemos. Toque de cornetas. Saem todos, exceto Brutus e Cássio.","cassiuswillyougoseetheorderofthecourse~goseetheorderofthecourse~38":"Cássio — Ireis ver a ordem da corrida?","brutusnoti~brutusnoti~10":"Brutus — Eu não.","cassiusiprayyoudo~cassiusiprayyoudo~17":"Cássio — Peço-vos, ide.","brutusiamnotgamesomeidolacksomepartoftha~usyourdesiresillleaveyou~109":"Brutus — Não sou afeito a jogos: falta-me um pouco\ndaquele espírito vivo que há em Antônio.\nNão quero estorvar, Cássio, vossos desejos;\ndeixo-vos.","cassiusbrutusidoobserveyounowoflateihave~eryourfriendthatlovesyou~160":"Cássio — Brutus, tenho reparado em vós ultimamente:\njá não vejo em vossos olhos aquela gentileza\ne mostra de afeto a que estava acostumado:\ntratais com mão demasiado dura e estranha\no vosso amigo que vos ama.","brutuscassiusbenotdeceivedifihaveveildmy~theshowsoflovetoothermen~364":"Brutus — Cássio,\nnão vos enganeis: se velei o meu olhar,\nvolto a perturbação do meu semblante\nsomente contra mim mesmo. Estou atormentado,\nultimamente, por paixões de certa diversidade,\nconcepções somente próprias de mim,\nque talvez manchem um pouco o meu comportamento;\nmas que por isso não se aflijam meus bons amigos—\nentre cujo número, Cássio, sois um—,\nnem interpretem mais longe a minha negligência\nsenão que o pobre Brutus, em guerra consigo mesmo,\nesquece as mostras de afeto para com os outros homens.","cassiusthenbrutusihavemuchmistookyourpas~dbrutuscanyouseeyourface~154":"Cássio — Então, Brutus, enganei-me muito quanto à vossa paixão;\npor causa do que este meu peito enterrou\npensamentos de grande valor, dignas cogitações.\nDizei-me, bom Brutus, podeis ver vosso rosto?","brutusnocassiusfortheeyeseesnotitselfbut~lectionbysomeotherthings~69":"Brutus — Não, Cássio; pois o olho não se vê a si mesmo,\nsenão por reflexo, por meio de outras coisas.","cassiustisjustanditisverymuchlamentedbru~hatnoblebrutushadhiseyes~277":"Cássio — É justo:\ne muito se lamenta, Brutus,\nque não tenhais espelhos tais que voltem\nvosso oculto mérito para vosso olhar,\npara que vísseis vossa sombra. Ouvi dizer\nque muitos dos mais respeitados de Roma,\nexceto o imortal César, falando de Brutus\ne gemendo sob o jugo desta era,\ndesejaram que o nobre Brutus tivesse os seus olhos.","brutusintowhatdangerswouldyouleadmecassi~elfforthatwhichisnotinme~95":"Brutus — A que perigos me quereis levar, Cássio,\nque quereis que eu procure em mim mesmo\naquilo que não está em mim?","cassiusthereforegoodbrutusbepreparedtohe~angerousflourishandshout~424":"Cássio — Portanto, bom Brutus, preparai-vos para ouvir:\ne já que sabeis que não podeis ver-vos a vós mesmo\ntão bem como por reflexo, eu, vosso espelho,\ndescobrirei modestamente a vós mesmo\naquilo de vós mesmo que ainda não conheceis.\nE não desconfieis de mim, gentil Brutus:\nfosse eu um gracejador vulgar, ou costumasse\ngastar com juramentos comuns o meu afeto\na todo novo protestante; se sabeis\nque eu adulo os homens e os abraço com força\ne depois os difamo, ou se sabeis\nque me ofereço nos banquetes\na toda a turba, então tende-me por perigoso. Toque de trombetas e aclamação.","brutuswhatmeansthisshoutingidofearthepeo~choosecaesarfortheirking~67":"Brutus — Que significa esta gritaria? Temo que o povo\nescolha César por seu rei.","cassiusaydoyoufearitthenmustithinkyouwou~thinkyouwouldnothaveitso~53":"Cássio — Ah, temeis isso?\nEntão devo pensar que não o quereríeis assim.","brutusiwouldnotcassiusyetilovehimwellbut~honourmorethanifeardeath~258":"Brutus — Não o quereria, Cássio; contudo o estimo bastante.\nMas por que me reteis aqui tanto tempo?\nQue é que quereis comunicar-me?\nSe for algo em prol do bem geral,\npondo a honra num olho e a morte no outro,\nolharei ambas com indiferença,\npois que os deuses me assistam como amo\no nome da honra mais do que temo a morte.","cassiusiknowthatvirtuetobeinyoubrutusasw~hepalmaloneshoutflourish~1323":"Cássio — Sei que essa virtude está em vós, Brutus,\ntão bem como conheço o vosso aspecto exterior.\nPois bem, a honra é o assunto da minha história.\nNão sei dizer o que vós e outros homens\npensais desta vida; mas, quanto a mim sozinho,\npreferiria não ser a viver para ser\nem temor de uma coisa como eu mesmo.\nNasci livre como César; assim vós:\nambos nos alimentamos tão bem, e ambos podemos\nsuportar o frio do inverno tão bem como ele:\npois uma vez, num dia cru e ventoso,\nquando o Tibre agitado se irritava com suas margens,\nCésar disse-me: “Ousas, Cássio, agora\nsaltar comigo nesta torrente irada\ne nadar até aquele ponto?” Ao dizer da palavra,\ntrajado como estava, mergulhei\ne mandei-o seguir-me; e de fato ele o fez.\nA torrente rugia, e nós a golpeamos\ncom músculos vigorosos, jogando-a de lado\ne vencendo-a com corações de rivalidade;\nmas antes que pudéssemos alcançar o ponto proposto,\nCésar gritou: “Socorre-me, Cássio, ou afundo!”\nEu, como Eneias, nosso grande ancestral,\ndas chamas de Troia sobre o ombro\no velho Anquises carregou, assim das ondas do Tibre\neu tirei o cansado César. E este homem\ntornou-se agora um deus, e Cássio é\ncriatura miserável e deve curvar o corpo\nse César displicentemente acena para ele.\nTeve uma febre quando estava na Espanha,\ne quando o acesso o tomava, notei\ncomo ele tremia: é verdade, este deus tremia:\nseus lábios covardes fugiam da sua cor,\ne aquele mesmo olho cujo aceno assombra o mundo\nperdia o seu lustre: ouvi-o gemer:\nsim, e aquela sua língua que mandou os romanos\nnotá-lo e escrever seus discursos em seus livros,\nai, gritava: “Dá-me de beber, Titínio”,\ncomo uma menina doente. Ó deuses, assombra-me\nque um homem de tão fraca têmpera pudesse\nassim tomar a dianteira do majestoso mundo\ne levar a palma sozinho. Aclamação. Toque de trombetas.","brutusanothergeneralshoutidobelievethatt~oursthatareheapdoncaesar~93":"Brutus — Outra aclamação geral!\nCreio que esses aplausos são\npor algumas novas honras que se amontoam sobre César.","cassiuswhymanhedothbestridethenarrowworl~ateinromeaseasilyasaking~910":"Cássio — Ora, homem, ele cavalga o estreito mundo\ncomo um Colosso, e nós, homens mesquinhos,\nandamos sob suas enormes pernas e espreitamos em volta\npara achar para nós sepulturas desonrosas.\nOs homens são às vezes senhores de seus destinos:\na culpa, caro Brutus, não está em nossas estrelas,\nmas em nós mesmos, que somos subalternos.\nBrutus e César: que deveria haver nesse “César”?\nPor que esse nome seria mais soado que o vosso?\nEscrevei-os juntos, o vosso é tão belo nome;\npronunciai-os, convém igualmente à boca;\npesai-os, é tão pesado; conjurai com eles,\nBrutus fará erguer um espírito tão depressa quanto César.\nAgora, em nome de todos os deuses de uma vez,\nde que carne se alimenta este nosso César,\nque cresceu tão grande? Idade, estás envergonhada!\nRoma, perdeste a raça dos sangues nobres!\nQuando passou uma era, desde o grande dilúvio,\nque não fosse famosa por mais de um só homem?\nQuando puderam dizer até agora, os que falavam de Roma,\nque suas largas muralhas cercavam um só homem?\nAgora é Roma de fato, e espaço bastante,\nquando nela só há um único homem.\nOh, vós e eu ouvimos nossos pais dizer\nque houve um Brutus outrora que teria tolerado\no diabo eterno a manter seu estado em Roma\ntão facilmente como um rei.","brutusthatyoudolovemeiamnothingjealouswh~histimeisliketolayuponus~447":"Brutus — Que me amais, disso não desconfio nada;\naonde quereis levar-me, tenho alguma ideia:\no que pensei disto e destes tempos\ncontarei depois; por ora,\nnão quisera, se com afeto vos pudesse rogar,\nser mais instado. O que dissestes\nconsiderarei; o que tendes a dizer\nouvirei com paciência, e acharei um tempo\nconveniente para ouvir e responder a tão altas coisas.\nAté então, meu nobre amigo, ruminai isto:\nBrutus preferiria ser um aldeão\na reputar-se filho de Roma\nsob estas duras condições que este tempo\npromete impor-nos.","cassiusiamgladthatmyweakwordshavestruckb~muchshowoffirefrombrutus~70":"Cássio — Alegro-me de que minhas fracas palavras\ntenham arrancado de Brutus ao menos esta mostra de fogo.","brutusthegamesaredoneandcaesarisreturnin~doneandcaesarisreturning~41":"Brutus — Os jogos acabaram e César está voltando.","cassiusastheypassbypluckcascabythesleeve~proceededworthynotetoday~107":"Cássio — Quando passarem, puxai Casca pela manga;\ne ele, a seu modo azedo, vos contará\no que se passou digno de nota hoje.","reentercaesarandhistrain~reentercaesarandhistrain~24":"Reentram César e seu Séquito.","brutusiwilldosobutlookyoucassiustheangry~conferencebysomesenators~228":"Brutus — Assim farei. Mas, vede, Cássio,\na mancha irada brilha na fronte de César,\ne todo o resto parece um séquito repreendido:\na face de Calpúrnia está pálida; e Cícero\nolha com olhos de furão e tão ardentes\ncomo o vimos no Capitólio,\ncontrariado em debate por alguns senadores.","cassiuscascawilltelluswhatthematteris~illtelluswhatthematteris~37":"Cássio — Casca nos dirá o que se passou.","caesarantonius~caesarantonius~14":"César — Antônio!","antonycaesar~antonycaesar~12":"Antônio — César?","caesarletmehavemenaboutmethatarefatsleek~omuchsuchmenaredangerous~136":"César — Quero ter em torno de mim homens gordos:\nhomens de cabeça lisa e que durmam à noite:\naquele Cássio tem um olhar magro e faminto;\npensa demais: tais homens são perigosos.","antonyfearhimnotcaesarhesnotdangeroushei~sanobleromanandwellgiven~64":"Antônio — Não o temais, César; não é perigoso;\né um nobre romano e bem-intencionado.","caesarwouldhewerefatterbutifearhimnotyet~arandallhistrainbutcasca~595":"César — Quisera que fosse mais gordo! Mas não o temo:\ncontudo, se meu nome estivesse sujeito a temer,\nnão conheço homem que eu devesse evitar\ntão cedo como esse magro Cássio. Lê muito;\né grande observador e vê\nbem através dos atos dos homens; não ama peças,\ncomo tu, Antônio; não ouve música;\nraramente sorri, e sorri de tal modo\ncomo se zombasse de si mesmo e desprezasse seu espírito,\nque pudesse ser movido a sorrir de qualquer coisa.\nTais homens como ele nunca têm sossego no coração\nenquanto veem alguém maior que eles,\ne por isso são muito perigosos.\nDigo-te antes o que é de temer\ndo que o que temo; pois sempre sou César.\nVem à minha direita, que este ouvido é surdo,\ne diz-me com verdade o que pensas dele. Toque de cornetas. Saem César e todo o Séquito, exceto Casca.","cascayoupulldmebythecloakwouldyouspeakwi~cloakwouldyouspeakwithme~44":"Casca — Puxastes-me pelo manto; quereis falar comigo?","brutusaycascatelluswhathathchancedtodayt~odaythatcaesarlookssosad~59":"Brutus — Sim, Casca; contai-nos o que ocorreu hoje,\nque César parece tão triste.","cascawhyyouwerewithhimwereyounot~youwerewithhimwereyounot~32":"Casca — Ora, estáveis com ele, não estáveis?","brutusishouldnotthenaskcascawhathadchanc~enaskcascawhathadchanced~42":"Brutus — Então não perguntaria a Casca o que ocorreu.","cascawhytherewasacrownofferedhimandbeing~enthepeoplefellashouting~112":"Casca — Ora, ofereceram-lhe uma coroa: e, sendo-lhe oferecida, ele a afastou com as costas da mão, assim; e então o povo pôs-se a gritar.","brutuswhatwasthesecondnoisefor~whatwasthesecondnoisefor~30":"Brutus — Para que foi o segundo ruído?","cascawhyforthattoo~cascawhyforthattoo~18":"Casca — Ora, por isso também.","cassiustheyshoutedthricewhatwasthelastcr~ricewhatwasthelastcryfor~44":"Cássio — Gritaram três vezes: para que foi o último grito?","brutuswasthecrownofferedhimthrice~thecrownofferedhimthrice~33":"Brutus — Foi-lhe oferecida a coroa três vezes?","cascaaymarrywastandheputitbythriceeveryt~ehonestneighboursshouted~105":"Casca — Sim, por Nossa Senhora, foi, e ele a afastou três vezes, cada vez com mais brandura que a outra, e a cada afastar meus honestos vizinhos gritaram.","cassiuswhoofferedhimthecrown~iuswhoofferedhimthecrown~28":"Cássio — Quem lhe ofereceu a coroa?","cascawhyantony~cascawhyantony~14":"Casca — Ora, Antônio.","brutustellusthemannerofitgentlecasca~themannerofitgentlecasca~36":"Brutus — Contai-nos como foi, gentil Casca.","cascaicanaswellbehangedastellthemannerof~ipsandreceivingthebadair~647":"Casca — Posso muito bem ser enforcado como contar como foi: foi pura tolice; não prestei atenção. Vi Marco Antônio oferecer-lhe uma coroa;—e no entanto não era coroa também, era uma dessas coronetas;—e, como vos disse, ele a afastou uma vez: mas, apesar de tudo, no meu entender, bem a queria ter. Então ele a ofereceu de novo; então ele a afastou de novo: mas, no meu entender, estava muito relutante em tirar os dedos dela. E então ele a ofereceu a terceira vez; ele a afastou a terceira vez: e a cada vez que a recusava, a ralé gritava e batia as mãos rachadas e atirava para o ar os barretes de dormir suados e soltava tanto bafo fedorento por César ter recusado a coroa que quase sufocou César; pois ele desmaiou e caiu com isso: e, de minha parte, não ousei rir, por medo de abrir os lábios e receber o ar ruim.","cassiusbutsoftiprayyouwhatdidcaesarswoun~ayyouwhatdidcaesarswound~41":"Cássio — Mas calma, peço-vos: como, César desmaiou?","cascahefelldowninthemarketplaceandfoamed~datmouthandwasspeechless~63":"Casca — Caiu na praça do mercado, e espumou pela boca, e ficou sem fala.","brutustisverylikehehaththefailingsicknes~hehaththefailingsickness~41":"Brutus — É muito provável: tem o mal caduco.","cassiusnocaesarhathitnotbutyouandiandhon~wehavethefallingsickness~72":"Cássio — Não, César não o tem; mas vós e eu\ne o honesto Casca, nós é que temos o mal caduco.","cascaiknownotwhatyoumeanbythatbutiamsure~inthetheatreiamnotrueman~178":"Casca — Não sei o que quereis dizer com isso; mas estou certo de que César caiu. Se a gentalha esfarrapada não o aplaudiu e vaiou, conforme ele lhes agradava e desagradava, como costumam fazer com os atores no teatro, não sou homem de verdade.","brutuswhatsaidhewhenhecameuntohimself~dhewhenhecameuntohimself~37":"Brutus — Que disse ele quando voltou a si?","cascamarrybeforehefelldownwhenheperceive~stheywouldhavedonenoless~500":"Casca — Ora, antes de cair, quando percebeu que a plebe comum estava contente por ele ter recusado a coroa, arrancou-me aberto o gibão e ofereceu-lhes a garganta para cortar. Se eu fosse homem de algum ofício, e não o tomasse na palavra, quisera ir para o inferno entre os patifes. E assim ele caiu. Quando voltou a si, disse que, se tivesse feito ou dito algo errado, desejava que suas senhorias pensassem que era a sua enfermidade. Três ou quatro mulheres, onde eu estava, gritaram: “Ai, boa alma!” e o perdoaram de todo o coração: mas não se deve fazer caso delas: se César tivesse apunhalado suas mães, teriam feito o mesmo.","brutusandafterthathecamethussadaway~terthathecamethussadaway~35":"Brutus — E depois disso ele veio embora, assim tão triste?","cascaay~cascaay~7":"Casca — Sim.","cassiusdidcicerosayanything~siusdidcicerosayanything~27":"Cássio — Cícero disse alguma coisa?","cascaayhespokegreek~cascaayhespokegreek~19":"Casca — Sim, falou grego.","cassiustowhateffect~cassiustowhateffect~19":"Cássio — Com que efeito?","cascanayanitellyouthatillneerlookyouithe~eryyetificouldrememberit~281":"Casca — Ora, se vos disser isso, nunca mais vos olharei no rosto: mas os que o entenderam sorriram uns para os outros e balançaram a cabeça; mas, de minha parte, para mim era grego. Posso dar-vos mais notícias também: Márulo e Flávio, por tirarem as echarpes das imagens de César, foram postos em silêncio. Passai bem. Houve mais tolices ainda, se eu pudesse lembrar.","cassiuswillyousupwithmetonightcasca~yousupwithmetonightcasca~35":"Cássio — Cearás comigo esta noite, Casca?","cascanoiampromisedforth~cascanoiampromisedforth~23":"Casca — Não, estou comprometido para fora.","cassiuswillyoudinewithmetomorrow~illyoudinewithmetomorrow~32":"Cássio — Jantarás comigo amanhã?","cascaayifibealiveandyourmindholdandyourd~yourdinnerworththeeating~59":"Casca — Sim, se eu estiver vivo e vosso desejo se mantiver e vosso jantar valer a pena ser comido.","cassiusgoodiwillexpectyou~assiusgoodiwillexpectyou~25":"Cássio — Bom: esperar-te-ei.","cascadosofarewellbothexit~ascadosofarewellbothexit~25":"Casca — Esperai. Adeus, ambos. Sai.","brutuswhatabluntfellowisthisgrowntobehew~mettlewhenhewenttoschool~71":"Brutus — Que sujeito rude este se tornou!\nEra de ânimo vivo quando ia à escola.","cassiussoishenowinexecutionofanyboldorno~swordswithbetterappetite~167":"Cássio — Assim é ainda agora na execução\nde qualquer empresa ousada ou nobre,\npor mais que tome esta forma lenta.\nEsta rudeza é um tempero para seu bom espírito,\nque dá aos homens estômago para digerir suas palavras\ncom melhor apetite.","brutusandsoitisforthistimeiwillleaveyout~metomeandiwillwaitforyou~130":"Brutus — E assim é. Por ora deixo-vos:\namanhã, se quiserdes falar comigo,\nirei à vossa casa; ou, se preferirdes,\nvinde à minha, e esperar-vos-ei.","cassiusiwilldosotillthenthinkoftheworlde~himorworsedaysendureexit~551":"Cássio — Assim farei: até então, pensai no mundo. Sai Brutus.\nPois bem, Brutus, és nobre; contudo vejo\nque teu honrado metal pode ser forjado\ncontra o que é sua inclinação: portanto convém\nque nobres espíritos se mantenham sempre com seus iguais;\npois quem é tão firme que não possa ser seduzido?\nCésar tem-me mágoa; mas ama Brutus:\nse eu fosse Brutus agora e ele fosse Cássio,\nele não me faria ceder. Esta noite eu,\nem letras diversas, pelas suas janelas atirarei,\ncomo se viessem de diversos cidadãos,\nescritos todos tendendo à grande opinião\nque Roma tem de seu nome; nos quais obscuramente\na ambição de César será aludida:\ne depois disto, que César se assente seguro;\npois o abalaremos, ou suportaremos dias piores. Sai.","sceneiii~sceneiii~8":"Cena III","thesameastreet~thesameastreet~14":"O mesmo lugar. Uma rua.","thunderandlightningenterfromoppositeside~thhissworddrawnandcicero~72":"Trovões e relâmpagos. Entram, por lados opostos, Casca, com a espada desembainhada, e Cícero.","cicerogoodevencascabroughtyoucaesarhomew~eathlessandwhystareyouso~74":"Cícero — Boa tarde, Casca: levastes César para casa?\nPor que estais sem fôlego? E por que olhais assim?","cascaarenotyoumovedwhenalltheswayofearth~sesthemtosenddestruction~370":"Casca — Não vos abalais, quando todo o domínio da terra\ntreme como coisa insegura? Ó Cícero,\nvi tempestades, quando os ventos ralhadores\nfenderam os carvalhos nodosos, e vi\no ambicioso oceano inchar, enfurecer-se e espumar,\npara se exaltar até as nuvens ameaçadoras:\nmas nunca até esta noite, nunca até agora,\natravessei uma tempestade a gotejar fogo.\nOu há uma guerra civil no céu,\nou então o mundo, atrevido demais com os deuses,\nos incita a enviar destruição.","cicerowhysawyouanythingmorewonderful~youanythingmorewonderful~36":"Cícero — Ora, vistes algo mais maravilhoso?","cascaacommonslaveyouknowhimwellbysighthe~climatethattheypointupon~594":"Casca — Um escravo comum—conheceis bem de vista—\n ergueu a mão esquerda, que flamejava e ardia\ncomo vinte tochas juntas, e contudo a mão,\ninsensível ao fogo, permaneceu sem queimadura.\nAlém disso—desde então não embainhei a espada—\n junto ao Capitólio encontrei um leão,\nque me fitou e passou carrancudo\nsem me molestar: e havia, juntas\nnum monte, uma centena de mulheres espectrais,\ntransformadas pelo medo; que juravam ter visto\nhomens todos em fogo andar para cima e para baixo pelas ruas.\nE ontem a ave da noite pousou\nem pleno meio-dia na praça do mercado,\npiando e guinchando. Quando estes prodígios\nse encontram assim em conjunto, que os homens não digam\n“Estas são as suas razões; são naturais”;\npois creio que são coisas agourentas\npara a região sobre a qual apontam.","ciceroindeeditisastrangedisposedtimebutm~esartothecapitoltomorrow~146":"Cícero — De fato, é um tempo de estranha disposição:\nmas os homens podem interpretar as coisas a seu modo,\ninteiramente fora do propósito das coisas mesmas.\nCésar vem ao Capitólio amanhã?","cascahedothforhedidbidantoniussendwordto~ouhewouldbetheretomorrow~65":"Casca — Vem; pois mandou Antônio\navisar-vos que estará lá amanhã.","cicerogoodnightthencascathisdisturbedsky~isturbedskyisnottowalkin~53":"Cícero — Boa noite então, Casca: este céu perturbado\nnão é para se andar sob ele.","cascafarewellciceroexitcicero~farewellciceroexitcicero~29":"Casca — Adeus, Cícero. Sai Cícero.","entercassius~entercassius~12":"Entra Cássio.","cassiuswhosthere~cassiuswhosthere~16":"Cássio — Quem está aí?","cascaaroman~cascaaroman~11":"Casca — Um romano.","cassiuscascabyyourvoice~cassiuscascabyyourvoice~23":"Cássio — Casca, pela voz.","cascayourearisgoodcassiuswhatnightisthis~odcassiuswhatnightisthis~40":"Casca — Tendes bom ouvido. Cássio, que noite é esta!","cassiusaverypleasingnighttohonestmen~pleasingnighttohonestmen~36":"Cássio — Uma noite muito agradável aos homens honestos.","cascawhoeverknewtheheavensmenaceso~erknewtheheavensmenaceso~34":"Casca — Quem jamais viu os céus ameaçarem assim?","cassiusthosethathaveknowntheearthsofullo~intheaimandveryflashofit~275":"Cássio — Os que viram a terra tão cheia de faltas.\nDe minha parte, andei pelas ruas,\nsubmetendo-me à perigosa noite,\ne, assim desabotoado, Casca, como vedes,\ndescobri o peito à pedra do trovão;\ne quando o azul relâmpago enviesado pareceu abrir\no seio do céu, apresentei-me\nbem na mira e no próprio clarão dele.","cascabutwhereforedidyousomuchtemptthehea~adfulheraldstoastonishus~140":"Casca — Mas por que tentastes tanto os céus?\nÉ próprio dos homens temer e tremer\nquando os deuses poderosíssimos por sinais enviam\ntão terríveis arautos para nos assombrar.","cassiusyouaredullcascaandthosesparksofli~thesestrangeeruptionsare~740":"Cássio — Sois obtuso, Casca, e essas faíscas de vida\nque deveriam estar num romano, ou vos faltam,\nou não as usais. Estais pálido, e fitais,\ne vestis o medo, e vos lançais no espanto,\nao ver a estranha impaciência dos céus:\nmas se quisésseis considerar a verdadeira causa\npor que todos esses fogos, por que todos esses fantasmas que deslizam,\npor que aves e feras fora de sua qualidade e espécie,\npor que velhos desatinam e crianças calculam,\npor que todas essas coisas mudam da sua ordenação,\nsuas naturezas e faculdades predispostas,\npara uma qualidade monstruosa—ora, achareis\nque o céu as infundiu com esses espíritos\npara fazê-las instrumentos de medo e aviso\na algum estado monstruoso.\nAgora poderia eu, Casca, nomear-vos um homem\nmuito semelhante a esta terrível noite,\nque troveja, relampeja, abre sepulturas e ruge\ncomo o leão no Capitólio,\num homem não mais poderoso que vós ou eu\nem ação pessoal, mas tornado prodigioso\ne temível como estas estranhas erupções.","cascatiscaesarthatyoumeanisitnotcassius~hatyoumeanisitnotcassius~39":"Casca — É César que quereis dizer; não é, Cássio?","cassiusletitbewhoitisforromansnowhavethe~sufferanceshowuswomanish~176":"Cássio — Seja quem for: pois os romanos agora\ntêm músculos e membros iguais aos de seus ancestrais;\nmas, ai do tempo! os espíritos de nossos pais morreram,\ne somos governados com o ânimo de nossas mães;\nnosso jugo e nossa tolerância mostram-nos efeminados.","cascaindeedtheysaythesenatorstomorrowmea~veryplacesavehereinitaly~126":"Casca — De fato, dizem que os senadores amanhã\npretendem estabelecer César como rei;\ne ele usará sua coroa por mar e por terra,\nem todo lugar, salvo aqui na Itália.","cassiusiknowwhereiwillwearthisdaggerthen~ffatpleasurethunderstill~410":"Cássio — Sei então onde usarei este punhal;\nCássio libertará Cássio da servidão:\nnisso, ó deuses, fazeis o fraco fortíssimo;\nnisso, ó deuses, derrotais os tiranos:\nnem torre de pedra, nem muralhas de bronze batido,\nnem masmorra sem ar, nem fortes elos de ferro\npodem reter a força do espírito;\nmas a vida, cansada destas barras mundanas,\nnunca carece de poder para se despedir a si mesma.\nSe sei isto, saiba todo o mundo além,\nque a parte da tirania que suporto\nposso sacudir à vontade. Ainda trovões.","cascasocanisoeverybondmaninhisownhandbea~owertocancelhiscaptivity~70":"Casca — Assim posso eu:\nassim todo servo na própria mão leva\no poder de cancelar o seu cativeiro.","cassiusandwhyshouldcaesarbeatyrantthenpo~angersaretomeindifferent~416":"Cássio — E por que então César seria tirano?\nPobre homem! Sei que não seria lobo\nse não visse que os romanos são apenas ovelhas:\nnão seria leão, se os romanos não fossem corças.\nOs que com pressa querem fazer um grande fogo\ncomeçam-no com palhas fracas: que lixo é Roma,\nque entulho e que refugo, quando serve\nde matéria vil para iluminar\ncoisa tão vil como César! Mas, oh, dor,\naonde me levaste? Talvez diga isto\ndiante de um servo bem disposto; então sei\nque minha resposta terá de ser dada. Mas estou armado,\ne os perigos me são indiferentes.","cascayouspeaktocascaandtosuchamanthatisn~neasfaraswhogoesfarthest~150":"Casca — Falais a Casca, e a um homem tal\nque não é mexeriqueiro zombador. Segurai, minha mão:\nsede faccioso pela reparação de todas estas mágoas,\ne porei este meu pé tão longe\ncomo quem for mais longe.","cassiustheresabargainmadenowknowyoucasca~oodyfieryandmostterrible~340":"Cássio — Eis um acordo feito.\nSabei agora, Casca, que já persuadi\nalguns dos romanos de espírito mais nobre\na empreender comigo uma ação\nde consequência honrosa e perigosa;\ne sei que, a esta hora, esperam-me\nno pórtico de Pompeu: pois agora, nesta noite temível,\nnão há movimento nem andar nas ruas;\ne a compleição do elemento\né condizente com a obra que temos em mãos,\nsangrenta, ígnea e terribilíssima.","cascastandcloseawhileforherecomesoneinha~leforherecomesoneinhaste~43":"Casca — Ficai quieto um instante, que aí vem um com pressa.","cassiustiscinnaidoknowhimbyhisgaitheisaf~whimbyhisgaitheisafriend~45":"Cássio — É Cina; conheço-o pelo andar;\né amigo.","entercinna~entercinna~10":"Entra Cina.","cinnawherehasteyouso~cinnawherehasteyouso~20":"Cina, aonde vais com tanta pressa?","cinnatofindoutyouwhosthatmetelluscimber~ouwhosthatmetelluscimber~39":"Cina — Procurar-vos. Quem é esse? Metelo Címber?","cassiusnoitiscascaoneincorporatetoouratt~emptsaminotstaydforcinna~64":"Cássio — Não, é Casca; um incorporado\nàs nossas tentativas. Não me esperam, Cina?","cinnaiamgladontwhatafearfulnightisthisth~fushaveseenstrangesights~79":"Cina — Alegro-me com isso. Que noite terrível é esta!\nDois ou três de nós viram visões estranhas.","cassiusaminotstaydfortellme~siusaminotstaydfortellme~27":"Cássio — Não me esperam? Dize-me.","cinnayesyouareocassiusifyoucouldbutwinth~thenoblebrutustoourparty~62":"Cina — Sim, esperam.\nÓ Cássio, se pudésseis\napenas ganhar o nobre Brutus para o nosso partido—","cassiusbeyoucontentgoodcinnatakethispape~sbrutusandtreboniusthere~238":"Cássio — Contentai-vos: bom Cina, tomai este papel\ne vede que o ponhais na cadeira do pretor,\nonde Brutus possa achá-lo; e atirai este\npela janela dele; fixai este com cera\nna estátua do velho Brutus: feito tudo isto,\nide ao pórtico de Pompeu, onde nos achareis.\nEstão lá Décio Brutus e Trebônio?","cinnaallbutmetelluscimberandhesgonetosee~owthesepapersasyoubademe~100":"Cina — Todos, exceto Metelo Címber; e ele foi\nprocurar-vos em vossa casa. Bem, apressar-me-ei,\ne porei estes papéis como me mandastes.","cassiusthatdonerepairtopompeystheatreexi~xtencounteryieldshimours~170":"Cássio — Feito isso, ide ao teatro de Pompeu. Sai Cina.\nVamos, Casca, vós e eu ainda antes do dia\nveremos Brutus em sua casa: três partes dele\njá são nossas, e o homem inteiro,\nno próximo encontro, se entrega a nós.","cascaohesitshighinallthepeoplesheartsand~etovirtueandtoworthiness~136":"Casca — Oh, ele está alto em todos os corações do povo:\ne o que pareceria ofensa em nós,\nseu semblante, como a mais rica alquimia,\nmudará em virtude e dignidade.","cassiushimandhisworthandourgreatneedofhi~ehimandbesureofhimexeunt~136":"Cássio — Dele, de seu valor e da nossa grande necessidade dele\nconcebestes muito bem. Vamos,\npois é depois da meia-noite; e antes do dia\niremos despertá-lo e assegurar-nos dele. Saem.","romebrutussorchard~romebrutussorchard~18":"Roma. O pomar de Brutus.","enterbrutus~enterbrutus~11":"Entra Brutus.","brutuswhatluciushoicannotbytheprogressof~swhenawakeisaywhatlucius~147":"Brutus — Olá, Lúcio, ei! \nPelo curso das estrelas não consigo \nadivinhar quão perto está o dia. Lúcio, digo eu! \nQuisera que fosse minha a culpa de dormir tão profundo. \nLúcio, vamos! Desperta, digo! Ei, Lúcio!","enterlucius~enterlucius~11":"Entra Lúcio.","luciuscalldyoumylord~luciuscalldyoumylord~20":"Lúcio — Chamastes, meu senhor?","brutusgetmeataperinmystudyluciuswhenitis~lightedcomeandcallmehere~64":"Brutus — Traze-me uma vela ao meu gabinete, Lúcio; \nquando estiver acesa, vem chamar-me aqui.","luciusiwillmylordexit~luciusiwillmylordexit~21":"Lúcio — Assim farei, meu senhor. Sai.","brutusitmustbebyhisdeathandformypartikno~vousandkillhimintheshell~854":"Brutus — Há de ser pela morte dele; e de minha parte, \nnão conheço motivo pessoal para investir contra ele, \nsenão o bem comum. Ele quer ser coroado: \ncomo isso poderia mudar-lhe a natureza, eis a questão. \nÉ o dia luminoso que faz sair a víbora; \ne isso exige andar com cautela. Coroá-lo? Isso... \nE então, concedo, lhe pomos um ferrão, \ncom que, a seu talante, possa fazer perigo. \nO abuso da grandeza está em que ela aparta \na piedade do poder; e, para falar a verdade sobre César, \nnunca soube que suas paixões pesassem \nmais que sua razão. Mas é prova comum \nque a humildade é a escada da ambição jovem, \npara a qual o que sobe volta o rosto; \nmas, tão logo alcança o último degrau, \nvolta então à escada as costas, \nolha as nuvens, desdenhando os baixos degraus \npor onde ascendeu. Assim pode César fazer. \nPortanto, para que não o faça, previne-se. E, já que a querela \nnão pode alegar pretexto pelo que ele é, \nformule-se assim: que o que ele é, aumentado, \nchegaria a estes e àqueles extremos; \ne por isso o tomemos por ovo de serpente \nque, chocado, como é de sua espécie, se faria daninho, \ne matemo-lo na casca.","reenterlucius~reenterlucius~13":"Reentra Lúcio.","luciusthetaperburnethinyourclosetsirsear~nttobedgiveshimtheletter~146":"Lúcio — A vela arde no vosso gabinete, senhor. \nProcurando uma pederneira junto à janela, achei \neste papel, assim lacrado; e tenho certeza \nde que não estava ali quando fui deitar. Entrega-lhe a carta.","brutusgetyoutobedagainitisnotdayisnottom~omorrowboytheidesofmarch~62":"Brutus — Volta para a cama; ainda não é dia. \nNão são amanhã, rapaz, os idos de março?","luciusiknownotsir~luciusiknownotsir~17":"Lúcio — Não sei, senhor.","brutuslookinthecalendarandbringmeword~hecalendarandbringmeword~37":"Brutus — Olha no calendário e traze-me a resposta.","luciusiwillsirexit~luciusiwillsirexit~18":"Lúcio — Sim, senhor. Sai.","brutustheexhalationswhizzingintheairgive~etitionatthehandofbrutus~503":"Brutus — Os meteoros que sibilam no ar \ndão tanta luz que posso ler por eles. Abre a carta e lê. \n“Brutus, tu dormes: desperta e vê-te a ti mesmo. \nHá de Roma, etc. Fala, fere, repara! \nBrutus, tu dormes: desperta!” \nTais incitamentos têm sido muitas vezes deixados \nonde os tenho encontrado. \n“Há de Roma, etc.” Assim devo completar: \nHá de Roma ficar sob o temor de um só homem? Como, Roma? \nMeus antepassados das ruas de Roma \nexpulsaram o Tarquínio, quando se fez chamar rei. \n“Fala, fere, repara!” Pedem-me, então, \nque fale e fira? Ó Roma, eu te faço promessa: \nse a reparação seguir, receberás \nteu pleno pedido da mão de Brutus!","luciussirmarchiswastedfourteendaysknocki~urteendaysknockingwithin~48":"Lúcio — Senhor, março consumiu catorze dias. Batem à porta.","brutustisgoodgotothegatesomebodyknocksex~henatureofaninsurrection~313":"Brutus — Está bem. Vai ao portão; alguém bate. Sai Lúcio. \nDesde que Cássio me aguçou contra César, \nnão dormi. \nEntre o cometimento de uma coisa terrível \ne o primeiro impulso, todo o intervalo é \ncomo um fantasma, ou um sonho hediondo: \no Gênio e os instrumentos mortais \nestão então em conselho; e o estado do homem, \nqual pequeno reino, sofre então \na natureza de uma insurreição.","luciussirtisyourbrothercassiusatthedoorw~oorwhodothdesiretoseeyou~60":"Lúcio — Senhor, é vosso cunhado Cássio à porta, \nque deseja ver-vos.","brutusishealone~brutusishealone~15":"Brutus — Está só?","luciusnosirtherearemoewithhim~snosirtherearemoewithhim~29":"Lúcio — Não, senhor, há mais gente com ele.","brutusdoyouknowthem~brutusdoyouknowthem~19":"Brutus — Conheces essa gente?","luciusnosirtheirhatsarepluckdabouttheire~verthembyanymarkoffavour~125":"Lúcio — Não, senhor; têm os chapéus enterrados até as orelhas, \ne metade do rosto sepultada nas capas, \nde modo que de nenhuma maneira os posso reconhecer \npor qualquer sinal de feição.","brutusletementerexitluciustheyarethefact~tohidetheefromprevention~312":"Brutus — Deixa-os entrar. Sai Lúcio. \nSão a facção. Ó conspiração, \ntens vergonha de mostrar tua fronte perigosa à noite, \nquando os males andam mais livres? Ó, então de dia, \nonde acharás caverna escura bastante \npara mascarar teu rosto monstruoso? Não busques nenhuma, conspiração; \nesconde-a em sorrisos e afabilidade: \npois se andares com tua aparência natural, \nnem o próprio Érebo seria sombrio bastante \npara te ocultar da prevenção.","entertheconspiratorscassiuscascadeciusci~telluscimberandtrebonius~69":"Entram os conspiradores, Cássio, Casca, Décio, Cina, Metelo Címber e Trebônio.","cassiusithinkwearetoobolduponyourrestgoo~rrowbrutusdowetroubleyou~67":"Cássio — Creio que somos atrevidos demais com o vosso repouso. \nBom dia, Brutus; incomodamos-vos?","brutusihavebeenupthishourawakeallnightkn~ementhatcomealongwithyou~71":"Brutus — Estou de pé há uma hora, desperto a noite toda. \nConheço estes homens que vêm convosco?","cassiusyeseverymanofthemandnomanherebuth~earsofyouthisistrebonius~143":"Cássio — Sim, a todos eles, e nenhum aqui \nque não vos honre; e todos desejam \nque tivésseis de vós mesmo aquela opinião \nque todo nobre romano tem de vós. \nEste é Trebônio.","brutusheiswelcomehither~brutusheiswelcomehither~23":"Brutus — Seja bem-vindo.","cassiusthisdeciusbrutus~cassiusthisdeciusbrutus~23":"Cássio — Este, Décio Brutus.","brutusheiswelcometoo~brutusheiswelcometoo~20":"Brutus — Também seja bem-vindo.","cassiusthiscascathiscinnaandthismetellus~nnaandthismetelluscimber~46":"Cássio — Este, Casca; este, Cina; e este, Metelo Címber.","brutustheyareallwelcomewhatwatchfulcares~sbetwixtyoureyesandnight~84":"Brutus — Todos são bem-vindos. \nQue cuidados vigilantes se interpõem \nentre os vossos olhos e a noite?","cassiusshallientreatawordbrutusandcassiu~dbrutusandcassiuswhisper~48":"Cássio — Posso pedir uma palavra? Brutus e Cássio cochicham.","deciushereliestheeastdothnotthedaybreakh~stdothnotthedaybreakhere~43":"Décio — Aqui fica o oriente: não rompe o dia aqui?","cascano~cascano~7":"Casca — Não.","cinnaopardonsiritdothandyongraylinesthat~cloudsaremessengersofday~71":"Cina — Oh, perdão, senhor, rompe; e aquelas linhas cinzentas \nque rendilham as nuvens são mensageiras do dia.","cascayoushallconfessthatyouarebothdeceiv~asthecapitoldirectlyhere~246":"Casca — Haveis de confessar que ambos vos enganais. \nAqui, para onde aponto minha espada, o sol se levanta, \nque vai muito para o sul, \npesando a jovem estação do ano. \nDaqui a uns dois meses, mais alto para o norte, \nele apresenta primeiro o seu fogo; e o alto oriente \nfica, como o Capitólio, diretamente aqui.","brutusgivemeyourhandsalloveronebyone~yourhandsalloveronebyone~36":"Brutus — Dai-me as mãos todos, um por um.","cassiusandletusswearourresolution~dletusswearourresolution~33":"Cássio — E juremos a nossa resolução.","brutusnonotanoathifnotthefaceofmenthesuf~misethathathpassdfromhim~889":"Brutus — Não, juramento não: se não o rosto dos homens, \no sofrimento de nossas almas, o abuso do tempo — \nse estes são motivos fracos, rompamos logo, \ne cada homem daqui para seu leito ocioso; \nque a tirania de olhar altivo prossiga à solta, \naté que cada um caia por sorteio. Mas se estes, \ncomo estou certo de que o fazem, têm fogo bastante \npara inflamar covardes e para aço de valor \nnos ânimos derretidos das mulheres, então, patrícios, \nque estímulo precisamos senão a nossa própria causa \npara nos picar à reparação? Que outro laço \nsenão romanos discretos, que deram a palavra \ne não a trairão? E que outro juramento \nsenão honestidade empenhada com honestidade, \nde que isto será, ou cairemos por isso? \nJurem padres e covardes e homens cautelosos, \nvelhas carcaças fracas e tais almas sofredoras \nque acolhem afrontas; jurem por causas más \ncriaturas de quem se duvida; mas não maculeis \na virtude íntegra de nosso empreendimento, \nnem o ânimo indomável de nossos espíritos, \npensando que nossa causa ou nossa execução \nprecisasse de um juramento; quando cada gota de sangue \nque todo romano leva, e nobremente leva, \né culpada de uma bastardia particular, \nse ele quebrar a menor partícula \nde qualquer promessa que lhe saiu da boca.","cassiusbutwhatofciceroshallwesoundhimith~illstandverystrongwithus~70":"Cássio — Mas e Cícero? Sondaremos ele? \nCreio que ficará muito firme conosco.","cascaletusnotleavehimout~cascaletusnotleavehimout~24":"Casca — Não o deixemos de fora.","cinnanobynomeans~cinnanobynomeans~16":"Cina — Não, de modo algum.","metellusoletushavehimforhissilverhairswi~tallbeburiedinhisgravity~197":"Metelo — Oh, tenhamo-lo, pois seus cabelos de prata \nnos granjearão boa opinião \ne comprarão votos de homens para louvar nossos feitos: \ndir-se-á que seu juízo guiou nossas mãos; \nnossa juventude e destempero não aparecerão em nada, \nmas tudo ficará enterrado em sua gravidade.","brutusonamehimnotletusnotbreakwithhimfor~nythingthatothermenbegin~82":"Brutus — Oh, não o nomeeis: não o abordemos; \npois ele nunca seguirá coisa alguma \nque outros homens comecem.","cassiusthenleavehimout~cassiusthenleavehimout~22":"Cássio — Então deixemo-lo de fora.","cascaindeedheisnotfit~cascaindeedheisnotfit~21":"Casca — Com efeito, não serve.","deciusshallnomanelsebetouchdbutonlycaesa~lsebetouchdbutonlycaesar~41":"Décio — Nenhum outro será atingido senão só César?","cassiusdeciuswellurgedithinkitisnotmeetm~onyandcaesarfalltogether~231":"Cássio — Décio, bem lembrado: creio que não convém \nque Marco Antônio, tão amado por César, \nsobreviva a César: acharemos nele \num hábil maquinador; e, sabeis, seus meios, \nse os aprimorar, bem podem estender-se \naté nos molestar a todos: para prevenir o que, \ncaiam juntos Antônio e César.","brutusourcoursewillseemtoobloodycaiuscas~sarmwhencaesarsheadisoff~712":"Brutus — Nosso proceder parecerá sanguinário demais, Caio Cássio, \ncortar a cabeça e depois retalhar os membros, \ncomo ira na morte e inveja depois; \npois Antônio não passa de um membro de César: \nsejamos sacrificadores, mas não açougueiros, Caio. \nTodos nos erguemos contra o espírito de César; \ne no espírito dos homens não há sangue: \nÓ, pudéssemos então alcançar o espírito de César \nsem desmembrar César! Mas, ai, \nCésar tem de sangrar por isso! E, gentis amigos, \nmatemo-lo com ousadia, mas não com ira; \ntrinchemo-lo como prato digno dos deuses, \nnão o talhemos como carcaça para cães; \ne que nossos corações, como sutis amos, \naticem seus servos a um ato de furor \ne depois pareçam repreendê-los. Isto tornará \nnosso propósito necessário e não invejoso: \no que, assim aparecendo aos olhos do povo, \nnos fará chamar purificadores, não assassinos. \nE quanto a Marco Antônio, não penseis nele; \npois nada pode mais que o braço de César \nquando a cabeça de César estiver cortada.","cassiusyetifearhimforintheingraftedloveh~aftedlovehebearstocaesar~54":"Cássio — Contudo o temo; \npois no amor enraizado que tem a César —","brutusalasgoodcassiusdonotthinkofhimifhe~towildnessandmuchcompany~168":"Brutus — Ai, bom Cássio, não penseis nele: \nse ama César, tudo o que pode fazer \né a si mesmo, entristecer-se e morrer por César: \ne muito seria que o fizesse; pois é dado \na jogos, a desvarios e a muita companhia.","treboniusthereisnofearinhimlethimnotdief~hishereafterclockstrikes~87":"Trebônio — Nenhum receio há nele: que não morra; \npois viverá, e rirá disto depois. Soa o relógio.","brutuspeacecounttheclock~brutuspeacecounttheclock~24":"Brutus — Silêncio! Contai o relógio.","cassiustheclockhathstrickenthree~heclockhathstrickenthree~32":"Cássio — O relógio deu três horas.","treboniustistimetopart~treboniustistimetopart~22":"Trebônio — É hora de nos separarmos.","cassiusbutitisdoubtfulyetwhethercaesarwi~ldhimfromthecapitoltoday~272":"Cássio — Mas ainda é duvidoso \nse César sairá hoje, ou não; \npois tornou-se supersticioso de uns tempos para cá, \nbem longe da opinião principal que tinha outrora \nsobre fantasias, sonhos e cerimônias: \npode ser que estes prodígios evidentes, \no terror insólito desta noite, \ne a persuasão de seus áugures \no retenham hoje longe do Capitólio.","deciusneverfearthatifhebesoresolvedicano~willbringhimtothecapitol~303":"Décio — Não temais isso: se ele estiver decidido, \neu o posso dobrar; pois ele gosta de ouvir \nque unicórnios se enganam com árvores, \nursos com espelhos, elefantes com covas, \nleões com redes e homens com aduladores; \nmas quando lhe digo que odeia aduladores, \ndiz que sim, sendo então o mais adulado. \nDeixai comigo; \npois sei dar à sua índole a verdadeira inclinação, \ne o levarei ao Capitólio.","cassiusnaywewillallofusbetheretofetchhim~allofusbetheretofetchhim~40":"Cássio — Não, iremos todos buscá-lo.","brutusbytheeighthhouristhattheuttermost~thhouristhattheuttermost~39":"Brutus — Pela oitava hora: é esse o limite?","cinnabethattheuttermostandfailnotthen~euttermostandfailnotthen~37":"Cina — Seja esse o limite, e não falteis então.","metelluscaiusligariusdothbearcaesarhardw~oneofyouhavethoughtofhim~105":"Metelo — Caio Ligário guarda rancor a César, \nque o repreendeu por falar bem de Pompeu: \nespanto-me de nenhum de vós ter pensado nele.","brutusnowgoodmetellusgoalongbyhimheloves~uthitherandillfashionhim~101":"Brutus — Agora, bom Metelo, passa por casa dele: \nele me quer bem, e dei-lhe razões; \nmanda-o apenas aqui, e eu o moldarei.","cassiusthemorningcomesuponswellleaveyoub~showyourselvestrueromans~129":"Cássio — A manhã nos alcança: deixar-vos-emos, Brutus. \nE, amigos, dispersai-vos; mas lembrai todos \no que dissestes, e mostrai-vos verdadeiros romanos.","brutusgoodgentlemenlookfreshandmerrilyle~reforethousleepstsosound~330":"Brutus — Bons senhores, mostrai rostos frescos e alegres; \nque nossos semblantes não vistam nossos propósitos, \nmas levai-o como nossos atores romanos, \ncom ânimo infatigável e constância formal: \ne assim bom dia a todos vós. Saem todos, menos Brutus. \nRapaz! Lúcio! Dormindo a sono solto? Não importa; \ngoza o orvalho de mel pesado do sono: \nnão tens imagens nem fantasias, \nque o cuidado inquieto desenha no cérebro dos homens; \npor isso dormes tão profundo.","enterportia~enterportia~11":"Entra Pórcia.","portiabrutusmylord~portiabrutusmylord~18":"Pórcia — Brutus, meu senhor!","brutusportiawhatmeanyouwhereforeriseyoun~itiontotherawcoldmorning~110":"Brutus — Pórcia, que fazeis? Por que vos levantais agora? \nNão é para vossa saúde expor assim \nvossa frágil condição à manhã crua e fria.","portianorforyoursneitheryouveungentlybru~ntedwithyourcauseofgrief~671":"Pórcia — Nem para a vossa tampouco. Rudemente, Brutus, \nfurtastes-vos do meu leito: e ontem à noite, na ceia, \nlevantastes-vos de súbito, e andastes de um lado a outro, \nmeditando e suspirando, de braços cruzados, \ne quando vos perguntei qual era a causa, \nencarastes-me com olhares duros; \ninsisti; então coçastes a cabeça, \ne com demasiada impaciência batestes o pé; \nmesmo assim insisti, e não respondestes, \nmas, com um aceno de mão irado, \nfizestes sinal que vos deixasse: assim fiz; \ntemendo reforçar aquela impaciência \nque parecia já demais inflamada, e ao mesmo tempo \nesperando que fosse só um efeito de humor, \nque às vezes tem sua hora em todo homem. \nNão vos deixa comer, nem falar, nem dormir, \ne se pudesse agir tanto sobre vossa aparência \nquanto prevaleceu sobre vosso temperamento, \nnão vos conheceria, Brutus. Caro senhor, \nfazei-me saber a causa da vossa aflição.","brutusiamnotwellinhealthandthatisall~wellinhealthandthatisall~36":"Brutus — Não estou bem de saúde, e é só isso.","portiabrutusiswiseandwerehenotinhealthhe~mbracethemeanstocomebyit~70":"Pórcia — Brutus é sábio e, se não tivesse saúde, \nabraçaria os meios de obtê-la.","brutuswhysoidogoodportiagotobed~hysoidogoodportiagotobed~31":"Brutus — Pois é o que faço. Boa Pórcia, ide para a cama.","portiaisbrutussickandisitphysicaltowalku~eirfacesevenfromdarkness~568":"Pórcia — Brutus está doente? E é saudável \nandar desabotoado e sorver os humores \nda manhã úmida? Ora, Brutus está doente, \ne sai furtivo do leito saudável, \npara desafiar o vil contágio da noite \ne tentar o ar catarral e impuro \npara acrescentar à sua doença? Não, meu Brutus; \ntendes algum mal enfermo na mente, \nque, pelo direito e virtude do meu posto, \neu devo conhecer: e, de joelhos, \nconjuro-vos, por minha beleza outrora louvada, \npor todos os vossos votos de amor e aquele grande voto \nque nos incorporou e fez um só, \nque me desvendeis, a vós mesmo, vossa metade, \npor que estais pesaroso, e que homens esta noite \nvieram procurar-vos: pois aqui estiveram \nseis ou sete, que escondiam o rosto \naté da escuridão.","brutuskneelnotgentleportia~utuskneelnotgentleportia~26":"Brutus — Não vos ajoelheis, gentil Pórcia.","portiaishouldnotneedifyouweregentlebrutu~isbrutusharlotnothiswife~302":"Pórcia — Não precisaria, se fôsseis o gentil Brutus. \nDentro do laço do matrimônio, dizei-me, Brutus, \nestá excetuado que eu não saiba segredos \nque vos pertençam? Sou eu vós mesmo \napenas, por assim dizer, em parte ou limitação, \npara vos fazer companhia às refeições, confortar vosso leito \ne falar-vos às vezes? Habito eu apenas nos subúrbios \ndo vosso bom prazer? Se não é mais que isso, \nPórcia é a meretriz de Brutus, não a esposa.","brutusyouaremytrueandhonourablewifeasdea~dropsthatvisitmysadheart~82":"Brutus — Sois minha verdadeira e honrada esposa, \ntão cara para mim quanto as gotas rubras \nque visitam meu triste coração.","portiaifthisweretruethenshouldiknowthiss~eandnotmyhusbandssecrets~368":"Pórcia — Se isso fosse verdade, então eu saberia este segredo. \nConcedo que sou mulher; mas também \numa mulher que o senhor Brutus tomou por esposa: \nconcedo que sou mulher; mas também \numa mulher de boa reputação, filha de Catão. \nPensais que não sou mais forte que meu sexo, \nsendo assim tão bem de pai e de marido? \nDizei-me vossos desígnios, não os revelarei: \nfiz forte prova de minha constância, \ndando-me a mim mesma uma ferida voluntária \naqui, na coxa: posso suportar isso com paciência, \ne não os segredos de meu marido?","brutusoyegodsrendermeworthyofthisnoblewi~rtialuciuswhosthatknocks~247":"Brutus — Ó deuses, \ntornai-me digno desta nobre esposa! Batem à porta. \nEscutai, escutai! Alguém bate: Pórcia, entrai um instante; \ne logo logo vosso peito partilhará \nos segredos do meu coração. \nTodos os meus compromissos vos explicarei, \ntodos os caracteres de minha fronte triste: \ndeixai-me com pressa. Sai Pórcia. \nLúcio, quem é que bate?","reenterluciuswithligarius~eenterluciuswithligarius~25":"Reentra Lúcio com Ligário.","luciushereisasickmanthatwouldspeakwithyo~manthatwouldspeakwithyou~41":"Lúcio — Aqui está um homem doente que quer falar-vos.","brutuscaiusligariusthatmetellusspakeofbo~andasidecaiusligariushow~67":"Brutus — Caio Ligário, de quem Metelo falou. \nRapaz, põe-te de lado. Caio Ligário! Então?","ligariusvouchsafegoodmorrowfromafeebleto~dmorrowfromafeebletongue~44":"Ligário — Dignai-vos aceitar o bom dia de uma língua fraca.","brutusowhatatimehaveyouchoseoutbravecaiu~chiefwouldyouwerenotsick~75":"Brutus — Oh, que hora escolhestes, bravo Caio, \npara usar lenço na cabeça! Quisera que não estivésseis doente!","ligariusiamnotsickifbrutushaveinhandanye~oitworthythenameofhonour~67":"Ligário — Não estou doente, se Brutus tem entre mãos \nalgum feito digno do nome de honra.","brutussuchanexploithaveiinhandligariusha~uahealthfuleartohearofit~67":"Brutus — Tal feito tenho entre mãos, Ligário, \ntivésseis ouvido são para ouvi-lo.","ligariusbyallthegodsthatromansbowbeforei~thebetterofthemwhatstodo~229":"Ligário — Por todos os deuses diante dos quais os romanos se curvam, \naqui rejeito minha doença! Alma de Roma! \nBravo filho, descendente de honrados lombos! \nTu, como exorcista, evocaste \nmeu espírito amortecido. Manda-me agora correr, \ne lutarei com coisas impossíveis; \nsim, levarei a melhor sobre elas. O que há por fazer?","brutusapieceofworkthatwillmakesickmenwho~thatwillmakesickmenwhole~42":"Brutus — Uma obra que tornará sãos os homens doentes.","ligariusbutarenotsomewholethatwemustmake~ewholethatwemustmakesick~44":"Ligário — Mas não há alguns sãos que devemos tornar doentes?","brutusthatmustwealsowhatitismycaiusishal~egoingtowhomitmustbedone~83":"Brutus — Isso também devemos. O que é, meu Caio, \ndesvendar-te-ei, enquanto caminhamos \npara aquele a quem se há de fazer.","ligariussetonyourfootandwithaheartnewfir~iceththatbrutusleadsmeon~101":"Ligário — Pondo-vos a caminho, \ne com o coração de novo em fogo eu vos sigo, \npara fazer não sei o quê: mas basta \nque Brutus me conduza.","brutusfollowmethenexeunt~brutusfollowmethenexeunt~24":"Brutus — Segue-me, então. Saem.","caesarshouse~caesarshouse~12":"A casa de César.","thunderandlightningentercaesarinhisnight~ntercaesarinhisnightgown~44":"Trovão e relâmpago. Entra César, de camisola.","caesarnorheavennorearthhavebeenatpeaceto~eymurdercaesarwhoswithin~114":"César — Nem o céu nem a terra tiveram paz esta noite: \ntrês vezes gritou Calpúrnia em sonho: \n“Socorro, ei! Assassinam César!” Quem está aí?","enteraservant~enteraservant~13":"Entra um Criado.","servantmylord~servantmylord~13":"Criado — Meu senhor?","caesargobidthepriestsdopresentsacrificea~metheiropinionsofsuccess~71":"César — Vai ordenar aos sacerdotes que façam sacrifício agora \ne traze-me o parecer deles sobre o êxito.","servantiwillmylordexit~servantiwillmylordexit~22":"Criado — Assim farei, meu senhor. Sai.","entercalpurnia~entercalpurnia~14":"Entra Calpúrnia.","calpurniawhatmeanyoucaesarthinkyoutowalk~tstiroutofyourhousetoday~79":"Calpúrnia — Que quereis, César? Pensais em sair a pé? \nHoje não saireis de vossa casa.","caesarcaesarshallforththethingsthatthrea~eofcaesartheyarevanished~112":"César — César sairá: as coisas que me ameaçaram \nsó olharam para as minhas costas; quando virem \no rosto de César, desvanecem-se.","calpurniacaesarineverstoodonceremoniesye~yondalluseandidofearthem~477":"Calpúrnia — César, nunca dei importância a cerimônias, \ncontudo agora me assustam. Há alguém lá dentro \nque, além das coisas que ouvimos e vimos, \nrelata visões horríveis vistas pela ronda. \nUma leoa pariu nas ruas; \ne sepulturas se abriram e entregaram seus mortos; \nferozes guerreiros de fogo lutaram nas nuvens, \nem fileiras e esquadrões e na exata forma da guerra, \nque chuviscaram sangue sobre o Capitólio; \no fragor da batalha retumbou no ar, \ncavalos relincharam, e moribundos gemeram, \ne fantasmas gritaram e guincharam pelas ruas. \nÓ César! Estas coisas passam de todo o costume, \ne eu as temo.","caesarwhatcanbeavoidedwhoseendispurposed~worldingeneralastocaesar~127":"César — O que se pode evitar, \ncujo fim é decretado pelos deuses poderosos? \nContudo César sairá; pois estas predições \nvalem para o mundo em geral como para César.","calpurniawhenbeggarsdietherearenocometss~zeforththedeathofprinces~90":"Calpúrnia — Quando morrem mendigos, não se veem cometas; \nos próprios céus flamejam a morte dos príncipes.","caesarcowardsdiemanytimesbeforetheirdeat~ndwillcomewhenitwillcome~197":"César — Os covardes morrem muitas vezes antes de morrer; \nos valentes só provam a morte uma vez. \nDe todas as maravilhas que já ouvi, \nparece-me a mais estranha que os homens tenham medo; \nvendo que a morte, fim necessário, \nvirá quando vier.","reenterservant~reenterservant~14":"Reentra o Criado.","whatsaytheaugurers~whatsaytheaugurers~18":"Que dizem os áugures?","servanttheywouldnothaveyoutostirforthtod~findaheartwithinthebeast~114":"Criado — Não querem que saiais hoje. \nTirando as entranhas de uma oferenda, \nnão puderam achar coração dentro do animal.","caesarthegodsdothisinshameofcowardicecae~bleandcaesarshallgoforth~244":"César — Os deuses fazem isto para envergonhar a covardia: \nCésar seria uma besta sem coração, \nse ficasse em casa hoje por medo. \nNão, César não ficará: o perigo sabe muito bem \nque César é mais perigoso que ele: \nsomos dois leões paridos no mesmo dia, \ne eu o mais velho e mais terrível: \ne César sairá.","calpurniaalasmylordyourwisdomisconsumedi~euponmykneeprevailinthis~208":"Calpúrnia — Ai, meu senhor, \nvossa sabedoria se consome em confiança. \nNão saiais hoje: chamai de meu medo \nque vos prende em casa, e não do vosso. \nMandaremos Marco Antônio ao Senado; \ne ele dirá que não estais bem hoje: \nDeixai-me, de joelhos, prevalecer nisto.","caesarmarkantonyshallsayiamnotwellandfor~thyhumouriwillstayathome~64":"César — Marco Antônio dirá que não estou bem; \ne, por teu capricho, ficarei em casa.","enterdecius~enterdecius~11":"Entra Décio.","heresdeciusbrutusheshalltellthemso~sbrutusheshalltellthemso~34":"Eis Décio Brutus, ele lhes dirá isso.","deciuscaesarallhailgoodmorrowworthycaesa~fetchyoutothesenatehouse~72":"Décio — César, salve! Bom dia, digno César: \nvenho buscar-vos para o Senado.","caesarandyouarecomeinveryhappytimetobear~ometodaytellthemsodecius~162":"César — E chegas em momento muito feliz, \npara levar minha saudação aos senadores \ne dizer-lhes que não irei hoje: \nnão posso, é falso, e que não ouso, mais falso ainda: \nnão irei hoje: dize-lhes isso, Décio.","calpurniasayheissick~calpurniasayheissick~20":"Calpúrnia — Dizei que está doente.","caesarshallcaesarsendaliehaveiinconquest~ellthemcaesarwillnotcome~127":"César — Enviará César uma mentira? \nEstendi tão longe meu braço em conquistas \npara ter medo de dizer a verdade a barbas brancas? \nDécio, vai dizer-lhes que César não virá.","deciusmostmightycaesarletmeknowsomecause~elaughdatwhenitellthemso~70":"Décio — Poderosíssimo César, deixai-me saber alguma causa, \npara que não riam de mim quando lhes disser isso.","caesarthecauseisinmywilliwillnotcomethat~thatiwillstayathometoday~396":"César — A causa está na minha vontade: não irei; \nisso basta para satisfazer o Senado. \nMas para tua satisfação particular, \nporque te quero bem, vou deixar-te saber: \nCalpúrnia aqui, minha esposa, me retém em casa: \nsonhou esta noite que viu minha estátua, \nque, como uma fonte de cem bicas, \ncorria sangue puro; e muitos romanos vigorosos \nvinham sorrindo e nele banhavam as mãos: \ne ela os toma por avisos, e presságios, \ne males iminentes; e de joelhos \nrogou-me que ficasse em casa hoje.","deciusthisdreamisallamissinterpreteditwa~lpurniasdreamissignified~275":"Décio — Este sonho está todo mal interpretado; \nfoi uma visão bela e afortunada: \nvossa estátua jorrando sangue por muitos canos, \nem que tantos romanos sorridentes se banharam, \nsignifica que de vós a grande Roma sugará \nsangue que revigora, e que grandes homens se acotovelarão \npor tinturas, manchas, relíquias e brasões. \nIsto é o que significa o sonho de Calpúrnia.","caesarandthiswayhaveyouwellexpoundedit~ayhaveyouwellexpoundedit~38":"César — E assim o expusestes bem.","deciusihavewhenyouhaveheardwhaticansayan~ndreasontomyloveisliable~420":"Décio — Fi-lo, quando ouvirdes o que posso dizer: \ne sabei agora: o Senado resolveu \ndar neste dia uma coroa ao poderoso César. \nSe lhes mandardes dizer que não ireis, \nsuas mentes podem mudar. Além disso, seria zombaria \nfácil de lançar, alguém dizer: \n“Dissolva-se o Senado até outro dia, \nquando a esposa de César tiver melhores sonhos.” \nSe César se esconde, não sussurrarão: \n“Vede, César tem medo”? \nPerdoai-me, César; pois o meu caro, caríssimo amor \npor nosso empreendimento manda-me dizer-vos isto; \ne a razão está sujeita ao meu amor.","caesarhowfoolishdoyourfearsseemnowcalpur~emgivememyrobeforiwillgo~90":"César — Quão tolos parecem agora os teus medos, Calpúrnia! \nEnvergonho-me de ter cedido a eles. \nDai-me o manto, pois irei.","enterpubliusbrutusligariusmetelluscascat~uscascatreboniusandcinna~56":"Entram Públio, Brutus, Ligário, Metelo, Casca, Trebônio e Cina.","andlookwherepubliusiscometofetchme~republiusiscometofetchme~34":"E olha, Públio veio buscar-me.","publiusgoodmorrowcaesar~publiusgoodmorrowcaesar~23":"Públio — Bom dia, César.","caesarwelcomepubliuswhatbrutusareyoustir~madeyouleanwhatistoclock~155":"César — Bem-vindo, Públio. \nComo, Brutus, também vós madrugastes? \nBom dia, Casca. Caio Ligário, \nCésar nunca foi tanto vosso inimigo \nquanto essa mesma febre que vos deixou magro. \nQue horas são?","brutuscaesartisstruckeneight~uscaesartisstruckeneight~28":"Brutus — César, deram oito horas.","caesarithankyouforyourpainsandcourtesy~uforyourpainsandcourtesy~38":"César — Agradeço-vos o incômodo e a cortesia.","enterantony~enterantony~11":"Entra Antônio.","seeantonythatrevelslongonightsisnotwiths~andingupgoodmorrowantony~65":"Vede! Antônio, que folga até tarde pelas noites, \nestá de pé, apesar disso. Bom dia, Antônio.","antonysotomostnoblecaesar~ntonysotomostnoblecaesar~25":"Antônio — O mesmo ao nobilíssimo César.","caesarbidthempreparewithiniamtoblametobe~earmethatimayrememberyou~169":"César — Mandai preparar lá dentro: \ntenho culpa de me fazerem esperar assim. \nAgora, Cina; agora, Metelo; ora, Trebônio! \nTenho uma hora de conversa guardada para vós; \nlembrai de me visitar hoje: \nficai perto de mim, para que me lembre de vós.","treboniuscaesariwillasideandsonearwillib~shallwishihadbeenfurther~84":"Trebônio — César, assim farei: à parte e tão perto estarei, \nque vossos melhores amigos desejarão que eu estivesse mais longe.","caesargoodfriendsgoinandtastesomewinewit~illstraightwaygotogether~84":"César — Bons amigos, entrai, e provai um pouco de vinho comigo; \ne nós, como amigos, iremos logo juntos.","brutusasidethateverylikeisnotthesameocae~syearnstothinkuponexeunt~82":"Brutus — À parte. Que cada semelhante não seja o mesmo, ó César, \no coração de Brutus se aflige ao pensar! Saem.","astreetnearthecapitol~astreetnearthecapitol~21":"Uma rua perto do Capitólio.","enterartemidorusreadingapaper~artemidorusreadingapaper~29":"Entra Artemidoro, lendo um papel.","artemidoruscaesarbewareofbrutustakeheedo~dtheethyloverartemidorus~329":"Artemidoro — “César, guarda-te de Brutus; toma cuidado com Cássio; não te aproximes de Casca; vigia Cina; não confies em Trebônio; observa bem Metelo Címber: Décio Brutus não te ama: fizeste mal a Caio Ligário. Há um só pensamento em todos estes homens, e é voltado contra César. Se não és imortal, olha em redor: a segurança abre caminho à conspiração. Os deuses poderosos te defendam! Teu amigo, “Artemidoro.”","herewillistandtillcaesarpassalongandasas~thtraitorsdocontriveexit~192":"Aqui ficarei até César passar, \ne como suplicante lhe darei isto. \nMeu coração lamenta que a virtude não possa viver \nfora dos dentes da inveja. \nSe leres isto, ó César, poderás viver; \nSe não, as Parcas com traidores conspiram. Sai.","sceneiv~sceneiv~7":"Cena IV","anotherpartofthesamestreetbeforethehouse~etbeforethehouseofbrutus~48":"Outra parte da mesma rua, diante da casa de Brutus.","enterportiaandlucius~enterportiaandlucius~20":"Entram Pórcia e Lúcio.","portiaipritheeboyruntothesenatehousestay~ttheegonewhydostthoustay~82":"Pórcia — Peço-te, rapaz, corre ao Senado; \nnão pares para me responder, mas vai-te: \nPor que ficas?","luciustoknowmyerrandmadam~uciustoknowmyerrandmadam~25":"Lúcio — Para saber meu recado, senhora.","portiaiwouldhavehadtheethereandhereagain~eepcounselartthouhereyet~218":"Pórcia — Queria ter-te lá, e aqui de volta, \nantes de poder dizer-te o que farás lá. \nÓ constância, sê forte a meu lado, \npõe uma montanha imensa entre meu coração e minha língua! \nTenho mente de homem, mas força de mulher. \nQuão difícil é para as mulheres guardar segredo! \nAinda estás aqui?","luciusmadamwhatshouldidoruntothecapitola~eturntoyouandnothingelse~83":"Lúcio — Senhora, que devo fazer? \nCorrer ao Capitólio, e nada mais? \nE assim voltar a vós, e nada mais?","portiayesbringmewordboyifthylordlookwell~imharkboywhatnoiseisthat~132":"Pórcia — Sim, traze-me notícia, rapaz, se teu senhor parece bem, \npois saiu enfermo: e toma boa nota \ndo que César faz, que suplicantes o cercam. \nEscuta, rapaz! Que barulho é esse?","luciusihearnonemadam~luciusihearnonemadam~20":"Lúcio — Não ouço nenhum, senhora.","portiapritheelistenwelliheardabustlingru~ndbringsitfromthecapitol~85":"Pórcia — Peço-te, escuta bem; \nouvi um rumor agitado, como uma briga, \ne o vento o traz do Capitólio.","luciussoothmadamihearnothing~ussoothmadamihearnothing~28":"Lúcio — Em verdade, senhora, não ouço nada.","enterthesoothsayer~enterthesoothsayer~18":"Entra o Adivinho.","portiacomehitherfellowwhichwayhastthoube~llowwhichwayhastthoubeen~42":"Pórcia — Vem cá, bom homem: por onde andaste?","soothsayeratmineownhousegoodlady~eratmineownhousegoodlady~32":"Adivinho — Em minha própria casa, boa senhora.","portiawhatistoclock~portiawhatistoclock~19":"Pórcia — Que horas são?","soothsayerabouttheninthhourlady~yerabouttheninthhourlady~31":"Adivinho — Perto da nona hora, senhora.","portiaiscaesaryetgonetothecapitol~aesaryetgonetothecapitol~33":"Pórcia — César já foi ao Capitólio?","soothsayermadamnotyetigototakemystandtos~seehimpassontothecapitol~63":"Adivinho — Senhora, ainda não: vou tomar meu posto, \npara vê-lo passar rumo ao Capitólio.","portiathouhastsomesuittocaesarhastthouno~esuittocaesarhastthounot~41":"Pórcia — Tens algum pedido a César, não é?","soothsayerthatihaveladyifitwillpleasecae~eechhimtobefriendhimself~104":"Adivinho — Tenho, senhora: se aprouver a César \nser tão bom para César que me ouça, \nrogar-lhe-ei que seja amigo de si mesmo.","portiawhyknowstthouanyharmsintendedtowar~yharmsintendedtowardshim~45":"Pórcia — Ora, sabes de algum mal que se trame contra ele?","soothsayernonethatiknowwillbemuchthatife~caesarashecomesalongexit~256":"Adivinho — Nenhum que eu saiba que será, muito que receio possa suceder. \nBom dia a vós. Aqui a rua é estreita: \na turba que segue César nos calcanhares, \nde senadores, de pretores, de suplicantes comuns, \nesmagará um homem fraco quase até a morte: \nirei para um lugar mais vazio, e ali \nfalarei ao grande César quando vier passando. Sai.","portiaimustgoinaymehowweakathingtheheart~saytotheeexeuntseverally~258":"Pórcia — Devo entrar. Ai de mim, que coisa fraca \né o coração de mulher! Ó Brutus, \nque os céus te deem êxito em teu empreendimento! \nCerto, o rapaz me ouviu: Brutus tem um pedido \nque César não concederá. Oh, sinto desmaiar. \nCorre, Lúcio, e recomenda-me a meu senhor; \ndize que estou alegre: volta a mim, \ne traze-me notícia do que ele te disser. Saem separadamente.","romebeforethecapitolthesenatesittingabov~tolthesenatesittingabove~41":"Roma. Diante do Capitólio; o Senado reunido no alto.","acrowdofpeopleamongthemartemidorusandthe~popiliuspubliusandothers~152":"Uma multidão de povo; entre ela Artemidoro e o Adivinho. Fanfarra. Entram César, Brutus, Cássio, Casca, Décio, Metelo, Trebônio, Cina, Antônio, Lépido, Popílio, Públio e outros.","caesartothesoothsayertheidesofmarchareco~yertheidesofmarcharecome~42":"César — Ao Adivinho. Os idos de março chegaram.","soothsayeraycaesarbutnotgone~hsayeraycaesarbutnotgone~28":"Adivinho — Sim, César; mas não passaram.","artemidorushailcaesarreadthisschedule~ilcaesarreadthisschedule~37":"Artemidoro — Salve, César! Lede este memorial.","deciustreboniusdothdesireyoutooerreadaty~leisurethishishumblesuit~71":"Décio — Trebônio deseja que leiais, \nquando vos aprouver, este seu humilde pedido.","artemidorusocaesarreadminefirstforminesa~rnearerreaditgreatcaesar~84":"Artemidoro — Ó César, lede primeiro o meu; pois o meu é um pedido \nque toca César mais de perto: lede-o, grande César.","caesarwhattouchesusourselfshallbelastser~ourselfshallbelastserved~43":"César — O que nos toca a nós mesmo será servido por último.","artemidorusdelaynotcaesarreaditinstantly~notcaesarreaditinstantly~40":"Artemidoro — Não demoreis, César; lede-o já.","caesarwhatisthefellowmad~caesarwhatisthefellowmad~24":"César — Como, está louco esse sujeito?","publiussirrahgiveplace~publiussirrahgiveplace~22":"Públio — Ei, tu, dá lugar.","cassiuswhaturgeyouyourpetitionsinthestre~hestreetcometothecapitol~58":"Cássio — Como, apresentais vossos pedidos na rua? \nVinde ao Capitólio.","caesargoesuptothesenatehousetherestfollo~atehousetherestfollowing~44":"César sobe à Casa do Senado, seguido pelos demais.","popiliusiwishyourenterprisetodaymaythriv~enterprisetodaymaythrive~41":"Popílio — Desejo que vosso empreendimento hoje prospere.","cassiuswhatenterprisepopilius~uswhatenterprisepopilius~29":"Cássio — Que empreendimento, Popílio?","popiliusfareyouwelladvancestocaesar~eyouwelladvancestocaesar~35":"Popílio — Passai bem. Aproxima-se de César.","brutuswhatsaidpopiliuslena~utuswhatsaidpopiliuslena~26":"Brutus — Que disse Popílio Lena?","cassiushewishdtodayourenterprisemightthr~arourpurposeisdiscovered~70":"Cássio — Desejou que hoje nosso empreendimento prosperasse. \nTemo que nosso propósito esteja descoberto.","brutuslookhowhemakestocaesarmarkhim~owhemakestocaesarmarkhim~35":"Brutus — Olha como ele se dirige a César: observa-o.","cassiuscascabesuddenforwefearpreventionb~rnbackforiwillslaymyself~124":"Cássio — Casca, sê rápido, pois tememos que nos previnam. \nBrutus, que se fará? Se isto for sabido, \nou Cássio ou César nunca voltará atrás, \npois eu me matarei.","brutuscassiusbeconstantpopiliuslenaspeak~esandcaesardothnotchange~94":"Brutus — Cássio, sê firme: \nPopílio Lena não fala de nossos propósitos; \npois, olha, ele sorri, e César não muda.","cassiustreboniusknowshistimeforlookyoubr~exeuntantonyandtrebonius~96":"Cássio — Trebônio conhece a hora; pois, vê, Brutus, \nele tira Marco Antônio do caminho. Saem Antônio e Trebônio.","deciuswhereismetelluscimberlethimgoandpr~tlypreferhissuittocaesar~68":"Décio — Onde está Metelo Címber? Que vá, \ne apresente logo seu pedido a César.","brutusheisaddressdpressnearandsecondhim~ssdpressnearandsecondhim~39":"Brutus — Está pronto: chegai perto e apoiai-o.","cinnacascayouarethefirstthatrearsyourhan~hefirstthatrearsyourhand~41":"Cina — Casca, és o primeiro a erguer a mão.","caesarareweallreadywhatisnowamissthatcae~randhissenatemustredress~66":"César — Estamos todos prontos? Que há de errado agora \nque César e seu Senado devam reparar?","metellusmosthighmostmightyandmostpuissan~eatanhumbleheartkneeling~101":"Metelo — Altíssimo, poderosíssimo e potentíssimo César, \nMetelo Címber lança diante do teu assento \num humilde coração — Ajoelhando-se.","caesarimustpreventtheecimberthesecouchin~utcausewillhebesatisfied~450":"César — Devo antecipar-me, Címber. \nEsses agachamentos e essas baixas cortesias \npoderiam inflamar o sangue de homens comuns, \ne converter ordenação prévia e primeiro decreto \nem lei de crianças. Não sejas tolo \nao pensar que César tem sangue tão rebelde \nque se derreta de sua verdadeira qualidade \ncom o que derrete tolos: falo de palavras doces, \nreverências curvadas e baixo rastejar de cão. \nTeu irmão está banido por decreto: \nse te curvas e imploras e rastejas por ele, \nchuto-te como um cão para fora do meu caminho. \nSabe: César não erra, nem sem causa \nse deixa satisfazer.","metellusistherenovoicemoreworthythanmyow~ealingofmybanishdbrother~109":"Metelo — Não há voz mais digna que a minha \npara soar mais doce no ouvido do grande César \npelo cancelamento do banimento de meu irmão?","brutusikissthyhandbutnotinflatterycaesar~immediatefreedomofrepeal~102":"Brutus — Beijo-te a mão, mas não por adulação, César; \nrogando-te que Públio Címber possa \nter imediata liberdade de retorno.","caesarwhatbrutus~caesarwhatbrutus~16":"César — Como, Brutus!","cassiuspardoncaesarcaesarpardonaslowasto~hisementforpubliuscimber~98":"Cássio — Perdão, César; César, perdão: \ntão baixo quanto a teu pé cai Cássio, \npara pedir a libertação de Públio Címber.","caesaricouldbewellmovedifiwereasyouifico~stantdoremaintokeephimso~521":"César — Poderia bem me comover, se fosse como vós; \nse eu pudesse rogar para comover, preces me comoveriam: \nmas sou constante como a estrela do norte, \ncuja qualidade verdadeiramente fixa e imóvel \nnão tem par no firmamento. \nOs céus são pintados de incontáveis centelhas, \nsão todas fogo e cada uma brilha, \nmas só uma em todas mantém seu lugar: \nassim no mundo; está bem provido de homens, \ne homens são carne e sangue, e sensíveis; \ncontudo, em seu número só conheço um \nque, inatacável, mantém seu posto, \nsem se abalar com o movimento: e que eu sou esse, \ndeixai-me mostrar um pouco, mesmo nisto; \nque fui constante em que Címber fosse banido, \ne constante permaneço em mantê-lo assim.","cinnaocaesar~cinnaocaesar~12":"Cina — Ó César —","caesarhencewiltthouliftupolympus~ncewiltthouliftupolympus~32":"César — Para trás! Levantarás o Olimpo?","deciusgreatcaesar~deciusgreatcaesar~17":"Décio — Grande César —","caesardothnotbrutusbootlesskneel~thnotbrutusbootlesskneel~32":"César — Não se ajoelha Brutus em vão?","cascaspeakhandsformecascafirstthentheoth~ndmarcusbrutusstabcaesar~79":"Casca — Falai, mãos, por mim! Casca primeiro, depois os outros Conspiradores e Marco Brutus apunhalam César.","caesarettubrutethenfallcaesardies~ubrutethenfallcaesardies~33":"César — Et tu, Brute! Então cai, César. Morre.","cinnalibertyfreedomtyrannyisdeadrunhence~laimcryitaboutthestreets~68":"Cina — Liberdade! Libertação! A tirania está morta! \nCorrei daqui, proclamai, gritai pelas ruas.","cassiussometothecommonpulpitsandcryoutli~reedomandenfranchisement~70":"Cássio — Alguns para as tribunas públicas, e gritai: \n“Liberdade, libertação e emancipação!”","brutuspeopleandsenatorsbenotaffrightedfl~stillambitionsdebtispaid~73":"Brutus — Povo e senadores, não vos assusteis; \nnão fujais; ficai quietos: a dívida da ambição está paga.","cascagotothepulpitbrutus~cascagotothepulpitbrutus~24":"Casca — Vai à tribuna, Brutus.","deciusandcassiustoo~deciusandcassiustoo~19":"Décio — E Cássio também.","brutuswherespublius~brutuswherespublius~19":"Brutus — Onde está Públio?","cinnaherequiteconfoundedwiththismutiny~confoundedwiththismutiny~38":"Cina — Aqui, bem atônito com este tumulto.","metellusstandfasttogetherlestsomefriendo~endofcaesarsshouldchance~60":"Metelo — Ficai firmes juntos, para que algum amigo de César \nnão venha a —","brutustalknotofstandingpubliusgoodcheert~manelsesotellthempublius~105":"Brutus — Não faleis em ficar firme. Públio, ânimo; \nnenhum mal se pretende contra tua pessoa, \nnem contra nenhum outro romano: dize-lhes isso, Públio.","cassiusandleaveuspubliuslestthatthepeopl~ulddoyouragesomemischief~79":"Cássio — E deixa-nos, Públio; para que o povo, \nprecipitando-se sobre nós, não faça mal à tua idade.","brutusdosoandletnomanabidethisdeedbutwet~idethisdeedbutwethedoers~47":"Brutus — Faze assim: e que homem nenhum responda por este feito, \nsenão nós, os autores.","reentertrebonius~reentertrebonius~16":"Reentra Trebônio.","cassiuswhereisantony~cassiuswhereisantony~20":"Cássio — Onde está Antônio?","treboniusfledtohishouseamazedmenwivesand~utandrunasitweredoomsday~81":"Trebônio — Fugiu para casa, aturdido: \nhomens, mulheres e crianças olham fixo, gritam e correm \ncomo se fosse o dia do juízo.","brutusfateswewillknowyourpleasuresthatwe~gdaysoutthatmenstandupon~100":"Brutus — Destinos, queremos conhecer vossos prazeres: \nque morreremos, sabemos; é só o tempo \ne o arrastar dos dias que os homens consideram.","cassiuswhyhethatcutsofftwentyyearsoflife~omanyyearsoffearingdeath~72":"Cássio — Ora, quem corta vinte anos de vida \ncorta outros tantos anos de temer a morte.","brutusgrantthatandthenisdeathabenefitsoa~rypeacefreedomandliberty~278":"Brutus — Admite isso, e então a morte é um benefício: \nassim somos amigos de César, que abreviamos \nseu tempo de temer a morte. Curvai-vos, romanos, curvai-vos, \ne banhemos as mãos no sangue de César \naté os cotovelos, e untemos as espadas: \ndepois caminhemos até a praça do mercado, \ne, agitando nossas armas rubras sobre as cabeças, \ngritemos todos: “Paz, liberdade e libertação!”","cassiusstoopthenandwashhowmanyageshences~bornandaccentsyetunknown~106":"Cássio — Curvai-vos, então, e lavai. Quantas eras depois \nesta nossa cena elevada será representada de novo \nem Estados por nascer e em sotaques ainda desconhecidos!","brutushowmanytimesshallcaesarbleedinspor~ongnoworthierthanthedust~92":"Brutus — Quantas vezes César sangrará por jogo, \nele que agora jaz ao pé da base de Pompeu, \nnão mais digno que o pó!","cassiussooftasthatshallbesooftenshallthe~tgavetheircountryliberty~88":"Cássio — Todas as vezes que isso se der, \ntodas essas vezes será o nosso grupo chamado \nos homens que deram liberdade à pátria.","deciuswhatshallweforth~deciuswhatshallweforth~22":"Décio — Então, saímos?","cassiusayeverymanawaybrutusshallleadandw~ldestandbestheartsofrome~95":"Cássio — Sim, todos fora: \nBrutus conduzirá; e honraremos seus passos \ncom os corações mais ousados e melhores de Roma.","brutussoftwhocomeshereafriendofantonys~omeshereafriendofantonys~38":"Brutus — Calma! Quem vem aí? Um amigo de Antônio.","servantthusbrutusdidmymasterbidmekneelth~aithsosaysmymasterantony~494":"Criado — Assim, Brutus, mandou-me meu amo ajoelhar; \nassim mandou-me Marco Antônio prostrar-me; \ne, prostrado, assim me mandou dizer: \nBrutus é nobre, sábio, valente e honesto; \nCésar era poderoso, ousado, régio e afetuoso: \ndize que amo Brutus, e o honro; \ndize que temi César, honrei-o e amei-o. \nSe Brutus se dignar de que Antônio \npossa vir a ele em segurança, e ser esclarecido \nde como César mereceu jazer morto, \nMarco Antônio não amará César morto \ntanto quanto Brutus vivo; mas seguirá \nas fortunas e assuntos do nobre Brutus \natravés dos riscos deste Estado não trilhado \ncom toda a verdadeira fé. Assim diz meu amo Antônio.","brutusthymasterisawiseandvaliantromanine~bymyhonourdepartuntouchd~138":"Brutus — Teu amo é um romano sábio e valente; \nnunca o julguei pior. \nDize-lhe que, se lhe aprouver vir a este lugar, \nficará satisfeito; e, por minha honra, \nsairá ileso.","servantillfetchhimpresentlyexit~illfetchhimpresentlyexit~31":"Criado — Vou buscá-lo já. Sai.","brutusiknowthatweshallhavehimwelltofrien~shallhavehimwelltofriend~41":"Brutus — Sei que o teremos bem por amigo.","cassiusiwishwemaybutyethaveiamindthatfea~allsshrewdlytothepurpose~93":"Cássio — Oxalá; mas ainda tenho um ânimo \nque muito o teme; e meu pressentimento sempre \ncai agudamente no alvo.","brutusbutherecomesantony~brutusbutherecomesantony~24":"Brutus — Mas eis que vem Antônio.","reenterantony~reenterantony~13":"Reentra Antônio.","welcomemarkantony~welcomemarkantony~17":"Bem-vindo, Marco Antônio.","antonyomightycaesardostthouliesolowareal~ndmasterspiritsofthisage~537":"Antônio — Ó poderoso César! Jazes tão baixo? \nTodas as tuas conquistas, glórias, triunfos, despojos \nencolheram-se a esta pequena medida? Adeus. \nNão sei, senhores, o que pretendeis, \nquem mais deve ser sangrado, quem mais está corrupto: \nse eu mesmo, não há hora tão própria \nquanto a hora da morte de César, nem instrumento \nde metade desse valor como essas vossas espadas, enriquecidas \ncom o sangue mais nobre de todo este mundo. \nRogo-vos, se me guardais rancor, \nagora, enquanto vossas mãos purpúreas fumegam e exalam, \ncumpri vosso prazer. Vivesse eu mil anos, \nnão me acharia tão disposto a morrer: \nnenhum lugar me agradará tanto, nenhum meio de morte, \ncomo aqui ao lado de César, e por vós abatido, \nespíritos escolhidos e senhores desta era.","brutusoantonybegnotyourdeathofusthoughno~goodthoughtsandreverence~439":"Brutus — Ó Antônio, não nos peças tua morte. \nEmbora agora devamos parecer sanguinários e cruéis, \ncomo, por nossas mãos e este nosso ato presente, \nvês que parecemos, vês contudo só nossas mãos \ne este sangrento ofício que fizeram: \nnossos corações não vês; são piedosos; \ne a piedade pelo mal geral de Roma — \ncomo fogo expulsa fogo, assim piedade piedade — \nfez este ato em César. Quanto a ti, \npara ti nossas espadas têm pontas de chumbo, Marco Antônio: \nnossos braços, na força da malícia, e nossos corações \nde têmpera de irmãos, recebem-te \ncom todo terno amor, bons pensamentos e reverência.","cassiusyourvoiceshallbeasstrongasanymans~edisposingofnewdignities~68":"Cássio — Tua voz será tão forte como a de qualquer homem \nna distribuição das novas dignidades.","brutusonlybepatienttillwehaveappeasedthe~ruckhimhavethusproceeded~156":"Brutus — Apenas tem paciência até apaziguarmos \na multidão, fora de si de medo, \ne então te daremos a causa \npor que eu, que amava César quando o feri, \nprocedi assim.","antonyidoubtnotofyourwisdomleteachmanren~nyprincesdostthouherelie~911":"Antônio — Não duvido de vossa sabedoria. \nQue cada um me estenda a mão sangrenta: \nprimeiro, Marco Brutus, apertarei a vossa; \ndepois, Caio Cássio, tomo vossa mão; \nagora, Décio Brutus, a vossa; agora a vossa, Metelo; \na vossa, Cina; e, meu valente Casca, a vossa; \nembora por último, não menos em afeto, a vossa, bom Trebônio. \nSenhores todos — ai, que direi? \nMeu crédito está agora em terreno tão escorregadio \nque de duas más maneiras tereis de me julgar: \nou covarde ou adulador. \nQue te amei, César, oh, é verdade: \nse então teu espírito nos olha agora, \nnão te afligirá mais que tua morte \nver teu Antônio fazendo as pazes, \napertando os dedos sangrentos de teus inimigos, \nnobilíssimo! na presença de teu cadáver? \nTivesse eu tantos olhos quanto tens feridas, \nchorando tão depressa quanto jorra teu sangue, \nmelhor me ficaria do que selar \npactos de amizade com teus inimigos. \nPerdoa-me, Júlio! Aqui foste acuado, bravo cervo; \naqui caíste; e aqui teus caçadores se postam, \nmarcados com teu despojo, e rubros em teu Letes. \nÓ mundo, tu eras a floresta deste cervo; \ne este, de fato, ó mundo, o coração de ti. \nComo um cervo, ferido por muitos príncipes, \njazes aqui!","cassiusmarkantony~cassiusmarkantony~17":"Cássio — Marco Antônio —","antonypardonmecaiuscassiustheenemiesofca~inafrienditiscoldmodesty~84":"Antônio — Perdoai-me, Caio Cássio: \nos inimigos de César dirão isto; \nem um amigo, é fria modéstia.","cassiusiblameyounotforpraisingcaesarsobu~allweonandnotdependonyou~134":"Cássio — Não vos censuro por louvar assim César; \nmas que pacto pretendeis ter conosco? \nQuereis ser marcado no número de nossos amigos; \nou seguiremos adiante sem contar convosco?","antonythereforeitookyourhandsbutwasindee~hereincaesarwasdangerous~180":"Antônio — Por isso tomei vossas mãos, mas fui, de fato, \ndesviado do ponto ao olhar para César caído. \nSou amigo de todos vós e amo a todos, \nsob a esperança de que me deis razões \npor que e em que César era perigoso.","brutusorelsewerethisasavagespectacleourr~esaryoushouldbesatisfied~118":"Brutus — Ou então seria isto um espetáculo selvagem: \nnossas razões são tão cheias de boa consideração \nque, fôsseis, Antônio, filho de César, \nficaríeis satisfeito.","antonythatsalliseekandammoreoversuitorth~akintheorderofhisfuneral~133":"Antônio — É tudo o que busco: \ne sou além disso suplicante para poder \nlevar seu corpo à praça do mercado; \ne na tribuna, como convém a um amigo, \nfalar na cerimônia de seu funeral.","brutusyoushallmarkantony~brutusyoushallmarkantony~24":"Brutus — Podeis, Marco Antônio.","cassiusbrutusawordwithyouasidetobrutusyo~edbythatwhichhewillutter~151":"Cássio — Brutus, uma palavra convosco. \nA Brutus, à parte. Não sabeis o que fazeis: não consintais \nque Antônio fale em seu funeral: \nsabeis quanto o povo pode se comover \ncom o que ele proferir?","brutusbyyourpardoniwillmyselfintothepulp~vantagemorethandouswrong~242":"Brutus — Com vossa licença; \nsubirei eu mesmo à tribuna primeiro, \ne mostrarei a razão da morte de nosso César: \no que Antônio disser, declararei \nque diz com licença e permissão, \ne que estamos contentes que César tenha \ntodos os ritos verdadeiros e cerimônias legais. \nIsso nos favorecerá mais do que prejudicará.","cassiusiknownotwhatmayfallilikeitnot~notwhatmayfallilikeitnot~36":"Cássio — Não sei o que possa suceder; não gosto disso.","brutusmarkantonyheretakeyoucaesarsbodyyo~oingaftermyspeechisended~249":"Brutus — Marco Antônio, aqui, tomai o corpo de César. \nNão nos censurareis em vosso discurso fúnebre, \nmas direis todo o bem que puderdes imaginar de César, \ne direis que o fazeis com nossa permissão; \ndo contrário, não tereis parte alguma \nem seu funeral: e falareis \nna mesma tribuna a que vou, \ndepois de terminado o meu discurso.","antonybeitsoidodesirenomore~onybeitsoidodesirenomore~27":"Antônio — Seja assim; \nnão desejo mais.","brutuspreparethebodythenandfollowusexeun~llowusexeuntallbutantony~53":"Brutus — Preparai o corpo, então, e segui-nos. Saem todos, menos Antônio.","antonyopardonmethoubleedingpieceofeartht~rionmengroaningforburial~735":"Antônio — Oh, perdoa-me, tu, pedaço de terra sangrando, \npor ser manso e gentil com estes açougueiros! \nTu és a ruína do mais nobre homem \nque jamais viveu na maré dos tempos. \nAi da mão que verteu este sangue precioso! \nSobre tuas feridas agora profetizo — \nque, como bocas mudas, abrem os lábios de rubi \npara pedir a voz e o falar da minha língua — \numa maldição cairá sobre os membros dos homens; \nfúria doméstica e feroz luta civil \nentravarão todas as partes da Itália; \nsangue e destruição serão tão usuais \ne objetos pavorosos tão familiares \nque mães apenas sorrirão ao ver \nseus filhos esquartejados pelas mãos da guerra; \ntoda piedade sufocada pelo costume de feitos cruéis: \ne o espírito de César, vagando por vingança, \ncom Ate a seu lado vinda ardente do inferno, \nnestas fronteiras com voz de monarca \ngritará “Estrago!”, e soltará os cães da guerra; \npara que este feito imundo cheire acima da terra \ncom homens carniça, gemendo por sepultura.","youserveoctaviuscaesardoyounot~veoctaviuscaesardoyounot~30":"Serves Otávio César, não é?","servantidomarkantony~servantidomarkantony~20":"Criado — Sirvo, Marco Antônio.","antonycaesardidwriteforhimtocometorome~dwriteforhimtocometorome~38":"Antônio — César escreveu-lhe que viesse a Roma.","servanthedidreceivehislettersandiscoming~outhocaesarseeingthebody~89":"Criado — Recebeu suas cartas, e está vindo; \ne mandou-me dizer-vos de viva voz — \nÓ César! — Vendo o corpo.","antonythyheartisbiggettheeapartandweeppa~towateristhymastercoming~135":"Antônio — Teu coração está cheio, afasta-te e chora. \nA paixão, vejo, é contagiosa; pois meus olhos, \nvendo essas contas de dor nos teus, \ncomeçaram a marejar. Teu amo está vindo?","servantheliestonightwithinsevenleaguesof~withinsevenleaguesofrome~44":"Criado — Pernoita hoje a sete léguas de Roma.","antonypostbackwithspeedandtellhimwhathat~andexeuntwithcaesarsbody~374":"Antônio — Volta a toda pressa e conta-lhe o que sucedeu: \naqui há uma Roma de luto, uma Roma perigosa, \nnenhuma Roma segura ainda para Otávio; \napressa-te e dize-lhe isso. Mas espera um pouco; \nnão voltarás até que eu tenha levado este cadáver \nà praça do mercado: ali verei, \nem minha oração, como o povo recebe \no cruel desfecho destes homens sanguinários; \nconforme o qual, discorrerás \nao jovem Otávio sobre o estado das coisas. \nEmprestai-me a mão. Saem com o corpo de César.","theforum~theforum~8":"O Fórum.","enterbrutusandcassiusandathrongofcitizen~siusandathrongofcitizens~41":"Entram Brutus e Cássio, e uma turba de Cidadãos.","citizenswewillbesatisfiedletusbesatisfie~atisfiedletusbesatisfied~41":"Cidadãos — Queremos ser satisfeitos; satisfaçam-nos.","brutusthenfollowmeandgivemeaudiencefrien~berenderedofcaesarsdeath~206":"Brutus — Então segui-me e dai-me audiência, amigos. \nCássio, vai à outra rua, \ne divide a multidão. \nOs que quiserem ouvir-me falar, fiquem aqui; \nos que quiserem seguir Cássio, vão com ele; \ne razões públicas serão dadas \nda morte de César.","firstcitizeniwillhearbrutusspeak~izeniwillhearbrutusspeak~32":"Primeiro Cidadão — Ouvirei Brutus falar.","secondcitizeniwillhearcassiusandcomparet~sbrutusgoesintothepulpit~137":"Segundo Cidadão — Ouvirei Cássio; e compararei as razões, \nquando as ouvirmos dadas em separado. Sai Cássio, com alguns dos Cidadãos. Brutus sobe à tribuna.","thirdcitizenthenoblebrutusisascendedsile~ebrutusisascendedsilence~43":"Terceiro Cidadão — O nobre Brutus subiu: silêncio!","brutusbepatienttillthelastromanscountrym~ioffendedipauseforareply~896":"Brutus — Tende paciência até o fim. Romanos, patrícios e amigos! Ouvi-me pela minha causa, e calai-vos, para que possais ouvir; crede em mim por minha honra, e respeitai minha honra, para que possais crer; julgai-me em vossa sabedoria, e despertai vossos sentidos, para que possais julgar melhor. Se há alguém nesta assembleia, algum caro amigo de César, a ele digo que o amor de Brutus por César não era menor que o seu. Se então esse amigo perguntar por que Brutus se ergueu contra César, esta é minha resposta: — Não que eu amasse menos a César, mas que amava mais a Roma. Preferiríeis que César vivesse e morrêsseis todos escravos, a que César estivesse morto e vivêsseis todos homens livres? Como César me amava, choro por ele; como era afortunado, alegro-me com isso; como era valente, honro-o: mas, como era ambicioso, matei-o. Há lágrimas por seu amor; alegria por sua fortuna; honra por seu valor; e morte por sua ambição. Quem aqui é tão vil que quereria ser escravo? Se alguém, fale; pois a ele ofendi. Quem aqui é tão rude que não quereria ser romano? Se alguém, fale; pois a ele ofendi. Quem aqui é tão baixo que não ame a sua pátria? Se alguém, fale; pois a ele ofendi. Faço uma pausa para resposta.","allnonebrutusnone~allnonebrutusnone~17":"Todos — Ninguém, Brutus, ninguém.","brutusthennonehaveioffendedihavedonenomo~dforwhichhesuffereddeath~199":"Brutus — Então a ninguém ofendi. Não fiz a César mais do que fareis a Brutus. A questão de sua morte está registrada no Capitólio; sua glória não diminuída, em que foi digno, nem suas ofensas agravadas, pelas quais sofreu a morte.","enterantonyandotherswithcaesarsbody~andotherswithcaesarsbody~35":"Entram Antônio e outros, com o corpo de César.","herecomeshisbodymournedbymarkantonywhoth~semycountrytoneedmydeath~259":"Aqui vem seu corpo, pranteado por Marco Antônio: que, embora não tenha tido mão em sua morte, receberá o benefício de seu morrer, um lugar na república; como qual de vós não receberá? Com isto me retiro — que, assim como matei meu melhor amigo pelo bem de Roma, tenho o mesmo punhal para mim, quando aprouver à minha pátria precisar de minha morte.","alllivebrutuslivelive~alllivebrutuslivelive~21":"Todos — Viva, Brutus! Viva, viva!","firstcitizenbringhimwithtriumphhomeuntoh~htriumphhomeuntohishouse~47":"Primeiro Cidadão — Levemo-lo em triunfo até sua casa.","secondcitizengivehimastatuewithhisancest~mastatuewithhisancestors~43":"Segundo Cidadão — Dai-lhe uma estátua junto com seus antepassados.","thirdcitizenlethimbecaesar~irdcitizenlethimbecaesar~26":"Terceiro Cidadão — Que seja César.","fourthcitizencaesarsbetterpartsshallbecr~rtsshallbecrowndinbrutus~52":"Quarto Cidadão — As melhores partes de César \nserão coroadas em Brutus.","firstcitizenwellbringhimtohishousewithsh~usewithshoutsandclamours~55":"Primeiro Cidadão — Levá-lo-emos à sua casa \ncom gritos e clamores.","brutusmycountrymen~brutusmycountrymen~18":"Brutus — Meus patrícios —","secondcitizenpeacesilencebrutusspeaks~peacesilencebrutusspeaks~37":"Segundo Cidadão — Paz, silêncio! Brutus fala.","firstcitizenpeaceho~firstcitizenpeaceho~19":"Primeiro Cidadão — Paz, ei!","brutusgoodcountrymenletmedepartaloneandf~etillantonyhavespokeexit~231":"Brutus — Bons patrícios, deixai-me partir só, \ne, por mim, ficai aqui com Antônio: \nhonrai o cadáver de César, e honrai seu discurso \nque tende às glórias de César; o qual Marco Antônio, \ncom nossa permissão, está autorizado a fazer. \nRogo-vos que homem nenhum se retire, \nsalvo eu só, até Antônio ter falado. Sai.","firstcitizenstayhoandletushearmarkantony~hoandletushearmarkantony~40":"Primeiro Cidadão — Ficai, ei! E ouçamos Marco Antônio.","thirdcitizenlethimgoupintothepublicchair~llhearhimnobleantonygoup~66":"Terceiro Cidadão — Que suba à cadeira pública; \nouvi-lo-emos. Nobre Antônio, subi.","antonyforbrutussakeiambeholdingtoyougoes~ngtoyougoesintothepulpit~53":"Antônio — Por amor de Brutus, estou em dívida convosco. Sobe à tribuna.","fourthcitizenwhatdoeshesayofbrutus~zenwhatdoeshesayofbrutus~34":"Quarto Cidadão — Que diz ele de Brutus?","thirdcitizenhesaysforbrutussakehefindshi~shimselfbeholdingtousall~61":"Terceiro Cidadão — Diz que, por amor de Brutus, \nsente-se em dívida conosco todos.","fourthcitizentwerebesthespeaknoharmofbru~espeaknoharmofbrutushere~47":"Quarto Cidadão — Melhor seria que não falasse mal de Brutus aqui.","firstcitizenthiscaesarwasatyrant~izenthiscaesarwasatyrant~32":"Primeiro Cidadão — Este César era um tirano.","thirdcitizennaythatscertainweareblesttha~eblestthatromeisridofhim~55":"Terceiro Cidadão — Não, isso é certo: \nsomos felizes que Roma se livrou dele.","secondcitizenpeaceletushearwhatantonycan~etushearwhatantonycansay~43":"Segundo Cidadão — Paz! Ouçamos o que Antônio pode dizer.","antonyyougentleromans~antonyyougentleromans~21":"Antônio — Vós, gentis romanos —","citizenspeaceholetushearhim~izenspeaceholetushearhim~27":"Cidadãos — Paz, ei! Ouçamo-lo.","antonyfriendsromanscountrymenlendmeyoure~tpausetillitcomebacktome~1105":"Antônio — Amigos, romanos, patrícios, emprestai-me os ouvidos; \nvenho enterrar César, não louvá-lo. \nO mal que os homens fazem vive depois deles; \no bem muitas vezes é enterrado com seus ossos; \nassim seja com César. O nobre Brutus \nvos disse que César era ambicioso: \nse assim foi, era uma grave falta, \ne gravemente César respondeu por ela. \nAqui, com licença de Brutus e dos demais — \npois Brutus é um homem honrado; \nassim são todos, todos homens honrados — \nvenho falar no funeral de César. \nEra meu amigo, fiel e justo para comigo: \nmas Brutus diz que era ambicioso; \ne Brutus é um homem honrado. \nTrouxe muitos cativos a Roma, \ncujos resgates encheram os cofres públicos: \nisso parecia ambição em César? \nQuando os pobres choraram, César chorou: \nambição deveria ser feita de matéria mais dura: \ncontudo Brutus diz que era ambicioso; \ne Brutus é um homem honrado. \nTodos vistes que nas Lupercais \nlhe ofereci três vezes uma coroa de rei, \nque ele três vezes recusou: era isso ambição? \nContudo Brutus diz que era ambicioso; \ne, por certo, é um homem honrado. \nNão falo para refutar o que Brutus disse, \nmas aqui estou para dizer o que sei. \nTodos o amastes outrora, não sem causa: \nque causa vos impede então de lamentá-lo? \nÓ juízo! Fugiste para as feras brutas, \ne os homens perderam a razão. Tolerai-me; \nmeu coração está no caixão ali com César, \ne devo parar até que ele volte a mim.","firstcitizenmethinksthereismuchreasoninh~ismuchreasoninhissayings~49":"Primeiro Cidadão — Parece-me que há muita razão no que diz.","secondcitizenifthouconsiderrightlyofthem~ercaesarhashadgreatwrong~67":"Segundo Cidadão — Se considerares bem o caso, \nCésar sofreu grande injustiça.","thirdcitizenhashemastersifeartherewillaw~willaworsecomeinhisplace~58":"Terceiro Cidadão — Sofreu, senhores? \nTemo que venha pior no lugar dele.","fourthcitizenmarkdyehiswordshewouldnotta~certainhewasnotambitious~86":"Quarto Cidadão — Notastes suas palavras? Não quis tomar a coroa; \nlogo é certo que não era ambicioso.","firstcitizenifitbefoundsosomewilldearabi~undsosomewilldearabideit~44":"Primeiro Cidadão — Se assim se achar, alguns pagarão caro.","secondcitizenpoorsoulhiseyesareredasfire~sareredasfirewithweeping~51":"Segundo Cidadão — Pobre alma! Seus olhos estão vermelhos como fogo de tanto chorar.","thirdcitizentheresnotanoblermaninrometha~oblermaninromethanantony~47":"Terceiro Cidadão — Não há homem mais nobre em Roma que Antônio.","fourthcitizennowmarkhimhebeginsagaintosp~khimhebeginsagaintospeak~43":"Quarto Cidadão — Agora o notai, ele começa a falar de novo.","antonybutyesterdaythewordofcaesarmightha~richlegacyuntotheirissue~625":"Antônio — Ontem ainda a palavra de César podia \nenfrentar o mundo; agora jaz ali, \ne ninguém tão pobre que lhe preste reverência. \nÓ senhores, se eu estivesse disposto a agitar \nvossos corações e mentes ao motim e à raiva, \nfaria mal a Brutus, e mal a Cássio, \nque, bem sabeis, são homens honrados: \nnão lhes farei mal; prefiro \nfazer mal aos mortos, a mim e a vós, \na fazer mal a tão honrados homens. \nMas aqui está um pergaminho com o selo de César; \nachei-o em seu gabinete, é seu testamento: \nsó que o povo ouvisse este testamento — \no qual, perdoai-me, não pretendo ler — \ne iriam beijar as feridas de César morto \ne molhar seus lenços em seu sangue sagrado, \nsim, pedir um fio de cabelo seu como lembrança, \ne, morrendo, mencioná-lo em seus testamentos, \nlegando-o como rica herança \na seus descendentes.","fourthcitizenwellhearthewillreaditmarkan~rthewillreaditmarkantony~44":"Quarto Cidadão — Ouviremos o testamento: lede-o, Marco Antônio.","allthewillthewillwewillhearcaesarswill~illwewillhearcaesarswill~38":"Todos — O testamento, o testamento! Queremos ouvir o testamento de César.","antonyhavepatiencegentlefriendsimustnotr~shouldowhatwouldcomeofit~246":"Antônio — Tende paciência, gentis amigos, não devo lê-lo; \nnão convém que saibais quanto César vos amava. \nNão sois de madeira, não sois pedras, mas homens; \ne, sendo homens, ouvindo o testamento de César, \nele vos inflamará, vos enlouquecerá: \nBem é que não saibais que sois seus herdeiros; \npois, se soubésseis, oh, que seria disso!","fourthcitizenreadthewillwellhearitantony~readusthewillcaesarswill~72":"Quarto Cidadão — Lede o testamento; queremos ouvi-lo, Antônio; \nlereis para nós o testamento, o testamento de César.","antonywillyoubepatientwillyoustayawhilei~avestabbdcaesaridofearit~134":"Antônio — Quereis ter paciência? Quereis esperar um pouco? \nExcedi-me ao falar-vos dele: \ntemo ofender os homens honrados \ncujos punhais apunhalaram César; temo-o.","fourthcitizentheyweretraitorshonourablem~eretraitorshonourablemen~42":"Quarto Cidadão — Eram traidores: homens honrados!","allthewillthetestament~allthewillthetestament~22":"Todos — O testamento! O testamento!","secondcitizentheywerevillainsmurderersth~derersthewillreadthewill~56":"Segundo Cidadão — Eram vilões, assassinos: o testamento! Lede o testamento.","antonyyouwillcompelmethentoreadthewillth~endandwillyougivemeleave~140":"Antônio — Compelis-me, então, a ler o testamento? \nEntão fazei um círculo em torno do corpo de César, \ne deixai-me mostrar-vos aquele que fez o testamento. \nDevo descer? E me dareis licença?","severalcitizenscomedown~severalcitizenscomedown~23":"Vários Cidadãos — Descei.","secondcitizendescend~secondcitizendescend~20":"Segundo Cidadão — Descei.","thirdcitizenyoushallhaveleaveantonycomes~haveleaveantonycomesdown~44":"Terceiro Cidadão — Tereis licença. Antônio desce.","fourthcitizenaringstandround~thcitizenaringstandround~28":"Quarto Cidadão — Um círculo; ficai em volta.","firstcitizenstandfromthehearsestandfromt~hehearsestandfromthebody~46":"Primeiro Cidadão — Afastai-vos do féretro, afastai-vos do corpo.","secondcitizenroomforantonymostnobleanton~forantonymostnobleantony~41":"Segundo Cidadão — Lugar para Antônio, nobilíssimo Antônio.","antonynaypressnotsouponmestandfaroff~ssnotsouponmestandfaroff~36":"Antônio — Não, não me aperteis tanto; ficai afastados.","severalcitizensstandbackroombearback~ensstandbackroombearback~36":"Vários Cidadãos — Para trás; lugar; recuai.","antonyifyouhavetearspreparetoshedthemnow~arrdasyouseewithtraitors~956":"Antônio — Se tendes lágrimas, preparai-vos para derramá-las agora. \nTodos conheceis este manto: lembro-me \nda primeira vez que César o vestiu; \nfoi numa tarde de verão, em sua tenda, \nnaquele dia em que venceu os nérvios: \nVede, neste lugar passou o punhal de Cássio: \nvede que rasgão fez o invejoso Casca: \npor aqui apunhalou o muito amado Brutus; \ne quando arrancou seu maldito aço, \nnotai como o sangue de César o seguiu, \ncomo se corresse para fora da porta, para saber \nse Brutus batera tão rudemente, ou não; \npois Brutus, como sabeis, era o anjo de César: \njulgai, ó deuses, quanto César o amava! \nEste foi o mais cruel golpe de todos; \npois quando o nobre César o viu apunhalar, \na ingratidão, mais forte que braços de traidores, \nvenceu-o por completo: então rebentou seu poderoso coração; \ne, no manto abafando o rosto, \njusto ao pé da estátua de Pompeu, \nque o tempo todo corria sangue, caiu o grande César. \nOh, que queda foi aquela, meus patrícios! \nEntão eu, e vós, e todos nós caímos, \nenquanto a sangrenta traição florescia sobre nós. \nOh, agora chorais; e, percebo, sentis \no golpe da piedade: são gotas bondosas. \nAlmas boas, ora, chorais só de ver \na veste de nosso César ferida? Olhai aqui, \naqui está ele próprio, desfigurado, como vedes, por traidores.","firstcitizenopiteousspectacle~citizenopiteousspectacle~29":"Primeiro Cidadão — Oh, espetáculo lastimável!","secondcitizenonoblecaesar~econdcitizenonoblecaesar~25":"Segundo Cidadão — Oh, nobre César!","thirdcitizenowoefulday~thirdcitizenowoefulday~22":"Terceiro Cidadão — Oh, dia de dor!","fourthcitizenotraitorsvillains~citizenotraitorsvillains~30":"Quarto Cidadão — Oh, traidores, vilões!","firstcitizenomostbloodysight~tcitizenomostbloodysight~28":"Primeiro Cidadão — Oh, visão sangrentíssima!","secondcitizenwewillberevenged~dcitizenwewillberevenged~29":"Segundo Cidadão — Seremos vingados.","allrevengeaboutseekburnfirekillslayletno~llslayletnotatraitorlive~53":"Todos — Vingança! Em volta! Buscai! Queimai! Fogo! Matai! Trucidai! Que nenhum traidor viva!","antonystaycountrymen~antonystaycountrymen~20":"Antônio — Esperai, patrícios.","firstcitizenpeacetherehearthenobleantony~etherehearthenobleantony~40":"Primeiro Cidadão — Paz aí! Ouvi o nobre Antônio.","secondcitizenwellhearhimwellfollowhimwel~lfollowhimwelldiewithhim~51":"Segundo Cidadão — Ouvi-lo-emos, segui-lo-emos, morreremos com ele.","antonygoodfriendssweetfriendsletmenotsti~nesofrometoriseandmutiny~729":"Antônio — Bons amigos, doces amigos, não vos queira eu incitar \na tão súbita torrente de motim. \nOs que fizeram este feito são honrados: \nque mágoas particulares tenham, ai, não sei, \nque os fizeram fazê-lo: são sábios e honrados, \ne sem dúvida vos responderão com razões. \nNão venho, amigos, roubar-vos os corações: \nnão sou orador, como é Brutus; \nmas, como todos me conheceis, um homem simples e rude, \nque ama o seu amigo; e que eles o sabem muito bem, \nque me deram licença pública para falar dele: \npois não tenho nem engenho, nem palavras, nem mérito, \nnem gesto, nem dicção, nem poder de oratória \npara agitar o sangue dos homens: falo apenas direto; \ndigo-vos o que vós mesmos sabeis; \nmostro-vos as feridas do doce César, pobres, pobres bocas mudas, \ne mando-as falar por mim: mas fosse eu Brutus, \ne Brutus Antônio, haveria um Antônio \nque eriçaria vossos espíritos e poria uma língua \nem cada ferida de César, que moveria \nas pedras de Roma a erguer-se e amotinar-se.","allwellmutiny~allwellmutiny~13":"Todos — Amotinar-nos-emos.","firstcitizenwellburnthehouseofbrutus~wellburnthehouseofbrutus~36":"Primeiro Cidadão — Queimaremos a casa de Brutus.","thirdcitizenawaythencomeseektheconspirat~ncomeseektheconspirators~43":"Terceiro Cidadão — Fora, então! Vamos, procuremos os conspiradores.","antonyyethearmecountrymenyethearmespeak~countrymenyethearmespeak~39":"Antônio — Ouvi-me ainda, patrícios; ouvi-me falar ainda.","allpeacehohearantonymostnobleantony~earantonymostnobleantony~35":"Todos — Paz, ei! Ouvi Antônio. Nobilíssimo Antônio!","antonywhyfriendsyougotodoyouknownotwhatw~eforgotthewillitoldyouof~137":"Antônio — Ora, amigos, ides fazer não sabeis o quê: \nem que César mereceu assim vossos afetos? \nAi, não sabeis: devo dizer-vos então: \nesquecestes o testamento de que vos falei.","allmosttruethewillletsstayandhearthewill~llletsstayandhearthewill~40":"Todos — Verdade. O testamento! Fiquemos e ouçamos o testamento.","antonyhereisthewillandundercaesarssealto~almanseventyfivedrachmas~100":"Antônio — Aqui está o testamento, e sob o selo de César. \nA cada cidadão romano ele dá, \na cada homem em particular, setenta e cinco dracmas.","secondcitizenmostnoblecaesarwellrevengeh~aesarwellrevengehisdeath~47":"Segundo Cidadão — Nobilíssimo César! Vingaremos sua morte.","thirdcitizenoroyalcaesar~thirdcitizenoroyalcaesar~24":"Terceiro Cidadão — Oh, régio César!","antonyhearmewithpatience~antonyhearmewithpatience~24":"Antônio — Ouvi-me com paciência.","allpeaceho~allpeaceho~10":"Todos — Paz, ei!","antonymoreoverhehathleftyouallhiswalkshi~esarwhencomessuchanother~211":"Antônio — Além disso, deixou-vos todos os seus passeios, \nseus caramanchões privados e pomares recém-plantados, \nneste lado do Tibre; deixou-os a vós, \ne a vossos herdeiros para sempre, prazeres comuns, \npara passear ao ar livre e recrear-vos. \nAqui havia um César! Quando virá outro assim?","firstcitizennevernevercomeawayawaywellbu~itorshousestakeupthebody~113":"Primeiro Cidadão — Nunca, nunca. Vinde, fora, fora! \nQueimaremos seu corpo no lugar sagrado, \ne com os tições incendiaremos as casas dos traidores. \nLevantai o corpo.","secondcitizengofetchfire~secondcitizengofetchfire~24":"Segundo Cidadão — Ide buscar fogo.","thirdcitizenpluckdownbenches~dcitizenpluckdownbenches~28":"Terceiro Cidadão — Arrancai os bancos.","fourthcitizenpluckdownformswindowsanythi~xeuntcitizenswiththebody~67":"Quarto Cidadão — Arrancai assentos, janelas, qualquer coisa. Saem os Cidadãos com o corpo.","antonynowletitworkmischiefthouartafootta~kethouwhatcoursethouwilt~64":"Antônio — Agora que opere. Malícia, estás em pé, \nsegue o rumo que quiseres!","hownowfellow~hownowfellow~12":"Então, companheiro!","servantsiroctaviusisalreadycometorome~aviusisalreadycometorome~37":"Criado — Senhor, Otávio já chegou a Roma.","antonywhereishe~antonywhereishe~15":"Antônio — Onde está ele?","servantheandlepidusareatcaesarshouse~lepidusareatcaesarshouse~36":"Criado — Ele e Lépido estão na casa de César.","antonyandthitherwillistraighttovisithimh~ismoodwillgiveusanything~100":"Antônio — E para lá irei já visitá-lo: \nvem como se eu desejasse. A Fortuna está alegre, \ne neste humor nos dará qualquer coisa.","servantiheardhimsaybrutusandcassiusareri~menthroughthegatesofrome~72":"Criado — Ouvi-o dizer que Brutus e Cássio \ncavalgaram como loucos pelos portões de Roma.","antonybeliketheyhadsomenoticeofthepeople~mbringmetooctaviusexeunt~79":"Antônio — Decerto tiveram notícia do povo, \nde como o comovi. Leva-me a Otávio. Saem.","astreet~astreet~7":"Uma rua.","entercinnathepoet~entercinnathepoet~17":"Entra Cina, o poeta.","cinnaidreamttonightthatididfeastwithcaes~yetsomethingleadsmeforth~130":"Cina — Sonhei esta noite que banqueteava com César, \ne coisas funestas carregam minha fantasia: \nnão tenho vontade de andar fora de casa, \ncontudo algo me leva para fora.","entercitizens~entercitizens~13":"Entram Cidadãos.","firstcitizenwhatisyourname~rstcitizenwhatisyourname~26":"Primeiro Cidadão — Como te chamas?","secondcitizenwhitherareyougoing~itizenwhitherareyougoing~31":"Segundo Cidadão — Para onde vais?","thirdcitizenwheredoyoudwell~rdcitizenwheredoyoudwell~27":"Terceiro Cidadão — Onde moras?","fourthcitizenareyouamarriedmanorabachelo~ouamarriedmanorabachelor~41":"Quarto Cidadão — És homem casado ou solteiro?","secondcitizenanswereverymandirectly~enanswereverymandirectly~35":"Segundo Cidadão — Responde a cada um diretamente.","firstcitizenayandbriefly~firstcitizenayandbriefly~24":"Primeiro Cidadão — Sim, e brevemente.","fourthcitizenayandwisely~fourthcitizenayandwisely~24":"Quarto Cidadão — Sim, e sabiamente.","thirdcitizenayandtrulyyouwerebest~zenayandtrulyyouwerebest~33":"Terceiro Cidadão — Sim, e com verdade, é melhor para ti.","cinnawhatismynamewhitheramigoingwheredoi~lywiselyisayiamabachelor~144":"Cina — Qual é meu nome? Para onde vou? Onde moro? Sou casado ou solteiro? Então, para responder a cada homem diretamente e brevemente, sabiamente e com verdade: sabiamente digo, sou solteiro.","secondcitizenthatsasmuchastosaytheyarefo~thatifearproceeddirectly~95":"Segundo Cidadão — É o mesmo que dizer que são tolos os que casam: levarás uma pancada de mim por isso, receio. Prossegue; diretamente.","cinnadirectlyiamgoingtocaesarsfuneral~iamgoingtocaesarsfuneral~37":"Cina — Diretamente, vou ao funeral de César.","firstcitizenasafriendoranenemy~itizenasafriendoranenemy~30":"Primeiro Cidadão — Como amigo ou como inimigo?","cinnaasafriend~cinnaasafriend~14":"Cina — Como amigo.","secondcitizenthatmatterisanswereddirectl~matterisanswereddirectly~41":"Segundo Cidadão — Esse ponto foi respondido diretamente.","fourthcitizenforyourdwellingbriefly~enforyourdwellingbriefly~35":"Quarto Cidadão — Quanto à tua morada — brevemente.","cinnabrieflyidwellbythecapitol~rieflyidwellbythecapitol~30":"Cina — Brevemente, moro junto ao Capitólio.","thirdcitizenyournamesirtruly~dcitizenyournamesirtruly~28":"Terceiro Cidadão — Teu nome, senhor, com verdade.","cinnatrulymynameiscinna~cinnatrulymynameiscinna~23":"Cina — Com verdade, meu nome é Cina.","firstcitizentearhimtopieceshesaconspirat~mtopieceshesaconspirator~42":"Primeiro Cidadão — Despedaçai-o; é um conspirador.","cinnaiamcinnathepoetiamcinnathepoet~nathepoetiamcinnathepoet~35":"Cina — Sou Cina, o poeta, sou Cina, o poeta.","fourthcitizentearhimforhisbadversestearh~estearhimforhisbadverses~57":"Quarto Cidadão — Despedaçai-o pelos maus versos, despedaçai-o pelos maus versos.","cinnaiamnotcinnatheconspirator~amnotcinnatheconspirator~30":"Cina — Não sou Cina, o conspirador.","fourthcitizenitisnomatterhisnamescinnapl~fhisheartandturnhimgoing~81":"Quarto Cidadão — Não importa, o nome dele é Cina; arrancai apenas o nome do seu coração, e mandai-o embora.","thirdcitizentearhimtearhimcomebrandshofi~metoligariusawaygoexeunt~130":"Terceiro Cidadão — Despedaçai-o, despedaçai-o! Vamos, tições, ei! Tições de fogo: para a casa de Brutus, para a de Cássio; queimai tudo: alguns para a casa de Décio, e alguns para a de Casca; alguns para a de Ligário: fora, vamos! Saem."}$tr$::jsonb, 536)
